window.__D("text/zohar-hebrew-translation/c032",{"p":[[9522012402,"<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. הִגִּיעוּ לְאוֹתוֹ מָקוֹם שֶׁל כְּפַר סִכְנִין, שֶׁהָיָה שָׁם רַב הַמְנוּנָא סָבָא. הִתְאָרְחוּ אֵצֶל אִשְׁתּוֹ, שֶׁהָיָה לָהּ בֵּן אֶחָד קָטָן, וְכָל הַיּוֹם הָיָה בְּבֵית הַסֵּפֶר. אוֹתוֹ יוֹם עָלָה מִבֵּית הַסֵּפֶר וּבָא הַבַּיְתָה, רָאָה אֶת אוֹתָם הַחֲכָמִים. אָמְרָה לוֹ אִמּוֹ, הִתְקָרֵב לַגְּבָרִים הָעֶלְיוֹנִים הַלָּלוּ וְתַרְוִיחַ מֵהֶם בְּרָכוֹת. קָרַב אֲלֵיהֶם, וְעַד שֶׁלֹּא קָרַב, חָזַר לְאָחוֹר. אָמַר לְאִמּוֹ, אֵינִי רוֹצֶה לִקְרַב אֲלֵיהֶם, שֶׁהֲרֵי יוֹם זֶה לֹא קָרְאוּ קְרִיאַת שְׁמַע, וְכָךְ לִמְּדוּנִי, כָּל מִי שֶׁלֹּא קָרָא קְרִיאַת שְׁמַע בְּעוֹנָתָהּ, הוּא בְּנִדּוּי כָּל אוֹתוֹ הַיּוֹם.</p>\n<p>שָׁמְעוּ הֵם וְתָמְהוּ, הֵרִימוּ יְדֵיהֶם וּבֵרְכוּהוּ. אָמְרוּ, וַדַּאי כָּךְ זֶה, וְיוֹם זֶה הִשְׁתַּדַּלְנוּ יַחַד עִם חָתָן וְכַלָּה שֶׁלֹּא הָיוּ לָהֶם צָרְכֵיהֶם וְהָיוּ מִתְאַחֲרִים לְהִזְדַּוֵּג, וְלֹא הָיָה אָדָם שֶׁיִּשְׁתַּדֵּל עֲלֵיהֶם, וְאָנוּ הִשְׁתַּדַּלְנוּ בָהֶם וְלֹא קָרָאנוּ קְרִיאַת שְׁמַע בְּעוֹנָתָהּ, וּמִי שֶׁעוֹסֵק בַּמִּצְוָה - פָּטוּר מֵהַמִּצְוָה. אָמְרוּ לוֹ, בְּנִי, אֵיךְ יָדַעְתָּ? אָמַר לָהֶם, בְּרֵיחַ לְבוּשְׁכֶם יָדַעְתִּי כְּשֶׁקָּרַבְתִּי אֲלֵיכֶם. תָּמְהוּ. יָשְׁבוּ, נָטְלוּ יְדֵיהֶם וְכָרְכוּ פַת.</p>\n<p>רַבִּי יְהוּדָה הָיוּ יָדָיו מְלֻכְלָכוֹת, וְנָטַל יָדָיו וּבֵרַךְ טֶרֶם שֶׁנָּטַל. אָמַר לוֹ, אִם תַּלְמִידֵי רַב שְׁמַעְיָה הֶחָסִיד אַתֶּם, לֹא הָיָה לָכֶם לְבָרֵךְ בְּיָדַיִם מְזֹּהָמוֹת, וּמִי שֶׁמְּבָרֵךְ בְּיָדַיִם מְזֹּהָמוֹת חַיָּב מִיתָה.</p>\n<p>פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, (שמות ל) בְּבֹאָם אֶל אֹהֶל מוֹעֵד יִרְחֲצוּ מַיִם וְלֹא יָמֻתוּ וְגוֹ'. לָמַדְנוּ מִפָּסוּק זֶה, שֶׁמִּי שֶׁלֹּא חוֹשֵׁשׁ לָזֶה וְיִתְרָאֶה לִפְנֵי הַמֶּלֶךְ בְּיָדַיִם מְזֹּהָמוֹת, חַיָּב מִיתָה. מָה הַטַּעַם? מִשּׁוּם שֶׁיְּדֵי הָאָדָם יוֹשְׁבִים בְּרוּמוֹ שֶׁל עוֹלָם. אֶצְבַּע אַחַת יֵשׁ בְּיַד הָאָדָם, וְהִיא הָאֶצְבַּע שֶׁהֵרִים מֹשֶׁה.</p>\n<p>כָּתוּב (שם כו) וְעָשִׂיתָ בְרִיחִם עֲצֵי שִׁטִּים חֲמִשָּׁה לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הָאֶחָד וַחֲמִשָּׁה בְרִיחִם לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הַשֵּׁנִית. וְכָתוּב וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה. וְאִם תֹּאמַר שֶׁאוֹתוֹ בְּרִיחַ הַתִּיכוֹן הוּא אַחֵר, שֶׁלֹּא הָיָה בִּכְלַל אוֹתָם חֲמִשָּׁה - לֹא כָּךְ. אֶלָּא אוֹתוֹ בְּרִיחַ הַתִּיכוֹן הָיָה מֵאוֹתָם חֲמִשָּׁה, שְׁנַיִם מִכָּאן וּשְׁנַיִם מִכָּאן וְאֶחָד בָּאֶמְצַע. הֲרֵי הָיָה בְּרִיחַ הַתִּיכוֹן עַמּוּד יַעֲקֹב, סוֹד מֹשֶׁה. כְּנֶגֶד זֶה חָמֵשׁ אֶצְבָּעוֹת בְּיַד הָאָדָם. וְהַבְּרִיחַ הַתִּיכוֹן בָּאֶמְצַע, גָּדוֹל וְעֶלְיוֹן מֵהַכֹּל, בּוֹ עוֹמְדִים שְׁאָר הָאֲחֵרִים.</p>\n<p>וְהֵם חֲמִשָּׁה בְרִיחִים, שֶׁנִּקְרָאִים חֲמֵשׁ מֵאוֹת שָׁנִים, שֶׁהוֹלֵךְ בָּהֶם עֵץ הַחַיִּים. וּבְרִית קֹדֶשׁ מִתְעוֹרֵר (נמול) בַּחֲמֵשׁ אֶצְבְּעוֹת הַיָּדַיִם, וְדָבָר (נסתר) תֵּמַהּ הוּא עַל מַה שֶּׁאָמַרְתָּ. וְלָכֵן כָּל בִּרְכוֹת הַכֹּהֵן תְּלוּיוֹת בָּאֶצְבָּעוֹת. פְּרִישַׂת יְדֵי משֶׁה עַל זֶה הָיְתָה.</p>\n<p>אִם כָּל זֶה יֵשׁ בָּהֶם, אֵין דִּין לִהְיוֹת בְּנִקָּיוֹן כְּשֶׁמְּבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁבָּהֶם וּבְדֻגָמָתָם מִתְבָּרֵךְ הַשֵּׁם הַקָּדוֹשׁ. וְלָכֵן אַתֶּם שֶׁחֲכָמִים אַתֶּם הַרְבֵּה, אֵיךְ לֹא הִשְׁגַּחְתֶּם לָזֶה? וְלֹא שִׁמַּשְׁתֶּם אֶת רַבִּי שְׁמַעְיָה הֶחָסִיד, וְהוּא אָמַר שֶׁכָּל טִנּוּךְ וְכָל לִכְלוּךְ הֶעֱלוּהוּ לַצַּד הָאַחֵר, שֶׁהֲרֵי הַצַּד הָאַחֵר נִזּוֹן מֵהַטִּנּוּךְ וְהַלִּכְלוּךְ הַזֶּה, וְעַל זֶה מַיִם אַחֲרוֹנִים חוֹבָה, וְחוֹבָה הֵם?!</p>\n<p>תָּמְהוּ וְלֹא יָכְלוּ לְדַבֵּר. אָמַר רַבִּי יְהוּדָה, בְּנִי, מַהוּ שֵׁם אָבִיךְ? שָׁתַק הַתִּינוֹק רֶגַע אֶחָד, עָמַד לִפְנֵי אִמּוֹ וְנָשַׁק לָהּ. אָמַר לָהּ, אִמִּי, עַל אַבּא שָׁאֲלוּ הַחֲכָמִים הַלָּלוּ, הַאִם אמַר לָהֶם? אָמְרָה לוֹ אִמּוֹ, בְּנִי, בָּדַקְתָּ אוֹתָם? אָמַר, הֲרֵי בָּדַקְתִּי וְלֹא מְצָאתִים כָּרָאוּי. לָחֲשָׁה לוֹ אִמּוֹ וְחָזַר אֲלֵיהֶם. אָמַר לָהֶם, אַתֶּם שְׁאַלְתֶּם עַל אַבָּא, וַהֲרֵי הִסְתַּלֵּק מֵהָעוֹלָם, וּבְכָל יוֹם שֶׁחֲסִידִים קְדוֹשִׁים הוֹלְכִים בַּדֶּרֶךְ, הוּא סוֹחֵר אַחֲרֵיהֶם. וְאִם אַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, אֵיךְ לֹא מְצָאתֶם אוֹתוֹ, הָלַךְ הַסּוֹחֵר אַחֲרֵיכֶם?</p>\n<p>אֲבָל בַּהַתְחָלָה רָאִיתִי בָכֶם, וְכָעֵת רָאִיתִי בָכֶם, שֶׁאַבָּא לֹא רָאָה חֲמוֹר שֶׁלֹּא (שיהיה) טָעַן אַחֲרָיו חֲמוֹר לִסְבֹּל עֹל הַתּוֹרָה. כֵּיוָן שֶׁלֹּא זְכִיתֶם שֶׁאַבָּא יִטְעַן אַחֲרֵיכֶם, לֹא אֹמַר לָכֶם מִיהוּ אַבָּא. אָמַר רַבִּי יְהוּדָה לְרַבִּי יִצְחָק, כְּנִדְמֶה לָנוּ, תִּינוֹק זֶה אֵינוֹ בֶּן אָדָם. אָכְלוּ, וְאוֹתוֹ תִּינוֹק הָיָה אוֹמֵר דִּבְרֵי תוֹרָה וְחִדּוּשֵׁי תוֹרָה. אָמְרוּ, הָבָה נְבָרֵךְ. אָמַר לָהֶם, נָאֶה אֲמַרְתֶּם, מִשּׁוּם שֶׁהַשֵּׁם הַקָּדוֹשׁ לֹא מִתְבָּרֵךְ בִּבְרָכָה זוֹ אֶלָּא בְּהַזְמָנָה.</p>\n<p>פָּתַח וְאָמַר, (תהלים לד) אֲבָרְכָה אֶת ה' בְּכָל עֵת וְגוֹ'. וְכִי מָה רָאָה דָוִד לוֹמַר אֲבָרְכָה אֶת ה'? אֶלָּא רָאָה דָוִד שֶׁצָּרִיךְ הַזְמָנָה, וְאָמַר אֲבָרְכָה. בִּגְלַל שֶׁבְּשָׁעָה שֶׁאָדָם יוֹשֵׁב עַל שֻׁלְחָנוֹ, הַשְּׁכִינָה עוֹמֶדֶת שָׁם, וְהַצַּד הָאַחֵר עוֹמֵד שָׁם. כְּשֶׁמְּזַמֵּן הָאָדָם לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַשְּׁכִינָה מִתְתַּקֶּנֶת (בהזמנה זו) לְגַבֵּי מַעְלָה לְקַבֵּל בְּרָכוֹת, וְהַצַּד הָאַחֵר מִתְכּוֹפֵף. (ואם נתקנת בברכות לגבי מעלה והצד האחר אינו בכלל) וְאִם לֹא מַזְמִין הָאָדָם לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַצַּד הָאַחֵר שׁוֹמֵעַ וּמְכַשְׁכֵּשׁ לִהְיוֹת לוֹ חֵלֶק בְּאוֹתָהּ בְּרָכָה.</p>\n<p>וְאִם תֹּאמַר, לָמָּה אֵין הַזְמָנָה בִּשְׁאָר הַבְּרָכוֹת? אֶלָּא אוֹתוֹ דְּבַר הַבְּרָכָה שֶׁמְּבָרְכִים עָלָיו, הוּא הַזְמָנָה. וּבֹא וּרְאֵה שֶׁכָּךְ זֶה, שֶׁזֶּה שֶׁמְּבָרֵךְ עַל הַפְּרִי, אוֹתוֹ פְּרִי הוּא הַזְמָנָה וּמְבָרְכִים עָלָיו, וְאֵין לוֹ חֵלֶק לַצַּד הָאַחֵר. וְקֹדֶם זֶה שֶׁהָיָה אוֹתוֹ פְּרִי בִּרְשׁוּת הַצַּד הָאַחֵר, לֹא מְבָרְכִים עָלָיו, וְכָתוּב (ויקרא יט) לֹא יֵאָכֵל, בִּשְׁבִיל שֶׁלֹּא יְבָרְכוּ עַל אוֹתוֹ הַפְּרִי וְלֹא יִתְבָּרֵךְ הַצַּד הָאַחֵר. כֵּיוָן שֶׁיָּצָא מֵרְשׁוּתוֹ, יֵאָכֵל, וּמְבָרְכִים עָלָיו. וְהִיא הַזְמָנָה לִבְרָכָה. וְכֵן כָּל דִּבְרֵי הָעוֹלָם שֶׁמְּבָרְכִים עֲלֵיהֶם, כֻּלָּם הַזְמָנָה לִבְרָכָה, וְאֵין בָּהֶם חֵלֶק לַצַּד הָאַחֵר.</p>\n<p>וְאִם תֹּאמַר, אַף כָּךְ לְבִרְכַּת זִמּוּן כּוֹס בְּרָכָה הָיְתָה הַזְמָנָה, מַדּוּעַ הָבָה וּנְבָרֵךְ? אֶלָּא הוֹאִיל וּבַתְּחִלָּה כְּשֶׁהָיָה שׁוֹתֶה אָמַר \"בּוֹרֵא פְּרִי הַגֶּפֶן\", הֲרֵי זֶה הָיָה הַזְמָנָה. וְכָעֵת לְבִרְכַּת הַמָּזוֹן צְרִיכִים שִׁנּוּי לְהַזְמָנָה אַחֶרֶת, שֶׁהֲרֵי כּוֹס זוֹ הוּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלֹא לַמָּזוֹן, וּמִשּׁוּם זֶה צָרִיךְ הַזְמָנַת הַפֶּה.</p>\n<p>וְאִם תֹּאמַר, נְבָרֵךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ זוֹהִי הַזְמָנָה, בָּרוּךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ זוֹהִי בְּרָכָה - כָּךְ זֶה בְּוַדַּאי. אֲבָל נְבָרֵךְ זוֹהִי הַזְמָנָה אַחֶרֶת, הַזְמָנָה שֶׁל בּוֹרֵא פְּרִי הַגֶּפֶן. (של הפה) שֶׁהַקּוֹדֶמֶת הִיא הַהַזְמָנָה לְכוֹס שֶׁל בְּרָכָה סְתָם. וְכוֹס זוֹ, כֵּיוָן שֶׁנָּטַל, הִיא הַזְמָנָה אַחֶרֶת בְּמִלַּת נְבָרֵךְ לְגַבֵּי עוֹלָם הָעֶלְיוֹן, שֶׁכָּל מְזוֹנוֹת וּבְרָכוֹת יוֹצְאוֹת מִשָּׁם. וּמִשּׁוּם זֶה הוּא בְּדֶרֶךְ נִסְתָּר, שֶׁעוֹלָם הָעֶלְיוֹן הוּא נִסְתָּר וְאֵין אֵלָיו הַזְמָנָה, אֶלָּא בְּדַרְגָּה זוֹ כּוֹס בְּרָכָה. (שבמלת נברך) אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקֵנוּ שֶׁמִּיּוֹם הָעוֹלָם עַד כָּעֵת לֹא שָׁמַעְנוּ דְבָרִים אֵלּוּ, וַדַּאי הֲרֵי אָמַרְנוּ שֶׁזֶּה אֵינוֹ בֶּן אָדָם.</p>\n<p>אָמַר לוֹ, בֵּן, מַלְאַךְ ה', אֲהוּבוֹ, מַה שֶּׁאָמַרְתָּ וְעָשִׂיתָ בְרִיחִם עֲצֵי שִׁטִּים חֲמִשָּׁה לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן וְגוֹ', וַחֲמִשָּׁה בְרִיחִם וְגוֹ', וַחֲמִשָּׁה בְרִיחִם לַיַּרְכָתַיִם יָמָּה - הֲרֵי הַרְבֵּה בְרִיחִים יֵשׁ כָּאן, וְיָדַיִם הֵם שְׁתַּיִם. אָמַר לוֹ, זֶהוּ שֶׁאָמַרְנוּ, מִפִּי הָאָדָם נִשְׁמָע מִיהוּ. אֲבָל הוֹאִיל וְלֹא הִשְׁגַּחְתֶּם - אֲנִי אֹמַר.</p>\n<p>פָּתַח וְאָמַר, (קהלת ב) הֶחָכָם עֵינָיו בְּרֹאשׁוֹ וְגוֹ'. וְכִי אֵיפֹה עֵינָיו שֶׁל הָאָדָם? אֶלָּא בְּרֹאשׁוֹ! שֶׁמָּא בְּגוּפוֹ אוֹ בִּזְרוֹעוֹ, שֶׁהוֹצִיא אֶת הֶחָכָם יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם?! אֶלָּא הַפָּסוּק כָּךְ הוּא בְּוַדַּאי. שֶׁלָּמַדְנוּ, לֹא יֵלֵךְ אָדָם בְּגִלּוּי רֹאשׁ אַרְבַּע אַמּוֹת. מָה הַטַּעַם? שֶׁשְּׁכִינָה שׁוֹרָה עַל רֹאשׁוֹ, וְכָל חָכָם עֵינָיו וּדְבָרָיו בְּרֹאשׁוֹ הֵם, בְּאוֹתוֹ שֶׁשּׁוֹרֶה וְעוֹמֵד עַל רֹאשׁוֹ.</p>\n<p>וּכְשֶׁעֵינָיו שָׁם, יֵדַע שֶׁאוֹתוֹ אוֹר שֶׁדּוֹלֵק עַל רֹאשׁוֹ צָרִיךְ שֶׁמֶן, מִשּׁוּם שֶׁגּוּף הָאָדָם הִיא פְּתִילָה, וְאוֹר דּוֹלֵק לְמַעְלָה, וּשְׁלֹמֹה הַמֶּלֶךְ צָוַח וְאָמַר: (שם ט) וְשֶׁמֶן עַל רֹאשְׁךְ אַל יֶחְסָר, שֶׁהֲרֵי הָאוֹר שֶׁבְּרֹאשׁוֹ צָרִיךְ שֶׁמֶן וְאוֹתָם מַעֲשִׂים טוֹבִים. וְלָכֵן הֶחָכָם עֵינָיו בְּרֹאשׁוֹ, וְלֹא בְמָקוֹם אַחֵר.</p>\n<p>אַתֶּם חֲכָמִים, וַדַּאי הַשְּׁכִינָה שׁוֹרָה עַל רָאשֵׁיכֶם, אֵיךְ לֹא הִשְׁגַּחְתֶּם לָזֶה? שֶׁכָּתוּב וְעָשִׂיתָ בְרִיחִם וְגוֹ', לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הָאֶחָד. וַחֲמִשָּׁה בְרִיחִם לְקַרְשֵׁי צֶלַע הַמִּשְׁכָּן הַשֵּׁנִית. הָאֶחָד וְהַשֵּׁנִית אָמַר הַפָּסוּק, שְׁלִישִׁית וּרְבִיעִית לֹא אָמַר הַפָּסוּק. שֶׁהֲרֵי אֶחָד וְשֵׁנִית נֶחְשָׁבִים לִשְׁנֵי צְדָדִים, וּמִשּׁוּם זֶה הַחֶשְׁבּוֹן בִּשְׁנֵי אֵלֶּה.</p>\n<p>בָּאוּ הֵם וּנְשָׁקוּהוּ. (כבתחלה) בָּכָה רַבִּי יְהוּדָה וְאָמַר, רַבִּי שִׁמְעוֹן, אַשְׁרֵי חֶלְקְךְ! אַשְׁרֵי הַדּוֹר! שֶׁהֲרֵי בִּזְכוּתְךְ אֲפִלּוּ תִּינוֹקוֹת שֶׁל בֵּית רַבָּן הֵם סְלָעִים רָמִים תַּקִּיפִים. בָּאָה אִמּוֹ. אָמְרָה לָהֶם, רַבּוֹתַי, בְּבַקָּשָׁה מִכֶּם אַל תַּשְׁגִּיחוּ עַל בְּנִי, אֶלָּא רַק בְּעַיִן טוֹבָה. אָמְרוּ לָהּ, אַשְׁרֵי חֶלְקֵךְ אִשָּׁה כְּשֵׁרָה, אִשָּׁה בְּרוּרָה מִכָּל שְׁאָר הַנָּשִׁים, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַר חֶלְקֵךְ וְהֵרִים דִּגְלֵךְ עַל כָּל שְׁאָר נְשׁוֹת הָעוֹלָם!</p>\n<p>אָמַר הַתִּינוֹק, אֲנִי לֹא פוֹחֵד מֵעַיִן רָעָה, שֶׁבֶּן דָּג גָּדוֹל וְנִכְבָּד אֲנִי, וְדָג לֹא פוֹחֵד מֵעַיִן רָעָה, שֶׁכָּתוּב (בראשית מח) וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ. מַה זֶּה לָרֹב? לִרְבּוֹת עַל הָעַיִן. וְשָׁנִינוּ, מַה דְּגֵי הַיָּם הַמַּיִם מְכַסִּים עֲלֵיהֶם וְאֵין עַיִן רָעָה וְכוּ'. לָרֹב וַדַּאי, בְּקֶרֶב הָאָרֶץ, בְּתוֹךְ בְּנֵי הָאָדָם עַל הָאָרֶץ. אָמְרוּ, בֵּן, מַלְאַךְ ה', אֵין בָּנוּ עַיִן רָעָה, וְלֹא מִצַּד עַיִן רָעָה בָּאנוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְכַסֶּה עָלֶיךְ בִּכְנָפָיו.</p>\n<p>פָּתַח וְאָמַר, (שם) הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע יְבָרֵךְ וְגוֹ'. פָּסוּק זֶה אָמַר יַעֲקֹב בְּרוּחַ הַקֹּדֶשׁ. אִם בְּרוּחַ הַקֹּדֶשׁ אָמַר אוֹתוֹ, סוֹד חָכְמָה יֵשׁ בּוֹ. הַמַּלְאָךְ, קוֹרֵא לוֹ מַלְאָךְ, וְקוֹרֵא לוֹ שֵׁמוֹת אֲחֵרִים. מַדּוּעַ נִקְרָא כָּאן מַלְאָךְ? אֶלָּא כְּשֶׁהוּא שָׁלִיחַ מִלְמַעְלָה וּמְקַבֵּל זֹּהַר מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁלְּמַעְלָה, (שאז) שֶׁכְּשֶׁמְּבָרְכִים אַבָּא וְאִמָּא לָזֶה, אוֹמְרִים לָהּ: בִּתִּי, לְכִי שִׁמְרִי בֵיתֵךְ! פִּקְדִי אֶת בֵּיתֵךְ! כָּךְ עֲשִׂי לְבֵיתֵךְ! לְכִי וְזוּנִי אוֹתָם. לְכִי, שֶׁאוֹתוֹ עוֹלָם שֶׁלְּמַטָּה מְחַכֶּה לָךְ, בְּנֵי בֵיתֵךְ מְחַכִּים לְמָזוֹן מִמֵּךְ! הֲרֵי לָךְ כָּל מַה שֶּׁתִּצְטָרְכִי לָתֵת לָהֶם. וְאָז הִיא מַלְאָךְ.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי בְּכַמָּה מְקוֹמוֹת נִקְרָא מַלְאָךְ, וְלֹא בָא לָזוּן עוֹלָמוֹת, וְעוֹד, שֶׁבְּשֵׁם זֶה לֹא זָן אֶת הָעוֹלָמוֹת, אֶלָּא בַשֵּׁם שֶׁל הַשֵּׁם - כָּךְ זֶה בְּוַדַּאי. כְּשֶׁשָּׁלִיחַ מִתּוֹךְ אַבָּא וְאִמָּא, נִקְרָא מַלְאָךְ. וְכֵיוָן שֶׁשּׁוֹרֶה עַל מְקוֹמוֹת, עַל שְׁנֵי כְרוּבִים, שְׁמוֹ ה'.</p>\n<p>כְּשֶׁנִּרְאָה לְמֹשֶׁה בַּתְּחִלָּה נִקְרָא מַלְאָךְ. לְיַעֲקֹב לֹא נִרְאָה כָּךְ, אֶלָּא בְדֻגְמָא, שֶׁכָּתוּב (שם כט) וְרָחֵל בָּאָה. זוֹ דְמוּת שֶׁל רָחֵל אַחֶרֶת, שֶׁכָּתוּב (ירמיה לא) כֹּה אָמַר ה' קוֹל בְּרָמָה נִשְׁמָע וְגוֹ', רָחֵל מְבַכָּה עַל בָּנֶיהָ. וְרָחֵל בָּאָה, סְתָם. עִם הַצּאן, הַדְּרָגוֹת שֶׁלָּהּ. אֲשֶׁר לְאָבִיהָ, וַדַּאי. וְכֻלָּם נִמְנוּ וְהִתְפַּקְּדוּ בְיָדֶיהָ. כִּי רֹעָה הִיא, הִיא מַנְהִיגָה אוֹתָם וּמֻפְקֶדֶת עֲלֵיהֶם.</p>\n<p>וְכָךָ כָּתוּב בְּמֹשֶׁה, (שמות ג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ. וְאִם תֹּאמַר שֶׁשֶּׁבַח אַבְרָהָם יוֹתֵר, שֶׁלֹּא כָתוּב בּוֹ מַלְאָךְ - אֶלָּא (בראשית יח) וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא וְגוֹ'. שָׁם בְּאַבְרָהָם נִרְאָה לוֹ אֲדנָי, בְּאָלֶ\"ף דָּלֶ\"ת, בִּגְלַל שֶׁבְּאוֹתוֹ זְמַן קִבֵּל בְּרִית. וּמַה שֶּׁעַד עַכְשָׁו הִתְכַּסָּה מִמֶּנּוּ, נִרְאָה לוֹ רִבּוֹן וְשַׁלִּיט, וְכָךְ נִרְאָה, שֶׁהֲרֵי אָז הִתְקַשֵּׁר בְּאוֹתָהּ דַּרְגָּה וְלֹא יוֹתֵר. וּמִשּׁוּם זֶה בְּשֵׁם שֶׁל אָדוֹן רִבּוֹן עָלָיו.</p>\n<p>אֲבָל מֹשֶׁה שֶׁלֹּא הָיָה בּוֹ פֵרוּד, שֶׁכָּתוּב (שמות ג) מֹשֶׁה מֹשֶׁה, שֶׁאֵין טַעַם מַפְסִיק, כְּמוֹ שֶׁכָּתוּב (בראשית כב) אַבְרָהָם אַבְרָהָם, שֶׁמַּפְסִיק הַטַּעַם, בִּגְלַל שֶׁכָּעֵת שָׁלֵם מַה שֶׁלֹּא הָיָה לִפְנֵי כֵן. יֵשׁ הֶפְרֵשׁ בֵּין אַבְרָהָם הַנּוֹכְחִי לְבֵין אַבְרָהָם שֶׁבַּתְּחִלָּה. אֲבָל מֹשֶׁה, מִיָּד שֶׁנּוֹלַד, אַסְפַּקְלַרְיָה הַמְּאִירָה הָיְתָה עִמּוֹ, שֶׁכָּתוּב (שמות ב) וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא. וְכָתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. מִיָּד נִקְשַׁר מֹשֶׁה בְּדַרְגָּתוֹ, וּמִשּׁוּם זֶה מֹשֶׁה מֹשֶׁה, וְלֹא מַפְסִיק הַטַּעַם.</p>\n<p>וְלָכֵן לְגַבֵּי מֹשֶׁה הִקְטִין עַצְמוֹ, שֶׁכָּתוּב מַלְאַךְ ה'. יַעֲקֹב קָרָא לוֹ בְשָׁעָה שֶׁהָיָה מִסְתַּלֵּק מִן הָעוֹלָם. מַלְאָךְ, מָה הַטַּעַם? מִשּׁוּם שֶׁבְּאוֹתָהּ שָׁעָה הָיָה יוֹרֵשׁ אוֹתָהּ לִשְׁלֹט. מֹשֶׁה בְּחַיָּיו. יַעֲקֹב לְאַחַר שֶׁהִסְתַּלֵּק מֵהָעוֹלָם. מֹשֶׁה בְּגוּף. יַעֲקֹב בְּרוּחַ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה.</p>\n<p>הַגֹּאֵל אֹתִי מִכָּל רָע, שֶׁלֹּא הִתְקָרֵב לְעוֹלָמִים לְצַד הָרָע, וְלֹא יָכֹל הָרָע לִשְׁלֹט בּוֹ. יְבָרֵךְ אֶת הַנְּעָרִים, אָז יַעֲקֹב הָיָה מְתַקֵּן אֶת בֵּיתוֹ כְּאָדָם שֶׁהוֹלֵךְ לְבַיִת חָדָשׁ וּמְתַקְּנוֹ בְתִקּוּנָיו וּמְקַשְּׁטוֹ בְקִשּׁוּטָיו. יְבָרֵךְ אֶת הַנְּעָרִים - אוֹתָם הַנּוֹדָעִים, אוֹתָם שֶׁנִּפְקְדוּ עַל הָעוֹלָם לִמְשֹׁךְ מֵהֶם בְּרָכוֹת, הֵם שְׁנֵי הַכְּרוּבִים. וְיִקָּרֵא בָהֶם שְׁמִי, כָּעֵת הִתְקִין בֵּיתוֹ, וְהוּא הִתְעַלָּה בְּדַרְגָּתוֹ, מִשּׁוּם שֶׁחִבּוּר הָיָה בְּיַעֲקֹב. הַגּוּף נִדְבַּק בְּמָקוֹם שֶׁהִצְטָרֵךְ, וּשְׁתֵּי זְרוֹעוֹת אִתּוֹ.</p>\n<p>לְאַחַר שֶׁאוֹתָם נְעָרִים מִתְבָּרְכִים כָּרָאוּי, אָז וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ. דֶּרֶךְ הַדָּגִים לְהִתְרַבּוֹת בְּתוֹךְ הַמַּיִם, וְאִם יוֹצְאִים מִתּוֹךְ הַמַּיִם לַיַּבָּשָׁה, מִיָּד מֵתִים. אֵלּוּ לֹא כָּךְ, אֶלָּא הֵם מֵהַיָּם הַגָּדוֹל, וּגְדֻלָּתָם לְהִתְרַבּוֹת וּלְהִתְגַּדֵּל בְּקֶרֶב הָאָרֶץ הִיא, מַה שֶּׁאֵין כָּךְ בְּכָל הַדָּגִים שֶׁבָּעוֹלָם.</p>\n<p>מַה כָּתוּב לְמַעְלָה? וַיְבָרֶךְ אֶת יוֹסֵף וַיֹּאמַר. וְלֹא מָצָאנוּ לוֹ כָּאן בְּרָכוֹת, שֶׁהֲרֵי אַחַר כָּךְ בֵּרְכוֹ, שֶׁכָּתוּב (שם מט) בֵּן פֹּרָת יוֹסֵף. אֶלָּא, כֵּיוָן שֶׁבֵּרַךְ אֶת הַנְּעָרִים הַלָּלוּ, בֵּרַךְ אֶת יוֹסֵף. שֶׁהֲרֵי לֹא יָכְלוּ לְהִתְבָּרֵךְ אֶלָּא מִתּוֹךְ יוֹסֵף, וּמִתּוֹךְ שֶׁהוּא נִסְתָּר וְלֹא נִרְאֶה בְגִלּוּי, כָּתוּב בְּנִסְתָּר - וְיִקָּרֵא בָהֶם שְׁמִי וְשֵׁם אֲבתַי. (לכסות עליו) מִן הָאָבוֹת מִתְבָּרְכִים, וְלֹא מִמָּקוֹם אַחֵר. בְּקֶרֶב הָאָרֶץ, זֶהוּ כִּסּוּי לְכַסּוֹת מַה שֶּׁצָּרִיךְ.</p>\n<p>בָּאוּ וְנָשְׁקוּ אוֹתוֹ כְּמִקֹּדֶם. אָמְרוּ, הָבָה וּנְבָרֵךְ. אָמַר הוּא, אֲנִי אֲבָרֵךְ, שֶׁכָּל מַה שֶּׁשְּׁמַעְתֶּם עַד כָּאן מִמֶּנִּי הָיָה, וַאֲקַיֵּם בִּי (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ. קוֹרְאִים בּוֹ יְבָרֵךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁנָּתַן מִלַּחְמוֹ לַדָּל. מִלֶּחֶם וְאֹכֶל שֶׁל הַתּוֹרָה שֶׁלִּי אֲכַלְתֶּם. אָמַר רַבִּי יְהוּדָה, בֵּן אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי שָׁנִינוּ בַּעַל הַבַּיִת בּוֹצֵעַ וְאוֹרֵחַ מְבָרֵךְ. אָמַר לוֹ, אֵינִי בַּעַל הַבַּיִת וְאֵינְכֶם אוֹרְחִים. אֲבָל מָצָאתִי פָסוּק וַאֲקַיְּמוֹ, שֶׁהֲרֵי אֲנִי בְּוַדַּאי טוֹב עַיִן, בְּלִי שְׁאֵלוֹתֵיכֶם אָמַרְתִּי עַד עַתָּה, וְלֶחֶם וְאֹכֶל שֶׁלִּי אֲכַלְתֶּם.</p>\n<p>לָקַח כּוֹס בְּרָכָה וּבֵרַךְ, וְיָדָיו לֹא יָכְלוּ לִסְבֹּל אֶת הַכּוֹס וְרָעֲדוּ. כְּשֶׁהִגִּיעַ לְעַל הָאָרֶץ וְעַל הַמָּזוֹן, אָמַר, (תהלים קטז) כּוֹס יְשׁוּעוֹת אֶשָּׂא וּבְשֵׁם ה' אֶקְרָא. עָמַד הַכּוֹס עַל תִּקּוּנוֹ, וְהִתְיַשֵּׁב בִּימִינוֹ וּבֵרַךְ. בַּסּוֹף אָמַר: יְהִי רָצוֹן שֶׁלְּאֶחָד מֵאֵלֶּה יִמָּשְׁכוּ לוֹ חַיִּים מִתּוֹךְ (המלך) עֵץ הַחַיִּים, שֶׁכָּל הַחַיִּים תְּלוּיִים בּוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יֶעֱרַב לוֹ, וְיִמְצָא עָרֵב לְמַטָּה שֶׁיַּסְכִּים בְּעַרְבוּתוֹ אֵצֶל הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>כֵּיוָן שֶׁבֵּרַךְ, סָתַם עֵינָיו רֶגַע אֶחָד, וְאַחַר כָּךְ פָּתַח אוֹתָם. אָמַר, חֲבֵרִים, שָׁלוֹם לָכֶם מֵרִבּוֹן הַטּוֹב שֶׁכָּל הָעוֹלָם שֶׁלּוֹ הוּא. תָּמְהוּ וּבָכוּ, וּבֵרְכוּהוּ. לָנוּ אוֹתוֹ לַיְלָה. בַּבֹּקֶר הִשְׁכִּימוּ וְהָלְכוּ. כְּשֶׁהִגִּיעוּ לְרַבִּי שִׁמְעוֹן סִפְּרוּ לוֹ אוֹתוֹ הַמַּעֲשֶׂה. תָּמַהּ רַבִּי שִׁמְעוֹן, אָמַר, בֶּן סֶלַע תַּקִּיף הוּא וְרָאוּי הוּא לְכָךְ, וְיוֹתֵר מִמַּה שֶּׁלֹּא חָשׁוּב בֶּן אָדָם, בְּנוֹ שֶׁל רַב הַמְנוּנָא סָבָא הוּא. הִזְדַּעֲזַע רַבִּי אֶלְעָזָר וְאָמַר, עָלַי לָלֶכֶת לִרְאוֹת אוֹתוֹ נֵר דּוֹלֵק. אָמַר רַבִּי שִׁמְעוֹן, זֶה לֹא עוֹלֶה בַשֵּׁם בָּעוֹלָם, שֶׁהֲרֵי דָּבָר עֶלְיוֹן יֵשׁ בּוֹ. וְסוֹד הוּא, שֶׁהֲרֵי אוֹר הַשֶּׁמֶן (ההמשכה) שֶׁל אָבִיו מֵאִיר עָלָיו, וְסוֹד זֶה לֹא מִתְפַּשֵּׁט בֵּין הַחֲבֵרִים.</p>\n<p>יוֹם אֶחָד הָיוּ הַחֲבֵרִים יוֹשְׁבִים וּמִתְנַגְּחִים אֵלֶּה בְאֵלֶּה, וְהָיוּ שָׁם רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי וּשְׁאָר הַחֲבֵרִים. אָמְרוּ, הֲרֵי כָּתוּב (דברים ב) אַל תָּצַר אֶת מוֹאָב וְאַל תִּתְגָּר בָּם מִלְחָמָה וְגוֹ'. בִּגְלַל רוּת וְנַעֲמָה שֶׁהָיוּ עֲתִידִים לָצֵאת מֵהֶם. צִפּוֹרָה אֵשֶׁת מֹשֶׁה שֶׁהָיְתָה מִמִּדְיָן, וְיִתְרוֹ וּבָנָיו שֶׁיָּצְאוּ מִמִּדְיָן, שֶׁהָיוּ כֻלָּם צַדִּיקֵי אֱמֶת, עַל אַחַת כַּמָּה וְכַמָּה. וְעוֹד מֹשֶׁה שֶׁגִּדְּלוּהוּ בְמִדְיָן, וְאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, (במדבר לא) נְקֹם נִקְמַת בְּנֵי יִשְׂרָאֵל מֵאֵת הַמִּדְיָנִים. אִם כָּךְ, מַשּׂוֹא פָנִים יֵשׁ בַּדָּבָר, שֶׁיּוֹתֵר רְאוּיִם בְּנֵי מִדְיָן לְהִנָּצֵל מִמּוֹאָב.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, לֹא דוֹמֶה מִי שֶׁעָתִיד לִלְקֹט תְּאֵנִים לְמִי שֶׁכְּבָר לִקֵּט אוֹתָן. אָמַר לוֹ רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁכְּבָר לִקֵּט לָהֶם, שֶׁבַח הוּא. אָמַר לוֹ, מִי שֶׁלֹּא לִקֵּט תְּאֵנִים, שׁוֹמֵר אֶת הַתְּאֵנָה תָּמִיד שֶׁלֹּא יִהְיֶה בָּהּ פְּגָם בִּשְׁבִיל הַתְּאֵנִים שֶׁעֲתִידָה לְהָבִיא. כֵּיוָן שֶׁלִּקֵּט תְּאֵנִים, עוֹזֵב אֶת הַתְּאֵנָה, וְיוֹתֵר לֹא שׁוֹמֵר אוֹתָהּ.</p>\n<p>כָּךָ מוֹאָב, שֶׁעֲתִידָה לְהָבִיא אוֹתָן תְּאֵנִים, שָׁמַר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב אַל תָּצַר אֶת מוֹאָב. מִדְיָן שֶׁנָּתַן כְּבָר תְּאֵנִים וְלִקְּטוּ אוֹתָן, כָּתוּב (במדבר כה) צָרוֹר אֶת הַמִּדְיָנִים. שֶׁהֲרֵי מִכָּאן וָהָלְאָה תְּאֵנָה זוֹ לֹא עֲתִידָה לְהָבִיא פֵרוֹת, וּמִשּׁוּם זֶה רְאוּיָה לִשְׂרֵפַת אֵשׁ. פָּתַח וְאָמַר, וַיֹּאמֶר מוֹאָב אֶל זִקְנֵי מִדְיָן וְגוֹ'. מוֹאָב הֵם מֻתָּרִים, וּמִשּׁוּם אוֹתָן תְּאֵנִים שֶׁעָתִיד מוֹאָב לְהוֹצִיא לָעוֹלָם נִצְּלוּ מֵעֹנֶשׁ.</p>\n<p>רַבִּי אֶלְעָזָר רָצָה לִרְאוֹת אֶת רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמִיו, וְהָיוּ הוֹלְכִים רַבִּי אַבָּא וְרַבִּי יוֹסֵי אִתּוֹ. הָלְכוּ בַדֶּרֶךְ, וְהָיוּ אוֹמְרִים דִּבְרֵי תוֹרָה כָּל אוֹתוֹ הַדֶּרֶךְ.</p>\n<p>אָמַר רַבִּי אַבָּא, מַה שֶּׁכָּתוּב (דברים ב) וַיֹּאמֶר ה' אֵלַי אַל תָּצַר אֶת מוֹאָב וְאַל תִּתְגָּר בָּם מִלְחָמָה וְגוֹ', וְכָתוּב (שם) וְקָרַבְתָּ מוּל בְּנֵי עַמּוֹן וְגוֹ' - דָּבָר זֶה כְּדָבָר זֶה. מַה הֶבְדֵּל בֵּין זֶה לָזֶה? אֶלָּא נִרְאֶה שֶׁשְּׁקוּלִים הָיוּ. וְשָׁנִינוּ, כְּשֶׁהָיוּ מִתְקָרְבִים לִבְנֵי מוֹאָב, הָיוּ יִשְׂרָאֵל נִרְאִים לִפְנֵיהֶם בְּכָל כְּלֵי קְרָב כְּשֶׁרָצוּ לְהִתְגָּרוֹת בָּהֶם. וּלְגַבֵּי בְּנֵי עַמּוֹן הָיוּ יִשְׂרָאֵל מְעֻטָּפִים בְּעִטּוּפֵיהֶם, וְלֹא נִרְאוּ כְלָל כְּלֵי קְרָב. וְהַפְּסוּקִים מוֹכִיחִים בְּשִׁקּוּל זֶה כָּזֶה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא. וְשָׁנִינוּ, שֶׁזּוֹ שֶׁהָיְתָה חֲצוּפָה וְאָמְרָה מוֹאָב, שֶׁכָּתוּב (בראשית יט) וַתִּקְרָא אֶת שְׁמוֹ מוֹאָב, נִרְאוּ יִשְׂרָאֵל חֲצוּפִים אֲלֵיהֶם כְּמוֹ שֶׁהִיא הָיְתָה חֲצוּפָה, שֶׁאָמְרָה מוֹאָב, מֵאָב הָיָה בֵּן זֶה. אֲבָל הַקְּטַנָּה שֶׁאָמְרָה בֶּן עַמִּי וְכִסְּתָה דְרָכֶיהָ, יִשְׂרָאֵל הָיוּ מְכַסִּים דַּרְכֵיהֶם אֲלֵיהֶם, מְעֻטָּפִים עִטּוּף הַטַּלִית, וְנִרְאִים לִפְנֵיהֶם כְּאַחִים מַמָּשׁ, וְכָךְ פֵּרְשׁוּהָ.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, נִזְכַּר רַבִּי אֶלְעָזָר בְּתִינוֹק זֶה. סָטוּ מֵהַדֶּרֶךְ שָׁלֹשׁ פַּרְסָאוֹת וְהִגִּיעוּ לְשָׁם. הִתְאָרְחוּ בְּאוֹתוֹ בַּיִת, נִכְנְסוּ וּמָצְאוּ אֶת אוֹתוֹ תִּינוֹק שֶׁהָיָה יוֹשֵׁב, וּמְתַקְּנִים לְפָנָיו שֻׁלְחָן. כֵּיוָן שֶׁרָאָה אוֹתָם, הִתְקָרֵב אֲלֵיהֶם. אָמַר לָהֶם, הִכָּנְסוּ חֲסִידִים קְדוֹשִׁים, הִכָּנְסוּ שְׁתִילֵי הָעוֹלָם, אוֹתָם שֶׁמְּשַׁבְּחִים אוֹתָם לְמַעְלָה וּלְמַטָּה, אוֹתָם שֶׁאֲפִלּוּ הַדָּגִים שֶׁבַּיָּם הַגָּדוֹל יוֹצְאִים אֲלֵיהֶם לַיַּבָּשָׁה. בָּא רַבִּי אֶלְעָזָר וּנְשָׁקוֹ בְרֹאשׁוֹ. חָזַר כְּמִקֹּדֶם וּנְשָׁקוֹ בְפִיו. אָמַר רַבִּי אֶלְעָזָר, נְשִׁיקָה רִאשׁוֹנָה עַל הַדָּגִים שֶׁעָזְבוּ אֶת הַמַּיִם וְהָלְכוּ לַיַּבָּשָׁה, וּנְשִׁיקָה שְׁנִיָּה עַל בֵּיצֵי הַדָּגִים שֶׁעָשׂוּ פְרִי טוֹב בָּעוֹלָם.</p>\n<p>אָמַר אוֹתוֹ תִּינוֹק, בְּרֵיחַ לְבוּשְׁכֶם רָאִיתִי שֶׁעַמּוֹן וּמוֹאָב מִתְגָּרִים בָּכֶם. אֵיךְ נִצַּלְתֶּם מֵהֶם? כְּלֵי קְרָב לֹא הָיוּ בִידֵיכֶם. וְאִם לֹא, לְבִטְחָה תֵּלְכוּ בְּלִי פַחַד. תָּמְהוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְהַחֲבֵרִים. אָמַר רַבִּי אַבָּא, אַשְׁרֵי הַדֶּרֶךְ הַזּוֹ וְאַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לִרְאוֹת אֶת זֶה. הַתְקִינוּ שֻׁלְחָן כְּמִקֹּדֶם.</p>\n<p>אָמַר, חֲכָמִים קְדוֹשִׁים, תִּרְצוּ לֶחֶם תַּפְנוּקִים לְלֹא קְרָב (או לחם קרב ושלחן של כלי קרב) וְשֻׁלְחָן שֶׁל כְּלֵי קְרָב, אוֹ לֶחֶם קְרָב, אוֹ תִרְצוּ לְבָרֵךְ לַמֶּלֶךְ בְּכָל כְּלֵי הַקְּרָב, שֶׁהֲרֵי הַשֻּׁלְחָן לֹא עוֹלֶה בְּלִי קְרָב? אָמַר רַבִּי אֶלְעָזָר, בֵּן אָהוּב חָבִיב קָדוֹשׁ, כָּךְ אָנוּ רוֹצִים, בְּכָל הַמִּינִים שֶׁל הַקְּרָב הָאֵלֶּה הִשְׁתַּדַּלְנוּ בָהֶם, וְיוֹדְעִים אָנוּ לַעֲרֹךְ בְּחֶרֶב וּבְקֶשֶׁת וּבְרֹמַח וּבְאַבְנֵי בְלִיסְטְרָאוֹת, וְאַתָּה תִּינוֹק עוֹד לֹא רָאִיתָ אֵיךְ עוֹרְכִים קְרָב גְּבָרִים חֲזָקִים שֶׁל הָעוֹלָם.</p>\n<p>שָׂמַח אוֹתוֹ תִּינוֹק, אָמַר, וַדַּאי שֶׁלֹּא רָאִיתִי, אֲבָל כָּתוּב (מלכים א כ) אַל יִתְהַלֵּל חוֹגֵר כִּמְפַתֵּחַ. הַתְקִינוּ שֻׁלְחָן בְּלֶחֶם וּבְכָל מַה שֶּׁצָּרִיךְ. אָמַר רַבִּי אֶלְעָזָר, כַּמָּה שִׂמְחָה יֵשׁ בְּלִבִּי בְּתִינוֹק זֶה, וְכַמָּה חִדּוּשִׁים יִתְחַדְּשׁוּ עַל שֻׁלְחָן זֶה, וְלָכֵן אָמַרְתִּי שֶׁיָּדַעְתִּי שֶׁזּוּג פַּעֲמוֹנֵי רוּחַ הַקֹּדֶשׁ הָיוּ הוֹלְכִים בָּהּ.</p>\n<p>אָמַר אוֹתוֹ תִּינוֹק, מִי שֶׁרוֹצֶה לֶחֶם עַל פִּי הַחֶרֶב - יֹאכַל. שָׂמַח רַבִּי אֶלְעָזָר, חָזַר וְקֵרַב הַתִּינוֹק אֵלָיו, אָמַר לוֹ, מִשּׁוּם שֶׁשִּׁבַּחְתָּ עַצְמְךְ, אַתָּה צָרִיךְ לַעֲרֹךְ קְרָב בַּתְּחִלָּה, וַאֲנִי אָמַרְתִּי בַּתְּחִלָּה, שֶׁהַקְּרָב יִהְיֶה אַחֲרֵי הָאֲכִלָה. אֲבָל כָּעֵת, מִי שֶׁרוֹצֶה סֹלֶת, תּוֹלֶה (יביא) כְּלֵי הַקְּרָב בְּיָדָיו. אָמַר רַבִּי אֶלְעָזָר, לְךְ רָאוּי לְהַרְאוֹת מֵאוֹתָם כְּלֵי הַקְּרָב שֶׁלְּךְ.</p>\n<p>פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, (במדבר טו) וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ תָּרִימוּ תְרוּמָה לַה'. פָּסוּק זֶה נֶאֱמַר עַל עֹמֶר הַתְּנוּפָה. אֵיזוֹ תְנוּפָה? אִם בִּגְלַל שֶׁהֱנִיפָהּ הַכֹּהֵן לְמַעְלָה, הִיא תְּנוּפָה. מָה אִכְפַּת לָנוּ אִם הֵנִיף אוֹ הִנְמִיךְ?</p>\n<p>אֶלָּא וַדַּאי צָרִיךְ לַהֲרִימָהּ לְמַעְלָה, וְהַיְנוּ תְּרוּמָה. וְאַף עַל גַּב שֶׁדָּרַשְׁנוּ שְׁנַיִם מִמֵּאָה וְכָךְ זֶה, אֲבָל תְּנוּפָה מַהִי הֲרָמָה (זו) ? וְסוֹד חָכְמָה כָּאן. אִי חֲסִידִים קְדוֹשִׁים, בַּעֲלֵי רְמָחִים, לֹא שִׁמַּשְׁתֶּם אֶת רַבִּי שְׁמַעְיָה הֶחָסִיד, שֶׁאִם לֹא תֵדְעוּ מַהִי תְנוּפָה, מַהִי חִטָּה, מַהִי שְׂעוֹרָה.</p>\n<p>תְּנוּפָה שֶׁאָמַרְנוּ, הַיְנוּ תְּנ\"וּ פֶ\"ה. וְסוֹד שֶׁלּוֹ - (ירמיה יג) תְּנוּ כָבוֹד לַה' אֱלֹהֵיכֶם. שֶׁהֲרֵי פֶּה הַיְנוּ כָבוֹד שֶׁרוֹצִים לָתֵת לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלָכֵן צְרִיכִים לְהָרִים לְמַעְלָה, לְהַרְאוֹת (שאינם נותנים אלא לפה הזה) שֶׁאָנוּ נוֹתְנִים שֶׁלּוֹ לַפֶּה הַזֶּה. שֶׁאֵין שֶׁבַח לַמֶּלֶךְ הָעֶלְיוֹן אֶלָּא כְּשֶׁיִּשְׂרָאֵל מְתַקְּנִים לוֹ לַכָּבוֹד הַזֶּה וְנוֹתְנִים כָּבוֹד לַמֶּלֶךְ. וְזֶהוּ תְּנוּ פֶה, תְּנוּ כָבוֹד, וַהֲרָמָה הִיא בְּוַדַּאי.</p>\n<p>הַפָּסוּק שֶׁהִתְחַלְנוּ - וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ. וְכִי לֶחֶם הָאָרֶץ הִיא שְׂעוֹרָה? לֹא כָּךְ. וְאָנוּ מַקְרִיבִים שְׂעוֹרָה מִשּׁוּם שֶׁשְּׂעוֹרָה קָדְמָה לִשְׁאָר הַלֶּחֶם שֶׁבָּעוֹלָם. שְׂעוֹרָה הוּא (שעור ה\"א, שהרי מקום) שְׂעוֹרָה שֶׁל הֵ\"א יָדוּעַ הוּא בַּשִּׁעוּר שֶׁל הֵ\"א. (חטה בה\"א נקודה וכו') חִטָּה נְקוּדָה בָּאֶמְצַע, שֶׁאֵין חֵלֶק לַצַּד הָאַחֵר שֶׁחֵטְא שָׁם. (אלא) חִטָּה בַּת שֶׁמִּתְחַטֵּאת לִפְנֵי אָבִיהָ וְעוֹשֶׂה רְצוֹנָהּ. וּמַה חִטָּה? כְּלַל עֶשְּׂרִים וּשְׁתַּיִם אוֹתִיּוֹת.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁהָיָה לָנוּ לִשְׁמֹעַ, כָּאן יֵשׁ לָנוּ לוֹמַר וְלִדְרֹךְ קֶשֶׁת. אָמַר אוֹתוֹ תִּינוֹק, הֲרֵי מָגֵן מוּל הַחֵץ. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי חִטָּה כָּךְ קוֹרְאִים לָהּ. אֲבָל רָאִינוּ שֶׁבַּשְּׁבָטִים כֻּלָּם אֵין חֵ\"ט, וּבָהּ יֵשׁ חֵ\"ט, וְקוֹרְאִים חִטָּה. אָמַר אוֹתוֹ תִּינוֹק, וַדַּאי כָּךְ זֶה, שֶׁהֲרֵי חֵ\"ט חוֹנֶה סָמוּךְ לָהּ. בַּשְּׁבָטִים אֵין הָאוֹתִיּוֹת הָאֵלּוּ, שֶׁהֲרֵי בָּאוּ מִצַּד קְדֻשָּׁה הָעֶלְיוֹנָה, אֲבָל אֵלֶיהָ יֵשׁ.</p>\n<p>וְאִם תִּרְצֶה לְהוֹצִיא חֶרֶב וְתֹאמַר לָמָּה נָקְטָה אוֹתִיּוֹת אֵלּוּ הַבַּת הַזּוֹ, אֶלָּא אִם תֵּדַע חֵטְא אָדָם הָרִאשׁוֹן שֶׁאָמְרוּ חִטָּה הָיָה, תֵּדַע זֶה. וְעֵץ זֶה כְּשֶׁנָּצַח, הַכֹּל צַד הַטּוֹב נָקַט לְכָל הַצַּד הָאַחֵר, וְכוֹפֵף אוֹתוֹ.</p>\n<p>הַחֲבֵרִים הָרִאשׁוֹנִים פֵּרְשׁוּ דָבָר זֶה וְשָׂמוּ אוֹתָהּ מֵרָחוֹק, חִטָּה סְתָם. בָּאוּ אַחֲרוֹנִים וְאָמְרוּ חִטָּה מַמָּשׁ. בָּא יְשַׁעְיָה וּפֵרְשָׁהּ, שֶׁכָּתוּב (ישעיה נד) וּמִמְּחִתָּה כִּי לֹא תִקְרַב אֵלָיִךְ. וְלָכֵן נְקוּדָה בָּאֶמְצַע, שֶׁלֹּא תִהְיֶה חַטָּאָה. שֶׁאִלּוּ לֹא הָיְתָה נְקוּדָה, תִּהְיֶה חַטָּאָה. וְחִלּוּף בֵּין ט' לְת' שָׁבְרוּ אֶת הַצַּד הָאַחֵר, בֵּרוּר (שלה) שֶׁל הַדָּבָר.</p>\n<p>אַתֶּם הַחֲבֵרִים, שֶׁלֹּא שִׁמַּשְׁתֶּם אֶת רַבִּי שְׁמַעְיָה הֶחָסִיד, אוֹמְרִים שֶׁבַּחֲמֵשֶׁת מִינֵי דָגָן אֵין חֵלֶק לַצַּד הָאַחֵר. וְלֹא כָּךְ, שֶׁהֲרֵי כָּל מַה שֶּׁנִּבְלֶה בָאָרֶץ יֵשׁ בּוֹ חֵלֶק לַצַּד הָאַחֵר, וּמַהוּ חֶלְקוֹ? מוֹץ שֶׁתִּדְּפֶנּוּ רוּחַ, שֶׁכָּתוּב (תהלים א) לֹא כֵן הָרְשָׁעִים כִּי אִם כַּמֹּץ אֲשֶׁר תִּדְּפֶנּוּ רוּחַ, וְזוֹהִי רוּחַ שֶׁל קְדֻשָּׁה. וְכָתוּב (שם קג) כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ וְגוֹ'. מִשּׁוּם שֶׁרוּחַ הַקֹּדֶשׁ מְפַזַּרְתּוֹ בְּכָל צִדְדֵי הָעוֹלָם שֶׁלֹּא יִמָּצֵא. זֶה בַּנְּקֵבָה. הַזָּכָר מַהוּ? תֶּבֶן.</p>\n<p>וּמוֹץ וְתֶבֶן הוֹלְכִים כְּאֶחָד, וְלָכֵן פָּטוּר מִמַּעֲשֵׂר, שֶׁאֵין בּוֹ חֵלֶק בַּקְּדֻשָּׁה. ה' - דָּגָן בְּנִקָּיוֹן (של דגן) בְּלִי תֶבֶן וּמוֹץ. ח\"ט - זָכָר וּנְקֵבָה, מוֹץ וְתֶבֶן. ה' בְּנִקְיוֹן הַדָּגָן. וְלָכֵן שְׁלֵמוּת הָעֵץ הוּא חִטָּה, וְהָעֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן הָיָה חִטָּה, שֶׁהַכֹּל הוּא בְּסוֹד, וּבִדְבַר חִטָּה. (בקדשה ה' נקיון הדגן בלי תבן ומוץ, ועל זה שלמות האילן הוא חטה, והכל הואבסוד החטה) תָּמַהּ רַבִּי אֶלְעָזָר וְתָמְהוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ זֶה.</p>\n<p>אָמַר אוֹתוֹ תִּינוֹק, כָּךְ זֶה בְּוַדַּאי הַפָּסוּק שֶׁהָיִינוּ שְׁרוּיִים בּוֹ, שֶׁהֲרֵי שְׂעוֹרָה קָדְמָה לָבֹא לָעוֹלָם, וְהִיא מְתֻקֶּנֶת לְמַאֲכַל בְּהֵמָה סְתָם. הִיא סוֹד אֶלֶף הָרִים שֶׁמְּגַדְּלִים בְּכָל יוֹם, וְהִיא אוֹכֶלֶת אוֹתָם. וְנִקְרֵאת לֶחֶם תְּרוּמָה, אֹכֶל שֶׁל אוֹתָהּ תְּרוּמָה, (ונקצרת) וְנִקְרֶבֶת בַּלַּיְלָה, שֶׁהֲרֵי כָּתוּב (ויקרא כב) וּבָא הַשֶּׁמֶשׁ וְטָהֵר וְאַחַר יֹאכַל מִן הַקְּדָשִׁים כִּי לַחְמוֹ הוּא. מִן הַקְּדָשִׁים - זוֹ תְרוּמָה. מִן הַקְּדָשִׁים וְלֹא קָדָשִׁים, שֶׁהֲרֵי קֹדֶשׁ סְתָם לֹא נִקְרָא תְרוּמָה, שֶׁחֹמֶר בַּקֹּדֶשׁ מִבַּתְּרוּמָה לָמַדְנוּ.</p>\n<p>אֶרֶץ הַקְּדוֹשָׁה בִּרְשׁוּת הַקָּדוֹשׁ בָּרוּךְ הוּא הָיְתָה, וְרָשׁוּת אַחֶרֶת לֹא נִכְנְסָה לְשָׁם. אֵיךְ נִבְדֶּקֶת הָאָרֶץ אִם עוֹמֶדֶת בֶּאֱמוּנָה וְלֹא הִתְחַבְּרָה בְרָשׁוּת אַחֶרֶת? בְּהַקְרָבַת תְּרוּמָה זוֹ שֶׁל שְׂעוֹרִים, כְּמוֹ סוֹד הַסּוֹטָה. אָמַר רַבִּי אַבָּא, וַדַּאי שְׁנִינוּת הַחֶרֶב אֵלֶיךְ. אָמַר אוֹתוֹ תִּינוֹק, וַדַּאי הִתְחַזַּקְתִּי בְּמָגֵן וְצִנָּה לְהִתְגּוֹנֵן מִמֶּנּוּ. אָמַר רַבִּי אַבָּא, בָּאָרֶץ הַקְּדוֹשָׁה אֵין רָשׁוּת אַחֶרֶת וְלֹא נִכְנֶסֶת לְשָׁם. מוֹץ וְתֶבֶן מִמָּה הָיוּ?</p>\n<p>פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ וְגוֹ'. וְכָתוּב וַיֹּאמֶר לָהֶם אֱלֹהִים פְּרוּ וּרְבוּ. וְכִי אִם לֹא שֶׁבָּא נָחָשׁ עַל חַוָּה, לֹא יַעֲשֶׂה תוֹלָדוֹת לָעוֹלָם?! אוֹ אִם לֹא חָטְאוּ יִשְׂרָאֵל בְּחֵטְא הָעֵגֶל, לֹא יַעֲשׂוּ תוֹלָדוֹת?! אֶלָּא וַדַּאי אִם לֹא יָבֹא נָחָשׁ עַל חַוָּה, יַעֲשֶׂה אָדָם תּוֹלָדוֹת מִיָּד וַדַּאי, שֶׁהֲרֵי נִגְזְרָה גְזֵרָה מִיָּד שֶׁנִּבְרָא, שֶׁכָּתוּב פְּרוּ וּרְבוּ וּמִלְאוּ אֶת הָאָרֶץ. וְאוֹתָם תּוֹלָדוֹת הָיוּ כֻלָּם בְּנִקָּיוֹן לְלֹא זֻהֲמָה כְּלָל. גַּם כָּךְ הָאָרֶץ הַקְּדוֹשָׁה, שֶׁהֲרֵי לֹא נִכְנְסָה בָּהּ רָשׁוּת אַחֶרֶת, יֵשׁ בָּהּ מוֹץ וְתֶבֶן שֶׁלֹּא מֵאוֹתוֹ הַצַּד. וּמִחוּץ לָאָרֶץ אוֹתוֹ מוֹץ וְתֶבֶן מִצַּד אַחֵר הוּא, שֶׁהוֹלְכִים אַחַר קְדֻשָּׁה כְּקוֹף אַחֲרֵי בְּנֵי אָדָם.</p>\n<p>בָּאוּ רַבִּי אֶלְעָזָר וְהַחֲבֵרִים וּנְשָׁקוּהוּ. אָמַר לוֹ, נִדְמֶה לִי שֶׁהִרְוַחְנוּ בִּכְלֵי הַקְּרָב לֶחֶם הַשֻּׁלְחָן. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ זֶה, שֶׁהֲרֵי כָּל מִינֵי קְרָב הֵם בְּיָדְךְ וּמַצְלִיחִים בְּיָדְךְ. בָּאוּ וּנְשָׁקוּהוּ כְּמִקֹּדֶם.</p>\n<p>פָּתַח הוּא וְאָמַר, (שם מ) וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם וְגוֹ'. עַד כָּאן חֶזְיוֹן הַדָּבָר, שֶׁהֲרֵי מִכָּאן וָהָלָה חֶזְיוֹנוֹ הָיָה, שֶׁכָּתוּב וְכוֹס פַּרְעֹה בְּיָדִי. אֲבָל חֶזְיוֹן הַדָּבָר הָיָה בִּגְלַל יוֹסֵף וּלְבַשְּׂרוֹ, שֶׁיִּשְׁמַע יוֹסֵף וְיֵדַע.</p>\n<p>שָׁנִינוּ, שִׁבְעָה רְקִיעִים הֵם, וְהֵם (שבעה) הֵיכָלוֹת. וְשִׁשָּׁה הֵם, וַחֲמִשָּׁה הֵם, וְכֻלָּם יוֹצְאִים מִתּוֹךְ יַיִן עַתִּיק עֶלְיוֹן. אוֹתוֹ יַיִן מְשָׁכוֹ יַעֲקֹב מֵרָחוֹק, וּסְחָטוֹ מֵעִנְבֵי אוֹתָהּ הַגֶּפֶן. אָז יַעֲקֹב הִמְשִׁיךְ אוֹתוֹ יַיִן שֶׁנִּרְאָה לוֹ, וְשָׂמַח וְשָׁתָה. זֶהוּ שֶׁכָּתוּב (שם כז) וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ. כָּאן נִכְלָל לְמַעְלָה וּלְמַטָּה. וְלָכֵן הִרְחִיק הַדָּבָר וּמְשָׁכוֹ בִמְשִׁיכוּת שְׁתֵּי תְנוּעוֹת, וְהַיְנוּ לוֹ. לוֹ לְמַטָּה, לוֹ לְמַעְלָה. (בשני צדדים אחז).</p>\n<p>חֲנוֹךָ מְטַטְרוֹן אָמַר, וַיָּבֵא לוֹ יַיִן - שֶׁשָּׂם מַיִם בְּאוֹתוֹ יַיִן. אִם לֹא יָשִׂים בּוֹ מַיִם, לֹא יָכוֹל לִסְבֹּל, וְנָאֶה אָמַר חֲנוֹךְ מְטַטְרוֹן. וּמִשּׁוּם זֶה הִמְשִׁיכוֹ בִּשְׁנֵי טְעָמִים, שֶׁהֲרֵי בִּשְׁנֵי צְדָדִים אָחוּז, וְאוֹתוֹ יַיִן הָלַךְ מִדַּרְגָּה לְדַרְגָּה, וְכָל הַטְּעָמִים בּוֹ, עַד שֶׁיּוֹסֵף הַצַּדִּיק טָעַם אוֹתוֹ, שֶׁהוּא דּוֹד נֶאֱמָן. זֶהוּ שֶׁכָּתוּב (שיר השירים ז) כְּיֵין הַטּוֹב הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים. מַהוּ כְּיֵין הַטּוֹב? שֶׁבָּא יַעֲקֹב וְשָׂם בּוֹ מַיִם. זֶהוּ יֵין הַטּוֹב וְכָךְ זֶה, כְּמוֹ שֶׁאָמַר חֲנוֹךְ מְטַטְרוֹן. תָּמַהּ רַבִּי אֶלְעָזָר וְתָמַהּ רַבִּי אַבָּא. אָמְרוּ, הֲרֵי הַיַּיִן (ס\"י מלאך) שֶׁלְּךְ הוּא נִצַּח מַלְאָךְ קָדוֹשׁ עַל פִּי (פה) רוּחַ הַקֹּדֶשׁ.</p>\n<p>אָמַר לוֹ, עַד עַתָּה אוֹתָהּ גֶּפֶן מְחַכָּה לַעֲשׂוֹת פֵּרוֹת. וּבַגֶּפֶן - זוֹהִי גֶפֶן הַנּוֹדַעַת בַּקֹּדֶשׁ. מִשּׁוּם שֶׁיֵּשׁ גֶּפֶן אַחֶרֶת שֶׁנִּקְרֵאת גֶּפֶן נָכְרִיָּה, וַעֲנָבֶיהָ אֵינָם עֲנָבִים, אֶלָּא קָשִׁים, אוֹחֲזִים הַלֵּב, נוֹשְׁכִים כַּכֶּלֶב. אוֹתָם עֲנָבִים נִקְרָאִים (ירמיה ב) סוּרֵי הַגֶּפֶן נָכְרִיָּה. אֲבָל גֶּפֶן זוֹ, עָלֶיהָ כָּתוּב וּבַגֶּפֶן, אוֹתָהּ הַיְדוּעָה, אוֹתָהּ שֶׁכָּל הַקְּדוֹשִׁים טָעֲמוּ יַיִן עַתִּיק, יַיִן טוֹב, יַיִן שֶׁיַּעֲקֹב נָתַן בּוֹ מַיִם, עַד שֶׁכָּל אֵלּוּ שֶׁיּוֹדְעִים לִטְעֹם טָעֲמוּ אוֹתוֹ, וְהָיָה טוֹב לַחֵךְ.</p>\n<p>וְאוֹתָהּ גֶּפֶן, כְּשֶׁמַּגִּיעַ אֵלֶיהָ, מוֹשִׁיטָה שְׁלֹשָׁה שָׂרִיגִים, וְהֵם שְׁלֹשׁ דְּמֻיּוֹת הָאָבוֹת שֶׁהִתְקַדְּשָׁה בָהֶם, וְאֵין קְדֻשָּׁה אֶלָּא בְּיַיִן, וְאֵין בְּרָכָה אֶלָּא בְּיַיִן, בְּמָקוֹם שֶׁיֵּשׁ חֶדְוָה. וְהִיא כְפֹרַחַת, כְּמוֹ כַלָּה שֶׁמִּתְקַשֶּׁטֶת וְנִכְנֶסֶת בְּאַהֲבָה, בְּחֶדְוַת אוֹתוֹ יַיִן שֶׁהִתְעָרֵב בְּמַיִם, וְאָז עָלְתָה נִצָּהּ, עוֹלָה אַהֲבָתָהּ לְדוֹדָהּ וְשׁוֹרָה לְנַגֵּן וּלְהִכָּנֵס בְּאַהֲבָה, וְאָז מִתְמַלְּאִים וּמִתְבַּשְּׁלִים אוֹתָם עֲנָבִים, רַכּוֹת וּמְלֵאוֹת מֵאוֹתוֹ יַיִן טוֹב עַתִּיק, יַיִן שֶׁיַּעֲקֹב שָׂם בּוֹ מַיִם.</p>\n<p>וְעַל זֶה מִי שֶׁמְּבָרֵךְ עַל הַיַּיִן וּמַגִּיעִים עַל הָאָרֶץ, צָרִיךְ לָשִׂים בּוֹ מַיִם, בִּגְלַל שֶׁאֵין לוֹ לְבָרֵךְ רַחֵם ה' עַל יִשְׂרָאֵל עַמָּךְ, פְּרָט לְמַיִם תּוֹךְ הַיַּיִן. וְאִם לֹא, מִי יָכוֹל לִסְבּל? זֶה הָיָה לְבַשֵּׂר לְיוֹסֵף, מִשּׁוּם שֶׁבּוֹ הָיָה הַדָּבָר תָּלוּי.</p>\n<p>חֲנוֹךָ מְטַטְרוֹן אָמַר, שְׁלֹשָׁה שָׂרִיגִם בְּוַדַּאי, כְּנֶגֶד שְׁלֹשֶׁת הָאָבוֹת. וַהֲרֵי אַרְבָּעָה הֵם שֶׁלָּהּ? אֶלָּא זֶהוּ שֶׁכָּתוּב וְהִיא כְפֹרַחַת. בִּזְמַן שֶׁהִיא עוֹלָה וּפוֹרַחַת בִּכְנָפֶיהָ לַעֲלוֹת, אָז עָלְתָה נִצָּהּ. זֶהוּ אוֹתוֹ רְבִיעִי שֶׁנִּשְׁאָר, שֶׁעוֹלֶה אִתָּהּ וְלֹא נִפְרָד מִמֶּנָּה. זֶהוּ שֶׁכָּתוּב (שמואל ב כב) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף. כְּשֶׁיָּעוּף כְפֹרַחַת, בִּזְמַן שֶׁפּוֹרַחַת. וְנָאֶה אָמַר חֲנוֹךְ מְטַטְרוֹן, וְכָךְ זֶה.</p>\n<p>תָּמַהּ רַבִּי אֶלְעָזָר וְתָמַהּ רַבִּי אַבָּא. אָמְרוּ, מַלְאָךְ קָדוֹשׁ, שָׁלִיחַ מִלְמַעְלָה, הֲרֵי יֵינְךְ הוּא נִצַּחְתָּ בְּסוֹד רוּחַ הַקֹּדֶשׁ. בָּאוּ כָּל הַחֲבֵרִים וּנְשָׁקוּהוּ. אָמַר רַבִּי אֶלְעָזָר, בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן.</p>\n<p>אָמַר אוֹתוֹ תִּינוֹק, חֲבֵרִים, לֶחֶם וְיַיִן עִקַּר הַשֻּׁלְחָן הֵם. כָּל שְׁאָר הַמַּאֲכָלִים נִמְשָׁכִים אַחֲרֵיהֶם. וְהַתּוֹרָה הִרְוִיחָה אוֹתָם, וְשֶׁלָּהּ הֵם. הַתּוֹרָה רוֹצָה מִכֶּם בְּבַקָּשָׁה, בְּאַהֲבָה, וְאוֹמֶרֶת, (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. וְהוֹאִיל וְהַתּוֹרָה מְזֻמֶּנֶת לָכֶם וְהִיא רוֹצֶה מִכֶּם דָּבָר זֶה, יֵשׁ לָכֶם לַעֲשׂוֹת אֶת רְצוֹנָהּ. (הוא) בְּבַקָּשָׁה מִכֶּם, הוֹאִיל וְהִיא מְזֻמֶּנֶת לָכֶם, שֶׁתַּעֲשׂוּ רְצוֹנָהּ. אָמְרוּ, כָּךְ זֶה בְּוַדַּאי. יָשְׁבוּ וְאָכְלוּ וְשָׂמְחוּ אִתּוֹ. כֵּיוָן שֶׁאָכְלוּ, הִתְעַכְּבוּ עַל הַשֻּׁלְחָן.</p>\n<p>פָּתַח הוּא וְאָמַר, וַיֹּאמֶר מוֹאָב אֶל זִקְנֵי מִדְיָן וְגוֹ'. וַיּאמְרוּ זִקְנֵי מוֹאָב וְאֶל זִקְנֵי מִדְיָן לֹא כָתוּב, אֶלָּא וַיֹּאמֶר מוֹאָב. עֲלָמִים לָקְחוּ עֵצָה מִסָּבִים, וְהַסָּבִים נִמְשְׁכוּ אַחֲרֵיהֶם, וְהֵם נָתְנוּ לָהֶם עֵצָה. אֵיזוֹ עֵצָה נָתְנוּ לָהֶם? עֵצָה רָעָה לָקְחוּ לְעַצְמָם. אָמְרוּ לָהֶם לְמוֹאָב: גִּדּוּל רָע גִּדַּלְנוּ בֵינֵינוּ. וּמִיהוּ? מֹשֶׁה רַבָּם. עַל כֹּמֶר אֶחָד שֶׁהָיָה בֵּינֵינוּ, שֶׁגִּדְּלוֹ וְהִגְדִּילוֹ בְּבֵיתוֹ וְנָתַן לוֹ בִּתּוֹ לְאִשָּׁה. וְלֹא עוֹד, אֶלָּא נָתַן לוֹ מָמוֹן וְשִׁלְּחוֹ לְמִצְרַיִם, לְהַשְׁמִיד אֶת כָּל הָאָרֶץ. וְהוּא וְכָל בֵּיתוֹ נִמְשְׁכוּ אַחֲרָיו. אִם נוּכַל לַעֲקֹר אוֹתוֹ רַבָּם מֵהָעוֹלָם, כָּל עַמּוֹ יֵעָקְרוּ מִיָּד מִן הָעוֹלָם. וְכָל הָעֵצָה הָרָעָה מֵאוֹתוֹ דְּבַר פְּעוֹר הָיָה מִמִּדְיָן.</p>\n<p>וּבֹא וּרְאֵה שֶׁהַכֹּל הָיָה מִמִּדְיָן, וְכָל עֲצָתָם הָיְתָה עַל מֹשֶׁה. וּבַעֲצָתָם שָׂכְרוּ אֶת בִּלְעָם כֵּיוָן שֶׁרָאוּ שֶׁבִּלְעָם לֹא יָכוֹל, לָקְחוּ עֵצָה אַחֶרֶת לְעַצְמָם, וְהִפְקִירוּ נְשֵׁיהֶם וּבְנוֹתֵיהֶם יוֹתֵר מִמּוֹאָב, שֶׁהֲרֵי עַל נְשׁוֹת מִדְיָן כָּתוּב, (במדבר לא) הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל וְגוֹ'. וְהַכֹּל הָיָה מִמִּדְיָן. לָקְחוּ עֵצָה יַחַד עִם נְשִׂיאָם שֶׁיַּפְקִיר בִּתּוֹ, שֶׁחָשְׁבוּ לִתְפֹּס אֶת מֹשֶׁה בְּרִשְׁתָּם, בְּכַמָּה מִינֵי כְשָׁפִים עִטְּרוּ אוֹתָהּ שֶׁיִּתָּפֵס הָרֹאשׁ שֶׁלָּהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא (ישעיה מד) מֵשִׁיב חֲכָמִים אָחוֹר.</p>\n<p>הֵם רָאוּ שֶׁהָרֹאשׁ יִתָּפֵס בְּרִשְׁתָּם, וְלֹא יָדְעוּ, רָאוּ וְלֹא רָאוּ. רָאוּ רֹאשׁ הָעָם שֶׁנּוֹפֵל אִתָּהּ וְכַמָּה אֲלָפִים אֲחֵרִים, וְחָשְׁבוּ שֶׁזֶּה מֹשֶׁה. הִפְקִירוּ אוֹתָהּ וְצִוּוּ אוֹתָהּ עַל מֹשֶׁה, שֶׁלֹּא תִזְדַּוְּגִי לְאַחֵר אֶלָּא בּוֹ. אָמְרָה לָהֶם, בַּמָּה אֵדַע? אָמְרוּ, אוֹתוֹ שֶׁתִּרְאִי שֶׁכֻּלָּם עוֹמְדִים לְפָנָיו, בּוֹ תִזְדַּוְּגִי וְלֹא בְאַחֵר. כֵּיוָן שֶׁבָּא זִמְרִי בֶּן סָלוּא, עָמְדוּ לְפָנָיו עֶשְׂרִים וְאַרְבָּעָה (חמשים ותשעה) אֶלֶף מִשֵּׁבֶט שִׁמְעוֹן, מִשּׁוּם שֶׁהָיָה נְשִׂיאָם, וְהִיא חָשְׁבָה שֶׁהוּא מֹשֶׁה, וְהִזְדַּוְּגָה אִתּוֹ. כֵּיוָן שֶׁרָאוּ כָּל אוֹתָם הַיֶּתֶר אֶת זֶה, עָשׂוּ מַה שֶּׁעָשׂוּ, וְהָיָה מַה שֶּׁהָיָה.</p>\n<p>וְהַכֹּל הָיָה מִמִּדְיָן בְּכַמָּה מִינִים, וּמִשּׁוּם כָּךְ נֶעֶנְשׁוּ מִדְיָן, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לְמֹשֶׁה, (במדבר לא) נְקֹם נִקְמַת בְּנֵי יִשְׂרָאֵל מֵאֵת הַמִּדְיָנִים. לְךְ רָאוּי וּלְךְ נָאֶה. לְמוֹאָב אֲנִי מַשְׁאִיר אוֹתָם לְאַחַר שֶׁיֵּצְאוּ מֵהֶם שְׁתֵּי מַרְגָּלִיּוֹת - הֲרֵי דָּוִד בֶּן יִשַׁי, שֶׁהוּא יִנְקֹם נִקְמוֹת מוֹאָב וְיִרְחַץ קְדֵרָה הַמְּלֵאָה טִנֹּפֶת פְּעוֹר. זֶהוּ שֶׁכָּתוּב (תהלים ס) מוֹאָב סִיר רַחְצִי, בְּוַדַּאי. וְעַד שֶׁאוֹתָן שְׁתֵּי מַרְגָּלִיּוֹת לֹא יָצְאוּ, לֹא נֶעֶנְשׁוּ. כֵּיוָן שֶׁיָּצְאוּ, בָּא דָוִד וְרָחַץ הַקְּדֵרָה מֵהַטִּנֹּפֶת שֶׁלָּהֶם. וְכֻלָּם נֶעֶנְשׁוּ - מִדְיָן בִּימֵי מֹשֶׁה, וּמוֹאָב בִּימֵי דָוִד.</p>\n<p>בֹּא וּרְאֵה, רִשְׁעֵי מִדְיָן עִם כָּל זֶה לֹא שָׁכְכוּ מִכָּל רָעוֹתֵיהֶם. אַחַר דּוֹרוֹת שֶׁרָאוּ שֶׁמֵּת יְהוֹשֻׁעַ וְכָל אוֹתָם זְקֵנִים שֶׁרְאוּיִים הָיוּ לְהֵעָשׂוֹת נֵס עַל יְדֵיהֶם, אָמְרוּ: כָּעֵת הַשָּׁעָה עוֹמֶדֶת לָנוּ. מֶה עָשׂוּ? בָּאוּ לַעֲמָלֵק וְאָמְרוּ: יֵשׁ לָכֶם לִזְכֹּר מֶה עָשׂוּ לָכֶם בְּנֵי יִשְׂרָאֵל וּמֹשֶׁה רַבָּם וִיהוֹשֻׁעַ תַּלְמִידוֹ, שֶׁהִשְׁמִידוּ אֶתְכֶם מֵהָעוֹלָם. כָּעֵת הוּא זְמַן שֶׁאֵין מִי שֶׁמֵּגֵן עֲלֵיהֶם, וְאָנוּ יַחַד אִתְּכֶם, שֶׁכָּתוּב (שופטים ו) מִדְיָן וַעֲמָלֵק וּבְנֵי קֶדֶם וְגוֹ', (שם) מִפְּנֵי מִדְיָן עָשׂוּ לָהֶם בְּנֵי יִשְׂרָאֵל אֶת הַמִּנְהָרוֹת וְגוֹ'. לֹא הָיָה בָּעוֹלָם מִי שֶׁיַּעֲשֶׂה רָע בַּכֹּל כְּמוֹ מִדְיָן. וְאִם תֹּאמַר עֲמָלֵק - בִּגְלַל קִנְאַת בְּרִית שֶׁהִתְקָרְבוּ לַבְּרִית, וְעַל זֶה מְקַנֵּא הַקָּדוֹשׁ בָּרוּךְ הוּא קִנְאַת עוֹלָמִים שֶׁלֹּא נִשְׁכַּחַת. אָמְרוּ, וַדַּאי כָּךְ זֶה, וְאֵין כָּאן סָפֵק בָּעוֹלָם.</p>\n<p>פָּתַח וְאָמַר, (דברים ב) וַיֹּאמֶר ה' אֵלַי אַל תָּצַר אֶת מוֹאָב וְגוֹ'. וַיֹּאמֶר ה' אֵלַי, וְכִי עַד עַכְשָׁו לֹא יָדַעְנוּ שֶׁעִם מֹשֶׁה הָיָה מְדַבֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא עִם אַחֵר שֶׁכָּתוּב וַיֹּאמֶר ה' אֵלַי?! אֵלַי לָמָּה? אֶלָּא אֶת מֹשֶׁה צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לְהַזִּיק אֶת מוֹאָב, אֲבָל לְאַחֵר לֹא. לְדָוִד לֹא צִוָּה אֶת זֶה, וּמִשּׁוּם זֶה, אֵלַי אַל תָּצַר אֶת מוֹאָב, אֲפִלּוּ לִתְחוּם קָטָן שֶׁלָּהֶם, שֶׁהֲרֵי מִכֶּם יֵצֵא מִי שֶׁיִּתֵּן נְקָמוֹת לְיִשְׂרָאֵל וְיִנְקֹם נִקְמוֹתֵיהֶם, וְהוּא דָּוִד שֶׁבָּא מֵרוּת הַמּוֹאֲבִיָּה.</p>\n<p>וְאַל תִּתְגָּר בָּם מִלְחָמָה. כָּל זֶה צִוָּה אֶת מֹשֶׁה, אֲבָל לְאַחֵר מֻתָּר. וְאִם תֹּאמַר לִיהוֹשֻׁעַ וְלַזְּקֵנִים שֶׁהָיוּ שֶׁהֶאֱרִיכוּ יָמִים אַחֲרָיו מֻתָּר - לֹא כָּךְ, מִשּׁוּם שֶׁכֻּלָּם מִבֵּית דִּין שֶׁל מֹשֶׁה הָיוּ, וּמַה שֶּׁנֶּאֱסַר לְמֹשֶׁה נֶאֱסַר לָהֶם. וְעוֹד, שֶׁלֹּא יָצְאוּ עֲדַיִן אוֹתָן מַרְגָּלִיּוֹת טוֹבוֹת, שֶׁהֲרֵי בִּימֵי הַשּׁוֹפְטִים יָצְאָה רוּת, וּבַת עֶגְלוֹן מֶלֶךְ מוֹאָב הָיְתָה. מֵת עֶגְלוֹן, שֶׁהָרַג אוֹתוֹ אֵהוּד, וּמִנּוּ מֶלֶךְ אַחֵר, וְזוֹ בִּתּוֹ שֶׁנִּשְׁאֲרָה, וְהָיְתָה בְּבֵית אוֹמֵן, וּבִשְׂדֵי מוֹאָב. כֵּיוָן שֶׁבָּא שָׁם אֱלִימֶלֶךְ, לְקָחָהּ לִבְנוֹ.</p>\n<p>וְאִם תֹּאמַר שֶׁאֱלִימֶלֶךְ גִּיְּרָה שָׁם - לֹא. אֶלָּא כָּל דַּרְכֵי הַבַּיִת וְאֹכֶל וּמִשְׁתֶּה לָמְדָה. מָתַי הִתְגַּיְּרָה? אַחֲרֵי שֶׁהָלְכָה עִם נָעֳמִי, אָז אָמְרָה (רות א) עַמֵּךְ עַמִּי וֵאלֹהַיִךְ אֱלֹהַי. נַעֲמָה יָצְאָה בִּבְנֵי עַמּוֹן בִּימֵי דָוִד.</p>\n<p>כְּשֶׁשָּׁרְתָה רוּחַ הַקֹּדֶשׁ עַל דָּוִד, אָמַר לוֹ, דָּוִד, כְּשֶׁמָּדַדְתִּי אֶת כָּל הָעוֹלָם וְהִפַּלְתִּי גוֹרָלוֹת, יִשְׂרָאֵל חֶבֶל נַחֲלָתוֹ הָיוּ, זָכַרְתִּי מַה שֶּׁעָשׂוּ מוֹאָב בְּחֶבֶל נַחֲלָתוֹ. מַה כָּתוּב? (שמואל ב ח) וַיְמַדְּדֵם בַּחֶבֶל. בְּאוֹתוֹ חֶבֶל נַחֲלַת ה'. כָּל אוֹתָם שֶׁהָיוּ מֵאוֹתוֹ זֶרַע, אוֹתוֹ חֶבֶל אָחַז בָּהֶם.</p>\n<p>כָּתוּב מְלֹא הַחֶבֶל. מַה זֶּה מְלֹא הַחֶבֶל? אֶלָּא אוֹתוֹ שֶׁכָּתוּב (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. וְהָיָה אוֹמֵר, זֶהוּ לְהַחֲיוֹת וְזֶהוּ לְהָמִית. וְאוֹתוֹ חֶבֶל אָחַז בְּאוֹתָם שֶׁנִּרְאוּ לַהֲמָתָה. בִּגְלַל זֶה אָחַז בְּחֶבֶל, וּפָשַׁט חֶבֶל עַל מַה שֶּׁעָשׂוּ בְּאוֹתוֹ חֶבֶל נַחֲלַת ה'.</p>\n<p>וּמִדְיָן, גִּדְעוֹן הִשְׁמִיד כָּל אוֹתוֹ הַזֶּרַע, שֶׁלֹּא הִשְׁאִיר מֵהֶם מִכָּל אֵלּוּ שֶׁהִזִּיקוּ לְיִשְׂרָאֵל בְּעֵצָה אוֹ בְּדָבָר אַחֵר. וּלְכָל אֵלּוּ שֶׁהִזִּיקוּ לְיִשְׂרָאֵל, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר לָהֶם שִׂנְאָה וְלוֹקֵחַ מֵהֶם נְקָמוֹת. אֲבָל אִם עֲתִידִים לָבֹא מֵהֶם טוֹב לָעוֹלָם, מַאֲרִיךְ רָגְזוֹ וְאַפּוֹ אִתָּם עַד שֶׁיֵּצֵא אוֹתוֹ טוֹב לָעוֹלָם, וְאַחַר כָּךְ לוֹקֵחַ נְקָמָה וְדִין מֵהֶם. אָמַר רַבִּי אֶלְעָזָר, כָּךְ זֶה בְּוַדַּאי, וְזֶהוּ בֵּרוּר הַדָּבָר. אָמַר אוֹתוֹ תִּינוֹק, מִכָּאן וָהָלְאָה חֲבֵרִים, הַתְקִינוּ כְּלֵי קְרָב בִּידֵיכֶם וְעִרְכוּ קְרָב.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ וְגוֹ'. דָּוִד הַמֶּלֶךְ הִזְמִין לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִזְמִין אֶת כֹּחוֹת הַשָּׁמַיִם, שֶׁהֵם כּוֹכָבִים וּמַזָּלוֹת וּשְׁאָר חֲיָלוֹת, וְשִׁתֵּף אֶת נִשְׁמָתוֹ אִתָּם לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב בָּרְכוּ ה' כָּל מַעֲשָׂיו בְּכָל מְקֹמוֹת מֶמְשַׁלְתּוֹ בָּרְכִי נַפְשִׁי אֶת ה'. חָתַם בְּנַפְשׁוֹ כָּל הַבְּרָכוֹת.</p>\n<p>הִזְמִין מַלְאֲכֵי מָרוֹם לְבָרְכוֹ, שֶׁכָּתוּב בָּרְכוּ ה' מַלְאָכָיו וְגוֹ', וְעַד שֶׁלֹּא בָאוּ יִשְׂרָאֵל מַלְאֲכֵי מָרוֹם הָיוּ עוֹשִׂים וּמְשַׁלְּמִים עֲשִׂיָּה. כֵּיוָן שֶׁבָּאוּ יִשְׂרָאֵל וְעָמְדוּ עַל הַר סִינַי וְאָמְרוּ נַעֲשֶׂה וְנִשְׁמָע, לָקְחוּ עֲשִׂיָּה מִמַּלְאֲכֵי הַשָּׁרֵת, נִכְלְלוּ בִדְבָרוֹ. וּמֵאָז עֲשִׂיָּה הָיְתָה בְּאֶרֶץ יִשְׂרָאֵל לְבַדָּם, וּמַלְאָכִים קְדוֹשִׁים לְבַדָּם. יִשְׂרָאֵל גּוֹמְרִים וּמַשְׁלִימִים עֲשִׂיָּה, וְלָכֵן גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ לִשְׁמֹעַ. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁלָּקְחוּ מֵהֶם עֲשִׂיָּה וְהִתְקַיְּמָה בָהֶם.</p>\n<p>אָמַר אוֹתוֹ תִּינוֹק, שְׁמֹר עַצְמְךְ וְהַצְלַח בְּכֵלֶיךְ. וְכִי שֶׁבַח זֶה בִּלְבַד לָקְחוּ יִשְׂרָאֵל, וְלֹא אַחֵר? אָמַר, שֶׁבַח זֶה מָצָאנוּ, וְלֹא אַחֵר. אָמַר אוֹתוֹ תִּינוֹק, כֵּיוָן שֶׁחַרְבְּךְ לֹא הִצְלִיחָה, אוֹ שֶׁאֵינְךְ מְנַעְנְעָהּ כָּרָאוּי, הַשְׁאֵר הַחֶרֶב לְמִי שֶׁעוֹרֵךְ קְרָב.</p>\n<p>שֶׁבַח עֶלְיוֹן שֶׁלֹּא נִמְסַר לְמַלְאָכִים עֶלְיוֹנִים לְבַדָּם, אֶלָּא יַחַד עִם יִשְׂרָאֵל, מִיהוּ? קָדוֹשׁ. בְּרָכָה נִמְסְרָה לָהֶם לְבַדָּם כְּמוֹ שֶׁנִּמְסְרָה לְיִשְׂרָאֵל, אֲבָל קָדוֹשׁ לֹא נִמְסַר לָהֶם לְבַדָּם, אֶלָּא עִם יִשְׂרָאֵל. שֶׁלֹּא מְקַדְּשִׁים קְדֻשָּׁה אֶלָּא עִם יִשְׂרָאֵל. וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (ישעיה ו) וְקָרָא זֶה אֶל זֶה וְאָמַר, מָתַי? בִּזְמַן שֶׁיִּשְׂרָאֵל מְקַדְּשִׁים לְמַטָּה. וְעַד שֶׁיִּשְׂרָאֵל לֹא מְקַדְּשִׁים לְמַטָּה, הֵם אֵינָם אוֹמְרִים קְדֻשָּׁה.</p>\n<p>מִשּׁוּם שֶׁקְּדֻשָּׁה עוֹלָה מִשְּׁלֹשָׁה עוֹלָמוֹת, וְלֹא מִשְּׁנַיִם, וְהַיְנוּ, וְקָרָא זֶה - הֲרֵי אֶחָד. אֶל זֶה - הֲרֵי שְׁנַיִם. וְאָמַר - הֲרֵי שְׁלֹשָׁה. שְׁלֹשָׁה עוֹלָמוֹת הֵם כְּנֶגֶד שָׁלֹשׁ קְדֻשּׁוֹת. וּמִשּׁוּם כָּךְ שֶׁבַח שֶׁל יִשְׂרָאֵל שֶׁלּוֹקְחִים קְדֻשָּׁה לְמַטָּה לְבַדָּם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּךְ זֶה וַדַּאי, וּדְבָרִים אֵלּוּ בֵּאַרְנוּם. וְעוֹד בֵּאַרְנוּ, שֶׁהֲרֵי שָׁלֹשׁ קְדֻשּׁוֹת נִמְסְרוּ לְיִשְׂרָאֵל לְמַטָּה מִפָּסוּק זֶה, (ויקרא כ) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים, (שם) כִּי קָדוֹשׁ אֲנִי ה'. וְהִתְקַדִּשְׁתֶּם - אֶחָד. וִהְיִיתֶם קְדשִׁים - שְׁנַיִם. כִּי קָדוֹשׁ אֲנִי ה' - הֲרֵי שְׁלֹשָׁה. כָּאן נִמְסְרָה לָהֶם קְדֻשָּׁה. אָמַר לוֹ, נָאֶה, וַהֲרֵי לֹא נִזְכַּרְתָּ בָּרֹמַח עַד שֶׁלְּקַחְתִּיהוּ מֵאֲחוֹרֵי כְתֵפְךְ וְשַׂמְתִּיהוּ בְיָדְךְ. מִכָּאן וָהָלְאָה תִּזָּכֵר בָּרֹמַח, שֶׁהוּא בְיָדְךְ. שׁוּב לַמָּקוֹם שֶׁהִשְׁאַרְתָּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הַדְּבָרִים שֶׁאָנוּ בָהֶם, בִּבְרָכָה הֵם. בָּרְכוּ, מַה זֶּה בָּרְכוּ? מְשִׁיכַת הַבְּרָכוֹת מִמָּקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת, עַד שֶׁנַּעֲשׂוֹת בְּרֵכָה, מֵרֹב מְשִׁיכוּת שֶׁנִּמְשֶׁכֶת, וּמִתּוֹךְ רֹב הַמַּיִם בְּאוֹתָהּ בְּרֵכָה מִיָּד יִרְבּוּ הַמַּיִם הַרְבֵּה דָגִים לְכַמָּה מִינִים, וְאוֹתָהּ מְשִׁיכַת מַיִם מַה הִיא? ה' מְשִׁיכוּת אוֹר הַמֵּאִיר מִתּוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁמְּאִירָה שֶׁנִּמְשָׁךְ מִלְמַעְלָה לְמַטָּה.</p>\n<p>זֶה לְמַלְאָכִים עֶלְיוֹנִים, שֶׁהֵם בְּבֵית מָרוֹם שֶׁל הַגֹּרֶן הָעֶלְיוֹן, נֶאֱמַר בָּרְכוּ ה'. אָנוּ שֶׁיּוֹשְׁבִים לְמַטָּה, מַדּוּעַ בָּרְכוּ אֶת ה'? מִשּׁוּם שֶׁאָנוּ צְרִיכִים לִמְשֹׁךְ עָלֵינוּ אֶת הָאֶת הַזֹּאת, וּבָהּ נִכָּנֵס לַמֶּלֶךְ לִרְאוֹת פָּנָיו. וְלָכֵן אָמַר דָּוִד, (תהלים יז) אֲנִי בְּצֶדֶק אֶחֱזֶה פָנֶיךְ. אֲנִי בְּצֶדֶק בְּוַדַּאי. וְלָכֵן רֵאשִׁית הַתְּפִלָּה - בָּרְכוּ אֶת ה', לִמְשֹׁךְ עַל רָאשֵׁינוּ הָאֶת הַזֹּאת. וְכֵיוָן שֶׁאָנוּ מוֹשְׁכִים עָלֵינוּ אֶת הָ\"אֶת\" הַזֹּאת, יֵשׁ לָנוּ לוֹמַר תְּפִלָּה וּלְשַׁבֵּחַ.</p>\n<p>וְלָכֵן אָסוּר לְבָרֵךְ אָדָם עַד שֶׁלֹּא יִתְפַּלֵּל הָאָדָם תְּפִלָּתוֹ וְיִמְשֹׁךְ אֶת הָ\"אֶת\" הַזֹּאת עַל רֹאשׁוֹ. וְאִם יַקְדִּים וִיבָרֵךְ לְאָדָם בַּתְּחִלָּה, הֲרֵי הִמְשִׁיךְ לְאוֹתוֹ אָדָם בָּמָה עַל רֹאשׁוֹ בִּמְקוֹם הָ\"אֶת\" הַזֹּאת.</p>\n<p>וְלָכֵן לַמַּלְאָכִים הָעֶלְיוֹנִים כָּתוּב בָּרְכוּ ה', וְאָנוּ אֶת ה', לְתוֹסֶפֶת. אָמַר אוֹתוֹ תִּינוֹק, וַדַּאי הֲרֵי יָדַעְתִּי שֶׁכְּלֵי הַקְּרָב שֶׁלְּךְ הֵם טוֹבִים, (אם תזכר) הִזָּכֵר בָּהֶם וְאַל תִּשְׁכָּחֵם, וַדַּאי גְּבוּרַת הָאָדָם שֶׁעוֹרֵךְ קְרָב בָּרֹמַח, וְחֶרֶב הִיא. אֲבָל מַה זֶּה גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ? אָמַר רַבִּי אֶלְעָזָר, הֲרֵי אָמַרְתִּי. אָמַר אוֹתוֹ תִּינוֹק, הֲרֵי יָדַעְתִּי שֶׁכֹּחַ זְרוֹעֲךְ נֶחֱלַשׁ, כָּעֵת הוּא זְמַן שֶׁלֹּא לְהַמְתִּין, אֶלָּא לְהַלְקוֹת בְּבַלִּיסְטְרָאוֹת אֶבֶן אַחַר אֶבֶן, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א יז) בַּקֶּלַע וּבָאֶבֶן. בִּבְהִילוּת זֶה אַחַר זֶה. שָׂמַח רַבִּי אֶלְעָזָר, וְשָׂמְחוּ רַבִּי אַבָּא וְהַחֲבֵרִים.</p>\n<p>פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, (שירהשירים א) שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם וְגוֹ'. אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת וְגוֹ'. דְּבָרִים הַלָּלוּ הֲרֵי פֵּרְשׁוּהָ. אֲבָל בְּשָׁעָה שֶׁהִיא בְּתוֹךְ אַהֲבָה רַבָּה לַאֲהוּבָהּ, מִתּוֹךְ דֹּחַק הָאַהֲבָה שֶׁלֹּא יְכוֹלָה לִסְבֹּל מַקְטִינָה עַצְמָהּ בְּקֹטֶן רַב עַד שֶׁלֹּא נִרְאֶה (את) מִמֶּנָּה, רַק קַטְנוּת שֶׁל נְקֻדָּה אַחַת, (ומהי, ' י'). וְאָז מִתְכַּסָּה מִכָּל הַחֲיָלוֹת וּמַחֲנוֹתֶיהָ וְאוֹמֶרֶת שְׁחוֹרָה אֲנִי, שֶׁאֵין בָּאוֹת הַזּוֹ לֹבֶן כְּמוֹ בִּשְׁאָר הָאוֹתִיּוֹת. וְזֶה שְׁחוֹרָה אֲנִי. וְאֵין לִי מָקוֹם לְהַכְנִיסְכֶם תַּחַת כְּנָפַי. כְּאָהֳלֵי קֵדָר - שָׁנִינוּ, זוֹ י', שֶׁאֵין בָּהּ לֹבֶן בִּפְנִים. כִּירִיעוֹת שְׁלֹמֹה - זוֹ ו'.</p>\n<p>וּמִשּׁוּם זֶה אַל תִּרְאֻנִי, אַל תִּסְתַּכְּלוּ בִי כְּלָל, שֶׁאֲנִי נְקֻדָּה קְטַנָּה. מָה עוֹשִׂים גְּבָרִים חֲזָקִים, חֵילוֹתֶיהָ? שׁוֹאֲגִים כַּאֲרָיוֹת תַּקִּיפִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) הַכְּפִירִים שּאֲגִים לַטָּרֶף. וּמִתּוֹךְ קוֹלוֹת וּשְׁאָגוֹת חֲזָקוֹת שֶׁשּׁוֹאֲגִים כְּמוֹ אֲרָיוֹת גִּבּוֹרִים תַּקִּיפֵי כֹחַ, שׁוֹמֵעַ הָאָהוּב לְמַעְלָה, וְיוֹדֵעַ שֶׁאֲהוּבָתוֹ בְּאַהֲבָה כְּמוֹתוֹ מִתּוֹךְ אַהֲבָתוֹ, עַד שֶׁלֹּא נִרְאֵית מִדְּמוּתָהּ וְיָפְיָהּ כְּלָל.</p>\n<p>וְאָז, מִתּוֹךְ קוֹלוֹת וּשְׁאָגוֹת שֶׁל אוֹתָם גִּבּוֹרֵי חַיִל שֶׁלָּהּ, יוֹצֵא דוֹדָהּ אֲהוּבָהּ מִתּוֹךְ הֵיכָלוֹ בְּכַמָּה מַתָּנוֹת, בְּכַמָּה אוֹצָרוֹת, בְּרֵיחוֹת וּבְשָׂמִים, וּבָא אֵלֶיהָ, וּמוֹצֵא אוֹתָהּ שְׁחוֹרָה קְטַנָּה לְלֹא דְמוּת וְיֹפִי כְּלָל. קָרֵב אֵלֶיהָ, מְחַבֵּק אוֹתָהּ וּמְנַשְּׁקָהּ עַד שֶׁמִּתְעוֹרֶרֶת לְאַט לְאַט מִתּוֹךְ רֵיחוֹת וּבְשָׂמִים וּבְחֶדְוָה שֶׁאֲהוּבָהּ עִמָּהּ, וְנִבְנֵית וְנַעֲשֵׂית בְּתִקּוּנֶיהָ, בִּדְמוּתָהּ, בְּיָפְיָהּ, ה' כְּמִקֹּדֶם.</p>\n<p>וְזְהִ גִּבֹּרֵי כֹחַ. עָשׂוּ לָהּ וְהֶחֱזִירוּהָ לִדְמוּתָהּ וְיָפְיָהּ, שֶׁתָּקְפָם וּגְבוּרָתָם גָּרְמוּ אֶת זֶה, וְעַל זֶה כָּתוּבּ גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ. עֹשֵׂי דְבָרוֹ בְּוַדַּאי, שֶׁמְּתַקְּנִים אֶת הַ\"דָּבָר\" הַזֶּה וּמַחֲזִירִים אוֹתוֹ לִדְמוּת רִאשׁוֹנָה. (ומכאן ולהלאה) כֵּיוָן שֶׁהִתְתַּקְּנָה וְנֶעֶשְׂתָה בִדְמוּתָהּ יָפָה כְּמִקֹּדֶם, אֲזַי הֵם וְכָל שְׁאָר הַחֲיָלוֹת עוֹמְדִים לִשְׁמֹעַ מַה שֶּׁהִיא אוֹמֶרֶת, וְהִיא עוֹמֶדֶת כְּמוֹ מֶלֶךְ בְּתוֹךְ חֵילוֹתָיו, וְזֶהוּ עֹשֵׂי דְבָרוֹ בְּוַדַּאי.</p>\n<p>כְּמוֹ זֶה לְמַטָּה - בִּזְמַן שֶׁהָרְשָׁעִים בַּדּוֹר, הִיא מִתְכַּסָּה וּמַקְטִינָה עַצְמָהּ עַד שֶׁלֹּא נִרְאֵית מִכָּל דְּמֻיּוֹתֶיהָ, פְּרָט לִנְקֻדָּה אַחַת. וּכְשֶׁבָּאִים גִּבֹּרֵי כֹחַ וְצַדִּיקֵי אֱמֶת, כִּבְיָכוֹל עוֹשִׂים אֶת הַדָּבָר הַזֶּה, וּמוּאֶרֶת לְאַט לְאַט, וְנַעֲשֵׂית בִּדְמוּתָהּ, בְּיָפְיָהּ, ה' כְּמִקֹּדֶם.</p>\n<p>בָּאוּ הַחֲבֵרִים וּנְשָׁקוּהוּ. אָמַר רַבִּי אֶלְעָזָר, אִלְמָלֵא יְחֶזְקֵאל הַנָּבִיא אָמַר אֶת זֶה, תְּמִיהָה הָיְתָה בָּעוֹלָם. לְקָחוֹ רַבִּי אֶלְעָזָר וּנְשָׁקוֹ כְּמִקֹּדֶם. אָמַר אוֹתוֹ תִּינוֹק, אֲנִי אַבְרֵךְ. אָמְרוּ לוֹ, אַתָּה בָּרוּךְ, וּלְךְ נָאֶה לְבָרֵךְ. אָמַר, כַּמָּה קְדוֹשִׁים אַתֶּם, כַּמָּה בְרָכוֹת מְזֻמָּנוֹת לָכֶם מֵאֵם הַקְּדוֹשָׁה, מִשּׁוּם שֶׁלֹּא מְנַעְתּוּנִי לְבָרֵךְ.</p>\n<p>פָּתַח וְאָמַר, (משלי יא) מֹנֵעַ בָּר יִקְּבֻהוּ לְאוֹם וּבְרָכָה לְרֹאשׁ מַשְׁבִּיר. פָּסוּק זֶה כְּמַשְׁמָעוֹ, אֲבָל שָׁנִינוּ, כָּל אָדָם חַיָּב בְּבִרְכַּת הַמָּזוֹן, וְאִם לֹא יָדַע - אִשְׁתּוֹ אוֹ בָּנָיו מְבָרְכִין לוֹ. וְתָבא מְאֵרָה לְאוֹתוֹ הָאִישׁ שֶׁלֹּא יוֹדֵעַ לְבָרֵךְ עַד שֶׁיִּצְטָרֵךְ לְאִשְׁתּוֹ וּלְבָנָיו שֶׁיְּבָרְכוּ לוֹ.</p>\n<p>וְאִם הוּא יוֹדֵעַ, צָרִיךְ לְחַנֵּךְ אֶת בְּנוֹ וְלָתֵת לוֹ כּוֹס לְבָרֵךְ. שֶׁמִּי שֶׁמּוֹנְעוֹ שֶׁלֹּא יִתְחַנֵּךְ, יִקְּבֻהוּ לְאוֹם. מֹנֵעַ בָּר - שֶׁלֹּא לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא יִתְחַנֵּךְ בְּמִצְות - יִקְּבֻהוּ לְאוֹם. יִקְּבֵהוּ הָיָה צָרִיךְ לוֹ לִכְתֹּב, אוֹ יִקְּבוּהוּ לְאֻמִּים, שֶׁהֲרֵי לְאֹם זֶה אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כה) וּלְאֹם מִלְאֹם יֶאֱמָץ. מַה זֶּה יִקְּבֻהוּ לְאוֹם? אֶלָּא לְאֵם כָּתוּב, לָאֵם הַקְּדוֹשָׁה. יִקְּבֻהוּ לָאָדָם הַזֶּה שֶׁמּוֹנֵעַ אוֹתוֹ בָּר מִלְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אֲנִי בֵּן יָחִיד הָיִיתִי לְאִמִּי, תְּנוּ לִי כּוֹס וַאֲבָרֵךְ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁנָּתַן בְּבֵית אִמִּי גְּבָרִים שֶׁל כֹּחַ שֶׁדִּבַּרְתִּי לִפְנֵיהֶם דְּבָרִים חֲזָקִים וְנִּצָחְתִּי אוֹתָם, וּמִשּׁוּם זֶה אֲנִי אֲבָרֵךְ. וְקֹדֶם זֶה הִתְיַשֵּׁב הַפָּסוּק עַל תִּקּוּנוֹ זֶה שֶׁהִתְחַלְנוּ בּוֹ.</p>\n<p>מֹנִעַּ בָּר יִקְּבֻהוּ לְאוֹם. מִי שֶׁמּוֹנֵעַ בָּר כְּמוֹ שֶׁנֶּאֱמַר, יִקְּבֻהוּ לְאוֹם, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כד) וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית אֶת הַשֵּׁם. אַף כָּאן יִקְּבֻהוּ, וִיפָרְשׁוּ אוֹתוֹ לְאֵם, יְפָרְשׁוּ אֶת חֲטָאָיו לָאֵם הַקְּדוֹשָׁה. וּבְרָכָה לְרֹאשׁ מַשְׁבִּיר, לְאוֹתוֹ אָדָם שֶׁיְּחַנֵּךְ אֶת בְּנוֹ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְחַנְּכוֹ בְּמִצְווֹת הַתּוֹרָה.</p>\n<p>וְסוֹד הַדָּבָר כָּתוּב בְּסוֹד שֶׁלְּמַעְלָה, (משלי ל) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. אוֹתוֹ שֵׁם יָדוּעַ, (ירמיה לא) ה' צְבָאוֹת שְׁמוֹ. שֶּׁם בְּנוֹ, יִשְׂרָאֵל כְּמוֹ, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל. וַהֲרֵי יִשְׂרָאֵל תְּלוּיִים בּוֹ כָּל מַפְתְּחוֹת הָאֱמוּנָה, וְהוּא מִשְׁתַּבֵּחַ וְאוֹמֵר, (תהלים ב) ה' אָמַר אֵלַי בְּנִי אַתָּה. וְכָךְ זֶה בְּוַדַּאי, שֶׁהֲרֵי אַבָּא וְאִמָּא עִטְּרוּ אוֹתוֹ וּבֵרְכוּהוּ בְּכַמָּה בְרָכוֹת וְאָמְרוּ וְצִוּוּ אֶת הַכֹּל. נַשְּׁקוּ בַר, נַשְּׁקוּ אֶת יַד הַבֵּן הַזֶּה כִּבְיָכוֹל נָתַן לוֹ שִׁלְטוֹן עַל הַכֹּל, שֶׁהַכֹּל יַעַבְדוּ אוֹתוֹ. פֶּן יֶאֱנַף, מִשּׁוּם שֶׁעִטְּרוּ אוֹתוֹ בְּדִין וּבְרַחֲמִים. מִי שֶׁזּוֹכֶה לְדִין - לְדִין. מִי שֶׁזּוֹכֶה לְרַחֲמִים - לְרַחֲמִים.</p>\n<p>כָּל הַבְּרָכוֹת שֶׁלְּמַעְלָה וּלְמַטָּה עוֹלוֹת לַבֵּן הַזֶּה וּמִתְעַטְּרוֹת. וּמִי שֶׁמּוֹנֵעַ בְּרָכוֹת מֵהַבֵּן הַזֶּה, יְפָרְשׁוּ אֶת חֲטָאָיו לִפְנֵי הַמֶּלֶךְ (אמא) הַקָּדוֹשׁ, לָאֵם מַמָּשׁ. וּבְרָכָה לְרֹאשׁ מַשְׁבִּיר, מִי שֶׁמְּבָרֵךְ וּמַזְמִין כּוֹס בְּרָכָה לְמִי שֶׁצָּרִיךְ אוֹתוֹ, בָּזֶה נִשְׁבָּר הַצַּד הָאַחֵר וְנִכְנָע בִּשְׁבִירָה, וְעוֹלֶה צַד הַקְּדֻשָּׁה. וְזֶהוּ שֶׁכָּתוּב וּבְרָכָה לְרֹאשׁ מַשְׁבִּיר. כְּמוֹ שֶׁהוּא מַעֲלֶה וּמְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְעוֹשֶׂה שֶׁיִּשָּׁבֵר צַד הָאַחֵר, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו בְּרָכוֹת מִלְמַעְלָה, וְאוֹתוֹ שֶׁנִּקְרָא בְרָכָה שׁוֹרֶה עַל רֹאשׁוֹ.</p>\n<p>מִכָּאן וָהָלְאָה, חֲבֵרִים, הָבָה וּנְבָרֵךְ. נָתְנוּ לוֹ כּוֹס שֶׁל בְּרָכָה וּבֵרַךְ. וְהַחֲבֵרִים כֻּלָּם הָיוּ בְחֶדְוָה, שֶׁהֲרֵי מִיּוֹם הַהִלּוּלָא שֶׁל רַבִּי אֶלְעָזָר לֹא שָׂמְחוּ הַחֲבֵרִים כְּאוֹתוֹ יוֹם שֶׁיָּשְׁבוּ שָׁם. הִקְדִּימוּ וּבֵרְכוּהוּ בְחֶדְוָה בִּרְצוֹן הַלֵּב. אָמַר אוֹתוֹ תִּינוֹק, אֵין לָכֶם לְהִפָּרֵד אֶלָּא מִתּוֹךְ דִּבְרֵי תוֹרָה, וְכָךְ לָמַדְנוּ.</p>\n<p>פָּתַח וְאָמַר, (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן וְגוֹ'. וַה' - זָקֵף טַעַם לְמַעְלָה, לָמָּה זֶה? אֶלָּא בְּאוֹתָהּ שָׁעָה כַּמָּה נָאֶה וְיָפֶה הָיָה לַכַּלָּה הַזֹּאת שֶׁהָיְתָה כְפוּפָה עַד עַתָּה בַּגָּלוּת, וְכָעֵת הוֹלֶכֶת בִּזְקִיפוּת רֹאשׁ בְּאוּכְלוּסֵיהַ בְּשִׂמְחָה.</p>\n<p>בְּוַה' זָקֵף טַעַם לְמַעְלָה. הֹלֵךְ לִפְנֵיהֶם יוֹמָם. עַד כָּאן לֹא יָדַע אִם כַּלָּה זוֹ הָלְכָה לִפְנֵיהֶם אִם לֹא, שֶׁהֲרֵי טַעַם מַפְסִיק בְּוַה'. אֶלָּא הִיא הָיְתָה שָׁם, אֲבָל מִי שֶׁהָלַךְ לִפְנֵיהֶם, זָקֵן עֶלְיוֹן, בַּעַל הַבַּיִת, אוֹתוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִשְׁבַּע (שהזמין) לוֹ, וּמִיהוּ? אַבְרָהָם, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. וְכָתוּב (ירמיה לא) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה. יוֹם שֶׁכָּל הַיָּמִים כְּלוּלִים בּוֹ, יוֹם שֶׁל שְׁאָר הַיָּמִים, הוּא שְׁאָר כָּל הַיָּמִים בְּוַדַּאי. וְעַל זֶה נִקְרָא יוֹמָם וְלֹא יוֹם, וּמִשּׁוּם זֶה הֹלֵךְ לִפְנֵיהֶם יוֹמָם. הוּא הוֹלֵךְ בַּיּוֹם, וְהַכַּלָּה הוֹלֶכֶת בַּלַּיְלָה, שֶׁכָּתוּב וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם, זוֹ כַּלָּה, כָּל אֶחָד כָּרָאוּי לוֹ. וְאַתֶּם חֲבֵרִים, יוֹמָם וָלַיְלָה יִהְיֶה לִפְנֵיכֶם בְּכָל שָׁעָה. נְשָׁקוּהוּ וּבֵרְכוּהוּ כְּמִקֹּדֶם וְהָלְכוּ.</p>\n<p>בָּאוּ לִפְנֵי רַבִּי שִׁמְעוֹן וְסִפְּרוּ לוֹ הַמַּעֲשֶׂה. תָּמַהּ. אָמַר, כַּמָּה נָאֶה הוּא, אֲבָל לֹא עוֹלֶה בְשֵׁם. עֵץ דַּק, כְּשֶׁעוֹלֶה אוֹרוֹ, עוֹלֶה לְפִי שָׁעָה, וּמִיָּד כָּבֶה וְשׁוֹקֵעַ. וְעוֹד הֲרֵי אָמַרְנוּ אוֹר זֶה מִמַּה נִּהְיָה.</p>\n<p>פָּתַח וְאָמַר, (תהלים קיב) גִּבּוֹר בָּאָרֶץ יִהְיֶה זַרְעוֹ דּוֹר יְשָׁרִים יְבֹרָךְ. כְּשֶׁבֶּן אָדָם גִּבּוֹר בָּאָרֶץ, גִּבּוֹר בַּתּוֹרָה, גִּבּוֹר בְּיִצְרוֹ - גִּבּוֹר בָּאָרֶץ וַדַּאי. עוֹלֶה אוֹרוֹ וְנִמְשָׁךְ בּוֹ מְשִׁיכוּת יֶתֶר, אָז דּוֹר יְשָׁרִים יְבֹרָךְ, יְבָרֵךְ כָּתוּב.</p>\n<p>אָמַר רַבִּי אַבָּא, וַהֲרֵי רָאִינוּ תִינוֹקוֹת שֶׁאוֹמְרִים דְּבָרִים עֶלְיוֹנִים וְאַחַר כָּךְ עוֹמְדִים רָאשֵׁי הָעוֹלָם. אָמַר לוֹ, תִּינוֹק שֶׁאָמַר דָּבָר אֶחָד אוֹ שְׁנַיִם לְפִי שָׁעָה, בְּלִי כַוָּנָתָם, מֻבְטָח אָדָם בָּזֶה, שֶׁיִּזְכֶּה לְלַמֵּד תּוֹרָה בְּיִשְׂרָאֵל. אֲבָל זֶה שֶׁאוֹרוֹ עוֹמֵד עַל עָמְדוֹ בְּדַעַת שְׁלֵמָה, לֹא כָּךְ. וְעוֹד, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְעֶרְגָּתוֹ לְהָרִיחַ תַּפּוּחַ זֶה. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>אַשְׁרֵיכֶם הַצַּדִּיקִים, שֶׁכָּתוּב בָּכֶם (מלכים ב יט) וְיָסְפָה פְּלֵיטַת בֵּית יְהוּדָה הַנִּשְׁאָרָה שֹׁרֶשׁ לְמָטָּה וְעָשָׂה פְרִי לְמָעְלָה. שֹׁרֶשׁ לְמָטָּה, כְּמוֹ אָבִיו שֶׁהִסְתַּלֵּק מֵהָעוֹלָם, וְהוּא שֹׁרֶשׁ לְמָטָּה בִּישִׁיבַת הָרָקִיעַ. וְעָשָׂה פְרִי לְמָעְלָה, בַּיְשִׁיבָה הָעֶלְיוֹנָה. כַּמָּה טוֹב הַשֹּׁרֶשׁ וְהַפְּרִי. וְאִם לֹא שֶׁלֹּא אֶהְיֶה מְקַטְרֵג לַקָּדוֹשׁ-בָּרוּךְ-הוּא, הוֹאִיל וְעֶרְגָּתוֹ לְהָרִיחַ בּוֹ, לֹא הָיָה מִי שֶׁיָּכוֹל לִשְׁלֹט בּוֹ. אֲבָל יְהִי רָצוֹן שֶׁאִמּוֹ לֹא תִרְאֶה צַעַר עָלָיו. וְכֵן הָיָה.</p>"],[9522012403,"<p>וַיִּשְׁלַח מַלְאָכִים אֶל בִּלְעָם בֶּן בְּעוֹר וְגוֹ'. הִנֵּה עַם יָצָא מִמִּצְרַיִם וְגוֹ'. כָּאן יֵשׁ עֶשְׂרִים וּשְׁמוֹנֶה תֵבוֹת כְּנֶגֶד עֶשְׂרִים וּשְׁמוֹנֶה דַּרְגוֹת הַמְּכַשְּׁפִים קוֹסְמֵי הַצִּפּוֹר. וְיֵשׁ לְהִסְתַּכֵּל, מִי שֶׁרָצָה לְדַבֵּר עִם בִּלְעָם וּלְהִתְחַבֵּר אִתּוֹ, לָמָּה שָׁלַח לוֹ מִיָּד עַד שֶׁלֹּא יָבֹא אֵלָיו דְּבָרִים בְּפֵרוּשׁ, שֶׁאָמַר הִנֵּה עַם יָצָא מִמִּצְרַיִם וְעַתָּה לְכָה אָרָה לִּי? הָיָה לוֹ לְהִתְחַבֵּר אִתּוֹ בַּתְּחִלָּה וּלְפַיְּסוֹ וּלְשַׁחֵד אוֹתוֹ, וְאַחַר כָּךְ לְהוֹדִיעוֹ דְבָרָיו!</p>\n<p>אֶלָּא אָמַר רַבִּי יוֹסֵי, מִכָּאן נוֹדָע שֶׁהֲרֵי יָדַע בָּלַק רְצוֹן אוֹתוֹ רָשָׁע, שֶׁרָצָה לְהִתְכַּבֵּד תָּמִיד בִּדְבָרִים גְּדוֹלִים, וְאֵין תַּאֲוָתוֹ אֶלָּא כְּשֶׁעוֹשֶׂה רָעוֹת.</p>\n<p>בָּלָק קִסֵּם קְסָמִים וְעָשָׂה כְשָׁפִים וְתִקֵּן צִפּוֹר, וְיָדַע שֶׁמַּעֲלוֹת מֹשֶׁה עֶלְיוֹנוֹת וְנִכְבָּדוֹת, וְכִשֵּׁף בִּכְשָׁפָיו וְקִסֵּם בִּקְסָמָיו, וְיָדַע שֶׁדַּרְגוֹת בִּלְעָם הָיוּ לְעֻמָּתוֹ, מִיָּד - וַיִּשְׁלַח מַלְאָכִים אֶל בִּלְעָם בֶּן בְּעוֹר.</p>\n<p>פְּתוֹרָה - שֵׁם הַמָּקוֹם הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (דברים כג) מִפְּתוֹר אֲרַם נַהֲרַיִם לְקַלֲלֶךָּ. לָמָּה נִקְרָא כָּךְ? מִשּׁוּם שֶׁכָּתוּב (ישעיה סה) הָעֹרְכִים לַגַּד שֻׁלְחָן. וְשֻׁלְחָן הָיָה מְסַדֵּר שָׁם כָּל יוֹם. שֶׁכָּךְ הוּא תִּקּוּן שֶׁל צְדָדִים רָעִים - מְסַדְּרִים לִפְנֵיהֶם שֻׁלְחָן בְּמַאֲכָל וּמִשְׁתֶּה, וְעוֹשִׂים כְּשָׁפִים וּמְקַטְּרִים לִפְנֵי הַשֻּׁלְחָן, וּמִתְכַּנְּסִים שָׁם כָּל רוּחוֹת הַטֻּמְאָה וּמוֹדִיעִים לָהֶם מַה שֶּׁהֵם רוֹצִים. וְכָל מְכַשְּׁפִים וְקוֹסְמִים שֶׁל הָעוֹלָם הָיוּ עַל אוֹתוֹ הַשֻּׁלְחָן, וּמִשּׁוּם זֶה נִקְרָא שֵׁם הַמָּקוֹם הַהוּא פְּתוֹרָא, שֶׁכָּךְ קוֹרְאִים בַּאֲרַם נַהֲרַיִם לְשֻׁלְחָן פְּתוֹרָא.</p>\n<p>פָּתַח וְאָמַר, (שמות כה) וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ'. וְכָתוּב וְנָתַתָּ עַל הַשֻּׁלְחָן לֶחֶם פָּנִים וְגוֹ'. כָּל אוֹתָם כְּלֵי קֹדֶשׁ רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לְפָנָיו לְהַמְשִׁיךְ רוּחַ קֹדֶשׁ מִלְמַעְלָה לְמַטָּה. אוֹתוֹ רָשָׁע בִּלְעָם הָיָה מְסַדֵּר כָּךְ לַצַּד הָאַחֵר, וְהָיָה מְסַדֵּר שֻׁלְחָן, וְלֶחֶם שֶׁהָיָה נִקְרָא (מלאכי א) לֶחֶם מְגֹאָל, כְּמוֹ שֶׁנֶּאֱמַר. שֶׁכָּךְ הוֹלֵךְ הַצַּד הָאַחֵר אַחַר הַקְּדֻשָּׁה כְּקוֹף אַחַר בְּנֵי אָדָם. וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (קהלת ב) כִּי מֶה הָאָדָם שֶׁיָּבוֹא אַחֲרֵי הַמֶּלֶךְ אֵת אֲשֶׁר כְּבָר עָשׂוּהוּ. וַהֲרֵי נִתְבָּאֵר פָּסוּק זֶה.</p>"],[9522012404,"<p>בֹּא וּרְאֵה, כָּתוּב (שופטים ה) ה' בְּצֵאתְךְ מִשֵּׂעִיר בְּצַעְדְּךְ מִשְּׂדֵה אֱדוֹם אֶרֶץ רָעָשָׁה וְגוֹ'. בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת תּוֹרָה לְיִשְׂרָאֵל, הָלַךְ וְזִמֵּן אֶת בְּנֵי עֵשָׂו וְלֹא קִבְּלוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) ה' מִסִּינַי בָּא וְזָרַח מִשֵּׂעִיר לָמוֹ, וְלֹא רָצוּ לְקַבְּלָהּ. הָלַךְ לִבְנֵי יִשְׁמָעֵאל, וְלֹא רָצוּ לְקַבְּלָהּ, שֶׁכָּתוּב הוֹפִיעַ מֵהַר פָּארָן. כֵּיוָן שֶׁלֹּא רָצוּ, חָזַר לָהֶם לְיִשְׂרָאֵל. כָּךְ שָׁנִינוּ.</p>\n<p>עֵכְשָׁו יֵשׁ לִשְׁאֹל, וַהֲרֵי שָׁנִינוּ שֶׁאֵין חַטָּאָה כְּשֶׁאָדָם מְדַקְדֵּק דִּיּוּקִים בַּתּוֹרָה וְיִשְׁאַל שְׁאֵלוֹתָיו לְהָאִיר דְּבָרָיו. פָּסוּק זֶה לֹא מִתְיַשֵּׁב, וְיֵשׁ לִשְׁאֹל, הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהָלַךְ לְשֵׂעִיר, לְאֵיזֶה נָבִיא שֶׁלָּהֶם הִתְגַּלָּה? וּכְשֶׁהָלַךְ לְפָארָן, לְאֵיזֶה נָבִיא שֶׁלָּהֶם הִתְגַּלָּה? אִם תֹּאמַר שֶׁהִתְגַּלָּה לְכֻלָּם, לֹא מָצָאנוּ זֶה לְעוֹלָמִים, פְּרָט לְיִשְׂרָאֵל לְבַדָּם, וְעַל יְדֵי מֹשֶׁה. וַהֲרֵי נִתְבָּאֵר שֶׁכָּךְ צָרִיךְ הַפָּסוּק לוֹמַר: ה' לְסִינַי בָּא וְזָרַח לְשֵׂעִיר לָמוֹ הוֹפִיעַ לְהַר פָּארָן. מַה זֶּה מִשֵּׂעִיר לָמוֹ? וּמַה זֶּה מֵהַר פָּארָן? הַכֹּל יֵשׁ לָדַעַת וּלְהִסְתַּכֵּל, וַהֲרֵי שָׁאַלְנוּ, וְלֹא שָׁמַעְנוּ וְלֹא יָדַעְנוּ.</p>\n<p>כְּשֶׁבָּא רַבִּי שִׁמְעוֹן, בָּא וְשָׁאַל דָּבָר כְּמִקֹּדֶם. אָמַר לוֹ, הֲרֵי שְׁאֵלָה זוֹ נֶאֶמְרָה. ה' מִסִּינַי בָּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות יט) הִנֵּה אָנֹכִי בָּא אֵלֶיךְ בְּעַב הֶעָנָן, וּמִסִּינַי בָּא וְהִתְגַּלָּה עֲלֵיהֶם. וְזָרַח מִשֵּׂעִיר לָמוֹ, מִמַּה שֶּׁאָמְרוּ בְּנֵי שֵׂעִיר שֶׁלֹּא רוֹצִים לְקַבֵּל, מִזֶּה הֵאִיר לָהֶם לְיִשְׂרָאֵל וְהוֹסִיף עֲלֵיהֶם אוֹר חֲבִיבוּת גְּדוֹלָה. גַּם כָּךְ הוֹפִיעַ וְהֵאִיר לְיִשְׂרָאֵל מֵהַר פָּארָן, מִמַּה שֶּׁאָמְרוּ בְּנֵי פָּארָן שֶׁלֹּא רוֹצִים לְקַבֵּל, מִזֶּה הוֹסִיפוּ יִשְׂרָאֵל חֲבִיבוּת וְאוֹר יוֹתֵר כָּרָאוּי.</p>\n<p>וּמַה שֶּׁשָּׁאַלְתָּ עַל יְדֵי מִי הִתְגַּלָּה אֲלֵיהֶם - (בא ראה) סוֹד עֶלְיוֹן הוּא, וְהִתְגַּלָּה הַדָּבָר עַל יָדְךְ. הַתּוֹרָה יָצְאָה מִסּוֹד עֶלְיוֹן, שֶׁל רֹאשׁ (קדוש) הַמֶּלֶךְ הַנִּסְתָּר. כְּשֶׁהִגִּיעָה לִזְרוֹעַ שְׂמֹאל (ימין), רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ זְרוֹעַ דָּם רַע שֶׁמִּתְרַבֶּה מִשָּׁם. אָמַר, צָרִיךְ לְבָרֵר וּלְלַבֵּן זְרוֹעַ זוֹ, וְאִם לֹא יִמֹּךְ אוֹתוֹ דָּם רַע, יִפְגֹּם הַכֹּל. אֲבָל צָרִיךְ לְבָרֵר מִכָּאן כָּל פְּגָם.</p>\n<p>מֶה עָשָׂה? קָרָא לְסָמָאֵ\"ל, וּבָא לְפָנָיו, וְאָמַר לוֹ: הֲתִרְצֶה תוֹרָתִי. אָמַר: מַה כָּתוּב בָּהּ? אָמַר לוֹ: לֹא תִרְצַח. דִּלֵּג הַקָּדוֹשׁ בָּרוּךְ הוּא לַמָּקוֹם שֶׁצָּרִיךְ. אָמַר: חַס וְשָׁלוֹם, תּוֹרָה זוֹ שֶׁלְּךְ הִיא, וְשֶׁלְּךְ תִּהְיֶה. לֹא רוֹצֶה תּוֹרָה זוֹ. שָׁב וְהִתְחַנֵּן לְפָנָיו. אָמַר: רִבּוֹן הָעוֹלָם, אִם אַתָּה נוֹתֵן לִי אוֹתָהּ, כָּל שִׁלְטוֹנִי עוֹבֵר, שֶׁהֲרֵי שִׁלְטוֹנִי עַל הֶרֶג הוּא, וּקְרָבוֹת לֹא יִהְיוּ, וְשִׁלְטוֹנִי עַל כּוֹכָב מַאְדִּים. אִם כָּךְ הַכֹּל יִתְבַּטֵּל מִן הָעוֹלָם.</p>\n<p>רִבּוֹן הָעוֹלָם, קַח תּוֹרָתְךְ, וְלֹא יִהְיֶה לִי חֵלֶק וְנַחֲלָה בָּהּ. אֲבָל אִם נוֹחַ לְפָנֶיךְ, הֲרֵי עַם בְּנֵי יַעֲקֹב לָהֶם רְאוּיָה. וְהוּא חָשַׁב שֶׁלָּשׁוֹן הָרָע אָמַר עֲלֵיהֶם. וְזֶהוּ וְזָרַח מִשֵּׂעִיר לָמוֹ, מִשֵּׂעִיר מַמָּשׁ יָצָא לְיִשְׂרָאֵל אוֹר. אָמַר סָמָאֵ\"ל: וַדַּאי אִם בְּנֵי יַעֲקֹב יְקַבְּלוּ אֶת זֶה, יַעַבְרוּ מִן הָעוֹלָם וְלֹא יִשְׁלְטוּ לְעוֹלָמִים. שָׁב אֵלָיו כַּמָּה פְעָמִים וְאָמַר זֶה, וְאָמַר לוֹ: אַתָּה בְּכוֹר, וּלְךְ רְאוּיָה. אָמַר לוֹ: הֲרֵי לוֹ בְּכוֹרָתִי, וַהֲרֵי מְכַרְתִּיהָ לוֹ, וַאֲנִי הוֹדֵיתִי. אָמַר לוֹ: הוֹאִיל וְלֹא רָצִיתָ שֶׁיִּהְיֶה לְךְ בָּהּ חֵלֶק, תַּעֲבֹר מִמֶּנָּה בַּכֹּל. אָמַר: יָפֶה.</p>\n<p>אָמַר לוֹ: הוֹאִיל וְכָךְ, תֵּן לִי עֵצָה אֵיךְ אֶעֱשֶׂה שֶׁיְּקַבְּלוּהָ בְּנֵי יַעֲקֹב שֶׁאַתָּה אוֹמֵר. אָמַר לוֹ: רִבּוֹן הָעוֹלָם, צָרִיךְ לְשַׁחֵד אוֹתָם. קַח אוֹר מֵאוֹר חֵילוֹת הַשָּׁמַיִם וְתֵן עֲלֵיהֶם, וּבָזֶה יְקַבְּלוּהָ, וַהֲרֵי שֶׁלִּי יְהֵא בַתְּחִלָּה. הִפְשִׁיט מִמֶּנּוּ אוֹר שֶׁכִּסָּה אוֹתוֹ, וְנָתַן לוֹ לָתֵת לָהֶם לְיִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב וְזָרַח מִשֵּׂעִיר לָמוֹ. מִשֵּׂעִיר מַמָּשׁ. זֶה סָמָאֵ\"ל, שֶׁכָּתוּב (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו. לָמוֹ - לְיִשְׂרָאֵל.</p>\n<p>כֵּיוָן שֶׁבִּעֵר זֶה וְהֶעֱבִיר דָּם רַע מִזְּרוֹעַ שְׂמֹאל, חָזַר לִזְרוֹעַ יָמִין (שמאל). רָאָה בּוֹ גַּם כָּךְ. אָמַר: כָּךְ גַּם צָרִיךְ לְנַקּוֹת מִדָּם רָע זְרוֹעַ זוֹ. קָרָא לְרַהַ\"ב, אָמַר לוֹ: הֲתִרְצֶה תוֹרָתִי? אָמַר לוֹ: מַה כָּתוּב בָּהּ? דִּלֵּג לוֹ וְאָמַר: לֹא תִנְאָף. אָמַר: אוֹי אִם יְרֻשָּׁה זוֹ יוֹרִישׁ לִי הַקָּדוֹשׁ בָּרוּךְ הוּא, יְרֻשָּׁה רָעָה שֶׁיַּעֲבֹר מִמֶּנִּי כָּל שִׁלְטוֹנִי בָהּ, שֶׁהֲרֵי בִּרְכַּת הַמַּיִם נָטַלְתִּי, בִּרְכַּת דְּגֵי הַיָּם, שֶׁכָּתוּב (בראשית א) פְּרוּ וּרְבוּ וְגוֹ', וְכָתוּב (שם יז) וְהִפְרֵיתִי אֹתוֹ וְהִרְבֵּיתִי אֹתוֹ וְגוֹ', וְכָתוּב (שם טז) וְהוּא יִהְיֶה פֶּרֶא אָדָם.</p>\n<p>הִתְחִיל לְהִתְחַנֵּן לִפְנֵי רִבּוֹנוֹ וְאָמַר לוֹ: רִבּוֹן הָעוֹלָם, שְׁנֵי בָנִים יָצְאוּ מֵאַבְרָהָם - הֲרֵי בְּנֵי יִצְחָק, תֵּן לָהֶם, וְלָהֶם רְאוּיָה. אָמַר לוֹ: אֵינִי יָכוֹל, שֶׁאַתָּה הַבְּכוֹר וּלְךְ רְאוּיָה. הִתְחִיל לְהִתְחַנֵּן לְפָנָיו, וְאָמַר: רִבּוֹן הָעוֹלָם, בְּכוֹרָתִי תְּהֵא שֶׁלּוֹ, וְאוֹר זֶה שֶׁיָּרַשְׁתִּי עַל זֶה, קַח וְתֵן לָהֶם. וְכָךְ עָשָׂה. זֶהוּ שֶׁכָּתוּב הוֹפִיעַ מֵהַר פָּארָן.</p>\n<p>מַה שּׁוֹנֶה שֶׁבְּסָמָאֵ\"ל כָּתוּב וְזָרַח, וּבְרַהַ\"ב כָּתוּב הוֹפִיעַ? אֶלָּא נָטַל בְּאוֹתוֹ אוֹר שֶׁהִפְשִׁיט מִמֶּנּוּ סָמָאֵ\"ל חֶרֶב וְהֶרֶג, לַהֲרֹג בְּדִין וְלַהֲרֹג כָּרָאוּי. זֶהוּ שֶׁכָּתוּב (שם) וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךְ. אַף עַל גַּב שֶׁלֹּא הָיְתָה שֶׁלְּךְ. וְנָטַל אוֹתָהּ בְּרָכָה שֶׁהִפְשִׁיט מִמֶּנּוּ רַהַ\"ב קְצָת, כְּמוֹ שֶׁהוֹפִיעַ קְצָת מִבִּרְכָתָם לַעֲשׂוֹת פְּרִיָּה וּרְבִיָּה. בִּגְלַל כָּךְ הוֹפִיעַ מֵהַר פָּארָן, וְלֹא כָתוּב וְזָרַח.</p>\n<p>כֵּיוָן שֶׁנָּטַל מַתָּנוֹת אֵלּוּ לְיִשְׂרָאֵל מֵאוֹתָם שַׁלִּיטִים גְּדוֹלִים, בָּא וְקָרָא לְכָל אוֹתָם רִבְבוֹת קֹדֶשׁ שֶׁמְּמֻנִּים עַל שְׁאָר הָעַמִּים, וְהֵשִׁיבוּ לוֹ גַּם כָּךְ, וּמִכֻּלָּם קִבֵּל וְנָטַל מַתָּנוֹת לָתֵת לָהֶם לְיִשְׂרָאֵל. לְרוֹפֵא שֶׁהָיָה לוֹ כְּלִי אֶחָד מָלֵא סַם חַיִּים וּשְׁמָרוֹ לִבְנוֹ. רָצָה לָתֵת לִבְנוֹ אֶת אוֹתוֹ כְּלִי שֶׁמֶן אֲפַרְסְמוֹן שֶׁל סַם חַיִּים. הָרוֹפֵא הָיָה חָכָם, אָמַר: עֲבָדִים רָעִים יֵשׁ בְּבֵיתִי, אִם יֵדְעוּ שֶׁאֲנִי נוֹתֵן לִבְנִי אוֹצָר זֶה, יֵרַע בְּעֵינֵיהֶם וְיִרְצוּ לְהָרְגוֹ.</p>\n<p>מֶה עָשָׂה? לָקַח קְצָת סַם הַמָּוֶת וְנָתַן עַל פֶּתַח הַכְּלִי, קָרָא לַעֲבָדָיו וְאָמַר לָהֶם: אַתֶּם נֶאֱמָנִים לְפָנַי, הֲתִרְצוּ אֶת אוֹתוֹ הַסַּם? אָמְרוּ: נִרְאֶה מַה זֶּה. טֶרֶם הֵרִיחוּ רָצוּ לָמוּת. אָמְרוּ בְלִבָּם: אִם סַם זֶה יִתֵּן לִבְנוֹ, וַדַּאי יָמוּת, וְאָנוּ נִירַשׁ אֶת אֲדוֹנֵנוּ. אָמְרוּ לְפָנָיו: מוֹרֵנוּ, סַם זֶה לֹא רָאוּי אֶלָּא לְבִנְךְ, וַהֲרֵי שְׂכַר עֲבוֹדָתֵנוּ הִשְׁאַרְנוּ אֶצְלְךְ, לֵךְ וְתֵן לוֹ לְֹשחַד שֶׁיְּקַבֵּל סַם זֶה.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא רוֹפֵא חָכָם, יָדַע שֶׁאִם יִתֵּן תּוֹרָה לְיִשְׂרָאֵל טֶרֶם שֶׁיּוֹדִיעַ לָהֶם, בְּכָל יוֹם הָיוּ רוֹדְפִים אֶת יִשְׂרָאֵל עָלֶיהָ וְהוֹרְגִים אוֹתָם. אֲבָל עָשָׂה אֶת זֶה, וְהֵם נָתְנוּ לוֹ מַתָּנוֹת וְאוֹצָרוֹת כְּדֵי שֶׁיְּקַבְּלוּהָ, וְכֻלָּם קִבְּלָם מֹשֶׁה לְתִתָּם לְיִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (תהלים סח) עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי וְגוֹ'. וּמִשּׁוּם זֶה יָרְשׁוּ יִשְׂרָאֵל אֶת הַתּוֹרָה בְּלִי עִרְעוּר וּבְלִי קִטְרוּג כְּלָל. בָּרוּךְ הוּא, בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>בֹּא וּרְאֵה, עֶדְיָם שֶׁל בְּנֵי יִשְׂרָאֵל אֵלּוּ מַתָּנוֹת וְאוֹצָרוֹת שֶׁקִּבְּלוּ, וּמִשּׁוּם זֶה לֹא הָיָה שׁוֹלֵט עֲלֵיהֶם הַמָּוֶת וְלֹא צַד הָאַחֵר. וְלֹא דַי לָהֶם שֶׁלָּקְחוּ הַתּוֹרָה בְּלִי עִרְעוּר כְּלָל, אֶלָּא שֶׁקִּבְּלוּ אוֹצָרוֹת וּמַתָּנוֹת מִכֻּלָּם. כֵּיוָן שֶׁחָטְאוּ מַה כָּתוּב? (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם. הֵם מַתָּנוֹת בָּאָדָם. מַה נִּשְׁאַר מֵהֶם? אוֹתוֹ שְׁבִי, שֶׁכָּתוּב עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי וְגוֹ'.</p>\n<p>הוֹסִיפוּ וְחָטְאוּ, מַה כָּתוּב? (במדבר כא) וַיִּשְׁמַע הַכְּנַעֲנִי מֶלֶךְ עֲרָד. וְכָתוּב וַיִּלָּחֶם בְּיִשְׂרָאֵל וַיִּשְׁבְּ מִמֶּנּוּ שֶׁבִי. (ועם כל זה) וְכָל זְמַן שֶׁיִּשְׂרָאֵל שָׁבִים לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם, אוֹתָם אוֹצָרוֹת (והכל) חוֹזְרִים אֲלֵיהֶם וּמִתְכַּסִּים בָּהֶם, וְלֶעָתִיד לָבא הַכֹּל יַחֲזֹּר, שֶׁכָּתוּב (דברים ל) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְגוֹ'. מִכָּאן וָהָלְאָה אֱמֹר דְּבָרְךְ.</p>"],[9522012405,"<p>אָמַר רַבִּי יוֹסֵי, (שופטים ה) ה' בְּצֵאתְךְ מִשֵּׂעִיר בְּצַעַדְךְ מִשְּׂדֵה אֱדוֹם אֶרֶץ רָעָשָׁה. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁב מִשֵּׂעִיר, שֶׁלֹּא קִבְּלוּ אֶת הַתּוֹרָה, אֶרֶץ רָעָשָׁה וְגוֹ'. מָה הַטַּעַם רָעָשָׁה? מִשּׁוּם שֶׁרָצְתָה לַחֲזֹר לְתֹהוּ וָבֹהוּ, שֶׁכָּךְ הִתְנָה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם: אִם יְקַבְּלוּ בְּנֵי יִשְׂרָאֵל אֶת הַתּוֹרָה - מוּטָב, וְאִם לֹא - יַחֲזֹר הָעוֹלָם לְתֹהוּ וָבֹהוּ. כֵּיוָן שֶׁרָאֲתָה הָאָרֶץ שֶׁהֲרֵי הִזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הָעַמִּים לְקַבֵּל הַתּוֹרָה וְלֹא קִבְּלוּ, וּמִכָּל הָעַמִּים לֹא נִשְׁאֲרוּ אֶלָּא יִשְׂרָאֵל לְבַדָּם, חָשְׁבָה הָאָרֶץ שֶׁיִּשְׂרָאֵל לֹא יְקַבְּלוּ כְמוֹתָם, וּמִשּׁוּם זֶה אֶרֶץ רָעָשָׁה. כֵּיוָן שֶׁאָמְרוּ נַעֲשֶׂה וְנִשְׁמָע, מִיָּד שָׁקָטָה, זֶהוּ שֶׁכָּתוּב (תהלים עו) אֶרֶץ יָרְאָה וְשָׁקָטָה. יָרְאָה בַּהַתְחָלָה, וּלְבַסּוֹף וְשָׁקָטָה.</p>\n<p>וּבֹא וּרְאֵה, מִשּׁוּם שֶׁיִּשְׂרָאֵל אָמְרוּ נַעֲשֶׂה, לֹא פוֹחֲדִים מִכָּל עֲשִׂיָּה שֶׁיּוּכְלוּ כָּל מְכַשְּׁפֵי הָעוֹלָם לַעֲשׂוֹת, וְלֹא מִכָּל קְסָמִים וּכְשָׁפִים שֶׁל הָעוֹלָם. מָה הַטַּעַם? אֶחָד בִּגְלַל זֶה, וְאֶחָד מִשּׁוּם שֶׁכְּשֶׁהוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם מִמִּצְרַיִם, שָׁבַר לִפְנֵיהֶם כָּל מִינֵי כְשָׁפִים וּקְסָמִים שֶׁלֹּא יוּכְלוּ לִשְׁלֹט בָּהֶם, וְאוֹתָהּ שָׁעָה שֶׁבָּא בָלָק הוּא יָדַע זֹּאת. מִיָּד - וַיִּשְׁלַח מַלְאָכִים אֶל בִּלְעָם בֶּן בְּעוֹר פְּתוֹרָה אֲשֶׁר עַל הַנָּהָר וְגוֹ'. מַה זֶּה פְּתוֹרָה? אֶלָּא שֶׁיַּתְקִין שֻׁלְחָן וְיִרְצֶה מִשָּׁם עֵצָה מַה לַּעֲשׂוֹת. אֲשֶׁר עַל הַנָּהָר?! עַל הַנְּהָרִים הָיָה לוֹ לִכְתֹּב! מַה זֶּה עַל הַנָּהָר? וַדַּאי כָּךְ זֶה, שֶׁעַל נָהָר אֶחָד עוֹמֵד תָּמִיד.</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא הָיוּ הוֹלְכִים לִרְאוֹת אֶת רַבִּי יוֹסֵי בֶּן רַבִּי שִׁמְעוֹן בֶּן לָקוּנְיָא, חָמִיו שֶׁל רַבִּי אֶלְעָזָר. קָמוּ בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה. יָשְׁבוּ. אָמַר רַבִּי אֶלְעָזָר, כָּעֵת הוּא הַזְּמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ בַּצַּדִּיקִים שֶׁל שָׁם. אָמַר רַבִּי אַבָּא, שַׁעֲשׁוּעַ זֶה מַהוּ? וְאֵיךְ מִשְׁתַּעֲשֵׁעַ בָּהֶם? אָמַר רַבִּי אֶלְעָזָר, דָּבָר זֶה סוֹד נִסְתָּר הוּא, טָמִיר אֵלַי, שֶׁלֹּא יָדוּעַ. אָמַר לוֹ, וְכִי בְרֵיקָנוּת הָיוּ עַמּוּדִים גְּדוֹלִים שֶׁמִּלְפָנִים בָּעוֹלָם הַזֶּה שֶׁלֹּא יוֹדְעִים וְלֹא רָדְפוּ אַחֲרֶיהָ לָדַעַת עַל מָה עוֹמְדִים בָּעוֹלָם הַזֶּה, וּלְמָה הָיוּ מְצַפִּים בְּאוֹתוֹ עוֹלָם?</p>"],[9522012406,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיה כה) ה' אֱלֹהַי אַתָּה אֲרוֹמִמְךְ אוֹדֶה שִׁמְךְ כִּי עָשִׂיתָ וְגוֹ'. פָּסוּק זֶה הוּא סוֹד הָאֱמוּנָה. ה' - סוֹד עֶלְיוֹן, רֵאשִׁית נְקֻדָּה עֶלְיוֹנָה נִסְתֶּרֶת שֶׁלֹּא יְדוּעָה. אֱלֹהַי - סוֹד (מלכים איט) קוֹל דְּמָמָה דַקָּה, וְהִיא הָרֵאשִׁית שֶׁעוֹמֶדֶת לִשְׁאֵלָה, וְנִסְתְּרָה וְלֹא יְדוּעָה, וְאֵין מִי שֶׁמֵּשִׁיב עָלֶיהָ, מִשּׁוּם שֶׁהִיא נִסְתֶּרֶת וּטְמִירָה וּגְנוּזָה.</p>\n<p>אַתָּה - זוֹ הַיָּמִין, רֵאשִׁית שֶׁעוֹמֶדֶת לִשְׁאֵלָה וּלְהָשִׁיב בָּהּ, וְהוּא כֹּהֵן עֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קי) אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק. מַה זֶּה עַל דִּבְרָתִי מַלְכִּי צֶדֶק? אֶלָּא כֹּהֵן עֶלְיוֹן זֶה, שֶׁהוּא עוֹמֵד עַל דָּבָר, מִשּׁוּם שֶׁאוֹתוֹ דָּבָר לֹא עוֹמֵד אֶלָּא בְּיָמִין. וְאוֹתוֹ דָּבָר מַהוּ? מַלְכִּי צֶדֶק, כָּךְ שְׁמוֹ. וּמַה שֶּׁאָמַר דִּבְרָתִי, מִשּׁוּם שֶׁנִּקְשָׁר בְּדָוִד. וְכָל דִּבְרֵי הַשֶּׁבַח שֶׁלּוֹ בָּאוּ בְאוֹתוֹ דָּבָר. וְעַל זֶה דִּבְרָתִי. וּמִשּׁוּם זֶה, אַתָּה - זֶה כֹּהֵן. וַהֲרֵי בֵּאַרְנוּ שֶׁשְּׁלֹשָׁה מְקוֹמוֹת הֵם שֶׁכָּל אֵחָד נִקְרָא אַתָּה.</p>\n<p>אֲרוֹמִמְךָֹ, הַכֹּל כְּאֶחָד. אוֹדֶה שִׁמְךְ כָּרָאוּי, וְשֵׁם זֶה יָדוּעַ. כִּי עָשִׂיתָ פֶּלֶא, כִּסּוּי וּלְבוּשׁ לְהִתְלַבֵּשׁ אוֹר נִסְתָּר עַתִּיק, רֵאשִׁית הַדַּרְגָּה הָעֶלְיוֹנָה, אָדָם הָרִאשׁוֹן, טָמִיר בְּכִסּוּי שֶׁל אוֹר אַחֵר.</p>\n<p>דָּבָר אַחֵר כִּי עָשִׂיתָ פֶּלֶא - כִּי עָשִׂיתָ אָלֶ\"ף. וּמַהוּ אָלֶ\"ף? הֲרֵי שָׁנִינוּ, אָלֶ\"ף בֵּי\"ת, אַלֵּף בִּינָה. אֲבָל דְּמוּת שֶׁל א' הִיא שְׁלֹשָׁה צְדָדִים, רֵאשִׁית הַסּוֹד הָעֶלְיוֹן שֶׁל אָדָם הָרִאשׁוֹן, מִשּׁוּם שֶׁבִּדְמוּת א' יֵשׁ שְׁתֵּי זְרוֹעוֹת, אַחַת מִכָּאן וְאַחַת מִכָּאן, וְהַגּוּף בָּאֶמְצַע, וְהַכֹּל סוֹד אֶחָד, וְהוּא סוֹד הַיִּחוּד - א'. וּמִשּׁוּם כָּךְ אָלֶף לְחֶשְׁבּוֹן אֶחָד, וְהַיְנוּ כִּי עָשִׂיתָ פֶּלֶא. וְרַב הַמְנוּנָא סָבָא אָמַר כָּךְ, כִּי עָשִׂיתָ פֶּלֶא, פֶּלֶא זוֹהִי דַּרְגָּה אַחַת מֵאוֹתָם פִּלְאוֹת חָכְמָה, וּמִיהוּ? זֶה (איוב כח) נָתִיב לֹא יְדָעוֹ עָיִט. וְהוּא פֶּלֶא.</p>\n<p>עֵצוֹת מֵרָחֹק. קָרָא לָזֶה בַתְּחִלָּה פֶּלֶא, וְכָאן אָמַר פֶּלֶא עֵצוֹת מֵרָחֹק. אֶלָּא שָׁם צָרִיךְ לִמְנוֹת שִׁשָּׁה צְדָדִים לִדְרָגוֹת עֶלְיוֹנוֹת, (ישעיה ט) פֶּלֶא יוֹעֵץ אֵל גִּבּוֹר אֲבִי עַד שַׂר שָׁלוֹם. וְכָאן לֹא בָא לִמְנוֹת חֶשְׁבּוֹן. אֲבָל עֵצוֹת מֵרָחֹק מִי הֵם? שְׁנֵי בַּדֵּי עֲרָבוֹת, שֶׁכָּל עֵצָה שֶׁל הַנְּבִיאִים בָּא מִשָּׁם. הֵם נִקְרָאִים עֵצוֹת מֵרָחֹק. אֱמוּנָה אֹמֶן, שְׁנַיִם שֶׁהֵם אֶחָד, נָהָר וְגַן. זֶה יוֹצֵא מֵעֵדֶן, וְזֶה מֻשְׁקֶה מִמֶּנּוּ. הֲרֵי כָּאן כָּל הַסּוֹד הַנִּסְתָּר שֶׁל הָאֱמוּנָה.</p>"],[9522012407,"<p>אָמַר רַבִּי אֶלְעָזָר, בִּלְעָם הָרָשָׁע מִי הֲרָגוֹ, וְאֵיךְ נֶהֱרַג? אָמַר רַבִּי יִצְחָק, פִּנְחָס וְסִיעָתוֹ הֲרָגוּהוּ, שֶׁכָּתוּב (במדבר לא) הָרְגוּ עַל חַלְלֵיהֶם. וְשָׁנִינוּ, בְּעִיר מִדְיָן הָיָה עוֹשֶׂה בְחָכְמַת כְּשָׁפָיו שֶׁטָּסִים בָּאֲוִיר הוּא וּמַלְכֵי מִדְיָן. וְאִלְמָלֵא צִיץ הַקְּדֻשָּׁה וּתְפִלַּת פִּנְחָס שֶׁהִפִּילוּם עַל הַהֲרוּגִים. זֶהוּ שֶׁכָּתוּב עַל חַלְלֵיהֶם, וְכָתוּב (יהושע יג) וְאֶת בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם הָרְגוּ בְנֵי יִשְׂרָאֵל בַּחֶרֶב. אָמַר לוֹ רַבִּי אֶלְעָזָר, כָּל זֶה יָדַעְתִּי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, כָּל דִּבְרֵי בִלְעָם הָרָשָׁע תַּקִּיפִים הֵם, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁכָּתוּב (דברים לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. וְאָמְרוּ, בְּיִשְׂרָאֵל לֹא קָם, אֲבָל בְּאֻמּוֹת הָעוֹלָם קָם, וּמִיהוּ? בִּלְעָם, וַהֲרֵי בֵּאַרְנוּ הַדָּבָר, מֹשֶׁה אֵין כְּמוֹתוֹ בַּכְּתָרִים הָעֶלְיוֹנִים, בִּלְעָם אֵין כְּמוֹתוֹ בַּכְּתָרִים הַתַּחְתּוֹנִים. זֶה בְּצַד הַקְּדֻשָּׁה, וְזֶה בְּצַד שְׂמֹאל. וְאִם כָּל זֶה הָיָה בְיָדוֹ וְכָל כָּךְ תַּקִּיף בְּחָכְמָה, אָדָם שֶׁיְּשַׁבַּח אֶת עַצְמוֹ בְּכֹחַ תַּקִּיף, שֶׁכָּתוּב (במדבר כג) וְאָנֹכִי אִקָּרֶה כֹּה - אֶעֱקֹר אֶת כֹּה מִזֶּה, אֵיךְ יָכְלוּ לְהָרְגוֹ?</p>\n<p>אֶלָּא בְּסֵפֶר חָכְמַת שְׁלֹמֹה הַמֶּלֶךְ כָּךְ אָמַר: שְׁלֹשָׁה סִימָנִים הֵם; סִימָן לַעֲבֵרָה - יֵרָקוֹן. סִימָן לִשְׁטוּת - דְּבָרִים. סִימָן שֶׁלֹּא יוֹדֵעַ כְּלוּם - שְׁבָחִים. וְזֶה הִכְרִיעַ לַשְּׁאָר, שׁוֹטֶה בְּכָל עֲבֵרוֹת, הַכֹּל יֵשׁ בּוֹ.</p>\n<p>וַהֲרֵי כָּתוּב (משלי כז) יְהַלֶּלְךְ זָר וְלֹא פִיךְ. וְאִם לֹא זָר - פִּיךְ! - לֹא כָּךְ. אֶלָּא אִם אֵין מִי שֶׁמַּכִּיר אוֹתְךְ, פְּתַח פִּיךְ לְדַבֵּר בַּתּוֹרָה וּלְהוֹדִיעַ דִּבְרֵי אֱמֶת בַּתּוֹרָה, וְאָז פִּתְחוֹן פִּיךְ בַּתּוֹרָה יְשַׁבְּחוּ דְבָרֶיךְ וְיֵדְעוּ מִי אַתָּה, שֶׁאֵין דָּבָר בָּעוֹלָם שֶׁמּוֹדִיעַ עַל הָאִישׁ אֶלָּא בִּזְמַן שֶׁפּוֹתֵחַ פִּיו. פִּיו מוֹדִיעַ לִבְנֵי אָדָם מִי הוּא.</p>"],[9522012408,"<p>אוֹתוֹ בִּלְעָם הָרָשָׁע, תִּשְׁבָּחוֹת מְשַׁבֵּחַ עַצְמוֹ בַּכֹּל. וְעִם כָּל זֶה גְּנֵבַת דַּעַת הָיָה גּוֹנֵב, וְהִתְעַלָּה בִדְבָרָיו. בִּדְבָרִים קְטַנִּים הָיָה עוֹשֶׂה גְדוֹלִים. מַה שֶּׁאָמַר עַל אוֹתָן מַעֲלוֹת, דִּבְרֵי טֻמְאָה הָיָה אוֹמֵר, וֶאֱמֶת אָמַר. אֲבָל אוֹתוֹ רָשָׁע הָיָה אוֹמֵר וּמְשַׁבֵּחַ עַצְמוֹ בְּדֶרֶךְ נִסְתָּר, וְהִתְעַלָּה בִדְבָרָיו. שֶׁכָּל מִי שֶׁהָיָה שׁוֹמֵעַ, חָשַׁב שֶׁהִתְעַלָּה עַל כָּל נְבִיאֵי הָעוֹלָם, שֶׁכָּתוּב (במדבר טו) שּמֵעַ אִמְרֵי אֵל וְיֹדֵעַ דַּעַת עֶלְיוֹן. מִי הָאִישׁ בָּעוֹלָם שֶׁהָיָה שׁוֹמֵעַ מִפִּיו דְּבָרִים אֵלּוּ שֶׁלֹּא חָשַׁב שֶׁאֵין בָּעוֹלָם נָבִיא נֶאֱמָן כְּמוֹתוֹ?!</p>\n<p>וֶאֱמֶת הָיָה, וְכָךְ הָיָה. נְאֻם שֹׁמֵעַ אִמְרֵי אֵל, כָּךְ הָיָה. וְיֹדֵעַ דַּעַת עֶלְיוֹן, כָּךְ הָיָה. וְאוֹתוֹ רָשָׁע הָיָה אוֹמֵר עַל מַעֲלוֹת שֶׁנִּדְבַּק בָּהֶם, שּמֵעַ אִמְרֵי אֵל. דָּבָר שֶׁהוּא בְּמַעֲלָה עֶלְיוֹנָה.</p>\n<p>וְכָךָ אָמַר, שֹׁמֵעַ אִמְרֵי אֵל. לֹא כָתוּב הָאֵל, שֶׁהֲרֵי (תהלים יח) הָאֵל תָּמִים דַּרְכּוֹ. אֲבָל סְתָם אֵל, אֵל אַחֵר הוּא. (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר. שּמֵעַ אִמְרֵי אֵל - דָּבָר קָטָן הוּא, וְדוֹמֶה לְמִי שֶׁלֹּא יוֹדֵעַ שֶׁהוּא גָּדוֹל וְעֶלְיוֹן. שּמֵעַ אִמְרֵי אֵל - אוֹתוֹ שֶׁנִּקְרָא אֵל אַחֵר, שֶׁכָּתוּב כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר.</p>\n<p>וְיֹדֵעַ דַּעַת עֶלְיוֹן, עַל כָּל דַּרְגוֹת הַטֻּמְאָה, אוֹתָם שֶׁמְּנַהֲגִים אֳנִיַּת הַיָּם וּסְעָרָה. אַרְבָּעִים חָסֵר אֶחָד הֵם. וְאוֹתוֹ רַב חוֹבֵל שֶׁכֻּלָּם מֻנְהָגִים עַל יָדָיו, הוּא עֶלְיוֹן עַל כֻּלָּם. בָּזֶה הָיָה נִדְבַּק אוֹתוֹ רָשָׁע, וְאָמַר שֶׁהָיָה יוֹדֵעַ דַּעַת עֶלְיוֹן, דַּרְגָּה שֶׁהוּא עֶלְיוֹן עַל כָּל מַנְהִיגֵי הַסְּפִינָה. מִי שׁוֹמֵעַ זֶה שֶׁלֹּא יִבָּהֵל בְּדַעְתּוֹ וְיֹאמַר שֶׁאֵין כָּמוֹהוּ בָּעוֹלָם? אֶלָּא אוֹתוֹ רָשָׁע מְשַׁבֵּחַ אֶת עַצְמוֹ בְּדֶרֶךְ נִסְתָּר וְאָמַר דִּבְרֵי אֱמֶת, וְגָנַב דַּעַת בְּנֵי הָעוֹלָם.</p>\n<p>אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחֱזֶה. מִי שֶׁשּׁוֹמֵעַ אֶת זֶה חָשַׁב שֶׁהָיָה רוֹאֶה מַה שֶּׁלֹּא רָאָה אַחֵר בָּעוֹלָם. מַחֲזֵה שַׁדַּי - זֶה עָנָף אֶחָד מֵאוֹתָם עֲנָפִים שֶׁהָיוּ יוֹצְאִים מִשַּׁדַּי, וְלָמָּה? שֶׁבְּחָכְמָה זוֹ נִרְאִים שְׁלֹשָׁה כְּנֶגֶד ש' שֶׁל שַׁדַּי, כְּנֶגֶד שְׁלֹשָׁה עֲנָפִים שֶׁבּוֹ, וּמַרְאֵה שְׁנֵי נְבִיאִים, בַּדֵּי עֲרָבוֹת, שֶׁתּוֹמְכִים בּוֹ, כְּנֶגֶד שִׁבְעִים וּשְׁנַיִם עַנְפֵי עַיִן הָרָע לִסְתֹּם אוֹתָם. כְּשֶׁבָּא בָּלָק, אָמַר, אֲנִי אוּכַל לָהֶם. עֲמָלֵק בְּיַחַד עִם חָכְמָה זוֹ בָּא אֲלֵיהֶם וְיָכֹל לָהֶם.</p>\n<p>וְשָׁלַח לְבִלְעָם וְאָמַר לוֹ, אֲנִי יֵשׁ בִּי שְׁתֵּי אוֹתִיּוֹת שֶׁל עֲמָלֵק, שֶׁהֵם ל\"ק, שֶׁהֵם סִיּוּם עֲמָלֵ\"ק. לִי יֵשׁ ל\"ק, וַעֲמָלֵק ל\"ק. לִי הַסִּיּוּם, וּבְךְ הָרֵאשִׁית - ב\"ל. אָמַר לוֹ רַבִּי שִׁמְעוֹן, כָּךְ אֱמֹר, רֵאשִׁית בָּלָק ב\"ל, וְרֵאשִׁית בִּלְעָם ב\"ל. רֵאשִׁית בָּלָק הָיְתָה בּוֹ בְּבִלְעָם, וְסִיּוּם עֲמָלֵק הָיָה בְּבָלָק, וְסִיּוּם בִּלְעָם הָיָה רֵאשִׁית עֲמָלֵק.</p>\n<p>וְאִם תֹּאמַר שֶׁלֹּא נוּכַל לָהֶם מִשּׁוּם שֶׁכִּשְׁפֵי מֹשֶׁה רַבָּם שֶׁהָיָה פּוֹשֵׁט יָדָיו, הֲרֵי יָד זוֹ יֵשׁ בְּאוֹתָם גְּדוֹלִים שֶׁיְּכוֹלִים בִּכְשָׁפִים לְהִתְחַזֵּק יוֹתֵר. וְהַיְנוּ שֶׁכָּתוּב וּקְסָמִים בְּיָדָם. בִּידֵיהֶם לֹא כָתוּב, אֶלָּא בְּיָדָם. יָד מוּל יָד. כָּךְ שָׁלַח לוֹ בָּלָק לְבִלְעָם.</p>\n<p>וְלָכֵן מַחֲזֵה שַׁדַּי, כְּמוֹ שֶׁאָמַרְנוּ. וְלָכֵן נֶעֶנְשׁוּ, וְנֶעֶנְשׁוּ לְמַעְלָה, וְנִקְרָאִים מַחֲזֶה, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) וּמוּל מֶחֱזָה אֶל מֶחֱזָה. עָנָף שֶׁיּוֹצֵא מִשָּׁם. וּמִיהוּ אוֹתוֹ מַחֲזֶה? עֲזָא וַעֲזָאֵל, שֶׁהֵם נֹפֵל וּגְלוּי עֵינָיִם, וְהוּא מַחֲזֵה שַׁדַּי, שֶׁהָיָה רוֹאֶה נוֹפֵל וּגְלוּי עֵינַיִם.</p>"],[9522012409,"<p>אֵיפֹה הָיָה בִּלְעָם בְּאוֹתָהּ שָׁעָה? אִם תֹּאמַר בְּמִדְיָן, הֲרֵי כָּתוּב וְעַתָּה הִנְנִי הוֹלֵךְ לְעַמִּי. אִם הָלַךְ לוֹ, מִי נָתַן אוֹתוֹ בְּמִדְיָן? אֶלָּא אוֹתוֹ רָשָׁע, כֵּיוָן שֶׁרָאָה שֶׁנָּפְלוּ מִיִּשְׂרָאֵל כ\"ד אֶלֶף עַל עֲצוֹתָיו, הִתְעַכֵּב שָׁם, וְהָיָה רוֹצֶה מֵהֶם שְׂכָרוֹ. וּבְעוֹד שֶׁהִתְעַכֵּב שָׁם, בָּא פִּנְחָס וּגְדוֹלֵי הַחַיִל לְשָׁם.</p>\n<p>כֵּיוָן שֶׁרָאָה אֶת פִּנְחָס, פָּרַח בָּאֲוִיר, וּשְׁנֵי בָנָיו עִמּוֹ, יוֹנוֹס וְיוֹמְבְּרוֹס. וְאִם תֹּאמַר, הֲרֵי מֵתוּ בְּמַעֲשֵׂה הָעֵגֶל, שֶׁהֲרֵי הֵם עָשׂוּ אוֹתוֹ? אֶלָּא כָּךְ הָיָה בְּוַדַּאי, וְזֶהוּ שֶׁכָּתוּב (שמות לב) וַיִּפֹּל מִן הָעָם בַּיּוֹם הַהוּא כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ. וְכִי לֹא הָיוּ יוֹדְעִים חֶשְׁבּוֹן קָטָן זֶה? וַהֲרֵי כַּמָּה חֶשְׁבּוֹנוֹת רָמִים עֶלְיוֹנִים וּגְדוֹלִים יָדַע הַכָּתוּב לִמְנוֹת, וְכָאן כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ? אֶלָּא אֵלּוּ בְּנֵי בִלְעָם, יוֹנוֹ\"ס וְיוֹמְבְּרוֹ\"ס, שֶׁהָיוּ שְׁקוּלִים כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ.</p>\n<p>אֶלָּא אוֹתוֹ רָשָׁע, כָּל כִּשְׁפֵי הָעוֹלָם הָיָה יוֹדֵעַ, וְלָקַח גַּם כָּךְ כִּשְׁפֵי בָנָיו שֶׁהָיוּ רְגִילִים בָּהֶם, וּבָהֶם טָס וְעָלָה. פִּנְחָס רָאָה אוֹתוֹ, שֶׁהָיָה אָדָם אֶחָד טָס בָּאֲוִיר וְהָיָה מִתְעַלֶּה בָּאֲוִיר מֵהָעַיִן, הֵרִים קוֹל לִבְנֵי חַיִל וְאָמַר: יֵשׁ מִי שֶׁיּוֹדֵעַ לִפְרֹחַ אַחֲרֵי אוֹתוֹ רָשָׁע, שֶׁהֲרֵי בִּלְעָם הוּא? רָאוּ אוֹתוֹ שֶׁהָיָה טָס.</p>\n<p>צַלְיָה בֶּן שֵׁבֶט דָּן קָם, וְלָקַח שִׁלְטוֹן שֶׁשּׁוֹלֵט עַל כְּשָׁפִים וּפָרַח אַחֲרָיו. כֵּיוָן שֶׁרָאָה אוֹתוֹ אוֹתוֹ רָשָׁע, עָשָׂה דֶרֶךְ אַחֵר בָּאֲוִיר, וּבָקַע חֲמִשָּׁה אֲוִירִים בְּאוֹתוֹ דֶּרֶךְ, וְהִתְעַלָּה וְהִתְכַּסָּה מֵהָעַיִן, וְאָז הִסְתַּכֵּן צַלְיָה בְּאוֹתָהּ שָׁעָה וְהָיָה בְצַעַר, שֶׁלֹּא יָדַע מַה יַּעֲשֶׂה.</p>\n<p>הֵרִים אֵלָיו פִּנְחָס קוֹל וְאָמַר: צֵל הַתַּנִּינִים שֶׁרוֹבְצִים עַל כָּל הַנְּחָשִׁים, הֲפֹךְ בְּשַׂעֲרוֹתֶיךְ. מִיָּד יָדַע וְגִלָּה אוֹתוֹ מָקוֹם, וְנִכְנַס אֵלָיו. מִיָּד הִתְגַּלָּה, וְיָרְדוּ שְׁנֵיהֶם לִפְנֵי פִנְחָס.</p>\n<p>בֹּא וּרְאֵה, אוֹתוֹ רָשָׁע כָּתוּב בּוֹ וַיֵּלֶךְ שֶׁפִי, זֶהוּ עֶלְיוֹן שֶׁדַּרְגוֹתָיו נָחָשׁ זָכָר. צַלְיָה לָקַח שְׁנַיִם, זָכָר ונְקֵבָה, וּבוֹ שָׁלַט עָלָיו, מִשּׁוּם שֶׁהַשִּׁלְטוֹן שֶׁשּׁוֹלֵט עֲלֵיהֶם לָקַח וְהִתְכּוֹפְפוּ לְפָנָיו. וְזֶה הָיָה (בראשית מט) שְׁפִיפֹן עֲלֵי אֹרַח. עַל אוֹתוֹ אֹרַח שֶׁעָשָׂה אוֹתוֹ רָשָׁע, שֶׁכָּתוּב (שם) יְהִי דָן נָחָשׁ עֲלֵי דֱרֶךָ - זֶה שִׁמְשׁוֹן. שְׁפִיפֹן עֲלֵי ארַח - זֶה צַלְיָה.</p>\n<p>הַנֹּשֵּׁךָ עִקְּבֵי סוּס - זֶה עִירָה, שֶׁהָיָה עִם דָּוִד, שֶׁהָיָה בָּא מִדָּן, וּבִגְלָלוֹ תְלוּיָה גְבוּרָתוֹ בְּדָוִד, שֶׁכָּתוּב (שמואל ב ח) וַיְעַקֵּר דָּוִד אֶת כָּל הָרֶכֶב. וַיִּפֹּל רֹכְבוֹ אָחוֹר - זֶה שְׂרָיָה, שֶׁעָתִיד לָבֹא יַחַד עִם מָשִׁיחַ בֶּן אֶפְרַיִם, וְהוּא מִשֵּׁבֶט דָּן, וְעָתִיד הוּא לַעֲשׂוֹת נְקָמוֹת וּקְרָבוֹת בִּשְׁאָר הָעַמִּים. וּכְשֶׁזֶּה יָקוּם, אָז מְחַכֶּה לִגְאֻלַּת יִשְׂרָאֵל, שֶׁכָּתוּב (בראשית מט) לִישׁוּעָתְךְ קִוִּיתִי ה'. וְאַךְ עַל גַּב שֶׁפֵּרְשׁוּהוּ לְפָסוּק זֶה, אֲבָל בֵּרוּר הַדָּבָר כְּמוֹ שֶׁנֶּאֱמַר וּכְמוֹ שֶׁפֵּרְשׁוּהוּ, וְעַל זֶה בָּא הַפָּסוּק וּמוֹכִיחַ.</p>\n<p>כֵּיוָ שֶׁיָּרַד אוֹתוֹ רָשָׁע אֶל פִּנְחָס, אָמַר לוֹ: רָשָׁע! כַּמָּה גִלְגּוּלִים רָעִים עָשִׂיתָ עַל הָעָם הַקָּדוֹשׁ. אָמַר לוֹ לְצַלְיָה: בֹּא וַהֲרֹג אוֹתוֹ, וְלֹא בַשֵּׁם, שֶׁלֹּא רָאוּי זֶה לְהַזְכִּיר עָלָיו קְדֻשָּׁה עֶלְיוֹנָה, בִּשְׁבִיל שֶׁלֹּא תֵצֵא נִשְׁמָתוֹ וְתִכָּלֵל בִּדְבָרִים שֶׁל דְּרָגוֹת קְדוֹשׁוֹת, וְתִתְקַיֵּם בּוֹ מַה שֶּׁאָמַר תָּמוֹת נַפְשִׁי מוֹת יְשָׁרִים.</p>\n<p>בְּאוֹתָהּ שָׁעָה עָשָׂה בּוֹ כַּמָּה מִינֵי מָוֶת וְלֹא מֵת, עַד שֶׁלָּקַח חֶרֶב שֶׁהָיָה מְתֻקָּן (חקוק) עָלֶיהָ נָחָשׁ מִצַּד אֶחָד וְנָחָשׁ מִצַּד שֵׁנִי. אָמַר לוֹ פִּנְחָס: בְּשֶׁלּוֹ קַח (הרג אותו), וּבְשֶׁלּוֹ יָמוּת. אָז הָרַג אוֹתוֹ וְיָכֹל לוֹ. שֶׁכָּךָ דֶּרֶךָ אוֹתוֹ צַד - מִי שֶׁהוֹלֵךָ אַחֲרָיו, בּוֹ יָמוּת, וּבוֹ תֵצֵא נִשְׁמָתוֹ, וּבוֹ יִכָּלֵל. וְכָךָ מֵת בִּלְעָם, וְדָנִים אוֹתוֹ בְּדִינֵי אוֹתוֹ הָעוֹלָם וְלֹא נִקְבָּר לְעוֹלָמִים. וְכָל עַצְמוֹתָיו נִרֻקְבוּ, וְנַעֲשׂוּ כַּמָּה נְחָשִׁים מְזהָמִים מַזִּיקִים שְׁאָר בְּרִיּוֹת, וַאֲפִלּוּ הַתּוֹלָעִים שֶׁהָיוּ אוֹכְלִים בְּשָׂרוֹ הָפְכוּ לִנְחָשִׁים.</p>\n<p>מָצָאנוּ בְסִפְרוֹ שֶׁל אַשְׁמְדַאי שֶׁנָּתַן לִשְׁלֹמֹה הַמֶּלֶךָ, שֶׁכָּל מִי שֶׁהָיָה רוֹצֶה לַעֲשׂוֹת כְּשָׁפִים חֲזָקִים נִסְתָּרִים מֵהָעַיִן, אִם יֵדַע הַסֶּלַע שֶׁשָּׁם נָפַל בִּלְעָם, יִמְצָא מֵאוֹתָם נְחָשִׁים שֶׁהָיוּ מֵעַצְמוֹת אוֹתוֹ הָרָשָׁע, אִם יַהֲרֹג אֶחָד מֵהֶם - בְּרֹאשׁוֹ יַעֲשֶׂה כְשָׁפִים עֶלְיוֹנִים, בְּגוּפוֹ כְּשָׁפִים אֲחֵרִים, בִּזְנָבוֹ כְּשָׁפִים אֲחֵרִים. שְׁלֹשָׁה מִינֵי כְשָׁפִים בְּכָל אֶחָד וְאֶחָד.</p>\n<p>כְּשֶׁבָּאָה מַלְכַּת שְׁבָא לִשְׁלֹמֹה, מֵאוֹתָם דְּבָרִים שֶׁשָּׁאֲלָה אֶת שְׁלֹמֹה, אָמְרָה: עֶצֶם הַנָּחָשׁ שֶׁל שְׁלֹשָׁה רָאשִׁים בַּמֶּה נִתְפָּס? מִיָּד - (מלכים א י) לֹא הָיָה דָבָר נֶעְלָם מִן הַמֶּלֶךְ אֲשֶׁר לֹא הִגִּיד לָהּ. הִיא שָׁאֲלָה עַל זֶה, וְהָיְתָה צְרִיכָה אוֹתָם נְחָשִׁים, וְלֹא יָכְלָה לָקַחַת אֶחָד מֵהֶם. מַה הֵשִׁיב לָהּ? דְּבָרִים שֶׁהָיוּ בְלִבָּהּ. כָּךְ הוֹדִיעַ לָהּ, שֶׁכָּתוּב וַיַּגֶּד לָהּ שְׁלֹמֹה אֶת כָּל דְּבָרֶיהָ. אוֹתָם נְחָשִׁים לֹא יְכוֹלִים לָהֶם כָּל בְּנֵי הָעוֹלָם, פְּרָט לְדָבָר שֶׁל סוֹד אֶחָד. וּמַהוּ? שִׁכְבַת זֶרַע רוֹתַחַת.</p>\n<p>וְאִם תֹּאמַר, מִי יָכוֹל? אֶלָּא בְּשָׁעָה שֶׁהָאִישׁ מוֹצִיא אוֹתָהּ שִׁכְבַת זֶרַע כְּשֶׁהוּא בְּתַאֲוָה, מוֹצִיא אוֹתָהּ לְשֵׁם אוֹתוֹ נָחָשׁ בִּרְצוֹן הַתַּאֲוָה. כְּשֶׁיּוֹצֵאת רוֹתַחַת, לוֹקְחִים אוֹתָהּ מִיָּד בִּלְבוּשׁ אֶחָד, וְאוֹתוֹ לְבוּשׁ זוֹרְקִים לַנָּחָשׁ, מִיָּד כּוֹפֵף רֹאשׁוֹ, וְתוֹפְסִים אוֹתוֹ כְּמוֹ שֶׁתּוֹפְסִים תַּרְנְגוֹל הַבַּיִת. וְאִם בְּכָל כְּלֵי הַקְּרָב שֶׁל הָעוֹלָם יַעַרְכוּ בְאֶחָד מֵהֶם - לֹא יְכוֹלִים לֹא. וּבָזֶה לֹא צָרִיךְ אָדָם בָּעוֹלָם כְּלֵי קְרָב וְלֹא דָבָר אַחֵר, וְלֹא צָרִיךְ לְהִשָּׁמֵר מֵהֶם, שֶׁהֲרֵי כֻּלָּם נִכְפִּים אֵלָיו. אָז דָּבְקוּ הַדְּבָרִים הַלָּלוּ בְּלִבָּהּ, וְהִתְאַוְּתָה לָזֶה.</p>\n<p>מִכָּאן וָהָלְאָה, אֶלְעָזָר בְּנִי, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מַה שֶּׁעוֹשֶׂה בְּאוֹתוֹ רָשָׁע, וְסוֹדוֹת נִסְתָּרִים אֵלּוּ לֹא הִצְטָרְכוּ לְהִתְגַּלּוֹת. אֲבָל מִשּׁוּם שֶׁהַחֲבֵרִים שֶׁכָּאן יָדְעוּ דְרָכִים נִסְתָּרִים שֶׁל הָעוֹלָם, גִּלִּיתִי לָכֶם. שֶׁהֲרֵי כַּמָּה מִנְהָגִים נִסְתָּרִים הֵם בָּעוֹלָם וּבְנֵי אָדָם לֹא יוֹדְעִים, וְאוֹתָם פְּלָאוֹת נִסְתָּרִים, גְּדוֹלִים וְעֶלְיוֹנִים. עָלָיו וְעַל שֶׁדּוֹמֶה לוֹ קָרָאנוּ, (משלי י) וְשֵׁם רְשָׁעִים יִרְקָב. אַשְׁרֵיהֶם צַדִּיקֵי הָאֱמֶת, עֲלֵיהֶם כָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ וְגוֹ'.</p>"],[9522012410,"<p>וְעַתָּה לְכָה נָּא אָרָה לִּי אֶת הָעָם הַזֶּה וְגוֹ'. רַבִּי אַבָּא פָּתַח, (שם קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף וְגוֹ'. שְׁלֹשָׁה הֵם שֶׁכָּתוּב בָּהֶם תְּפִלָּה. וּבֵאֲרוּ דָבָר זֶה (אבל דבר זה) - אֶחָד הָיָה מֹשֶׁה, וְאֶחָד הָיָה דָּוִד, וְאֶחָד עָנִי, שֶׁנִּכְלָל בָּהֶם וְהִתְחַבֵּר בָּהֶם. וְאִם תֹּאמַר, הֲרֵי כָּתוּב (חבקוק ג) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא - הֲרֵי אַרְבָּעָה הֵם? אֶלָּא חֲבַקּוּק לֹא בִגְלַל תְּפִלָּה הָיָה, וְאַף עַל גַּב שֶׁכָּתוּב בּוֹ תְּפִלָּה, תִּשְׁבַּחַת וְהוֹדָאָה הִיא לַקָּדוֹשׁ-בָּרוּךְ-הוּא עַל שֶׁהֱחֱיָהוּ וְעָשָׂה אִתּוֹ נִסִּים וּגְבוּרוֹת, שֶׁהֲרֵי בֶּן הַשּׁוּנַמִּית הָיָה.</p>\n<p>אֲבָל שָׁלֹשׁ הֵן שֶׁנִּקְרָאוֹת תְּפִלָּה: (תהלים צ) תְּפִלָּה לְמֹשֶׁה אִישׁ הָאֱלֹהִים, תְּפִלָּה זוֹ שֶׁאֵין כְּמוֹתָהּ בְּאִישׁ אַחֵר. תְּפִלָּה לְדָוִד, תְּפִלָּה זוֹ הִיא תְּפִלָּה שֶׁאֵין כְּמוֹתָהּ בְּמֶלֶךְ אַחֵר. תְּפִלָּה לְעָנִי, תְּפִלָּה הִיא מֵאוֹתָן שָׁלֹשׁ. מִי חֲשׁוּבָה מִכֻּלָּן? הֱוֵי אוֹמֵר תְּפִלַּת הֶעָנִי. תְּפִלָּה זוֹ קוֹדֶמֶת לִתְפִלַּת מֹשֶׁה, וְקוֹדֶמֶת לִתְפִלַּת דָּוִד, וְקוֹדֶמֶת לְכָל שְׁאָר תְּפִלּוֹת הָעוֹלָם.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁהֶעָנִי הוּא שְׁבוּר לֵב, וְכָתוּב (שם לד) קָרוֹב ה' לְנִשְׁבְּרֵי לֵב וְגוֹ'. וְהֶעָנִי עוֹשֶׂה תָמִיד קְטָטָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב וְשׁוֹמֵעַ דְּבָרָיו. כֵּיוָן שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ, פּוֹתֵחַ כָּל חַלּוֹנוֹת הָרְקִיעִים, וְכָל שְׁאָר הַתְּפִלּוֹת שֶׁעוֹלֶה לְמַעְלָה, דּוֹחֶה אוֹתָן אוֹתוֹ עָנִי שְׁבוּר לֵב, שֶׁכָּתוּב תְּפִלָּה לְעָנִי כִי יַעֲטֹף. כִּי יִתְעַטֵּף צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה כִי יַעֲטֹף? אֶלָּא הוּא עוֹשֶׂה עִטּוּף לְכָל תְּפִלּוֹת הָעוֹלָם, וְלֹא נִכְנָסוֹת עַד שֶׁנִּכְנֶסֶת תְּפִלָּתוֹ.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא אוֹמֵר: יִתְעַטְּפוּ כָּל הַתְּפִלּוֹת, וּתְפִלָּה זוֹ תִּכָּנֵס אֵלַי. אֵינִי רוֹצֶה כָּאן בֵּית דִּין שֶׁיִּדּוֹן בֵּינֵינוּ. לְפָנַי יִהְיוּ תַּרְעוֹמוֹת שֶׁלּוֹ, וַאֲנִי וְהוּא לְבַדֵּנוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְיַחֵד לְבַדּוֹ בְּאוֹתָן הַתַּרְעוֹמוֹת, בְּאוֹתָהּ תְּפִלָּה, שֶׁכָּתוּב וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ. לִפְנֵי ה' בְּוַדַּאי.</p>\n<p>כָּל חֵילוֹת הַשָּׁמַיִם שׁוֹאֲלִים אֵלֶּה לְאֵלֶּה: בַּמֶּה מִתְעַסֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא? בַּמֶּה מִשְׁתַּדֵּל? אוֹמְרִים: מִתְיַחֵד בְּעֶרְגָּה בַּכֵּלִים שֶׁלּוֹ. כֻּלָּם לֹא יוֹדְעִים מַה נַּעֲשֶׂה מִתְּפִלַּת אוֹתוֹ עָנִי וּמִכָּל אוֹתָן תַּרְעוֹמוֹתָיו. שֶׁאֵין תַּאֲוָה לֶעָנִי אֶלָּא כְּשֶׁשּׁוֹפֵךְ דִּמְעוֹתָיו בְּתַרְעֹמֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְאֵין תַּאֲוָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא כְּשֶׁמְּקַבֵּל אוֹתָם וְנִשְׁפָּכִים לְפָנָיו. וְזוֹהִי תְפִלָּה שֶׁעוֹשָׂה עִטּוּף וְעוֹטֶפֶת כָּל תְּפִלּוֹת הָעוֹלָם.</p>\n<p>מֹשֶׁה הִתְפַּלֵּל תְּפִלָּתוֹ, וְהִתְעַכֵּב כַּמָּה יָמִים בִּתְפִלָּה זוֹ. דָּוִד רָאָה שֶׁכָּל הַחַלּוֹנוֹת וְכָל שַׁעֲרֵי הַשָּׁמַיִם, כֻּלָּם מְזֻמָּנִים לְהִפָּתֵחַ לְעָנִי, וְאֵין בְּכָל תְּפִלּוֹת הָעוֹלָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב מִיָּד כְּמוֹ לִתְפִלַּת הֶעָנִי. כֵּיוָן שֶׁרָאָה אֶת זֶה, עָשָׂה עַצְמוֹ עָנִי וּמִסְכֵּן. פָּשַׁט לְבוּשׁ הַמַּלְכוּת וְיָשַׁב עַל הָאָרֶץ כְּמוֹ עָנִי וְאָמַר תְּפִלָּה, שֶׁכָּתוּב (תהלים פו) תְּפִלָּה לְדָוִד הַטֵּה ה' אָזְנְךְ עֲנֵנִי. וְאִם תֹּאמַר לָמָּה? בִּגְלַל כִּי עָנִי וְאֶבְיוֹן אָנִי. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, דָּוִד, וְלֹא מֶלֶךְ אַתָּה, וְשׁוֹלֵט עַל מְלָכִים חֲזָקִים, וְאַתָּה עוֹשֶׂה עַצְמְךְ עָנִי וְאֶבְיוֹן?! מִיָּד הֶחֱזִיר תְּפִלָּתוֹ לְגָוֶן אַחֵר וְעָזַב דְּבַר אֶבְיוֹן וְעָנִי, וְאָמַר שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי. וְעִם כָּל זֶה, הַכֹּל הָיָה בְּדָוִד.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, יָפֶה אָמַרְתָּ, וְעִם כָּל זֶה (ועל זה) צָרִיךְ לְאָדָם שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ (להיות שם עני ואביון) לַעֲשׂוֹת עַצְמוֹ עָנִי, כְּדֵי שֶׁתִּכָּנֵס תְּפִלָּתוֹ בִּכְלַל כָּל הָעֲנִיִּים. שֶׁהֲרֵי כָּל שׁוֹמְרֵי הַשְּׁעָרִים לֹא מַשְׁאִירִים כָּךְ לְהִכָּנֵס כְּמוֹ שֶׁמַּשְׁאִירִים אֶת הָעֲנִיִּים, שֶׁהֲרֵי בְּלִי רְשׁוּת נִכְנָסִים. וְאִם עוֹשֶׂה אָדָם עַצְמוֹ וְשָׂם רְצוֹנוֹ תָּמִיד כְּעָנִי, תְּפִלָּתוֹ עוֹלָה וְנִפְגֶּשֶׁת עִם אוֹתָן תְּפִלּוֹת הָעֲנִיִּים וּמִתְחַבֶּרֶת אִתָּן, וְעוֹלָה יַחַד אִתָּן וְנִכְנֶסֶת בִּכְלָלָן, וּמִתְקַבֶּלֶת בְּרָצוֹן לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ (בהם).</p>"],[9522012411,"<p>דָּוִד הַמֶּלֶךְ שָׂם אֶת עַצְמוֹ בְּאַרְבָּעָה דְרָכִים: שָׂם עַצְמוֹ יַחַד עִם עֲנִיִּים, שָׂם עַצְמוֹ יַחַד עִם חֲסִידִים, שָׂם עַצְמוֹ יַחַד עִם עֲבָדִים, וְשָׂם עַצְמוֹ יַחַד עִם אוֹתָם שֶׁמּוֹסְרִים עַצְמָם וְנַפְשָׁם עַל קְדֻשַּׁת שְׁמוֹ. שָׂם עַצְמוֹ עִם עָנִי, שֶׁכָּתוּב כִּי עָנִי וְאֶבְיוֹן אָנִי. שָׂם עַצְמוֹ יַחַד עִם חֲסִידִים, שֶׁכָּתוּב שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי, מִשּׁוּם שֶׁצָּרִיךְ הָאָדָם שֶׁלֹּא לָשִׂים עַצְמוֹ רָשָׁע. וְאִם תֹּאמַר, אִם כָּךְ, לֹא יְפָרֵט חֲטָאָיו לְעוֹלָמִים? לֹא כָּךְ! אֶלָּא כְּשֶׁיְּפָרֵט חֲטָאָיו, אָז הוּא חָסִיד, שֶׁבָּא לְקַבֵּל תְּשׁוּבָה. מוֹצִיא עַצְמוֹ מִצַּד הָרָע שֶׁהָיָה בַּטִּנֹּפֶת שֶׁלּוֹ עַד עַכְשָׁו, וְכָעֵת נִדְבָּק בַּיָּמִין הָעֶלְיוֹן, שֶׁהִיא פְשׁוּטָה לְקַבְּלוֹ.</p>\n<p>וְלֹא תֹאמַר שֶׁלֹּא יְקַבְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁיְּפָרֵט חֲטָאָיו מִיּוֹם שֶׁהָיָה בָּעוֹלָם, (אם כך) אֵיפֹה (או) אוֹתָם שֶׁהִתְכַּסּוּ מִמֶּנּוּ, שֶׁלֹּא יָכוֹל לְהַגִּיעַ. אֶלָּא לֹא צָרִיךְ לְפָרֵשׁ, פְּרָט לְאוֹתָם שֶׁיִּזְכֹּר מָהֵם. וְאִם שָׂם רְצוֹנוֹ בָהֶם, כָּל הָאֲחֵרִים נִמְשָׁכִים אַחֲרֵיהֶם. שֶׁהֲרֵי לָמַדְנוּ, אֵין בּוֹדְקִים חוֹרֵי הַבַּיִת הָעֶלְיוֹנִים לְמַעְלָה, וְלֹא אוֹתָם תַּחְתּוֹנִים לְמַטָּה בְּבִעוּר חָמֵץ. אֵין כֵּיוָן שֶׁבָּדַק כְּפִי מַרְאֵה עֵינָיו מַה שֶּׁיָּכוֹל לְהַגִּיעַ, הַכֹּל נִמְשָׁךְ אַחֲרֵי זֶה וְהִתְבַּטֵּל יַחַד אִתּוֹ.</p>\n<p>וְכָךָ גָּרַסְנוּ בִנְגָעִים: עֶשְׂרִים וְאַרְבָּעָה רָאשֵׁי אֵיבָרִים הֵם שֶׁלֹּא מְטַמְּאִים מִשּׁוּם מִחְיָה. וְהַכֹּהֵן לֹא טוֹרֵחַ אַחֲרֵיהֶם, וְהַיְנוּ מַה שֶּׁכָּתוּב, (ויקרא יג) לְכָל מַרְאֵה עֵינֵי הַכֹּהֵן. מָקוֹם שֶׁיָּכוֹל לִרְאוֹת מַכְתֵּשׁ בְּהִסְתַּכְּלוּת אַחַת, וְלֹא צָרִיךְ לְהַנְמִיךְ אֶת עַצְמוֹ וּלְהָרִים עֵינָיו כָּאן וְכָאן. גַּם כָּךְ לֹא צָרִיךְ לְפָרֵט חֲטָאָיו (לבקש) מִיּוֹם שֶׁהָיָה, שֶׁהֲרֵי חוֹרֵי הַבַּיִת הַתַּחְתּוֹנִים, וְלֹא אֵלּוּ שֶׁהִתְכַּסּוּ שֶׁלֹּא יָכוֹל לְהַגִּיעַ, שֶׁהֵם חוֹרֵי הַבַּיִת הָעֶלְיוֹנִים לְמַעְלָה, (אלא) בֹּא רְאֵה, לְכָל מַרְאֵה עֵינֵי הַכֹּהֵן. וְכֻלָּם נִמְשָׁכִים אַחֲרֵיהֶם. וְעַל זֶה שָׂם דָּוִד עַצְמוֹ בְּתוֹךְ הַחֲסִידִים.</p>\n<p>הוּא שָׂם עַצְמוֹ יַחַד עִם עֲבָדִים, שֶׁכָּתוּב (תהלים קכג) הִנֵּה כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם. וְכָתוּב (שם פו) הוֹשַׁע עַבְדְּךְ אַתָּה אֱלֹהַי. שָׂם עַצְמוֹ עִם אוֹתָם שֶׁמָּסְרוּ נַפְשָׁם עַל קְדֻשַּׁת שְׁמוֹ, שֶׁכָּתוּב (שם) שַׂמֵּחַ נֶפֶשׁ עַבְדֶּךְ כִּי אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. בְּכָל הָאַרְבָּעָה הַלָּלוּ שָׂם עַצְמוֹ דָּוִד הַמֶּלֶךְ לִפְנֵי אֲדוֹנוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הֵרַמְתִּי יָדִי בִּתְפִלָּה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. שֶׁהֲרֵי שָׁנִינוּ, אָסוּר לוֹ לָאָדָם לְהָרִים יָדָיו לְמַעְלָה פְּרָט לִתְפִלָּה, וּבִבְרָכוֹת וּבְתַחֲנוּנִים לַאֲדוֹנוֹ, שֶׁכָּתוּב (בראשית יד) הֲרִמֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן, וּמְתַרְגְּמִים: הֵרַמְתִּי יָדִי בִּתְפִלָּה. שֶׁהֲרֵי בְּאֶצְבְּעוֹת הַיָּדַיִם יֵשׁ דְּבָרִים עֶלְיוֹנִים. וְכָעֵת כָּךְ אֲנִי עוֹשֶׂה, וְאוֹמֵר שֶׁכָּל מִי שֶׁאַרְבָּעָה אֵלּוּ יְסַדֵּר לִפְנֵי אֲדוֹנוֹ וְעוֹשֶׂה עַצְמוֹ בְרָצוֹן בְּתִקּוּן זֶה כָּרָאוּי, בְּתִקּוּן זֶה לֹא תַחֲזֹר תְּפִלָּתוֹ רֵיקָם.</p>\n<p>בַּתְּחִלָּה עֶבֶד - לְסַדֵּר שֶׁבַח לִפְנֵי אֲדוֹנוֹ וּלְזַמֵּר לְפָנָיו, וְזֶה בַּתִּשְׁבָּחוֹת שֶׁלִּפְנֵי הַתְּפִלָּה. אַחַר כָּךְ עֶבֶד לְאַחַר שֶׁהִתְפַּלֵּל תְּפִלַּת עֲמִידָה, הוּא עֶבֶד שֶׁסִּדֵּר תְּפִלַּת אֲדוֹנוֹ. אַחַר כָּךְ עֶבֶד אַחַר שֶׁהִתְפַּלֵּל כָּל תְּפִלָּתוֹ וְהָלַךְ לוֹ. וְעַל זֶה עָשָׂה עַצְמוֹ דָּוִד שָׁלֹשׁ פָּעָמִים בִּתְפִלָּה זוֹ עֶבֶד, שֶׁכָּתוּב הוֹשַׁע עַבְדְּךְ אַתָּה אֱלֹהַי. שַׂמֵּחַ נֶפֶשׁ עַבְדֶּךְ. וְכָתוּב (תהלים פו) תְּנָה עֻזְּךְ לְעַבְדֶּךְ. הֲרֵי שָׁלֹשׁ פְּעָמִים צָרִיךְ לָשִׂים עַצְמוֹ עֶבֶד.</p>\n<p>אַחַר כָּךְ לָשִׂים עַצְמוֹ תּוֹךְ אֵלּוּ שֶׁמָּסְרוּ נַפְשָׁם עַל קְדֻשַּׁת שְׁמוֹ, כְּלוֹמַר בַּיִּחוּד שֶׁל שְׁמַע יִשְׂרָאֵל. שֶׁכָּל מִי שֶׁשָּׂם כָּךְ רְצוֹנוֹ בְּזֶה הַפָּסוּק, נֶחְשָׁב לוֹ כְּאִלּוּ מָסַר עַצְמוֹ עַל קְדֻשַּׁת הַשֵּׁם.</p>\n<p>לְאַחַר שֶׁשָּׂם עַצְמוֹ עָנִי, בִּזְמַן שֶׁנִּכְנָס וְדוֹפֵק עַל פְּתָחִים שֶׁל רוּמֵי מְרוֹמִים, כְּשֶׁאוֹמֵר אֱמֶת וְיַצִּיב (וסומך) גְּאֻלָּה לִתְפִלָּה, לִהְיוֹת בִּתְפִלַּת עֲמִידָה שְׁבוּר לֵב עָנִי וּמִסְכֵּן. וְלָשִׂים רְצוֹנוֹ לְהִכָּלֵל בְּתוֹךְ הָעֲנִיִּים בְּשִׁבְרוֹן לֵב בִּנְמִיכוּת נֶפֶשׁ.</p>\n<p>לְאַחַר שֶׁשָּׂם עַצְמוֹ בְּתוֹךְ חֲסִידִים בְּשׁוֹמֵעַ תְּפִלָּה לְפָרֵשׁ חֲטָאָיו, שֶׁכָּךְ צָרִיךְ יָחִיד בְּשׁוֹמֵעַ תְּפִלָּה בִּשְׁבִיל לְהִתְדַּבֵּק בַּיָּמִין שֶׁפְּשׁוּטָה לְקַבֵּל שָׁבִים, אָז נִקְרָא חָסִיד. הֲרֵי אַרְבָּעָה אֵלֶּה כָּרָאוּי.</p>\n<p>מִי כּוֹלֵל כָּל אֵלֶּה? אוֹתוֹ שֶׁצָּרִיךְ לִכְלֹל אוֹתָם, וְזֶהוּ עֶבֶד שֶׁכּוֹלֵל אֶת כָּל הַשְּׁאָר. שְׁלֹשָׁה עֲבָדִים הֵם בִּשְׁלֹשָׁה מְקוֹמוֹת, וְכֻלָּם אֶחָד. וַעֲלֵיהֶם כָּתוּב (שם קכג) הִנֵּה כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם וְגוֹ'. בֵּין עֶבֶד לְעֶבֶד הֵם אוֹתָם אֲחֵרִים. בֵּין עֶבֶד רִאשׁוֹן לְעֶבֶד שֵׁנִי יֵשׁ לוֹ לִמְסֹר נַפְשׁוֹ עַל יִחוּד קְדֻשַּׁת שְׁמוֹ, וְלָשִׂים עַצְמוֹ עָנִי וּמִסְכֵּן בִּתְפִלַּת עֲמִידָה, וְלָשִׂים עַצְמוֹ בְּתוֹךְ חֲסִידִים בְּשׁוֹמֵעַ תְּפִלָּה. עֶבֶד שְׁלִישִׁי לְאַחַר שֶׁסִּיֵּם וְסִדֵּר הַכֹּל.</p>\n<p>לָמַדְנוּ, בְּאוֹתָהּ שָׁעָה שֶׁמְּסַדֵּר בֶּן אָדָם כָּל אַרְבָּעָה הַסִּדּוּרִים הַלָּלוּ בִּרְצוֹן הַלֵּב, נוֹחַ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּפוֹרֵשׂ יְמִינוֹ עָלָיו, בְּאוֹתוֹ עֶבֶד שְׁלִישִׁי, וְקוֹרֵא עָלָיו וְאוֹמֵר לוֹ עַבְדִּי אַתָּה, שֶׁכָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. וַדַּאי תְּפִלָּה שֶׁל אָדָם זֶה לֹא תַחֲזֹר רֵיקָם לְעוֹלָמִים. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בֹּא וּרְאֵה, שְׁנֵי עֶבֶד מֵאוֹתָם הַשְּׁלֹשָׁה הֵם שֶׁכּוֹלְלִים כָּל אֵלֶּה, שֶׁהֲרֵי הַשְּׁלִישִׁי עוֹמֵד לַחְתֹּם בּוֹ חוֹתַם לְמַעְלָה לָשִׂים בּוֹ יָד מִימִין הַמֶּלֶךְ וּלְהִשְׁתַּבֵּחַ בּוֹ. אֲבָל שְׁנֵי אֵלֶּה, רִאשׁוֹן וְשֵׁנִי, הֵם כְּלַל הַכֹּל. וְדָוִד מְשַׁבֵּחַ עַצְמוֹ בָהֶם, שֶׁכָּתוּב (תהלים קטז) אָנָּה ה' כִּי אֲנִי עַבְדֶּךְ אֲנִי עַבְדְּךְ וְגוֹ', שֶׁאֵלּוּ כוֹלְלִים כָּל הַשְּׁאָר. שְׁלִישִׁי בְּךְ עוֹמֵד לִגְאֹל אוֹתִי, שֶׁכָּתוּב הוֹשַׁע עַבְדְּךְ אַתָּה אֱלֹהַי. מִי שֶׁמְּסַדֵּר אֶת זֶה, שֶׁיִּהְיֶה יָדוּעַ לוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ, וְקוֹרֵא עָלָיו עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ.</p>\n<p>אָמַר רַבִּי אַבָּא, עַל זֶה קָרָאנוּ, (שם יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וְגוֹ'. כַּמָּה מְתוּקִים דְּבָרִים עַתִּיקִים שֶׁסִּדְּרוּ הָרִאשׁוֹנִים. וְאָנוּ, כְּשֶׁטּוֹעֲמִים אוֹתָם, לֹא יְכוֹלִים לֶאֱכֹל. וַדַּאי זֶה כָּךְ, וְהַפָּסוּק מוֹכִיחַ עַל שְׁלֹשָׁה עֲבָדִים, וְהֵם אֶחָד וּבְמָקוֹם אֶחָד. וּשְׁנַיִם כְּפִי שֶׁאָמַרְתָּ, וְאֶחָד הוּא לְהִתְעַטֵּר בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים עֲבָדַי הֵם וְגוֹ'. לֹא יִמָּכְרוּ מִמְכֶּרֶת עָבֶד. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא צָרִיךְ לְהִתְעַטֵּר בִּשְׁלֹשֶׁת אֵלֶּה. וְעַל זֶה לֹא יִמָּכְרוּ לְשֵׁם עֶבֶד, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיה נ) מִי בָכֶם יְרֵא ה' וְגוֹ'. מַה זֶּה שּמֵעַ בְּקוֹל עַבְדּוֹ? פָּסוּק זֶה בֵּאֲרוּהוּ הַחֲבֵרִים בִּתְפִלָּה, וְכָךְ הוּא. מִי שֶׁרָגִיל לָבֹא לְבֵית הַכְּנֶסֶת לְהִתְפַּלֵּל וְיוֹם אֶחָד לֹא בָא, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל עָלָיו וְאוֹמֵר: מִי בָכֶם יְרֵא ה' שֹׁמֵעַ בְּקוֹל עַבְדּוֹ אֲשֶׁר הָלַךְ חֲשֵׁכִים וְאֵין נֹגַהּ לוֹ. מַה זֶּה שּמֵעַ בְּקוֹל עַבְדּוֹ? בְּמִי? אִם תֹּאמַר בְּנָבִיא אוֹ בְאִישׁ אַחֵר - מִי נָתַן נָבִיא אוֹ אָדָם אַחֵר לִתְפִלָּה, שֶׁמִשּׁוּם שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ שׁוֹמֵעַ בְּקוֹל נָבִיא אוֹ אָדָם בָּעוֹלָם?!</p>\n<p>אֶלָּא אוֹתוֹ שֶׁמִּתְפַּלֵּל תְּפִלּוֹת בְּכָל יוֹם, הוּא שׁוֹמֵעַ בְּאוֹתוֹ קוֹל שֶׁקּוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִשְׁתַּבֵּחַ בּוֹ וְאָמַר שֶׁהוּא עַבְדּוֹ וַדַּאי. שּמֵעַ בְּקוֹל, בְּאֵיזֶה קוֹל? בְּאוֹתוֹ שֶׁנִּקְרָא עַבְדּוֹ. שֶׁבַח עֶלְיוֹן הוּא שֶׁיּוֹצֵא עָלָיו קוֹל שֶׁהוּא עַבְדּוֹ. וְעוֹד, שֶׁקּוֹל נִשְׁמָע בְּכָל אוֹתָם רְקִיעִים שֶׁהוּא עֶבֶד הַמֶּלֶךְ הַקָּדוֹשׁ, וְזֶהוּ שׁוֹמֵעַ בְּקוֹל עַבְדּוֹ.</p>\n<p>אֲשֶׁר הָלַךְ חֲשֵׁכִים וְאֵין נֹגַהּ לוֹ. וְכִי מִשּׁוּם שֶׁלֹּא בָא לְהִתְפַּלֵּל הָלַךְ חֲשֵׁכִים? אֶלָּא פֵּרְשׁוּהָ. אֲבָל עַד שֶׁלֹּא יִתְכַּנְּסוּ יִשְׂרָאֵל לְבָתֵּי כְנֵסִיּוֹת לְהִתְפַּלֵּל, הַצַּד הָאַחֵר עוֹמֵד וְסוֹגֵר כָּל הָאוֹרוֹת הָעֶלְיוֹנִים שֶׁלֹּא יִתְפַּשְּׁטוּ וְיֵצְאוּ עַל הָעוֹלָם. וְשָׁלֹשׁ פְּעָמִים בְּיוֹם הוֹלְכִים צַד הָאַחֵר, זָכָר וּנְקֵבָה, וּמְשׁוֹטְטִים בָּעוֹלָם. וְאוֹתוֹ זְמַן נִתְקָן לִתְפִלָּה, מִשּׁוּם שֶׁאֵין שָׁם קִטְרוּג כְּלָל.</p>\n<p>וְאָז הוּא זְמַן לִתְפִלָּה, מִשּׁוּם שֶׁהֵם הוֹלְכִים לְשׁוֹטֵט בְּהָרֵי הַחֹשֶׁךְ, וְהַר נִשְׁפֶּה, אָז נִפְתָּחִים חַלּוֹנוֹת אוֹרוֹת עֶלְיוֹנִים, וְיוֹצְאִים וְשׁוֹרִים עַל בָּתֵּי כְּנֵסִיּוֹת בְּרֹאשׁ אֵלּוּ שֶׁמִּתְפַּלְלִים תְּפִלּוֹת, וּמִתְחַלְּקִים אוֹרוֹת עַל רָאשֵׁיהֶם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל עַל אוֹתוֹ שֶׁלֹּא נִמְצָא שָׁם וְאוֹמֵר: חֲבָל עַל פְּלוֹנִי שֶׁהָיָה רָגִיל כָּאן, וְכָעֵת שֶׁהָלַךְ חֲשֵׁכִים וְעָבַר מִלִּפְנֵי הָאוֹרוֹת וְהָלַךְ לְשׁוֹטֵט בְּהָרֵי הָעוֹלָם, וְיָצָא מֵאוֹתוֹ נֹגַהּ אוֹר שֶׁמֵּאִיר וְאֵין (לו) בּוֹ חֵלֶק, אֵין נֹגַהּ לוֹ, כְּמוֹ שֶׁמִּתְחַלֵּק וְשׁוֹרֶה עַל הָאֲחֵרִים שֶׁשָּׁם, כַּמָּה טוֹבוֹת אָבְדוּ מִמֶּנּוּ. (אין נגה לו כעת שהלך חשכים) וְאִלּוּ הָיָה שָׁם, יִבְטַח בְּשֵׁם ה' - בִּכְלַל הָעֶבֶד הָרִאשׁוֹן, וְיִשָּׁעֵן בֵּאלֹהָיו - בְּסוֹד הָעֶבֶד הַשֵּׁנִי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, וַדַּאי רוּחַ נְבוּאָה שׁוֹרָה עָלֶיךְ. אָמַר רַבִּי אַבָּא, אַרְיֵה בֶּן אַרְיֵה, מִי יָקוּם לִפְנֵיהֶם כְּשֶׁשּׁוֹאֲגִים לִטְרֹף טֶרֶף? כָּל אַרְיוֹת הָעוֹלָם הֵם תַּקִּיפִים, וְאֵלֶּה יוֹתֵר מִכֻּלָּם. כָּל הָאֲרָיוֹת שֶׁבָּעוֹלָם קָשִׁים לְהוֹצָאַת הַטֶּרֶף מִפִּיהֶם, וְאֵלּוּ נוֹחִים לְהוֹצִיא מִפִּיהֶם טֶרֶף. הֵם טוֹרְפִים טֶרֶף וְנוֹתְנִים לְכֻלָּם.</p>\n<p>אֲשֶׁר הָלַךְ חֲשֵׁכִים, אֲשֶׁר הָלְכוּ צָרִיךְ לוֹ לִכְתֹּב! אָמַר רַבִּי אֶלְעָזָר, מִשּׁוּם שֶׁהֵם שְׁרוּיִים בְּחִבּוּר וּמִיָּד נִפְרָדִים. הָלַךְ הַחִבּוּר - חֲשֵׁכִים נִפְרְדוּ. שׁוֹרִים בְּחִבּוּר וְנִפְרָדִים מִיָּד. כְּמוֹ זֶה (יחזקאל א) רוּחַ סְעָרָה בָּאָה, כְּלַל שֶׁל זָכָר וּנְקֵבָה. בָּאָה וְהִיא עוֹזֶבֶת אוֹתוֹ, מִיָּד נִפְרָדִים.</p>"],[9522012412,"<p>וַיַּרְא בָּלָק וְגוֹ'. רַבִּי אֶלְעָזָר אָמַר, וַדַּאי מַה שֶּׁאָמַר רַבִּי חִיָּיא, דָּבָר נִסְתָּר הָיָה. אֲבָל כָּתוּב, (תהלים פד) גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ וְגוֹ'. וְכִי דָּוִד הַמֶּלֶךְ עַל צִפּוֹר בָּעוֹלָם הָיָה אוֹמֵר דָּבָר זֶה?</p>\n<p>אֶלָּא כְּמוֹ שֶׁשָּׁנִינוּ כַּמָּה חֲבִיבוֹת הַנְּשָׁמוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אִם תֹּאמַר כָּל נִשְׁמוֹת הָעוֹלָם - לֹא כָּךְ! אֶלָּא אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים שֶׁשָּׁם מְדוֹרָן אִתּוֹ, מְדוֹרֵיהֶן לְמַעְלָה וּמְדוֹרֵיהֶן לְמַטָּה, וְכָךְ נֶאֱמַר. גַּם צִפּוֹר מָצְאָה בַיִת - אֵלּוּ רוּחוֹת הַצַּדִּיקִים.</p>\n<p>שָׁנִינוּ, שָׁלֹשׁ חוֹמוֹת הֵן לְגַן עֵדֶן, וּבֵין כָּל אַחַת וְאַחַת כַּמָּה רוּחוֹת וּנְשָׁמוֹת מְטַיְּלוֹת שָׁם וְנֶהֱנוֹת מֵרֵיחַ שֶׁל עִנּוּגֵי הַצַּדִּיקִים שֶׁבִּפְנִים, אַף עַל גַּב שֶׁלֹּא זָכוּ לְהִכָּנֵס. אֲבָל עִנּוּג רוּחוֹת הַצַּדִּיקִים שֶׁבִּפְנִים - (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים וְגוֹ'.</p>\n<p>וְיָמִים רְשׁוּמִים יֵשׁ בְּשָׁנָה, וְהֵם יְמֵי נִיסָן וִימֵי תִּשְׁרֵי, שֶׁאוֹתָן רוּחוֹת מְשׁוֹטְטוֹת וּפוֹקְדוֹת מָקוֹם שֶׁצָּרִיךְ. וְאַף עַל גַּב שֶׁפְּעָמִים רַבּוֹת מְשׁוֹטְטוֹת, אֲבָל יָמִים אֵלּוּ רְשׁוּמִים הֵם וְנִרְאִים עַל גַּבֵּי חוֹמוֹת הַגִּנָּה, כָּל אַחַת וְאַחַת כְּמַרְאֵה צִפֳּרִים מְצַפְצְפוֹת בְּכָל בּקֶר וּבֹקֶר.</p>\n<p>וְאוֹתוֹ צִפְצוּף שֶׁבַח הַקָּדוֹשׁ בָּרוּךְ הוּא, וּתְפִלָּה עַל חַיֵּי בְּנֵי אָדָם שֶׁל הָעוֹלָם. מִשּׁוּם שֶׁאוֹתָם יָמִים כָּל יִשְׂרָאֵל מִתְעַסְּקִים בְּמִצְווֹת, וּבְמִצְווֹת רִבּוֹן הָעוֹלָם. וְאָז בְּשִׂמְחָה נִרְאוֹת צִפֳּרִים מְצַפְצְפוֹת, וְעַל גַּבֵּי הַחוֹמוֹת שֶׁל גַּן עֵדֶן מְצַפְצְפוֹת מְשַׁבְּחוֹת וּמוֹדוֹת וּמִתְפַּלְלוֹת עַל חַיֵּי הָעוֹלָם הַזֶּה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, וַדַּאי יָפֶה אָמַרְתָּ שֶׁוַּדַּאי אוֹתָן רוּחוֹת שָׁם. אֲבָל מַה תֹּאמַר עַל וּדְרוֹר קֵן לָהּ? אָמַר, כָּךְ לָמַדְתִּי, זוֹהִי נְשָׁמָה קְדוֹשָׁה שֶׁעוֹלָה לְמַעְלָה, וְעוֹלָה לְמָקוֹם טָמִיר וְגָנוּז שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, וַדַּאי יָפֶה אָמַרְתָּ וְיָפֶה הוּא, אֲבָל כָּל זֶה בְּגַן עֵדֶן שֶׁלְּמַטָּה הוּא, וּכְמוֹ שֶׁאָמַרְתָּ הוּא וְכָךְ זֶה וַדַּאי. גַּם צִפּוֹר מָצְאָה בַיִת - אֵלּוּ רוּחוֹת קְדוֹשׁוֹת שֶׁזָּכוּ לְהִכָּנֵס וְלָצֵאת אַחַר כָּךְ, מִשּׁוּם שֶׁמְּשׁוֹטְטוֹת וְנִרְאוֹת כְּמַרְאֵה צִפֳּרִים, וְאֵלּוּ רוּחוֹת מָצְאָה בַיִת. וַדַּאי שֶׁלְּכָל אַחַת וְאַחַת יֵשׁ לָהֶן מְדוֹרִים יְדוּעִים בִּפְנִים.</p>\n<p>וְעִם כָּל זֶה, כֻּלָּם נִכְוִים מֵחֻפַּת חַבְרֵיהֶם. אֵלּוּ שֶׁיֵּשׁ לָהֶם דְּרוֹר וְחֵרוּת מֵהַכֹּל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַרְאֶה לָהֶם הֵיכָל טָמִיר גָּנוּז אֶחָד שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ, וְאוֹתוֹ הֵיכָל נִקְרָא קַן צִפּוֹר, וּמִשָּׁם מִתְעַטְּרִים עֲטָרוֹת לַמָּשִׁיחַ לֶעָתִיד לָבֹא. וּבְיָמִים רְשׁוּמִים, שָׁלֹשׁ פְּעָמִים בְּשָׁנָה, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהִשְׁתַּעֲשֵׁעַ בְּאוֹתָם הַצַּדִּיקִים, וּמַרְאֶה לָהֶם הֵיכָל טָמִיר גָּנוּז שֶׁלֹּא יוֹדְעִים וְלֹא מַכִּירִים אוֹתוֹ כָּל הַצַּדִּיקִים שֶׁשָּׁם.</p>\n<p>אֲשֶׁר שָׁתָה אֶפְרֹחֶיהָ אֶת מִזְבְּחוֹתֶיךְ - אֵלּוּ אוֹתָם צַדִּיקִים שֶׁנִּתְקְנוּ בְּבָנִים קְדוֹשִׁים, שֶׁזָּכוּ לַתּוֹרָה שֶׁבִּכְתָב וְלַתּוֹרָה שֶׁבְּעַל פֶּה בָּעוֹלָם הַזֶּה. וְאֵלּוּ נִקְרָאִים שְׁנֵי מִזְבְּחוֹת. מִתְעַטְּרִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהֲרֵי זְכוּת בְּנֵיהֶם בָּעוֹלָם הַזֶּה מְגִנָּה עֲלֵיהֶם, וּמְעַטְּרִים אוֹתָם שָׁם. מִי הָרוּחַ שֶׁזּוֹכָה לְכָל זֶה? זוֹ שֶׁשָּׁתָה אֶפְרֹחֶיהָ, לְלַמֵּד לְמִזְבְּחוֹתֶיךְ וְגוֹ'. מִכָּאן וָהָלְאָה אֱמֹר דְבָרְךְ, שֶׁהֲרֵי בְּלִי בוּשָׁה אֲנִי נִרְאֶה שָׁם.</p>\n<p>פָּתַח כְּמִקֹּדֶם רַבִּי אֶלְעָזָר וְאָמַר, גַּם צִפּוֹר מָצְאָה בַיִת - זֶה יִתְרוֹ. וּדְרוֹר קֵן לָהּ - זֶה בָּנָיו שֶׁהָיוּ בְּלִשְׁכַּת הַגָּזִית מְלַמְּדִים תּוֹרָה וְחוֹתְכִים דִּבְרֵי תוֹרָה בְּפִיהֶם. מַה זֶּה מָצְאָה בַיִת? אֶלָּא בַּהַתְחָלָה לָקְחוּ וְחָנוּ בַמִּדְבָּר, לָקְחוּ מֵעֹנֶג מִדְיָן וּמֵהַמְּתִיקוּת שֶׁשָּׁם וְחָנוּ בַמִּדְבָּר. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכִּסּוּפָם הָיָה עַל הַתּוֹרָה, מָשַׁךְ אוֹתָם מִשָּׁם וְהִכְנִיסָם לְלִשְׁכַּת הַגָּזִית. וּדְרוֹר קֵן לָהּ - הַכֹּל אֶחָד. צִפּוֹר דְּרוֹר הַכֹּל הוּא אֶחָד. (שופטים ד) חֶבֶר הַקֵּינִי. (שמואל אטו) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וַיַּרְא בָּלָק בֶּן צִפּוֹר. וְכִי מַה שּׁוֹנֶה שֶׁהִזְכִּיר שֵׁם אָבִיו מִשְּׁאָר מְלָכִים? אֶלָּא יִתְרוֹ נִמְשַׁךְ וְנֶעֱבַר מֵעֲבוֹדָה זָרָה, וּבָא לִדְבֹּק בְּיִשְׂרָאֵל הוּא וּבָנָיו, וְכָל הָעוֹלָם נִדּוּ אוֹתוֹ וְרָדְפוּ אַחֲ רָיו.</p>\n<p>בָּלָק מִבְּנֵי בָנָיו הָיָה, וְעָבַר מִדֶּרֶךְ אָבִיו. כֵּיוָן שֶׁרָאוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן, שֶׁהָיוּ יַחַד בְּאַחֲוָה שֶׁלָּהֶם בַּעֲבוֹדָה זָרָה בַּחֵלֶק שֶׁלָּהֶם, שֶׁיִּתְרוֹ וּבָנָיו נִדְבְּקוּ בַשְּׁכִינָה וְזֶה נִמְשַׁךְ מֵהֶם, בָּאוּ וְהִמְלִיכוּהוּ עֲלֵיהֶם בְּשָׁעָה זוֹ, שֶׁכָּתוּב וּבָלָק בֶּן צִפּוֹר מֶלֶךְ לְמוֹאָב בָּעֵת הַהִיא. בְּאוֹתָהּ עֵת הָיָה מֶלֶךְ, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם. וְעַל זֶה כָּתוּב בֶּן צִפּוֹר, מַה שֶּׁלֹּא רָאוּי לַעֲשׂוֹת כָּךְ. וַיַּרְא בָּלָק, וַיִּשְׁמַע הָיָה צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה וַיַּרְא? רְאִיָּה רָאָה, וְיָדַע שֶׁעָתִיד הוּא לִפֹּל בִּידֵי יִשְׂרָאֵל, וְיִשְׂרָאֵל יִפְּלוּ בְיָדוֹ בַּהַתְחָלָה, וְאַחַר כָּךְ הוּא בִּידֵי יִשְׂרָאֵל. וַיַּרְא בָּלָק בֶּן צִפּוֹר.</p>"],[9522012413,"<p>רַבִּי אַבָּא פָּתַח, (שיר השירים א) אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים צְאִי לָךְ בְּעִקְבֵי הַצֹּאן. כְּנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. כְּנֶסֶת יִשְׂרָאֵל, מַה זֶּה כְּנֶסֶת? זוֹהִי עֲצֶרֶת הִתְכַּנְּסוּת, כְּמוֹ שֶׁנֶּאֱמַר (במדבר י) מְאַסֵּף לְכָל הַמַּחֲנוֹת. מִי שֶׁמְּכַנֵּס כָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים אֵלָיו.</p>\n<p>וּמִתּוֹךָ שֶׁלִּפְעָמִים הַשְּׁכִינָה נִקְרֵאת נְקֵבָה, וְנֶאֱמַר עֲצֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כ) כִּי עָצוֹר עָצַר ה', שֶׁמַּחֲזִיק וְלֹא נוֹתֵן - כָּךְ זֶה וַדַּאי, שֶׁהֲרֵי מִתּוֹךְ אֱמוּנָה רַבָּה שֶׁלָּהּ שֶׁלֹּא נִמְצָא בָּהּ מוּם (מח), נוֹתְנִים לָהּ לְלֹא עִכּוּב כְּלָל. וְהִיא, כְּשֶׁבָּאָה אֵלֶיהָ, כָּל מַה שֶּׁכּוֹנֶסֶת עָצַר וּמְעַצֵּר וּמְעַכֶּבֶת, שֶׁלֹּא יוֹרֵד וּמֵאִיר אֶלָּא כְּפִי הַטַּל, טִפִּין טִפִּין, מְעַט מְעַט. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא נִמְצֵאת לְמַטָּה אֱמוּנָה, אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כח) זְעֵיר שָׁם זְעֵיר שָׁם. זְכוּת קְטַנָּה וְהֶאָרַת טַל קְטַנָּה, מִדָּה כְּנֶגֶד מִדָּה.</p>\n<p>שֶׁאִלְמָלֵא תִמָּצֵא אֱמוּנָה כְּמוֹ שֶׁנִּמְצְאוּ בָהּ, הִיא מְרֻקֶּנֶת בְּכָל צַד וְצַד לְלֹא עִכּוּב כְּלָל, וְהִיא שְׂמֵחָה. וְאָז נוֹתְנִים לָהּ מַתָּנוֹת וְאוֹצָרוֹת רַבִּים זֶה עַל זֶה, וְלֹא יְעַכְּבוּ אוֹתָהּ כְּלָל. אֲבָל הַתַּחְתּוֹנִים מְעַכְּבִים אוֹתָם וּמְעַכְּבִים אוֹתָהּ, וְאָז הִיא עֲצֶרֶת. עָצוֹר עָצַר ה' וַדַּאי. כִּבְיָכוֹל נוֹתֵן תַּמְצִית, וְלֹא יוֹתֵר.</p>\n<p>וְעִם כָּל זֶה, כְּמוֹ אִמָּא נוֹתֶנֶת לְבָנִים בַּסֵּתֶר שֶׁלֹּא יוֹדְעִים עָלֶיהָ, כָּךְ הִיא עוֹשָׂה לְבָנֶיהָ יִשְׂרָאֵל. וְלָמַדְנוּ מִתּוֹךְ מְנוֹרָה הַקְּדוֹשָׁה, שֶׁבְּשָׁעָה שֶׁהִיא עוֹלָה לָקַחַת עִנּוּגִים וְכִסּוּפִים וְנִמְצָא מוּם בְּיִשְׂרָאֵל לְמַטָּה, אָז מַגִּיעָה אֵלֶיהָ טִפַּת חַרְדָּל וּמִיָּד נִּפְרֶדֶת, וְיוֹשֶׁבֶת עָלֶיהָ יָמִים בְּמִנְיָן, וְאָז יוֹדְעִים לְמַעְלָה שֶׁהַמּוּם בְּיִשְׂרָאֵל.</p>\n<p>וּמִתְעוֹרֵר הַשְּׂמֹאל מִיָּד, וּמוֹשֵׁךְ חוּט לְמַטָּה. (בראשית כז) וַתִּכְהֶיןָ עֵינָיו מֵרְאֹת, מַה שֶּׁהָיָה מִסְתַּכֵּל בְּעַיִן יָפָה בִּכְלַל אַבְרָהָם בְּלִי דִין כְּלָל, אָז וַתִּכְהֶיןָ עֵינָיו מֵרְרֹאת, מֵרְאֹת בְּוַדַּאי מִלְּהִסְתַּכֵּל בִּכְלָל שֶׁל רַחֲמָנוּת. אָז הִתְעוֹרְרוּת סָמָאֵ\"ל בְּקוֹל תַּקִּיף לְהִתְעוֹרֵר עַל הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקְרָא אֶת עֵשָׂו בְּנוֹ הַגָּדל וְגוֹ'. גָּדוֹל הוּא לְגַבֵּי מַחֲנוֹת הַצַּד הָאַחֵר, הוּא גָּדוֹל, וּמַנְהִיג לְכָל סְפִינוֹת הַיָּם שֶׁמְּעֻרְעָרִים בְּרוּחַ רָעָה, לְהַטְבִּיעָם בְּעֹמֶק הַיָּם בְּאוֹתָן מְצוּלוֹת יָם שֶׁלּוֹ.</p>\n<p>וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא בְּרַחֲמָנוּת, אָז כָּל חֲטָאֵי וְכָל עֲונוֹת יִשְׂרָאֵל נוֹתֵן לוֹ, וְהוּא מַטִּיל אוֹתָם לִמְצוּלוֹת יָם. כָּל מַחֲנוֹתָיו נִקְרָאִים מְצוּלוֹת יָם, וְהֵם לוֹקְחִים אוֹתָם וּמְשׁוֹטְטִים בָּהֶם בְּכָל שְׁאָר הָעַמִּים. וְכִי חֲטָאֵי יִשְׂרָאֵל וַעֲונוֹתיהֶם זוֹרְקִים וּמְחַלְּקִים לָעָם שֶׁלָּהֶם? אֶלָּא הֵם מְצַפִּים וּמְחַכִּים לַמַּתָּנוֹת שֶׁלְּמַעְלָה כְּמוֹ כְלָבִים לְיַד הַשֻּׁלְחָן. וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לוֹקֵחַ כָּל חֲטָאֵי יִשְׂרָאֵל וְזוֹרֵק עֲלֵיהֶם, כֻּלָּם חוֹשְׁבִים שֶׁמַּתָּנוֹת וְאוֹצָרוֹת שֶׁהוּא רוֹצֶה לָתֵת לְיִשְׂרָאֵל הֶעֱבִיר אוֹתָם מֵהֶם וְנָתַן לָהֶם, וּמִיָּד כֻּלָּם כְּאֶחָד זוֹרְקִים (ומראה וזורקים) אוֹתָם עַל שְׁאָר הָעַמִּים.</p>\n<p>בֹּא וּרְאֵה, כְּנֶסֶת יִשְׂרָאֵל הִיא אוֹמֶרֶת בַּתְּחִלָּה (בגלות), (שיר השירים א) שְׁחוֹרָה אֲנִי וְנָאוָה. מַקְטִינָה עַצְמָהּ לְיַד הַמֶּלֶךְ הָעֶלְיוֹן. וְאָז שׁוֹאֶלֶת מִמֶּנּוּ וְאוֹמֶרֶת, (שם) הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי אֵיכָה תִרְעֶה אֵיכָה תַּרְבִּיץ בַּצָּהֳרָיִם. לָמָּה שְׁתֵּי פְעָמִים אֵיכָה אֵיכָה? אֶלָּא הִיא רוֹמֶזֶת עַל שְׁנֵי חֻרְבָּנוֹת שֶׁל שְׁנֵי בָּתֵּי הַמִּקְדָּשׁ, שֶׁקּוֹרְאִים הַכֹּל אֵיכָה אֵיכָה. אֵיכָה תִרְעֶה - בְּחֻרְבַּן בַּיִת רִאשׁוֹן. אֵיכָה תַּרְבִּיץ - בְּחֻרְבַּן בַּיִת שֵׁנִי. וְעַל זֶה פַּעֲמַיִם אֵיכָה אֵיכָה.</p>\n<p>תִרְעָה, תַּרְבִּיץ, לֹא זֶה כָּזֶה. גָּלוּת בָּבֶל שֶׁהִיא זְמַן מוּעָט, קוֹרֵא בָּהּ תִרְעֶה. וְעַל גָּלוּת אֱדוֹם שֶׁהִיא לִזְמַן מְרֻבֶּה, קוֹרֵא בָּהּ תַּרְבִּיץ. וְעַל זֶה פַּעֲמַיִם אֵיכָה אֵיכָה. וְעוֹד תִרְעֶה, תַּרְבִּיץ - יִרְעֶה הָיָה לוֹ לִכְתֹּב! יַרְבִּיץ הָיָה לוֹ לִכְתֹּב! גַּם כָּךְ, שֶׁהֲרֵי עַל יִשְׂרָאֵל הִיא אָמְרָה. אֶלָּא הִיא אָמְרָה עַל עַצְמָהּ: אֵיכָה תִרְעֶה כַּלָּתְךְ לְבָנֶיהָ בַּגָּלוּת כְּשֶׁיִּהְיוּ בֵּין שְׁאָר הָעַמִּים? אֵיכָה תַּרְבִּיץ בַּצָּהֳרַיִם, אֵיךְ תַּטִּיף עֲלֵיהֶם טַל וּמַיִם תּוֹךְ חֲמִימוּת הַצָּהֳרַיִם?</p>\n<p>שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה. בְּשָׁעָה שֶׁיִּשְׂרָאֵל קוֹרְאִים מִתּוֹךְ צָרָה וְדחַק שֶׁלָּהֶם, וּשְׁאָר הָעַמִּים מְחָרְפִים וּמְגַדְּפִים אוֹתָם: מָתַי תֵצְאוּ מֵהַגָּלוּת? אֵיךְ אֱלֹהֵיכֶם אֵינוֹ עוֹשֶׂה לָכֶם נִסִּים? (והם ממציאים עצמם ואומרים, כה תרעה אותנו בימים הראשונים, כה תרביץ במים הקדושים לצנן החמימות של רשפים ושלהבות שלהם. והם משבחים כל זה) (והם משבחים לקדוש ברוך הוא ומודים לו עם כל הצער ואריכות הגלות, ואומרים, כה תרעה אותנו בימים הראשונים, כה תרביץ עמנו בגלות ותגאל אותנו לזמן האחרון. כל זה שבח ואמונה שמתאים להם לישראל) וַאֲנִי יוֹשֵׁב כְּעֹטְיָה וְלֹא יָכוֹל לַעֲשׂוֹת לָהֶם נִסִּים וְלָתֵת לָהֶם נְקָמוֹת. הוּא מֵשִׁיב לָהּ: אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים. פָּסוּק זֶה כָּךְ צָרִיךְ לְכָתְבוֹ: אִם לֹא תֵדְעִי הַיָּפָה בַּנָּשִׁים. לָמָּה לָךְ? אֶלָּא, אִם לֹא תֵדְעִי לָךְ - לְחַזֵּק עַצְמֵךְ בַּגָּלוּת וּלְהַגְבִּיר כֹּחַ לְהָגֵן עַל בָּנַיִךְ - צְאִי לָךְ, צְאִי לָךְ לְהִתְחַזֵּק בְּעִקְבֵי הַצֹּאן. אוֹתָם תִּינוֹקוֹת שֶׁל בֵּית רַבָּן שֶׁלּוֹמְדִים תּוֹרָה.</p>\n<p>וּרְעִי אֶת גְּדִיֹּתַיִךְ - אֵלּוּ (ישעיה כח) עַתִּיקֵי מִשָּׁדָיִם שֶׁמִּסְתַּלְּקִים מֵהָעוֹלָם וְנִמְשָׁכִים לְבֵית הַיְשִׁיבָה הָעֶלְיוֹנָה, שֶׁהִיא עַל מִשְׁכְּנוֹת הָרֹעִים. עַל דַּוְקָא. בְּמִשְׁכְּנוֹת הָרוֹעִים לֹא כָתוּב, אֶלָּא עַל מִשְׁכְּנוֹת הָרֹעִים, זֶה יְשִׁיבַת מְטַטְרוֹ\"ן שֶׁשָּׁם כָּל הַחֲזָקִים וְתִינוֹקוֹת הָעוֹלָם וּמַנְהִיגֵי הַתּוֹרָה בָּעוֹלָם הַזֶּה בְּאִסּוּר וְהֶתֵּר, בְּכָל מַה שֶּׁצְּרִיכִים בְּנֵי הָעוֹלָם, שֶׁהֲרֵי עִקְבֵי הַצֹאן אוֹתָם תִּינוֹקוֹת שֶׁאָמַרְנוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, עִקְבֵי הַצֹּאן - אֵלּוּ תַּלְמִידֵי בֵּית רַב שֶׁאַחַר כָּךְ בָּאִים בָּעוֹלָם וּמוֹצְאִים תּוֹרָה בְּדֶרֶךְ יְשָׁרָה וְדֶרֶךְ פְּתוּחָה, וְעַל זֶה הֵם מְחַדְּשִׁים דְּבָרִים עַתִּיקִים בְּכָל יוֹם, וְשׁוֹרָה עֲלֵיהֶם הַשְּׁכִינָה וּמַקְשִׁיבָה לְדִבְרֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (מלאכי ג) וַיַּקְשֵׁב ה' וַיִּשְׁמָע. אָמַר רַבִּי אַבָּא, כָּךְ זֶה בְּוַדַּאי, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>דָּבָר אַחֵר אִם לֹא תֵדְעִי לָךְ - לָךְ לָמָּה? אֶלָּא בְּכָל מָקוֹם שֶׁיִּשְׂרָאֵל בַּגָּלוּת, הִיא עִמָּם בַּגָּלוּת, וְעַל זֶה כָּתוּב לָךְ. וְכָתוּב (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר, וְזֶהוּ לָךְ. הַיָּפָה בַּנָּשִׁים, הַיָּפָה - הִיא אָמְרָה שֶׁהִיא שְׁחוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים א) שְׁחוֹרָה אֲנִי. וְהוּא אָמַר אֵלֶיהָ: יָפָה אַתְּ, נָאָה, הַיָּפָה בַּנָּשִׁים, נָאָה עַל כָּל הַדְּרָגוֹת, וְכָתוּב (שם ו) יָפָה אַתְּ רַעְיָתִי.</p>\n<p>דָּבָר אַחֵר הַיָּפָה בַּנָּשִׁים - טוֹבָה בְּטוֹבוֹת. שֶׁעוֹשָׂה טוֹבוֹת לְבָנֶיהָ בִּטְמִירוּת בְּצוּרָה גְנוּזָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִרְבָּה טוֹב עָלָיו, כָּל מַה שֶּׁהִיא עוֹשָׂה לְבָנֶיהָ בְּצוּרָה טְמִירָה וּגְנוּזָה, אַף עַל גַּב שֶׁהַמַּעֲשִׂים לֹא כְשֵׁרִים. מִכָּאן שֶׁרָאוּי לְאַבָּא כְּשֶׁאִמָּא מְרַחֶמֶת עַל הַבָּנִים וְטוֹב לוֹ כָּל מַה שֶּׁעוֹשָׂה לְבָנֶיהָ רַחֲמִים בְּנִסְתָּר, אַף עַל גַּב שֶׁמַּעֲשָׂיו לֹא כְשֵׁרִים.</p>\n<p>אָמַר רַבִּי אַבָּא, תְּמֵהַנִי עַל מַה שֶּׁכָּתוּב (דברים כא) כִּי יִהְיֶה לְאִישׁ בֵּן סוֹרֵר וּמוֹרֶה וְגוֹ', וְתָפְשׂוּ בוֹ אָבִיו וְאִמּוֹ וְגוֹ'. וְשָׁנִינוּ שֶׁבְּאוֹתָהּ שָׁעָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה כְּתֹב. אָמַר לוֹ מֹשֶׁה, רִבּוֹן הָעוֹלָם, תַּעֲזֹּב אֶת זֶה, יֵשׁ אָב שֶׁיַּעֲשֶׂה כָּךְ לִבְנוֹ? וּמֹשֶׁה מַרְחִיק הָיָה לִרְאוֹת בְּחָכְמָה כָּל מַה שֶּׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנֵי לְיִשְׂרָאֵל. אָמַר, רִבּוֹן הָעוֹלָם, תַּעֲזֹּב דָּבָר זֶה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, אֲנִי רוֹאֶה מַה שֶּׁאַתָּה אוֹמֵר. כְּתֹב וְקַבֵּל שָׂכָר. אַתָּה יוֹדֵעַ, וַאֲנִי יוֹדֵעַ יוֹתֵר. מַה שֶּׁאַתָּה רוֹאֶה, עָלַי אוֹתוֹ מַעֲשֶׂה. דְּרֹשׁ הַמִּקְרָא וְתִמְצָא.</p>\n<p>בְּאוֹתָהּ שָׁעָה רָמַז לְיוֹפִיאֵ\"ל, רַבַּן הַתּוֹרָה, אָמַר לְמֹשֶׁה: אֲנִי דָרַשְׁתִּי פָסוּק זֶה. כָּתוּב כִּי יִהְיֶה לְאִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שמות טו) ה' אִישׁ מִלְחָמָה. בֵּן - זֶה יִשְׂרָאֵל. סוֹרֵר וּמוֹרֶה - שֶׁכָּתוּב (הושע ד) כִּי כְּפָרָה סֹרֵרָה סָרַר יִשְׂרָאֵל. אֵינֶנּוּ שֹׁמֵעַ בְּקוֹל אָבִיו וּבְקוֹל אִמּוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. וְיִסְּרוּ אֹתוֹ, שֶׁכָּתוּב (מלכים ב יז) וַיָּעַד ה' בְּיִשְׂרָאֵל וּבִיהוּדָה בְּיַד כָּל נְבִיאֵי כָל חֹזֶה וְגוֹ'. וְלֹא שָׁמַע אֲלֵיהֶם, שֶׁכָּתוּב וְלֹא יִשְׁמְעוּ אֶל ה' וְגוֹ'. וְתָפְשׂוּ בוֹ אָבִיו וְאִמּוֹ - בְּדַעַת אַחַת, בְּהַסְכָּמָה אַחַת.</p>\n<p>וְהוֹצִיאוּ אֹתוֹ אֶל זִקְנֵי עִירוֹ וְאֶל שַׁעַר מְקֹמוֹ. אֶל זִקְנֵי עִירוֹ?! אֶל זִקְנֵי עִירָם וְאֶל שַׁעַר מְקוֹמָם הָיָה צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה אֶל זִקְנֵי עִירוֹ, וְאֶל שַׁעַר מְקֹמוֹ? אֶלָּא, אֶל זִקְנֵי עִירוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶל שַׁעַר מְקֹמוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. זִקְנֵי עִירוֹ - אֵלּוּ יָמִים רִאשׁוֹנִים, יָמִים עַתִּיקֵי (סבי) הַכֹּל. שַׁעַר מְקֹמוֹ - זֶה מוּסַף שַׁבָּת.</p>\n<p>וְעִם כָּל זֶה, אַף עַל גַּב שֶׁכֻּלָּם יוֹדְעִים, דִּין לְמַעְלָה הוּא, מִשּׁוּם שֶׁבֵּית דִּין שֶׁל אִמָּא קְרוֹבִים הֵם לְיִשְׂרָאֵל וְאוֹחֲזִים בָּהֶם, וְכָל קָרוֹב לֹא דָן דִּין לִקְרוֹבִים (לקרוביו), וּפָסוּל הוּא לְדִין. בַּתְּחִלָּה מַה כָּתוּב? אֶל זִקְנֵי עִירוֹ וְאֶל שַׁעַר מְקֹמוֹ. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם קְרוֹבִים, מִיָּד סִלֵּק הַדִּין מִשַּׁעַר מְקוֹמוֹ. מַה כָּתוּב אַחֲרָיו? וְאָמְרוּ אֶל זִקְנֵי עִירוֹ, לְחוּד. וְאֶל שַׁעַר מְקוֹמוֹ לֹא כָתוּב, אֶלָּא אֶל זִקְנֵי עִירוֹ.</p>\n<p>בְּנֵנוּ זֶה, וַדַּאי, וְלֹא שֶׁל שְׁאָר הָעַמִּים. סוֹרֶה וּמֹרֶה אֵינֶנּוּ שּמֵעַ בְּקֹלֵנוּ. מַה שּׁוֹנֶה שֶׁהֲרֵי בַּהַתְחָלָה לֹא כָתוּב זוֹלֵל וְסֹבֵא, וְאַחַר כָּךְ כָּתוּב זוֹלֵל וְסֹבֵא? אֶלָּא מִי גָרַם לָהֶם לְיִשְׂרָאֵל לִהְיוֹת סוֹרֵר וּמֹרֶה לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם? בִּגְלַל שֶׁהוּא זוֹלֵל וְסֹבֵא בִּשְׁאָר הָעַמִּים, שֶׁכָּתוּב (תהלים קו) וַיִּתְעָרְבוּ בַגּוֹיִם וַיִּלְמְדוּ מַעֲשֵׂיהֶם, וְכָתוּב (במדבר כה) וַיּאכַל הָעָם וַיִּשְׁתַּחֲווּ, שֶׁעִקַּר וִיסוֹד אֲכִילָה וּשְׁתִיָּה כְּשֶׁעוֹשִׂים בִּשְׁאָר הָעַמִּים. זֶה גוֹרֵם לָהֶם לִהְיוֹת בֵּן סוֹרֵר וּמֹרֶה לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם.</p>\n<p>וְעַל זֶה, וּרְגָמֻהוּ כָּל אַנְשֵׁי עִירוֹ בָאֲבָנִים. אֵלֶּה כָּל שְׁאָר הָעַמִּים שֶׁהָיוּ מְקַלְּעִים אוֹתָם בַּאֲבָנִים, וְסוֹתְרִים אֶת הַחוֹמוֹת וּמְנַתְּצִים אֶת הַמִּגְדָּלִים, וְלֹא מוֹעִיל לָהֶם כְּלוּם. כֵּיוָן שֶׁשָּׁמַע מֹשֶׁה, אָז כָּתַב פָּרָשָׁה זוֹ.</p>\n<p>וְעִם כָּל זֶה - הַיָּפָה בַּנָּשִׁים, טוֹבָה וְנִכְבָּדָה בִּנְשׁוֹת הָעוֹלָם. צְאִי לָךְ בְּעִקְבֵי הַצֹּאן, הֲרֵי בֵּאַרְנוּ - אֵלּוּ בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת. וּרְעִי אֶת גְּדִיּתַיִךְ - אֵלּוּ תִינוֹקוֹת שֶׁל בֵּית רַבָּן שֶׁלֹּא טָעֲמוּ טַעַם חֵטְא בָּעוֹלָם. עַל מִשְׁכְּנוֹת הָרֹעִים - אֵלּוּ מְלַמְּדֵי תִינוֹקוֹת וְרָאשֵׁי יְשִׁיבוֹת.</p>\n<p>דָּבָר אַחֵר עַל מִשְׁכְּנוֹת הָרֹעִים, חָסֵר ו' - אוֹתָם רָעִים אֵלּוּ מַלְכֵי הָאֱמוֹרִי שֶׁלָּקְחוּ יִשְׂרָאֵל אֶת אַרְצָם לִרְעוֹת מִקְנֵיהֶם, וּלְבֵית מִרְעֶה נָתַן יִשְׂרָאֵל אֶרֶץ זוֹ. אָז שָׁמַע בָּלָק שֶׁהָאָרֶץ שֶׁהָיְתָה חֲשׁוּבָה כָּל כָּךְ, עָשׂוּ יִשְׂרָאֵל קְרָב זֶה וְסָתְרוּ אוֹתָהּ, עַד שֶׁשָּׂמוּהָ בֵּית מִרְעֶה. אָז הִשְׁתַּדֵּל בְּכָל מַה שֶּׁהִשְׁתַּדֵּל, וְשִׁתֵּף אִתּוֹ אֶת בִּלְעָם.</p>"],[9522012414,"<p>וַיַּרְא בָּלָק. רַבִּי חִזְקִיָּה פָּתַח, (ישעיה נו) כֹּה אָמַר ה' שִׁמְרוּ מִשְׁפָּט וַעֲשׂוּ צְדָקָה כִּי קְרוֹבָה יְשׁוּעָתִי וְגוֹ'. כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאַף עַל גַּב שֶׁחָטְאוּ לְפָנָיו וְחוֹטְאִים לְפָנָיו בְּכָל פַּעַם וּפַעַם, הוּא עוֹשֶׂה לְיִשְׂרָאֵל זְדוֹנוֹת כִּשְׁגָגוֹת.</p>\n<p>וְכָךָ אָמַר רַב הַמְנוּנָא סָבָא, שְׁלֹשָׁה שַׁעֲרֵי דִין תִּקְּנוּ (חכמים) בְּסִדְרֵי הַמִּשְׁנָה: אֶחָד - רִאשׁוֹן בְּאַרְבָּעָה אֲבוֹת נְזִיקִין, הַשּׁוֹר וְכוּ'. שֵׁנִי - טַלִּית שֶׁנִּמְצְאָה. שְׁלִישִׁי - שֻׁתָּפִים וְסוֹד אֲבֵדָה. מָה הַטַּעַם? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל זְמַן עוֹשֶׂה לְיִשְׂרָאֵל זְדוֹנוֹת כִּשְׁגָגוֹת, וְאֵלּוּ שֶׁסִּדְּרוּ מִשְׁנָיוֹת שֶׁל שָׁלֹשׁ בָּבוֹת - דֶּרֶךְ הַכָּתוּב נָקְטוּ, שֶׁכָּתוּב (שמותכב) עַל כָּל דְּבַר פֶּשַׁע, וְזֶהוּ פֶּשַׁע שֶׁלֹּא בְזָדוֹן, וּמַהוּ? עַל שׁוֹר, עַל חֲמוֹר, עַל שֶׂה - זֶה בָּבָא קַמָּא, שֶׁכָּאן הוּא בְּאוֹתָם דְּבָרִים. עַל שַׂלְמָה - זוֹ בָּבָא מְצִיעָא. עַל כָּל אֲבֵדָה - זוֹ בָּבָא שְׁלִישִׁית.</p>\n<p>שֶׁדֶּרֶךָ הַכָּתוּב לָקַח. שֶׁכְּשֶׁמַּגִּיעַ לְבָבָא מְצִיעָא, הָיָה אוֹמֵר: רֵאשִׁית שֶׁלָּקְחוּ בְטַלִּית זוֹ לָמָּה? כֵּיוָן שֶׁנִּמְצָא פָסוּק, אָמַר: וַדַּאי זוֹ הֲלָכָה לְמֹשֶׁה מִסִּינַי, וּבֵאֲרוּ כָּל דִּבְרֵי חֲכָמִים.</p>\n<p>כֹּה אָמַר ה'. מַה שּׁוֹנֶה בְּכָל מָקוֹם שֶׁל נְבִיאִים שֶׁכָּתוּב כֹּה אָמַר ה', וּבְמֹשֶׁה לֹא כָתוּב כָּךְ? אֶלָּא מֹשֶׁה שֶׁנְּבוּאָתוֹ הָיְתָה מִתּוֹךְ אַסְפַּקְלַרְיָה הַמְּאִירָה שֶׁלְּמַעְלָה, לֹא כָתוּב בּוֹ כֹּה. אֲבָל שְׁאָר הַנְּבִיאִים שֶׁהָיוּ מִתְנַבְּאִים מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה, הִתְנַבְּאוּ מִתּוֹךְ כֹּה. (להראות שהכל הוא אחד ללא פרוד, שאף על גב שאמרו וכו', לא אמרו אלא מתוך כה).</p>\n<p>וְעַתָּה לְכָה נָּא אָרָה לִּי אֶת הָעָם הַזֶּה וְגוֹ'. וְעַתָּה, רַבִּי אֶלְעָזָר אָמַר, אָמַר אוֹתוֹ רָשָׁע, וַדַּאי הַשָּׁעָה עוֹמֶדֶת לִי לַעֲשׂוֹת מַה שֶּׁאֲנִי רוֹצֶה. רָאָה, וְלֹא רָאָה יָפֶה. רָאָה כַּמָּה אֲלָפִים נוֹפְלִים מִיִּשְׂרָאֵל עַל יָדוֹ לִזְמַן מוּעָט, אָמַר, וַדַּאי הַשָּׁעָה עוֹמֶדֶת לִי, וְלָכֵן וְעַתָּה, וְלֹא בִזְמַן אַחֵר.</p>\n<p>לְכָה, ?, לֵךְ הָיָה לוֹ לִכְתֹּב! מַה זֶּה לְכָה? אָמַר, נְזָרֵז עַצְמֵנוּ לְאוֹתוֹ שֶׁמְּרַחֵף בִּכְנָפָיו עֲלֵיהֶם לְאוֹתוֹ שֶׁשְּׁמוֹ כֹּ\"ה. וְעַתָּה לְכָה, נַעֲרֹךְ קְרָב בְּאוֹתוֹ כֹּ\"ה. (ועתה לכה, כמו שנאמר (מלכים ב ג) ועתה לשלל מואב).</p>\n<p>אָמַר, עַד עַתָּה לֹא הָיָה בָּעוֹלָם מִי שֶׁיָּכוֹל לָהֶם, בִּגְלַל אוֹתוֹ הַפַּטְרוֹן שֶׁעוֹמֵד עֲלֵיהֶם. כָּעֵת שֶׁהַשָּׁעָה עוֹמֶדֶת לָנוּ, לְכֹה נַעֲשֶׂה קְרָב. וְכָל עֲצַת אוֹתוֹ רָשָׁע לְכֹ\"ה הָיְתָה, שֶׁכָּתוּב וְאָנֹכִי אִקָּרֶה כֹּה. אֶעֱקֹר אֶת אוֹתָהּ כֹּה מִמְּקוֹמָהּ. וּשְׁנֵיהֶם בְּעֵצָה רָעָה הָיוּ לַכֹּה הַזּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ב) עַל ה' וְעַל מְשִׁיחוֹ. לֹא יָדְעוּ שֶׁהֲרֵי אַחַר כָּךְ הַכֹּה הַזּוֹ תַּעֲקֹר אוֹתָם מִן הָעוֹלָם.</p>"],[9522012415,"<p>כִּי עָצוּם הוּא מִמֶּנִּי. וְכִי עַד אוֹתָהּ שָׁעָה אֵיפֹה עָרְכוּ קְרָב בּוֹ וְנִצְּחוּ אוֹתוֹ? בְּאֵיזֶה מָקוֹם נִפְגְּשׁוּ בְחַרְבָּם וְהָיוּ גְבָרִים כְּגִבּוֹרִים לְהַרְאוֹת גְּבוּרָתָם? מַה זֶּה כִּי עָצוּם הוּא מִמֶּנִּי? אֶלָּא אוֹתוֹ רָשָׁע הָיָה חָכָם וְרָאָה לְמֵרָחוֹק. רָאָה אֶת דָּוִד הַמֶּלֶךְ שֶׁבָּא מֵרוּת הַמּוֹאֲבִיָּה גִּבּוֹר תַּקִּיף כְּאַרְיֵה, וְעָשָׂה קְרָבוֹת תַּקִּיפִים וְנִצַּח אֶת מוֹאָב, וְשָׂם אוֹתָם תַּחַת רַגְלָיו. אָמַר, עָצוּם הוּא. אוֹתוֹ שֶׁיָּרַשׁ אוֹתָהּ גְּבוּרָה, מֶלֶךְ אֶחָד מֵהֶם יֵצֵא מֵאִתָּנוּ לְהַשְׁמִיד אֶת מוֹאָב.</p>\n<p>אוּלַי אוּכַל נַכֶּה בּוֹ. פָּסוּק זֶה כָּךְ הָיָה לוֹ לוֹמַר: אוּלַי אוּכַל אַכֶּה בּוֹ, אוֹ אוּלַי נוּכַל נַכֶּה בּוֹ. אֶלָּא אוֹתוֹ רָשָׁע הָיָה חָכָם. אָמַר, רָאִיתִי יָד אַחַת שֶׁל אַרְיֵה תַּקִּיף אֶחָד, פְּרוּשׂ רֶגֶל (יד), אִם אוּכַל עִמְּךְ שֶׁנִּתְחַבֵּר (שנינו) שְׁנֵיהֶם (ונתחבר) וְנִגְרַע מֵאוֹתוֹ אַרְיֵה יָד זוֹ, עַד שֶׁלֹּא יָבֹא אתוֹ מֶלֶךְ לָעוֹלָם וְלֹא יְגָרֵשׁ אֶת מוֹאָב מִמְּקוֹמוֹ.</p>\n<p>אָרָה לִּי. מַה זֶּה אָרָה לִּי? אָמַר רַבִּי אַבָּא, אוֹתוֹ רָשָׁע בִּשְׁתֵּי לְשׁוֹנוֹת אָמַר לְבִלְעָם. אֶחָד אָמַר אָרָה לִּי, וְאֶחָד אָמַר קָבָה לִּי. מַה בֵּין זֶה לָזֶה? אֶלָּא אָמַר לוֹ, אָרָה לִּי עֲשָׂבִים וְכִשְׁפֵי רָאשֵׁי נְחָשִׁים, וְשִׂים אוֹתָם בִּקְדֵרַת הַמְּכַשְּׁפִים. כֵּיוָן שֶׁרָאָה שֶׁכֹּחוֹ יוֹתֵר בְּפִיו, שָׁב וְאָמַר וּלְכָה נָא קָבָה לִּי.</p>\n<p>וַאֲפִלּוּ כָּךְ, אוֹתוֹ בָּלָק הָרָשָׁע לֹא עָזַב אֶת כְּשָׁפָיו, אֶלָּא לִקֵּט כָּל מִינֵי עֲשָׂבִים, כִּשּׁוּף שֶׁל רָאשֵׁי נְחָשִׁים, וְלָקַח קְדֵרַת מְכַשְּׁפִים וְנָעַץ אוֹתָהּ תַּחַת הַקַּרְקַע אֶלֶף וַחֲמֵשׁ מֵאוֹת אַמָּה (על אלף וחמש מאות אמה), וְגָנַז אוֹתָהּ לְסוֹף הַיָּמִים. כֵּיוָן שֶׁבָּא דָוִד, כָּרָה בַתְּהוֹם אֶלֶף וַחֲמֵשׁ מֵאוֹת אַמָּה, וְהוֹצִיא מַיִם מֵהַתְּהוֹם וְנִסֵּךְ עַל הַמִּזְבֵּחַ. בְּאוֹתָהּ שָׁעָה אָמַר, אֲנִי אֶרְחַץ אוֹתָהּ הַקְּדֵרָה. (תהלים קח) מוֹאָב סִיר רַחְצִי. סִיר רַחְצִי בְּוַדַּאי.</p>\n<p>עֵל אֱדוֹם אַשְׁלִיךְ נַעֲלִי. מַה זֶּה אַשְׁלִיךְ נַעֲלִי? אֶלָּא גַּם זֶה כָּךְ הָיָה לְמֵרָחוֹק, שֶׁכָּתוּב (בראשית כה) וַיֹּאמֶר עֵשָׂו אֶל יַעֲקֹב הַלְעִיטֵנִי נָא מִן הָאָדם הָאָדם הַזֶּה כִּי עָיֵף אָנֹכִי. הַלְעִיטֵנִי, הַלְעָטָה מַמָּשׁ, פְּתִיחַת הַפֶּה וְהַגָּרוֹן לִבְלֹעַ. אָמַר דָּוִד לְאוֹתוֹ הַבַּלְעָן מַלְעִיט הַלְּעָטִים: אֲנִי אֶזְרֹק עָלָיו נַעֲלִי לִסְתֹּם אֶת גְּרוֹנוֹ.</p>\n<p>עָלֵי פְלֶשֶׁת אֶתְרוֹעָע. גַּם כָּךְ זֶה לְמֵרָחוֹק הִסְתַּכֵּל דָּוִד, וְאָמַר: כְּנַעַן הוּא צַד רַע שֶׁל הַצַּד הָאַחֵר הַהוּא, וּפְלִשְׁתִּים הֵם מִשָּׁם, לְצַד אַחֵר מַה צָּרִיךְ? תְּרוּעָה, שֶׁכָּתוּב (במדבר י) וְכִי תָבֹאוּ מִלְחָמָה בְּאַרְצְכֶם (וגו') וַהֲרֵעֹתֶם וְגוֹ', לִשְׁבֹּר כֹּחוֹ וְתָקְפּוֹ, וּמִשּׁוּם כָּךְ עֲלֵי פְלֶשֶׁת אֶתְרוֹעָע. וְכָךְ רָאוּי לָהֶם.</p>\n<p>וְעַתָּה לְכָה נָּא אָרָה לִּי אֶת הָעָם הַזֶּה כִּי עָצוּם הוּא מִמֶּנִּי. רַבִּי חִזְקִיָּה פָּתַח, (ישעיה יא) וְהָיָה צֶדֶק אֵזוֹר מָתְנָיו וְהָאֱמוּנָה אֵזוֹר חֲלָצָיו. פָּסוּק זֶה הַכֹּל הוּא אֶחָד. מַה חִדּוּשׁ בָּא לְהַשְׁמִיעֵנוּ? שֶׁהֲרֵי צֶדֶק הַיְנוּ אֱמוּנָה, וֶאֱמוּנָה הַיְנוּ צֶדֶק. אֵזוֹר מָתְנָיו הַיְנוּ אֵזוֹר חֲלָצָיו. וְלֹא מָצָאנוּ פָסוּק כְּמוֹ זֶה.</p>\n<p>אֶלָּא לֹא צֶדֶק כְּמוֹ אֱמוּנָה, וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד, וְדַרְגָּה אַחַת הִיא. אֲבָל בִּזְמַן שֶׁעוֹמְדִים בְּדִין קָשֶׁה וּמְקַבְּלִים מִצַּד שְׂמֹאל, אָז נִקְרָא צֶדֶק דִּין מַמָּשׁ, וְהַיְנוּ (שם כו) כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל. שֶׁדַּרְגָּה זוֹ שֶׁל מִשְׁפָּט הִיא רַחֲמִים. וּכְשֶׁמִּתְקָרֵב מִשְׁפָּט בְּצֶדֶק, אָז מִתְבַּשֵּׂם (הכל), וִיכוֹלִים בְּנֵי הָעוֹלָם לִסְבֹּל דִּין בְּצֶדֶק.</p>\n<p>(ועל זה צדק אינו כאמונה) אֱמוּנָה, בְּשָׁעָה שֶׁמִּתְחַבֶּרֶת בָּהּ (אז הוא) אֱמֶת, לְשִׂמְחָה. וְכָל הַפָּנִים מְאִירוֹת, אָז נִקְרֵאת אֱמוּנָה. וְיֵשׁ וַתְּרָנוּת לַכֹּל, וְכָל הַנְּשָׁמוֹת עוֹלוֹת, מִתְחַיְּבוֹת בְּכַמָּה חִיּוּבִים שֶׁל רְשָׁעִים רָעִים, וְכֵיוָן שֶׁהֵן עוֹלוֹת בְּפִקָּדוֹן (מקדים), הוּא מַחֲזִירָן בְּרַחֲמִים וְחָס עֲלֵיהֶן, וְאָז נִקְרֵאת אֱמוּנָה, וְאֵין אֱמוּנָה לְלֹא אֱמֶת.</p>\n<p>כָּעֵת אֵזוֹר מָתְנָיו וְאֵזוֹר חֲלָצָיו. מַה כָּאן שְׁנֵי אֵזוֹרִים? וּמָתְנַיִם וַחֲלָצַיִם, אַף עַל גַּב שֶׁהֵן אַחַת, שְׁתֵּי דְרָגוֹת הֵן, אַחַת לְמַעְלָה וְאַחַת לְמַטָּה. לְמַעְלָה בְּרֵאשִׁית נִקְרָא מָתְנַיִם, וּלְמַטָּה בַּסּוֹף נִקְרָא חֲלָצַיִם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לב) וַחֲגוֹרָה עַל חֲלָצָיִם. בַּסּוֹף, עַל רֹאשׁ הַיְרֵכַיִם. כְּשֶׁאִשָּׁה בְצַעַר, מְנַתְּקִים אוֹתָם חֲלָצַיִם מֵרֹאשׁ הַיְרֵכַיִם, וְשָׂמָה יָדֶיהָ בִּכְאֵב עֲלֵיהֶם.</p>\n<p>וְלָכֵן לִגְבוּרָה וְלִקְרָב - צֶדֶק אֵזוֹר מָתְנָיו, וְכָךְ צָרִיךְ. לְרַחֲמָנוּת וּלְטוֹב - אֱמוּנָה אֵזוֹר חֲלָצָיו. בְּדַרְגָּה אַחַת יָדוּן אֶת הָעוֹלָם וְשׁוֹלֵט לִשְׁנֵי צְדָדִים, אֶחָד לְרַחֲמִים לְיִשְׂרָאֵל, וְאֶחָד דִּין לִשְׁאָר הָעַמִּים.</p>\n<p>וְאִם תֹּאמַר, צֶדֶק הוּא דִּין הַקָּשֶׁה? וַהֲרֵי כָּתוּב (ויקרא יט) בְּצֶדֶק תִּשְׁפֹּט עֲמִיתֶךְ, (דברים טז) צֶדֶק צֶדֶק תִּרְדּף, וְכַמָּה הֵם - וַדַּאי כָּךְ זֶה, שֶׁהֲרֵי בְּצֶדֶק אֵין כְּלָל וַתְּרָנוּת. גַּם כָּךְ מִי שֶׁדָּן אֶת חֲבֵרוֹ, לֹא צָרִיךְ לַעֲשׂוֹת לוֹ וַתְּרָנוּת מֵהַדִּין כְּלָל, אֶלָּא בְּצֶדֶק, שֶׁלֹּא יַשְׁגִּיחַ עַל הָאַהֲבָה, (ויקרא יט) מֹאזְנֵי צֶדֶק, בְּלִי וַתְּרָנוּת לְצַד זֶה וּלְצַד זֶה לְמִי שֶׁנּוֹתֵן וּלְמִי שֶׁמְּקַבֵּל. וּמִשּׁוּם זֶה דַּרְגָּה אַחַת הִיא, וּמִתְחַלֶּקֶת לִשְׁנֵי צְדָדִים. וּשְׁנֵי צְדָדִים אֵלֶּה, שְׁנֵי אֵזוֹרִים, עוֹמְדִים, אֶחָד לִשְׁאָר הָעַמִּים וְאֶחָד לְיִשְׂרָאֵל. וּבְשָׁעָה שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, הִתְאַזְּרוּ בָאֵזוֹרִים הַלָּלוּ - אֶחָד שֶׁל קְרָב, וְאֶחָד הָיָה שֶׁל שָׁלוֹם. (והכל היה בצדק)</p>\n<p>כְּשֶׁיִּתְיָעֵץ בָּלָק, אָמַר וַאֲגָרֲשֶׁנּוּ מִן הָאָרֶץ. אָמַר, אוֹתָהּ דַּרְגָּה (שנאחזה בו הארץ, וזה וכו') שֶׁהֵם נֶאֱחָזִים בָּהּ, מִן הָאָרֶץ וַדַּאי. וְזֶהוּ כִּי עָצוּם הוּא מִמֶּנִּי, בְּוַדַּאי. מִי יָכוֹל לְהִלָּחֵם וְלַעֲמֹד בָּהֶם בְּיִשְׂרָאֵל?! דַּרְגָּתָם חֲזָקָה הִיא מִשֶּׁלִּי! וּמִשּׁוּם זֶה - וַאֲגָרֲשֶׁנּוּ מִן הָאָרֶץ. וְאִם אֲגָרֲשֶׁנּוּ מִן הָאָרֶץ הַזֹּאת וַאֲגָרֵשׁ אוֹתָם מִמֶּנָּה, אוּכַל לַעֲשׂוֹת כָּל רְצוֹנִי. כֹּחָם הוּא בַּמֶּה? בַּפֶּה וּבְמַעֲשֶׂה. הֲרֵי הַפֶּה שֶׁלְּךְ, וְהַמַּעֲשֶׂה שֶׁלִּי.</p>\n<p>כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וְגוֹ'. וְכִי מֵאַיִן הָיָה יוֹדֵעַ? הֲרֵי פֵּרְשׁוּהָ, שֶׁהֲרֵי בַּהַתְחָלָה כָּתוּב, (במדבר כא) וְהוּא נִלְחַם בְּמֶלֶךְ מוֹאָב הָרִאשׁוֹן וַיִּקַּח אֶת כָּל אַרְצוֹ מִיָּדוֹ. שֶׁשָּׂכַר אֶת בִּלְעָם וְכוּ'. אֲבָל כִּי יָדַעְתִּי, יְדִיעָה וַדַּאי יָדַע בְּחָכְמָתוֹ. אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וְגוֹ', מַה צָּרִיךְ כָּאן בְּרָכָה, שֶׁהֲרֵי בִּשְׁבִיל קְלָלָה הָלַךְ? וְאִם אוֹתוֹ דָּבָר שֶׁהָיָה יוֹדֵעַ מִבִּלְעָם בַּהַתְחָלָה הָיָה קְלָלָה, מַה זֶּה אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ?</p>\n<p>אֶלָּא דָּבָר זֶה לֹא יְדַעְתִּיו וְלֹא זָכִיתִי בוֹ עַד שֶׁבָּא רַבִּי אֶלְעָזָר וְדָרַשׁ, (תהלים לד) אֲבָרְכָה אֶת ה' בְּכָל עֵת תָּמִיד תְּהִלָּתוֹ בְּפִי. וְכָתוּב (שם טז) אֲבָרֵךְ אֶת ה' אֲשֶׁר יְעָצַנִי. מִי (צריך) שֶׁצָּרִיךְ בְּרָכָה מִן הַתַּחְתּוֹנִים. אֶת, שֶׁהֲרֵי נֶאֱחָז בָּהֶם כְּשַׁלְהֶבֶת בִּפְתִילָה. וְדָוִד שֶׁיָּדַע אֶת זֶה, אָמַר אֲבָרְכָה אֶת. אָמַר אוֹתוֹ רָשָׁע, אוֹתָהּ דַּרְגָּה שֶׁלָּהֶם, אֲחוּזָה בָהֶם בִּגְלַל בִּרְכוֹתֵיהֶם, שֶׁמְּבָרְכִים אוֹתָהּ בְּכָל יוֹם. כֹּחַ יֵשׁ לְךְ לְבָרֵךְ אֶת אוֹתָהּ דַּרְגָּה, וְתַעֲקֹר אוֹתָהּ מֵהֶם. וְזֶהוּ כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וְגוֹ'. וּבָזֶה נוּכַל לָהֶם. תְּבָרֵךְ אֶת אוֹתָהּ דַּרְגָּה, וּתְקַלֵּל אֶת הַפְּתִילָה. וְעַל זֶה אָמַר וְאָנֹכִי אִקָּרֶה כֹּה, אֶעֱקֹר אוֹתָהּ מֵהֶם שֶׁלֹּא תֹאחַז בָּהֶם.</p>\n<p>וְעוֹד אִקָּרֶה כֹּה - אַשְׁפִּיעַ וְאַמְשִׁיךְ אֶת אוֹתָהּ דַּרְגָּה בַּחֲטָאִים וְטֻמְאָה וּבְקֶרִי וּבְטֻמְאָה שֶׁעָשׂוּ בָנֶיהָ, וְהִיא תַעֲשֶׂה אִתָּם גְּמָר. מִיָּד - וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן וּקְסָמִים בְּיָדָם. שֶׁלֹּא יֹאמַר אוֹתוֹ רָשָׁע שֶׁאֵין עִמּוֹ אוֹתָם מִינֵי כְשָׁפִים שֶׁצָּרִיךְ בְּיָדוֹ לְהִתְעַכֵּב עֲלֵיהֶם (ויתעכב עליהם).</p>"],[9522012416,"<p>פָּתַח וְאָמַר, (ירמיה מו) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל (וגו'), כִּי אִתְּךְ אָנִי וְגוֹ'. פָּסוּק זֶה נֶאֱמַר וְהִתְעוֹרְרוּ בוֹ, אֲבָל עַד כָּעֵת יֵשׁ לְהִתְעוֹרֵר יוֹתֵר. אַתָּה מַהוּ? סוֹד אֲרוֹן הַבְּרִית, שֶׁזּוֹהִי דַרְגָּה שֶׁהוֹלֶכֶת בַּגָּלוּת עִם בָּנֶיהָ, הָעָם הַקָּדוֹשׁ. בְּשָׁעָה שֶׁבִּקֵּשׁ מֹשֶׁה רַחֲמִים עַל יִשְׂרָאֵל, מַה כָּתוּב? (במדבר יא) וְאִם כָּכָה אַתְּ עֹשֶׂה לִּי הָרְגֵנִי נָא הָרֹג, וּפֵרְשׁוּהָ.</p>\n<p>אֲבָל כָּךְ אָמַר מֹשֶׁה, דַּרְגָּה אַחַת שֶׁנָּתַתָּ לִי נִקְרֵאת אַתָּה, מִשּׁוּם שֶׁאֵין לָהּ פְּרֵדָה מִמְּךְ. ה' שֶׁלָּהּ נֶאֶחְזָה בְיִשְׂרָאֵל. אִם אַתָּה (תשמידם מהעולם) יִשָּׁמְדוּ בָעוֹלָם, הֲרֵי ה' שֶׁל הַשֵּׁם הַזֶּה שֶׁאֲחוּזָה בָהֶם מָעֳבֶרֶת מִמֶּנּוּ, אִם כָּךְ אַתְּ עֹשֶׂה לִּי - שֶׁה', עִקַּר הַשֵּׁם הַזֶּה, תֵּעָקֵר.</p>\n<p>וְעַל זֶה אָמַר יְהוֹשֻׁעַ אַחַר כָּךְ, (יהושע ז) וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. שֶׁהֲרֵי וַדַּאי שֵׁם זֶה עִקַּר וִיסוֹד הַכֹּל, אַתָּה הוּא ה'. וּמֹשֶׁה, אַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא אָמַר לוֹ כָּךְ, יָדַע שֶׁזֶּה בָזֶה תָלוּי וְהַחֵטְא גוֹרֵם. וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְגוֹ', הַכֹּל אֶחָד. כִּי אִתְּךְ אֲנִי, הֲרֵי בֵּאַרְנוּ כִּי אִתִּי אַתָּה לֹא כָתוּב, אֶלָּא כִּי אִתְּךְ אָנִי. כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם, בְּכָל הַגּוֹיִם אֶעֱשֶׂה כָלָה.</p>\n<p>רַב הַמְנוּנָא הָרִאשׁוֹן אָמַר, דֹּחַק וְצָרוֹת יִשְׂרָאֵל כַּמָּה טוֹב וְכַמָּה תוֹעֶלֶת גָרְמוּ לָהֶם. רִפְיוֹן שֶׁל שְׁאָר הָעַמִּים כַּמָּה רָעוֹת גָּרְמוּ לָהֶם. דּחַק וְצָרוֹת יִשְׂרָאֵל גּוֹרֵם לָהֶם שֶׁטּוֹב יִהְיֶה וְתוֹעֶלֶת, וּמָהֵם? כָּלָה. הַכֹּל דָּחוּק. רִפְיוֹן שֶׁל שְׁאָר הָעַמִּים גּוֹרֵם לָהֶם רִפְיוֹן וְרַע, וְזֶהוּ כָלָה. וְכָךְ רָאוּי לָהֶם, שֶׁהֲרֵי כָּל רִפְיוֹן בְּלֹא דחַק שֶׁהָיָה לָהֶם בָּעוֹלָם הַזֶּה, גּוֹרֵם לָהֶם רִפְיוֹן אַחַר כָּךְ בְּלִי דחַק. כָּלָה. (ישעיה כח) כִּי כָלָה וְנֶחֱרָצָה שָׁמַעְתִּי. כִּי אֶעֱשֶׂה כָלָה. כָלָה בְּרִפְיוֹן. לְיִשְׂרָאֵל שֶׁהָיָה לָהֶם דּחַק וְצָרוֹת - כַּלָּה, (שם סא) וְכַכַּלָּה תַּעְדֶּה כֵלֶיהָ.</p>\n<p>מַה זֶּה כֵלֶיהָ? אֵלּוּ יִשְׂרָאֵל שֶׁהֵם כְּלֵי הַכַּלָּה הַזּוֹ. יִשְׂרָאֵל שֶׁהָיָה לָהֶם דּחַק וְצָרוֹת - (עמוס ט) אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת, סֻכַּת שָׁלוֹם. לִשְׁאָר הָעַמִּים שֶׁהָיָה לָהֶם רִפְיוֹן צָרָה וְצוּקָה - כָלָה בְּרִפְיוֹן, כְּמוֹ שֶׁהָיָה לָהֶם בַּתְּחִלָּה. וְעַל זֶה (ירמיהמו) כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם וְגוֹ', וְאֹתְךְ לֹא אֶעֱשֶׂה כָלָה. שֶׁהֲרֵי אֵין רָאוּי לְךְ, שֶׁהֲרֵי דְּחוּקִים הֱיִיתֶם בַּתְּחִלָּה פְּעָמִים רַבּוֹת בְּדחַק שֶׁל גָּלוּת תָּמִיד, וְדָחוּק תִּהְיֵה כַּלָּה. (תוריש כליה).</p>\n<p>וְיִסַּרְתִּיךָֹ לַמִּשְׁפָּט. פָּסוּק זֶה כָּךְ צָרִיךְ לוֹ לְכָתְבוֹ: וְיִסַּרְתִּיךְ בַּמִּשְׁפָּט, שֶׁהֲרֵי מָתַי יִסּוּרִים? בִּשְׁעַת הַדִּין. (וכאן לא כך, אלא) מַה זֶּה וְיִסַּרְתִּיךְ לַמִּשְׁפָּט? אֶלָּא כָּתוּב (ישעיה ג) ה' בְּמִשְׁפָּט יָבא עִם זִקְנֵי עַמּוֹ. וְאוֹתוֹ הַיּוֹם הִקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא רְפוּאָה לְיִשְׂרָאֵל עַד שֶׁלֹּא יַעֲלוּ לַדִּין כְּדֵי שֶׁיּוּכְלוּ לַעֲמֹד בּוֹ. וּמָה רְפוּאָתָם? הִיא שֶׁבְּכָל שָׁעָה וְשָׁעָה הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן יִסּוּרִים לְיִשְׂרָאֵל מְעַט מְעַט בְּכָל פַּעַם וּפַעַם וּבְכָל דּוֹר וָדוֹר, כְּדֵי שֶׁכְּשֶׁיִּכָּנְסוּ לְיוֹם הַדִּין הַגָּדוֹל שֶׁיִּחְיוּ הַמֵּתִים, לֹא יִשְׁלֹט עֲלֵיהֶם הַדִּין.</p>\n<p>וְנַקֵּה לֹא אֲנַקֶּךָּ, מַהוּ? אֶלָּא כְּשֶׁיִּשְׂרָאֵל עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לְבַדָּם וְלֹא נִכְנָסִים בְּדִין עִם שְׁאָר הָעַמִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לָהֶם לִפְנִים מִשּׁוּרַת הַדִּין, וְהוּא מְכַפֵּר עֲלֵיהֶם. וּבִזְמַן שֶׁנִּכְנָסִים בְּדִין עִם שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מָה עוֹשֶׂה? יוֹדֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁסָּמָאֵ\"ל אַפּוֹטְרוֹפּוֹס שֶׁל עֵשָׂו יָבא לְהַזְכִּיר חֲטָאֵי יִשְׂרָאֵל וְכוֹנֵס כֻּלָּם אֵלָיו לְיוֹם הַדִּין, וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִקְדִּים לָהֶם רְפוּאָה, וְעַל כָּל חֵטְא וְחֵטְא הִלְקָה וְנִקָּה אוֹתָם בְּיִסּוּרִים מְעַט מְעַט. וְזֶהוּ וְנַקֵּה, בְּיִסּוּרִין. וּמִשּׁוּם זֶה בְּדִין אֱמֶת לֹא אֲנַקֶּךָּ מֵעוֹלָם בְּדִין אַחֲרֵי שֶׁסָּבַלְתָּ יִסּוּרִים מְעַט מְעַט.</p>\n<p>וְעוֹד לֹא אֲנַקֶּךָּ - אַף עַל גַּב שֶׁאַתֶּם בָּנַי, לֹא אֶעֱזֹּב אֶת חֲטָאֵיכֶם, אֶלָּא אֶפָּרַע מִכֶּם מְעַט מְעַט, כְּדֵי שֶׁתִּהְיוּ צַדִּיקִים לְיוֹם הַדִּין הַגָּדוֹל. כְּשֶׁבָּאִים לַדִּין, בָּא סָמָאֵ\"ל בְּכַמָּה פְתָקִים עֲלֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא פִּתְקֵי הַיִּסּוּרִים שֶׁסָּבְלוּ יִשְׂרָאֵל עַל כָּל חֵטְא וְחֵטְא, וְנִמְחוּ כָּל הַחֲטָאִים, וְלֹא עָשָׂה לָהֶם וַתְּרָנוּת כְּלָל. אָז תָּשַׁשׁ כֹּחוֹ וְחֵילוֹ שֶׁל סָמָאֵ\"ל וְלֹא יָכוֹל לָהֶם, וְיָעֳבַר מֵהָעוֹלָם הוּא וְכָל צְדָדָיו וְכָל הָעַמִּים. זֶהוּ שֶׁכָּתוּב וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְגוֹ', בִּגְלַל זֶה וְיִסַּרְתִּיךְ לַמִּשְׁפָּט וְנַקֵּה לֹא אֲנַקֶּךָּ.</p>"],[9522012417,"<p>וְדָוִד הַמֶּלֶךְ אָמַר, (תהלים יא) כִּי הִנֵּה הָרְשָׁעִים יִדְרְכוּן קֶשֶׁת כּוֹנְנוּ וְגוֹ'. וְאַף עַל גַּב שֶׁפָּסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ, עַל שֶׁבְנָא וְיוֹאָח הַמְמֻנִּים שֶׁל חִזְקִיָּה נֶאֱמַר. אֲבָל פָּסוּק זֶה עַל סָמָאֵ\"ל וְסִיעָתוֹ גַּם כָּךְ נֶאֱמַר, שֶׁכָּל מַעֲשָׂיו וַעֲצוֹתָיו הֵם עַל יִשְׂרָאֵל. בָּלָק וּבִלְעָם אוֹתוֹ דֶּרֶךְ מַמָּשׁ נָקְטוּ, וַהֲרֵי נִתְבָּאֵר שֶׁחִבּוּר רָע עָשׂוּ. אָמְרוּ, עֲמָלֵ\"ק - עַ\"ם לָ\"ק, עַם שֶׁהִלְקָה אוֹתָם כְּנָחָשׁ שֶׁמַּכֶּה בִזְנָבוֹ. הֲרֵי אָנוּ יוֹתֵר. בָּלָ\"ק - בָּ\"א לָ\"ק, בָּא מִי שֶׁמַּלְקֶה אוֹתָם בִּרְצוֹנוֹ. בִּלְעָ\"ם - בַּ\"ל עַ\"ם, אֵין עַם וְאֵין רוֹעֶה. שֵׁם שֶׁלָּנוּ גּוֹרֵם לְהַשְׁמִידָם וְלַעֲקֹר אוֹתָם מִן הָעוֹלָם.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא חָשַׁב בְּגָוֶן אַחֵר אֶת שְׁמוֹתיהֶם. בְּבָלָק בַּ\"ל, בְּבִלְעָם בַּ\"ל - הֲרֵי בִּלְבֵּ\"ל. אֵיזֶה אוֹתִיּוֹת נִשְׁאֲרוּ? עֵמֶ\"ק. בִּלְבֵּל עֹמֶק מַחֲשַׁבְתָּם שֶׁלֹּא יִשְׁלְטוּ בָעוֹלָם וְלֹא יִשָּׁאֲרוּ בָעוֹלָם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, יָפֶה אָמַרְתָּ, אֲבָל בָּלָק תִּפַּח רוּחוֹ בַּגֵּיהִנֹּם, וּבִלְעָם יִשְׁתַּחֲקוּ שָׁם עַצְמוֹתָיו וְרוּחוֹ. וְכָךְ הוּא עֵצָה רָעָה לָקְחוּ עַל הַפַּטְרוֹן, עַל הַכֹּה הַזּוֹ, שֶׁחָשְׁבוּ לַעֲקֹר אֶת הַכֹּה הַזּוֹ, וְחָשְׁבוּ לְסַלְּקָהּ לְצַד רָע בַּפֶּה וּבְמַעֲשֶׂה.</p>\n<p>אָמַר אוֹתוֹ רָשָׁע, הָרִאשׁוֹנִים הִשְׁתַּדְּלוּ וְלֹא יָכְלוּ, דּוֹר הַפְּלַגָּה הִשְׁתַּדְּלוּ וְלֹא יָכְלוּ. עָשׂוּ מַעֲשֶׂה, וּפֶה חָסֵר מֵהֶם, שֶׁלְּשׁוֹנָם הִתְבַּלְבְּלָה וְלֹא יָכְלוּ. אֲבָל אַתָּה, הֲרֵי פִּיךְ שָׁנוּן וּלְשׁוֹנְךְ מְתֻקֶּנֶת בִּשְׁנֵי צְדָדִים אֵלּוּ - אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ, וַאֲשֶׁר תָּאֹר יוּאָר. אוֹתוֹ הַצַּד שֶׁאַתָּה רוֹצֶה לְסַלֵּק לְמַעְלָה בְּפִיךְ וּלְשׁוֹנְךְ, הִסְתַּלֵּק. וְאוֹתוֹ הַצַּד שֶׁאַתָּה רוֹצֶה לְקַלֵּל, בְּכֹחַ פִּיךְ תְּקַלֵּל (וצד לפניך) וְהַכֹּל תָּלוּי בְּךְ, שֶׁהֲרֵי הַמַּעֲשֶׂה נִתְתַּקֵּן. אֲבָל בְּדִבּוּר הַכֹּל תָּלוּי, וְעַל זֶה (במעשה) כְּמַעֲשֵׂה נַחַשׁ אֲנִי אַתְקִין, וְאַתָּה תַּשְׁלִים הַכֹּל בְּפִיךְ. אוֹתוֹ צַד שֶׁתְּבָרֵךְ - מְבֹרָךְ, וְאוֹתוֹ צַד שֶׁתָּאֹר - יוּאָר.</p>\n<p>וְהוּא לֹא יָדַע שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא (איוביב) מֵסִיר שָׂפָה לְנֶאֱמָנִים וְטַעַם זְקֵנִים יִקָּח, וְהַכֹּל עוֹמֵד בִּרְשׁוּתוֹ. מֵסִיר שָׂפָה לְנֶאֱמָנִים - אֵלּוּ דּוֹר הַפְּלַגָּה, שֶׁבִּלְבֵּל לְשׁוֹנָם שֶׁלֹּא יִשְׁלְטוּ בַדָּבָר כְּלָל, שֶׁכָּתוּב (בראשית יא) אֲשֶׁר לֹא יִשְׁמְעוּ אִישׁ שְׂפַת רֵעֵהוּ. וְטַעַם זְקֵנִים יִקָּח - אֵלּוּ בִּלְעָם וּבָלָק שֶׁשְּׁנֵיהֶם הָיוּ בְעֵצָה אַחַת, שֶׁכָּתוּב וַיַּעַל בָּלָק וּבִלְעָם פָּר וָאַיִל בַּמִּזְבֵּחַ.</p>\n<p>בֹּא וּרְאֵה, אוֹתוֹ בִּלְעָם הָרָשָׁע כָּל מַעֲשָׂיו לְרָע, בְּרוּם לֵב. שְׁנֵיהֶם הָיוּ מַעֲלִין קָרְבָּן, שֶׁכָּתוּב וַיַּעַל בָּלָק וּבִלְעָם. וְכָל הַמִּזְבְּחוֹת הָיָה בָּלָק מְסַדֵּר, וְהוּא הָרָשָׁע הָיָה מְשַׁבֵּחַ עַצְמוֹ וְאוֹמֵר (במדבר כג), אֶת שִׁבְעַת (שבע) הַמִּזְבְּחֹת עָרַכְתִּי וָאַעַל פָּר וָאַיִל בַּמִּזְבֵּחַ. וְאִלּוּ אֶת בָּלָק לֹא שִׁתֵּף יַחַד אִתּוֹ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע! הַכֹּל יָדַעְתִּי, אֶלָּא שׁוּב אֶל בָּלָק, וְאַתָּה לֹא צָרִיךְ לְדַבֵּר, אֶלָּא - וְכֹה תְדַבֵּר. זֶהוּ שֶׁכָּתוּב וְטַעַם זְקֵנִים יִקָּח.</p>\n<p>דָּבָר אַחֵר וְטַעַם זְקֵנִים יִקָּח - שֶׁכָּתוּב וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן וּקְסָמִים בְּיָדָם. טַעַם אוֹתָם זְקֵנִים נָטַל מֵהֶם, וְלֹא יָכְלוּ לִשְׁלֹט כְּלָל בְּכִשְׁפֵיהֶם. וַיְדַבְּרוּ אֵלָיו דִּבְרֵי בָלָק, דְּבָרִים בְּגִלּוּי וְלֹא בְלַחַשׁ. פְּגוּם אֹזֶן הָיָה, וּפְגוּם עַיִן, וּפְגוּם רֶגֶל. מִשְּׁלֹשָׁה מְקוֹמוֹת הָיָה פָּגוּם. מְתֻקָּן הָיָה לַצַּד הָאַחֵר, וְכָךְ צָרִיךְ אוֹתוֹ צַד אַחֵר - מָקוֹם שֶׁהַפְּגָם שָׁרוּי, כָּל מִין לְמִינוֹ.</p>"],[9522012418,"<p>וַיֹּאמֶר אֲלֵיהֶם לִינוּ פֹה הַלַּיְלָה וַהֲשִׁבֹתִי. הֵם כָּתוּב, וַיְדַבְּרוּ אֵלָיו. וְהוּא כָּתוּב, וַיֹּאמֶר אֲלֵיהֶם. לִינוּ פֹה הַלַּיְלָה, מִשּׁוּם שֶׁהַלַּיְלָה הוּא שְׁעַת הַצַּד הָאַחֵר לִכְשָׁפִים, בְּשָׁעָה שֶׁנִּמְצָאִים וְשׁוֹלְטִים צְדָדִים רָעִים וּמִתְפַּשְּׁטִים בָּעוֹלָם. כַּאֲשֶׁר יְדַבֵּר ה' אֵלָי, שֶׁבַח הָיָה מְשַׁבֵּחַ אֶת עַצְמוֹ בְּשֵׁם ה'.</p>\n<p>וַיֵּשְׁבוּ שָׂרֵי מוֹאָב. וְשָׂרֵי מִדְיָן נִפְרְדוּ מֵהֶם וְלֹא רָצוּ לָשֶׁבֶת שָׁם. וְזִקְנֵי מוֹאָב נִשְׁאֲרוּ, שֶׁכָּתוּב וַיֵּשְׁבוּ שָׂרֵי מוֹאָב, לְבַדָּם. נָאֶה עָשׂוּ מִדְיָן שֶׁנִּפְרְדוּ מִכֹּל וָכֹל מֵהֶם. וְאִלְמָלֵא לֹא הָיוּ מַכִּים בַּסּוֹף שֶׁהָיוּ בַעֲצַת בִּלְעָם, לִשְׁלֹחַ נְשׁוֹתֵיהֶם לְיִשְׂרָאֵל בַּשִּׁטִּים לְיִשְׂרָאֵל לְהַטְעוֹתָם. וְהַכָּתוּב מוֹכִיחַ אֶת חֶטְאָם, שֶׁכָּתוּב (במדבר כה) כִּי צֹרַרִים הֵם לָכֶם בְּנִכְלֵיהֶם אֲשֶׁר נִכְּלוּ לָכֶם עַל דְּבַר פְּעוֹר וְעַל דְּבַר כָּזְבִּי בַת נְשִׂיא מִדְיָן אֲחֹתָם וְגוֹ'. בִּשְׁנֵי אֵלֶּה חָטְאוּ, וְהָיָה חֶטְאָם גָּדוֹל. הִכּוּ אַחַר כָּךְ בַּזָּנָב. וְלָכֵן אֵלּוּ נִשְׁאֲרוּ אִתּוֹ, וְאֵלּוּ הָלְכוּ לְבַדָּם.</p>\n<p>דָּבָר אַחֵר וַיֵּשְׁבוּ שָׂרֵי מוֹאָב עִם בִּלְעָם - כַּמָּה נָאֶה הָיָה לָהֶם לִבְנֵי מִדְיָן שֶׁהָלְכוּ, אִם רְצוֹנָם כָּךְ. אֲבָל יְשִׁיבָה שֶׁיָּשְׁבוּ הֵם בְּמוֹאָב גָּרְמָה לָהֶם טוֹב מִשּׁוּם שֶׁנִּשְׁאֲרוּ שָׁם. וּמַה שֶּׁהָלְכוּ אוֹתָם שֶׁל מִדְיָן, גָּרְמוּ לָהֶם רָע. מָה הַטַּעַם? אֵלּוּ חָשְׁשׁוּ לִכְבוֹד דְּבַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיָשְׁבוּ. וְאֵלּוּ לֹא חָשְׁשׁוּ לָזֶה כְּלוּם, וְהָלְכוּ לְדַרְכָּם.</p>\n<p>בְּשָׁעָה שֶׁאָמַר אוֹתוֹ רָשָׁע וַהֲשִׁבתִי אֶתְכֶם דָּבָר כַּאֲשֶׁר יְדַבֵּר ה', מִיָּד הִזְדַּעְזְעוּ אוֹתָם שֶׁל מוֹאָב לַדָּבָר הַזֶּה וְיָשְׁבוּ שָׁם. וְאוֹתָם שֶׁל מִדְיָן לֹא חָשְׁשׁוּ לָזֶה כְּלוּם וְהָלְכוּ לָהֶם, וְנֶעֶנְשׁוּ אַחַר כָּךְ. וְעַל זֶה, וַיֵּשְׁבוּ שָׂרֵי מוֹאָב עִם בִּלְעָם. בְּאוֹתוֹ הַלַּיְלָה אוֹתוֹ רָשָׁע לָחַשׁ לְחָשִׁים וְעָשָׂה בִקְסָמִים, וְהִמְשִׁיךְ עֲלֵיהֶם רוּחַ מִלְמָעְלָה. מִיָּד - וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם, אֱלֹהִים סְתָם, דַּרְגָּתוֹ מִצַּד אַחֵר שֶׁל הַשְּׂמֹאל.</p>"],[9522012419,"<p>וַיֹּאמֶר מִי הָאֲנָשִׁים הָאֵלֶּה עִמָּךְ. דַּרְגָּתוֹ מִצַּד הַשְּׂמֹאל הָיְתָה, שֶׁהִצְטָרֵךְ לִשְׁאֹל. וְאַף עַל גַּב שֶׁהַחֲבֵרִים הִתְעוֹרְרוּ בָזֶה בְּגָוֶן אַחֵר, וְהֵם אָמְרוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא (עשה בו) נִסָּה אוֹתוֹ בִּדְבָרָיו. שְׁלֹשָׁה הָיוּ., אֶחָד חִזְקִיָּה, וְאֶחָד יְחֶזְקֵאל, וְאֶחָד בִּלְעָם. שְׁנַיִם לֹא עָמְדוּ כָרָאוּי, וְאֶחָד עָמַד, וּמִיהוּ? יְחֶזְקֵאל, שֶׁכָּתוּב (יחזקאל לז) הֲתִחְיֶינָה הָעֲצָמוֹת הָאֵלֶּה. וְהוּא שָׁב וְאָמַר, וַיֹּאמֶר ה' אֱלֹהִים אַתָּה יָדָעְתָּ. חִזְקִיָּה אָמַר, (מלכים ב כ) מֵאֶרֶץ רְחוֹקָה בָּאוּ (אלי) מִבָּבֶל. בִּלְעָם אָמַר, בָּלָק בֶּן צִפּוֹר מֶלֶךְ מוֹאָב שָׁלַח אֵלַי. חָשׁוּב אֲנִי בְּעֵינֵי מְלָכִים וְשַׁלִּיטִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁאַל אוֹתוֹ לְהַטְעוֹתוֹ, שֶׁכָּתוּב (איוב יב) מַשְׂגִּיא לַגּוֹיִם וַיְאַבְּדֵם, וּפֵרְשׁוּהָ.</p>\n<p>כּוּתִי אֶחָד שָׁאַל אֶת רַבִּי אֶלְעָזָר, אָמַר לוֹ, כֹּחַ חָזָק רָאִיתִי בְּבִלְעָם יוֹתֵר מִמֹּשֶׁה. שֶׁאִלּוּ בְּמֹשֶׁה כָּתוּב וַיִּקְרָא אֶל מֹשֶׁה, וּבְבִלְעָם כָּתוּב וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם, וְכָתוּב וַיָּבא אֱלֹהִים אֶל בִּלְעָם.</p>\n<p>אָמַר לוֹ, לְמֶלֶךְ שֶׁיּוֹשֵׁב בְּהֵיכָלוֹ עַל כִּסֵּא, וּמְצֹרָע אֶחָד קָרָא לַפֶּתַח. אָמַר: מִי הוּא שֶׁמַּכֶּה לַשַּׁעַר. אָמְרוּ: מְצֹרָע פְּלוֹנִי. אָמַר: אַל יִכָּנֵס לְכָאן וְלֹא יְטַנֵּף אֶת הַהֵיכָל, יָדַעְתִּי שֶׁאִם עִם שָׁלִיחַ אֹמַר לוֹ, לֹא יַחְשֹׁשׁ, וְיֵלֵךְ בְּנִי וְיִטָּמֵא וְיִקְרַב אֵלָיו. אֲבָל אֲנִי אֵלֵךְ וְאַתְרֶה בּוֹ שֶׁיַּרְחִיק דַּרְכּוֹ מִמּוֹשַׁב בְּנִי וְלֹא יְטַמֵּא אוֹתוֹ. הִקְדִּים הַמֶּלֶךְ וְהָלַךְ אֵלָיו וְהִתְרָה, וְאָמַר לוֹ: מְצֹרָע מְצֹרָע, מְנַע רַגְלְךְ מֵהַדֶּרֶךְ שֶׁבְּנִי נִמְצָא שָׁם, וְאִם לֹא - אֲנִי נִשְׁבַּע שֶׁיַּעֲשׂוּ בְּנֵי שִׁפְחוֹתַי מִגּוּפְךְ חֲתִיכוֹת.</p>\n<p>כְּשֶׁאֲהוּב הַמֶּלֶךְ קוֹרֵא לַפֶּתַח, אָמַר הַמֶּלֶךְ: מִי הוּא? אָמְרוּ: פְּלוֹנִי אוֹהַבְךְ. אָמַר הַמֶּלֶךְ: אֲהוּבִי חֲבִיב נַפְשִׁי, לֹא יִקְרָא לוֹ קוֹל אַחֵר, אֶלָּא אֲנִי. צָוַח הַמֶּלֶךְ וְאָמַר: פְּלוֹנִי פְּלוֹנִי הִכָּנֵס, חֲבִיב נַפְשִׁי, אֲהוּבִי, הַתְקִינוּ הֵיכָלוֹת לְדַבֵּר אִתּוֹ.</p>\n<p>כָּךָ בִּלְעָם אוֹתוֹ מְצֹרָע, רָחוֹק מִבְּנֵי אָדָם, קָרָא לְפֶתַח הַמֶּלֶךְ. שָׁמַע הַמֶּלֶךְ וְאָמַר: מְצֹרָע טָמֵא לֹא יִכָּנֵס וְלֹא יְטַנֵּף אֶת הֵיכָלִי. אֲנִי צָרִיךְ לָלֶכֶת לְהַתְרוֹת בּוֹ שֶׁלֹּא יִקְרַב לְשַׁעַר בְּנִי וְלֹא יְטַמֵּא אוֹתוֹ. וְעַל זֶה, וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם. אָמַר לוֹ: מְצֹרָע מְצֹרָע, לֹא תֵלֵךְ עִמָּהֶם, לֹא תָאֹר אֶת הָעָם כִּי בָרוּךְ הוּא. אַל תִּקְרַב לִבְנִי הֵן לְטוֹב הֵן לְרָע, טָמֵא אַתָּה בַכֹּל. אֲבָל בְּמֹשֶׁה כָּתוּב וַיִּקְרָא אֶל מֹשֶׁה, קוֹל הַמֶּלֶךְ, וְלֹא עַל יְדֵי שָׁלִיחַ אַחֵר. מֵאֹהֶל מוֹעֵד, מֵהֵיכַל הַמֶּלֶךְ, מֵהֵיכָל הַמְתֻקָּן, מֵהֵיכָל הַנִּכְבָּד שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים תְּאֵבִים אֵלָיו וְלֹא יְכוֹלִים לְהִתְקָרֵב אֵלָיו.</p>\n<p>וַיֹּאמֶר בִּלְעָם אֶל הָאֱלֹהִים בָּלָק בֶּן צִפֹּר. וְהוּא אָמַר מֶלֶךְ מוֹאָב, מֶלֶךְ חָשׁוּב, שָׁלַח אֵלָי. מֶלֶךְ מוֹאָב. רְאוּ גַאֲוָה שֶׁל אוֹתוֹ הָרָשָׁע, (שאפלו לבלק לא החשיב כלום) שֶׁכָּתוּב מֶלֶךְ מוֹאָב וְלֹא אָמַר לְמוֹאָב, מִכְּלָל אָדָם שֶׁלֹּא רָאוּי לְמֶלֶךְ, וַהֲרֵי נַעֲשָׂה מֶלֶךְ לְמוֹאָב. רִאשׁוֹן מַה כָּתוּב בּוֹ? (במדבר כא) וְהוּא נִלְחַם בְּמֶלֶךְ מוֹאָב הָרִאשׁוֹן. מֶלֶךְ בֶּן מֶלֶךְ. חָשׁוּב בֶּן חָשׁוּב. אֲבָל זֶה כָּתוּב מֶלֶךְ לְמוֹאָב, הַפָּסוּק מֵעִיד מֶלֶךְ לְמוֹאָב. וַהֲרֵי הִתְעוֹרַרְנוּ שֶׁהִתְכַּוֵּן הוּא לְגֵאוּת לֵב גְּדוֹלָה: כָּל מַלְכֵי הָעוֹלָם שׁוֹלְחִים אֵלַי שְׁלִיחֵיהֶם. (ויאמר בלעם אל האלהים בלק בן צפר מלך מואב שלח אלי. ראו גאותו של אותו רשע, שאמר מלך מואב ולא אמר מלך למואב. במלך מואב הראשון מה כתוב בו, ' (במדבר כא) והוא נלחם במלך מואב הראשון. מלך בן מלך. חשוב בן חשוב. אבל זה מלך למואב כתוב. והפסוק מעיד עליו, מלך למואב בעת ההיא גבר שלא ראוי למלך והנה נעשה מלך. והרי התעוררנו שמתכון לגאות לב גדולה, שכל מלכי העולם שולחים אלי שליחים) (וחשוב אני אליהם).</p>"],[9522012420,"<p>רַבִּי פִּנְחָס הָיָה הוֹלֵךְ לִרְאוֹת אֶת בִּתּוֹ, אִשְׁתּוֹ שֶׁל רַבִּי שִׁמְעוֹן, שֶׁהָיְתָה חוֹלָה, וְהָיוּ הוֹלְכִים אִתּוֹ הַחֲבֵרִים, וְהוּא רָכַב עַל חֲמוֹרוֹ. עַד שֶׁהָיָה הוֹלֵךְ בַּדֶּרֶךְ, פָּגַע בִּשְׁנֵי עַרְבִים. אָמַר לָהֶם, בְּשָׂדֶה זֶה הִתְעוֹרֵר קוֹל מִימֵי הָעוֹלָם. אָמְרוּ לוֹ, מִימֵי הָעוֹלָם אֵין אָנוּ יוֹדְעִים, מִיָּמֵינוּ אָנוּ יוֹדְעִים. שֶׁהֲרֵי יוֹם אֶחָד הָיוּ אוֹתָם לִסְטִים מְקַפְּחִים דְּרָכִים שֶׁל אֲנָשִׁים בְּאוֹתוֹ שָׂדֶה, וּפָגְעוּ בְּאוֹתָם יְהוּדִים וְרָצוּ לְקַפְּחָם, וְנִשְׁמַע מֵרָחוֹק בַּשָּׂדֶה הַזֶּה קוֹל הַחֲמוֹר הַזֶּה שֶׁנָּעַר פַּעֲמַיִם, וּבָאָה שַׁלְהֶבֶת אֵשׁ בְּאוֹתוֹ קוֹל (באותו שדה) וְשָׂרַף אוֹתָם, וְנִצְּלוּ אוֹתָם יְהוּדִים. אָמַר לָהֶם, עַרְבִים, בְּדָבָר זֶה שֶׁאֲמַרְתֶּם לִי, תִּנָּצְלוּ יוֹם זֶה מִלִּסְטִים אֲחֵרִים שֶׁמְּחַכִּים לָכֶם בַּדֶּרֶךְ.</p>\n<p>בָּכָה רַבִּי פִּנְחָס וְאָמַר, רִבּוֹן הָעוֹלָם התרַחָשּוּת נס זִה עָשּיּתָ בּגלָליּ, וְנִצְּלוּ אוֹתָם יְהוּדִים וְלֹא יָדַעְתִּי. פָּתַח וְאָמַר, (תהלים קלו) לְעֹשֵׂה נִפְלָאוֹת גְּדלוֹת לְבַדּוֹ כִּי לְעוֹלָם חַסְדּוֹ. כַּמָּה טוֹבוֹת עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּנֵי הָאָדָם, וְכַמָּה נִסִּים מַרְחִישׁ לָהֶם בְּכָל יוֹם, וְלֹא יוֹדֵעַ, רַק הוּא בִּלְבַדּוֹ. אָדָם קָם בַּבֹּקֶר וְנָחָשׁ בָּא לְהָרְגוֹ, וְהָאָדָם שָׂם רַגְלוֹ עַל רֹאשׁוֹ וְהוֹרְגוֹ, וְלֹא יָדַע בָּזֶה הָאִישׁ, פְּרָט לַקָּדוֹשׁ- בָּרוּךְ-הוּא בִּלְבַדּוֹ - הָוֵי לְעֹשֵׂה נִפְלָאוֹת גְּדלוֹת לְבַדּוֹ. אָדָם הוֹלֵךְ בַּדֶּרֶךְ וְלִסְטִים מְחַכִּים לְהָרְגוֹ, בָּא אַחֵר וְנִתָּן כֹּפֶר תַּחְתָּיו וְהוּא נִצָּל, לֹא יָדַע הַטּוֹב שֶׁעָשָׂה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַנֵּס שֶׁהִרְחִישׁ לוֹ, רַק הוּא בִּלְבַדּוֹ - הָוֵי לְעֹשֵׂה נִפְלָאוֹת גְּדֹלוֹת לְבַדּוֹ. לְבַדּוֹ עָשָׂה וְיוֹדֵעַ, וְאַחֵר לֹא יוֹדֵעַ.</p>\n<p>אָמַר לַחֲבֵרִים, חֲבֵרִים, מַה שֶּׁשָּׁאַלְתִּי לָעַרְבִים הָאֵלֶּה שֶׁנִּמְצָאִים תָּמִיד בַּשָּׂדוֹת אִם קוֹל הַחֲבֵרִים שֶׁהֵם מִשְׁתַּדְּלִים בַּתּוֹרָה שָׁמְעוּ, שֶׁהֲרֵי רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר בְּנוֹ וּשְׁאָר הַחֲבֵרִים הָלְכוּ לְפָנֵינוּ וְלֹא יָדְעוּ מֵאִתָּנוּ, וְשָׁאַלְתִּי לָעַרְבִים הַלָּלוּ עֲלֵיהֶם, שֶׁיָּדַעְתִּי שֶׁקּוֹלוֹ שֶׁל רַבִּי שִׁמְעוֹן יַרְגִּיז שָׂדוֹת וְהָרִים, וְהֵם גִּלּוּ לִי מַה שֶּׁלֹּא יָדַעְתִּי.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, אוֹתָם עַרְבִים חָזְרוּ אֵלָיו. אָמְרוּ לוֹ, זָקֵן זָקֵן, אַתָּה שְׁאַלְתָּנוּ מִימֵי הָעוֹלָם, וְלֹא שָׁאַלְתָּ עַל יוֹם זֶה, שֶׁרָאִינוּ תְמִיהָה עַל תְּמִיהָה. רָאִינוּ חֲמִשָּׁה בְּנֵי אָדָם יוֹשְׁבִים, וְזָקֵן אֶחָד יַחַד אִתָּם, וְרָאִינוּ עוֹפוֹת מִתְכַּנְּסִים וּפוֹרְשִׂים כְּנָפַיִם עַל רָאשֵׁיהֶם, אֵלּוּ הוֹלְכִים וְאֵלּוּ שָׁבִים, וְהַצֵּל לֹא עָבַר מֵעַל רָאשֵׁיהֶם, וְאוֹתוֹ זָקֵן הֵרִים קוֹלוֹ עֲלֵיהֶם, וְהֵם שׁוֹמְעִים.</p>\n<p>אָמַר, עַל זֶה שָׁאַלְתִּי. עַרְבִים עַרְבִים, תֵּלְכוּ, וְדֶרֶךְ זוֹ תְּהֵא תְקִינָה לִפְנֵיכֶם בְּכָל מַה שֶּׁתִּרְצוּ. שְׁנֵי דְבָרִים אֲמַרְתֶּם לִי שֶׁשָּׂמַחְתִּי בָהֶם. הָלְכוּ. אָמְרוּ לוֹ הַחֲבֵרִים, אוֹתוֹ מָקוֹם שֶׁרַבִּי שִׁמְעוֹן שָׁרוּי בּוֹ, אֵיךְ אָנוּ יוֹדְעִים? אָמַר לָהֶם, תַּשְׁאִירוּ לְבַעַל פְּסִיעוֹת הַבְּהֵמוֹת שֶׁהוּא יַדְרִיךְ פְּסִיעוֹתָיו לְשָׁם. לֹא הָיָה טוֹעֵן חֲמוֹרוֹ, וַחֲמוֹרוֹ סָטָה מֵהַדֶּרֶךְ שְׁנֵי מִילִין, וְהָלַךְ לְשָׁם.</p>\n<p>הִתְחִיל לִנְהֹר שָׁלֹשׁ פְּעָמִים, יָרַד רַבִּי פִּנְחָס וְאָמַר לַחֲבֵרִים, נָקוּם לְקַבֵּל סֵבֶר פְּנֵי הַיָּמִים, שֶׁעַכְשָׁו יֵצְאוּ אֵלֵינוּ פָּנִים גְּדוֹלוֹת וּפָנִים קְטַנּוֹת. שָׁמַע רַבִּי שִׁמְעוֹן נַהֲרַת הַחֲמוֹר, אָמַר לַחֲבֵרִים, נָקוּם שֶׁהֲרֵי קוֹל (שמחת) הַחֲמוֹר שֶׁל הַזָּקֵן הֶחָסִיד הִתְעוֹרֵר אֵלֵינוּ. קָם רַבִּי שִׁמְעוֹן וְקָמוּ הַחֲבֵרִים.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים צח) מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה וְגוֹ'. מִזְמוֹר, זָקוּף טַעַם לְמַעְלָה, (שיר יתום קראנו לזה) לָמָּה? אֶלָּא רָשׁוּם טַעַם גָּדוֹל, שֶׁהֲרֵי בָּא אוֹתוֹ מִזְמוֹר מִתְעַטֵּר בַּעֲטֶרֶת עֶלְיוֹנָה לְמַעְלָה עַל רֹאשׁוֹ וּבָא זָקוּף. מִי אָמַר שִׁירָה זוֹ? אוֹתָן פָּרוֹת בְּאוֹתָן גְּעִיּוֹת שֶׁהָיוּ גוֹעוֹת. שִׁירוּ לַה' שִׁיר חָדָשׁ, לְמִי הָיוּ אוֹמְרוֹת שִׁירוּ? לְכַמָּה מֶרְכָּבוֹת, לְכַמָּה מְמֻנִּים, לְכַמָּה דְרָגוֹת, שֶׁהָיוּ בָאִים שָׁם וְיָצְאוּ לְקַבֵּל אֶת הָאָרוֹן (סתם), וְלָהֶם הָיוּ אוֹמְרוֹת.</p>"],[9522012421,"<p>שִׁירוּ לַה' שִׁיר חָדָשׁ - זָכָר. מָה הַטַּעַם כָּאן שִׁיר, וּמֹשֶׁה אָמַר שִׁירָה, נְקֵבָה? אֶלָּא שָׁם בְּמֹשֶׁה אָרוֹן אֶחָד (לחוד). זֹּאת, יָצְאָה מֵהַגָּלוּת הִיא וְאוּכְלוּסֶיהָ, וְלֹא יוֹתֵר, וּמִשּׁוּם זֶה אֶת הַשִּׁירָה הַזֹּאת, נְקֵבָה. אֲבָל כָּאן אָרוֹן וּמַה שֶּׁהָיָה בְּתוֹכוֹ יָצָא, וּמִשּׁוּם אוֹתוֹ שֶׁהָיָה גָּנוּז בְּתוֹכוֹ נֶאֱמַר שִׁיר חָדָשׁ, זָכָר.</p>\n<p>כִּי נִפְלָאוֹת עָשָׂה - מַה שֶּׁעָשָׂה לִפְלִשְׁתִּים וּמַה שֶּׁעָשָׂה לָעֲבוֹדָה זָרָה שֶׁלָּהֶם. הוֹשִׁיעָה לּוֹ יְמִינוֹ, לְמִי? לְעַצְמוֹ. מִי זֶה עַצְמוֹ? אוֹתוֹ מִזְמוֹר עַצְמוֹ, וְרוּחַ עֶלְיוֹנָה קְדוֹשָׁה גְּנוּזָה בּוֹ. יְמִינוֹ - אוֹתוֹ שֶׁיָּרַשׁ הַזָּקֵן, וְזוֹ יְמִינוֹ, שֶׁהֶחֱזִיק בְּאוֹתוֹ מִזְמוֹר וְלֹא הִשְׁאִירוֹ בְּיַד אַחֵר.</p>\n<p>כָּאן יֵשׁ לְגַלּוֹת דָּבָר אֶחָד: כָּל פַּעַם שֶׁאוֹתוֹ יָמִין הָיָה לְהַרְחִישׁ נֵס, הָיָה מַחֲזִיק בְּמִזְמוֹר זֶה וְשָׂם אוֹתוֹ לְפָנָיו לְהַחֲזִיק בּוֹ, כְּאַבָּא שֶׁמְּחַזֵּק יְמִינוֹ בְּחָזֵה בְּנוֹ לְפָנָיו וְאוֹמֵר: מִי הוּא שֶׁיִּקְרַב לִבְנִי? כֵּיוָן שֶׁסָּרַח לְגַבֵּי אָבִיו, שָׂם אָבִיו יָדָיו עַל כְּתֵפָיו לְאָחוֹר, וּזְרָקוֹ בִידֵי שׂוֹנְאָיו.</p>\n<p>כִּבְיָכוֹל בַּהַתְחָלָה כָּתוּב, (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. בְּכֹחַ מִי? אוֹתוֹ הַנּוֹדָע. בְּעַרְבִית קוֹרְאִים לְחָזֵה כֹּחַ. אוֹתוֹ יָמִין נֶאְדָּרִי וְנִתְחַזֵּק בְּכֹחַ. מִי הוּא שֶׁיִּקְרַב לִבְנִי. אַחַר כָּךְ מַה כָּתוּב? (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב. שָׂם יְמִינוֹ עַל כְּתֵפוֹ וְדָחָה אוֹתוֹ לִידֵי שׂוֹנְאָיו. בַּהַתְחָלָה יְמִינוֹ לְפָנָיו בְּחֲזֵהוּ לְהִתְחַזֵּק בּוֹ, וְאַחַר כָּךְ לַאֲחוֹרָיו עַל כְּתֵפָיו לִדְחוֹת אוֹתוֹ. וְכָאן - הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ, שְׁתֵּי זְרוֹעוֹת לְהִתְחַזֵּק בּוֹ.</p>"],[9522012422,"<p>שֶׁאִם אוֹתָן פָּרוֹת שֶׁלֹּא הִתְרַגְּלוּ בְנִסִּים, אֶלָּא אוֹתָהּ שָׁעָה בַּגְּעִיָּה שֶׁלָּהֶן אָמְרוּ שִׁירָה זוֹ, נְעִירַת חֲמוֹר הַזָּקֵן הֶחָסִיד שֶׁרָגִיל בְּנִסִּים עַל אַחַת כַּמָּה וְכַמָּה שֶׁאָמַר שִׁירָה. חֲבֵרִים, אִם תֹּאמְרוּ שֶׁאֵין דַּרְכּוֹ שֶׁל הַחֲמוֹר בְּכָךְ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, צְאוּ וּרְאוּ אֲתוֹן בִּלְעָם הָרָשָׁע שֶׁנִּצְּחָה אֶת בְּעָלֶיהָ בַּכֹּל. חֲמוֹרוֹ שֶׁל רַבִּי פִּנְחָס בֶּן יָאִיר עַל אַחַת כַּמָּה וְכַמָּה. וְעוֹד, אֲתוֹן בִּלְעָם כְּשֶׁדִּבְּרָה, מַלְאָךְ עֶלְיוֹן הָיָה עָלֶיהָ מִלְמַעְלָה.</p>\n<p>כָּעֵת יֵשׁ לְגַלּוֹת. חֲבֵרִים שִׁמְעוּ. פִּי הָאָתוֹן שֶׁנִּבְרָא בְּעֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת, הֲעוֹלֶה בְדַעְתְּכֶם שֶׁהַפֶּה הָיָה פָּתוּחַ מֵאוֹתוֹ זְמַן, אוֹ שֶׁתְּנַאי הִתְנָה הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתוֹ זְמַן? לֹא כָּךְ. וְסוֹד כָּאן שֶׁנִּמְסַר לַחֲכָמִים שֶׁלֹּא מַשְׁגִּיחִים עַל טִפְּשׁוּת הַלֵּב. פִּי הָאָתוֹן - דַּרְגַּת הָאֲתוֹנוֹת, אוֹתוֹ עֶלְיוֹן שֶׁל צַד נְקֵבוֹת, אוֹתוֹ שֶׁהָיָה שָׁרוּי עַל אוֹתָהּ אָתוֹן וְדִבֵּר מֵעָלֶיהָ. וּכְשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְדַרְגָּה זוֹ שֶׁנִּקְרֵאת פִּי הָאָתוֹן, סָתַם אוֹתָהּ בְּתוֹךְ (האתון) נֶקֶב תְּהוֹם רַבָּה, וְסָתַם עָלֶיהָ עַד אוֹתוֹ זְמַן. כְּשֶׁהִגִּיעַ אוֹתוֹ זְמַן, פָּתַח אוֹתוֹ נֶקֶב, וְיָצָא וְשָׁרָה עָלֶיהָ וְדִבְּרָה.</p>\n<p>כְּמוֹ זֶה, (במדבר טז) וַתִּפְתַּח הָאָרֶץ אֶת פִּיהָ. אֶת - לְרַבּוֹת דּוּמָ\"ה, שֶׁהוּא פִּי הָאָרֶץ. אֶת פִּי הָאָתוֹן - לְרַבּוֹת קַמְרִיאֵ\"ל, שֶׁנִּקְרָא פִּי הָאָתוֹן. פִּי הַבְּאֵר כְּמוֹ זֶה. מַה זֶּה פִּי הַבְּאֵר? אוֹתָהּ דַּרְגָּה שֶׁהָיְתָה מְמֻנָּה עָלֶיהָ לְמַטָּה, וְהִיא תַּחַת פִּי ה', וּמִיהוּ? יְהַדְרִיאֵ\"ל שְׁמוֹ. שְׁלֹשֶׁת הַפִּיּוֹת הַלָּלוּ נִבְרְאוּ עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת. בְּשָׁעָה שֶׁקָּדַשׁ הַיּוֹם, עוֹלֶה פִּי הַמְמֻנֶּה עַל כָּל יֶתֶר הַפִּיּוֹת, וּמִיהוּ? אוֹתוֹ יוֹם שֶׁהִתְעַלָּה וְהִתְקַדֵּשׁ בַּכֹּל, אוֹתוֹ שֶׁנִּקְרָא (ישעיה נח) פִּי ה'. עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת נִבְרְאוּ שְׁאָר הַפִּיּוֹת. הִתְקַדֵּשׁ הַיּוֹם, עָלָה הַפֶּה שֶׁשּׁוֹלֵט עַל הַכֹּל, פִּי ה'.</p>\n<p>בֵּין כָּךְ רָאוּ אֶת רַבִּי פִּנְחָס שֶׁהָיָה בָּא. הִגִּיעוּ אֵלָיו, בָּא רַבִּי פִּנְחָס וְנָשַׁק אֶת רַבִּי שִׁמְעוֹן. אָמַר, נָשַׁקְתִּי אֶת פִּי ה', הִתְבַּשֵּׂם בַּבְּשָׂמִים שֶׁל גִּנָּתוֹ. שָׂמְחוּ כְאֶחָד וְיָשְׁבוּ. כֵּיוָן שֶׁיָּשְׁבוּ, פָּרְחוּ כָּל אוֹתָם עוֹפוֹת שֶׁהָיוּ עוֹשִׂים צֵל וְהִתְפַּזְּרוּ. הֶחֱזִיר רֹאשׁוֹ רַבִּי שִׁמְעוֹן וְהֵרִים לָהֶם קוֹל וְאָמַר, עוֹפוֹת הַשָּׁמַיִם! אֵינְכֶם מַשְׁגִּיחִים בִּכְבוֹד רִבּוֹנְכֶם שֶׁעוֹמֵד כָּאן?! עָמְדוּ, וְלֹא לָקְחוּ מִמְּקוֹמָם, וְלֹא קָרְבוּ אֵלָיו. אָמַר רַבִּי פִּנְחָס, אֹמַר לָהֶם שֶׁיֵּלְכוּ לְדַרְכָּם, שֶׁהֲרֵי לֹא נָתְנוּ לָהֶם רְשׁוּת לַחֲזֹּר?</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, יָדַעְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהַרְחִישׁ לָנוּ נֵס. עוֹפוֹת עוֹפוֹת! לְכוּ לְדַרְכְּכֶם, וְאִמְרוּ לְאוֹתוֹ הַמְמֻנֶּה עֲלֵיכֶם שֶׁהֲרֵי בַּהַתְחָלָה הָיָה בִּרְשׁוּתוֹ, וְכָעֵת זֶה לֹא קַיָּם בִּרְשׁוּתוֹ. אֲבָל הֶעֱלֵינוּ אוֹתוֹ לְיוֹם הַסֶּלַע, כְּשֶׁעוֹלֶה עָנָן בֵּין שְׁנֵי חֲזָקִים, וְלֹא מִתְחַבְּרִים. הִתְפַּזְּרוּ אוֹתָם עוֹפוֹת וְהָלְכוּ.</p>"],[9522012423,"<p>בֵּין כָּךְ הֲרֵי שְׁלֹשָׁה אִילָנוֹת מִתְפַּשְּׁטִים בַּעֲנָפִים לִשְׁלֹשָׁה צְדָדִים עֲלֵיהֶם, וּמַעְיַן מַיִם נוֹבְעִים לִפְנֵיהֶם. שָׂמְחוּ כָּל הַחֲבֵרִים, וְשָׂמְחוּ רַבִּי פִּנְחָס וְרַבִּי שִׁמְעוֹן. אָמַר רַבִּי פִּנְחָס, טֹרַח גָּדוֹל הָיָה לְאוֹתָם עוֹפוֹת בַּתְּחִלָּה, וְטֹרַח בַּעֲלֵי חַיִּים לֹא צְרִיכִים, שֶׁהֲרֵי כָּתוּב (תהלים קמה) וְרַחֲמָיו עַל כָּל מַעֲשָׂיו. אָמַר רַבִּי שִׁמְעוֹן, אֲנִי לֹא הִטְרַחְתִּי אוֹתָם. אֲבָל אִם הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלֵינוּ, אֵינֶנּוּ יְכוֹלִים לִדְחוֹת אֶת הַמַּתָּנוֹת שֶׁלּוֹ. יָשְׁבוּ תַחַת אוֹתוֹ הָאִילָן, וְשָׁתוּ מֵהַמַּיִם וְנֶהֱנוּ שָׁם.</p>\n<p>פָּתַח רַבִּי פִּנְחָס וְאָמַר, (שיר השירים ד) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנֹזְלִים מִן לְבָנוֹן. מַעְיַן גַּנִּים, וְכִי אֵין מַעְיָן אֶלָּא אוֹתוֹ מִן גַּנִּים? וַהֲרֵי כַּמָּה מַעְיָנוֹת טוֹבִים וְנִכְבָּדִים יֵשׁ בָּעוֹלָם! אֶלָּא אֵין כָּל הַהֲנָאוֹת שָׁווֹת. יֵשׁ מַעְיָן שֶׁיּוֹצֵא בַמִּדְבָּר בְּמָקוֹם יָבֵשׁ - הֲנָאָה יֵשׁ לְמִי שֶׁיּוֹשֵׁב וְשׁוֹתֶה. אֲבָל מַעְיַן גַּנִּים, כַּמָּה טוֹב הוּא וְנִכְבָּד. אוֹתוֹ מַעְיָן עוֹשֶׂה טוֹב לָעֲשָׂבִים וְלַפֵּרוֹת, מִי שֶׁמִּתְקָרֵב אֵלָיו נֶהֱנֶה בַכֹּל., נֶהֱנֶה בַמַּיִם, נֶהֱנֶה בָעֲשָׂבִים, נֶהֱנֶה בַפֵּרוֹת. אוֹתוֹ מַעְיָן מִתְעַטֵּר בַּכֹּל. כַּמָּה שׁוֹשַׁנִּים, כַּמָּה עִשְׂבֵי רֵיחַ סְבִיבוֹ, כַּמָּה נָאֶה אוֹתוֹ מַעְיָן מִשְּׁאָר הַמַּעְיָנוֹת, בְּאֵר מַיִם חַיִּים.</p>\n<p>וְכָךָ בֵּאַרְנוּ, הַכֹּל בִּכְנֶסֶת יִשְׂרָאֵל אוֹמֵר, הִיא מַעְיַן גַּנִּים. מִי הַגַּנִּים? חֲמִשָּׁה גַנִּים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ- הוּא שֶׁמִּשְׁתַּעֲשֵׁעַ בָּהֶם, וּמַעְיָן אֶחָד מֵעֲלֵיהֶם שֶׁמַּשְׁקֶה אוֹתָם וּמַרְוֶה אוֹתָם, טָמִיר וְגָנוּז, וְכֻלָּם עוֹשִׂים פֵּרוֹת וּתְבוּאָה. גִּנָּה אַחַת יֵשׁ תַּחַת מֵהֶם, וְאוֹתָהּ הַגִּנָּה שְׁמוּרָה סָבִיב מִכָּל צִדְדֵי הָעוֹלָם. תַּחַת גִּנָּה זוֹ יֵשׁ גַּנִּים אֲחֵרִים עוֹשִׂים פֵּרוֹת לְמִינֵיהֶם.</p>\n<p>וְגִנָּה זוֹ הִתְהַפְּכָה וְהָיְתָה לְמַעְיָן שֶׁמַּשְׁקֶה אוֹתָם, בְּאֵר מַיִם חַיִּים. כְּשֶׁצָּרִיךְ זֶה מַעְיָן, וּכְשֶׁצָּרִיךְ זֶה בְּאֵר. מַה בֵּין זֶה לָזֶה? לֹא דוֹמֶה. כְּשֶׁנִּמְשָׁכִים הַמַּיִם מֵאֲלֵיהֶם לִכְשֶׁשּׁוֹאֲבִים מַיִם לְהַשְׁקוֹת. וְנֹזְלִים מִן לְבָנוֹן, אֵיזֶה נֹזְלִים? נוֹזְלִים אֵלּוּ חוֹזְרִים לְמַעְיָן, (של כלם) כְּשֶׁנּוֹבְעִים מַיִם וְנוֹזְלוֹת טִפּוֹת לְמַעְלָה (מלמעלה) אֵלּוּ אַחַר אֵלּוּ, מַיִם מְתוּקִים שֶׁהַנֶּפֶשׁ הוֹלֶכֶת אַחֲרֵיהֶם. כָּךְ הֵם חֲמִשָּׁה מְקוֹרוֹת שֶׁיָּצְאוּ מִן לְבָנוֹן, נַעֲשׂוּ נוֹזְלִים בְּמַעְיָן זֶה. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הִרְחִישׁ לָנוּ נֵס בְּמָקוֹם זֶה, קָרָאנוּ עַל מַעְיָן זֶה פָּסוּק זֶה. (מה הנוזלים, ' אלו חמשה מקורות שיצאו מלבנון למעלה, נעשו נוזלים כאשר חזרו למעין, נובעים מים ונוזלות טפות אלו אחר אלו מים מתוקים, שהנפש הולכת אחריהם. כך הקדוש ברוך הוא הרחיש להם נס במקום זה במעין זה, ועל מעין זה קראנו פסוק זה).</p>"],[9522012424,"<p>עוֹד פָּתַח וְאָמַר, (דברים כ) כִּי תָצוּר אֶל עִיר יָמִים רַבִּים לְהִלָּחֵם עָלֶיהָ לְתָפְשָׂהּ וְגוֹ'. כַּמָּה טוֹבִים הֵם דַּרְכֵי וּשְׁבִילֵי הַתּוֹרָה, שֶׁהֲרֵי בְּכָל דָּבָר וְדָבָר יֵשׁ כַּמָּה עֵצוֹת, כַּמָּה טוֹבוֹת לִבְנֵי אָדָם, כַּמָּה מַרְגָּלִיּוֹת שֶׁמְּאִירוֹת לְכָל צַד, וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ כַּמָּה נֵרוֹת מְאִירִים לְכָל צַד. פָּסוּק זֶה הוּא כִּפְשׁוּטוֹ, וְיֵשׁ בּוֹ כְּפִי מִדְרָשׁוֹ, וְיֵשׁ בּוֹ חָכְמָה עֶלְיוֹנָה לְהַזְהִיר לְמִי שֶׁצָּרִיךְ. אַשְׁרֵי חֶלְקוֹ מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה תָּמִיד.</p>\n<p>מִי שֶׁמִּשְׁתַּדֵּל בָּהּ, מַה כָּתוּב בּוֹ? (תהלים א) כִּי אִם בְּתוֹרַת ה' חֶפְצוֹ וּבְתוֹרָתוֹ יֶהְגֶּה יוֹמָם וָלָיְלָה, וְהָיָה כְּעֵץ. לָמָּה זֶה סָמוּךְ לָזֶה? אֶלָּא מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, לֹא יִהְיֶה כְעֵץ יָבֵשׁ, אֶלָּא כְּעֵץ שָׁתוּל עַל פַּלְגֵי מָיִם. מָה אִילָן יֵשׁ בּוֹ שָׁרָשִׁים, וְיֵשׁ בּוֹ קְלִפּוֹת, וְיֵשׁ בּוֹ מֹחַ, וְיֵשׁ בּוֹ עֲנָפִים, וְיֵשׁ בּוֹ עָלִים, וְיֵשׁ בּוֹ פְּרָחִים, וְיֵשׁ בּוֹ פְּרִי - שִׁבְעָה סוּגִים אֵלּוּ עוֹלִים לְשִׁבְעָה עָשָׂר, לְשִׁבְעִים, גַּם דִּבְרֵי תוֹרָה יֵשׁ בָּהֶם פְּשַׁט הַמִּקְרָא, דְּרָשׁ, רֶמֶז שֶׁרוֹמֵז חָכְמָה, גִּימַטְרִיָּאוֹת, סוֹדוֹת טְמִירִים, סוֹדוֹת נִסְתָּרִים אֵלּוּ עַל אֵלּוּ, פָּסוּל וְכָשֵׁר, טָמֵא וְטָהוֹר, אִסּוּר וְהֶתֵּר. מִכָּאן וָהָלְאָה מִתְפַּשְּׁטִים הָעֲנָפִים לְכָל צַד, וְהָיָה כְּעֵץ וַדַּאי. וְאִם לֹא - אֵינוֹ חָכָם בְּחָכְמָה.</p>\n<p>בֹּא וּרְאֵה כַּמָּה חֲבִיבִים אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֲפִלּוּ בִּזְמַן שֶׁהַדִּין תָּלוּי בָּעוֹלָם וְנִתְּנָה רְשׁוּת לַמַּשְׁחִית לְהַשְׁחִית, הַקָּדוֹשׁ בָּרוּךְ הוּא מְצַוֵּהוּ עֲלֵיהֶם, עַל אוֹתָם הַמִּשְׁתַּדְּלִים בַּתּוֹרָה, וְכָךְ אוֹמֵר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: כִּי תָצוּר אֶל עִיר, בִּגְלַל הַחֲטָאִים הָרַבִּים שֶׁחָטְאוּ לְפָנַי וְהִתְחַיְּבוּ בְדִין. יָמִים רַבִּים, מַה זֶּה רַבִּים? (שלשה ימים זה אחר זה נקראו ימים רבים. אף כאן כי תצור אל עיר ימים רבים) שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה שֶׁנּוֹדָע דֶּבֶר בָּעִיר. מִנַּיִן לָנוּ שֶׁיָּמִים רַבִּים הֵם שְׁלֹשָׁה? שֶׁכָּתוּב (ויקרא טו) וְאִשָּׁה כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים. וְכִי יָמִים רַבִּים הֵם? אֶלָּא שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה נִקְרָאִים יָמִים רַבִּים. גַּם כָּךְ, כִּי תָצוּר אֶל עִיר יָמִים רַבִּים - שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה שֶׁנּוֹדָע דֶּבֶר בָּעִיר. בֹּא וַאֲצַוְּךְ עַל (כל) בְּנֵי בֵיתִי: לֹא תַשְׁחִית אֶת עֵצָהּ - זֶה תַּלְמִיד חָכָם שֶׁהוּא בָּעִיר, שֶׁהוּא עֵץ הַחַיִּים, אִילָן שֶׁנּוֹתֵן פֵּרוֹת.</p>\n<p>דָּבָר אַחֵר אֶת עֵצָהּ - אוֹתוֹ שֶׁנּוֹתֵן עֵצָה לָעִיר לְהִנָּצֵל מִן הַדִּין וּמְלַמֵּד אוֹתָם דֶּרֶךְ שֶׁיֵּלְכוּ בָהּ, וְעַל זֶה לֹא תַשְׁחִית אֶת עֵצָהּ לִנְדּחַ עָלָיו גַּרְזֶן. לִנְדּחַ עָלָיו דִּין, וְלֹא לְהוֹשִׁיט עָלָיו חֶרֶב לוֹהֶטֶת, חֶרֶב שְׁנוּנָה, אוֹתָהּ שֶׁהוֹרֶגֶת שְׁאָר אַנְשֵׁי הָעוֹלָם. כִּי מִמֶּנּוּ תֹאכֵל. וְכִי אוֹתוֹ מְחַבֵּל אוֹכֵל מִמֶּנּוּ? לֹא. אֶלָּא כִּי מִמֶּנּוּ תֹאכֵל, אוֹתוֹ סֶלַע קָשָׁה, אוֹתָהּ שֶׁכָּל רוּחוֹת חֲזָקוֹת וּקְדוֹשׁוֹת יוֹצְאוֹת מִמֶּנָּה, שֶׁאֵין הֲנָאָה וְתַאֲוָה לְרוּחַ הַקֹּדֶשׁ בָּעוֹלָם הַזֶּה אֶלָּא תּוֹרָתוֹ שֶׁל אוֹתוֹ צַדִּיק. כִּבְיָכוֹל הוּא מְפַרְנֵס אוֹתָהּ וְנוֹתֵן לָהּ מָזוֹן בָּעוֹלָם הַזֶּה יוֹתֵר מִכָּל קָרְבְּנוֹת הָעוֹלָם.</p>\n<p>בְּקָרְבָּן מַה כָּתוּב? (שיר השירים ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי אִכְלוּ רֵעִים. וּמִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ וּבָטְלוּ הַקָּרְבָּנוֹת, אֵין לוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא אֶלָּא אוֹתָם דִּבְרֵי תוֹרָה, וְהַתּוֹרָה שֶׁמִּתְחַדֶּשֶׁת בְּפִיו. בִּשְׁבִיל כָּךְ כִּי מִמֶּנּוּ תֹאכֵל, וְאֵין לָהּ מָזוֹן בָּעוֹלָם הַזֶּה אֶלָּא מִמֶּנּוּ וּמֵאוֹתָם שֶׁכְּמוֹתוֹ. וְכֵיוָן שֶׁמִּמֶּנּוּ תֹאכֵל וְהוּא זָן אוֹתָהּ - אֹתוֹ לֹא תִכְרֹת. תִּהְיֶה (טמיר) זָהִיר בּוֹ שֶׁלֹּא תִתְקָרֵב אֵלָיו.</p>\n<p>כִּי הָאָדָם עֵץ הַשָּׂדֶה - זֶה נִקְרָא אָדָם שֶׁנּוֹדָע מַעְלָה וּמַטָּה. עֵץ הַשָּׂדֶה - עֵץ גָּדוֹל וְתַקִּיף שֶׁאוֹתוֹ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', (זה) סָמוּךְ עָלָיו, אִילָן שֶׁנּוֹדַע לְאוֹתוֹ שָׂדֶה תָּמִיד. לָבא מִפָּנֶיךְ בַּמָּצוֹר - דָּבָר זֶה חוֹזֵר לְרֹאשׁ הַפָּסוּק שֶׁכָּתוּב לֹא תַשְׁחִית אֶת עֵצָהּ, אוֹתוֹ שֶׁנּוֹתֵן לָהֶם עֵצָה וּמַתְקִין אֶת הָעִיר. לָבֹא מִפָּנֶיךְ בַּמָּצוֹר, הוּא נוֹתֵן לָהֶם עֵצָה לְהִתְתַּקֵּן וְלַחֲזֹר בִּתְשׁוּבָה, וּמַתְקִין לוֹ כְּלֵי זַיִן, חֲצוֹצְרוֹת וְשׁוֹפָרוֹת. לָבֹא מִפָּנֶיךְ, מַה זֶּה לָבֹא מִפָּנֶיךְ? לָבֹא לְפָנַי וְלַעֲלוֹת מִפָּנֶיךְ, מִפְּנֵי הַפַּחַד שֶׁלְּךְ. בַּמָּצוֹר, בְּמָקוֹם שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים לֹא יְכוֹלִים לַעֲלוֹת לְשָׁם. וּמִיהוּ? דַּרְגָּה שֶׁבַּעֲלֵי תְשׁוּבָה נִכְנָסִים לְשָׁם. וּמִי הִיא? תְּשׁוּבָה. זֶהוּ מָצוֹר, מָקוֹם חָזָק וְסֶלַע חָזָק.</p>\n<p>וְכֵיוָן שֶׁעֵצָה זוֹ לוֹקְחִים, אֲנִי מְכַפֵּר לַחֲטָאֵיכֶם וּמִתְקַבְּלִים בְּרָצוֹן לְפָנַי. וְכָל זֶה פּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אוֹתָם הַמִּשְׁתַּדְּלִים בַּתּוֹרָה. מִשּׁוּם כָּךְ צַדִּיקִים הֵם כְּשֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה הֵם עֵצִים גְּדוֹלִים בָּעוֹלָם הַזֶּה.</p>\n<p>רְאוּ מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנָּטַע אִילָנוֹת אֵלּוּ, אַשְׁרֵי הַדֶּרֶךְ הַזֶּה. וְלֹא דַי אִילָן אֶחָד, אֶלָּא שְׁלֹשָׁה אִילָנוֹת גְּדוֹלִים פָּרְשׂוּ עֲנָפִים לְכָל צַד עָשָׂה לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא. יְהִי רָצוֹן לִפְנֵי הַשָּׁמַיִם שֶׁלֹּא יָעָבְרוּ לְעוֹלָם אִילָנוֹת אֵלּוּ וּמַעְיָן זֶה מִמָּקוֹם זֶה, וְעַד הַיּוֹם עוֹמְדִים שָׁם, וְאוֹתוֹ מַעְיַן מַיִם. וְהָאֲנָשִׁים קוֹרְאִים לָהֶם נְצִיבוּת שֶׁל רַבִּי פִּנְחָס בֶּן יָאִיר.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית לג) וַיִּשָּׂא אֶת עֵינָיו וַיַּרְא אֶת הַנָּשִׁים וְאֶת הַיְלָדִים וַיֹּאמֶר מִי אֵלֶּה לָּךְ וַיֹּאמַר הַיְלָדִים אֲשֶׁר חָנַן אֱלֹהִים אֶת עַבְדֶּךְ. בֹּא וּרְאֵה, אוֹתוֹ עֵשָׂו הָרָשָׁע נָתַן עֵינוֹ לְעַיֵּן בַּנָּשִׁים, וּבִגְלָלוֹ הִתְקִין יַעֲקֹב תִּקּוּנָיו. שָׂם שְׁפָחוֹת מִקָּדִימָה, וּבְנֵיהֶם לְאָחוֹר, שֶׁחֲשׁוּבִים יוֹתֵר. לֵאָה אַחֲרֵיהֶם, וּבָנֶיהָ מֵאָחוֹר. אַחַר כָּךְ יוֹסֵף, וְאַחֲרֶיהָ רָחֵל, וְהוּא עָבַר לִפְנֵיהֶם.</p>\n<p>כְּשֶׁכֻּלָּם הִשְׁתַּחֲווּ, מַה כָּתוּב? וַתִּגַּשְׁןָ הַשְּׁפָחוֹת הֵנָּה וְיַלְדֵיהֶן וַתִּשְׁתַּחֲוֶיןָָ. וְאַחַר כָּךְ כָּתוּב, וַתִּגַּשׁ גַּם לֵאָה וִילָדֶיהָ וַיִּשְׁתַּחֲווּ וְאַחַר נִגַּשׁ יוֹסֵף וְרָחֵל וְגוֹ'. וַהֲרֵי יוֹסֵף לְאָחוֹר הָיָה, וְרָחֵל לְפָנָיו! אֶלָּא בֵּן טוֹב, בֵּן אָהוּב, צַדִּיק הָעוֹלָם, יוֹסֵף. כֵּיוָן שֶׁרָאָה עֵינוֹ שֶׁל אוֹתוֹ רָשָׁע מִסְתַּכֵּל בַּנָּשִׁים, פָּחַד עַל אִמּוֹ. יָצָא מֵאַחֲרֶיהָ וּפָרַשׂ זְרוֹעוֹתָיו וְגוּפוֹ וְכִסָּה עָלֶיהָ כְּדֵי שֶׁלֹּא יִתֵּן אוֹתוֹ רָשָׁע עֵינוֹ בְאִמּוֹ. כַּמָּה הִתְגַּדֵּל? שֵׁשׁ אַמּוֹת לְכָל צַד, וְכִסָּה עָלֶיהָ, וְלֹא יָכְלָה עֵינוֹ שֶׁל אוֹתוֹ רָשָׁע לִשְׁלֹט עָלֶיהָ.</p>\n<p>כְּמוֹ זֶה, וַיִּשָּׂא בִלְעָם אֶת עֵינָיו. עֵינוֹ כָּתוּב, אוֹתָהּ עַיִן רָעָה (שתי עינים היה זוקף. אלא בשעה) שֶׁרָצָה לְהִסְתַּכֵּל עֲלֵיהֶם. וַיַּרְא אֶת יִשְׂרָאֵל שֹׁכֵן לִשְׁבָטָיו. מַה זֶּה שֹׁכֵן לִשְׁבָטָיו? אֶלָּא שֵׁבֶט יוֹסֵף הָיָה שָׁם וְשֵׁבֶט בִּנְיָמִין. שֵׁבֶט יוֹסֵף שֶׁלֹּא שׁוֹלֶטֶת בָּהֶם עַיִן הָרָע, שֶׁכָּתוּב (שם מט) בֵּן פֹּרָת יוֹסֵף. מַה זֶּה בֵּן פֹּרָת יוֹסֵף? שֶׁהִתְגַּדֵּל לְכַסּוֹת עַל אִמּוֹ. בֵּן פֹּרָת עֲלֵי עָיִן, שֶׁלֹּא שָׁלְטָה בּוֹ עַיִן הָרָע. שֵׁבֶט בִּנְיָמִין, שֶׁכָּתוּב בּוֹ (דברים לג) וּבֵין כְּתֵפָיו שָׁכֵן. וְכָתוּב יִשְׁכֹּן לָבֶטַח. מַה זֶּה לָבֶטַח? שֶׁלֹּא פוֹחֵד מֵעַיִן הָרָע וְלֹא פוֹחֵד מִפְּגָעִים רָעִים.</p>\n<p>אָמַר אוֹתוֹ רָשָׁע, אֲנִי אַעֲבִיר חוֹמָה זוֹ שֶׁלֹּא תַעֲמֹד, וַאֲנִי אֶסְתַּכֵּל כְּמוֹ שֶׁצָּרִיךְ. רָחֵל הָיְתָה שָׁם, רָאֲתָה שֶׁעַיִן אוֹתוֹ רָשָׁע שְׁנוּנָה לְהַזִּיק. מֶה עָשְׂתָה? יָצְאָה וּפָרְשָׂה כְנָפֶיהָ עֲלֵיהֶם וְכִסְּתָה עַל בָּנֶיהָ. זֶהוּ שֶׁכָּתוּב וַיִּשָּׂא בִלְעָם אֶת עֵינָיו וַיַּרְא אֶת יִשְׂרָאֵל. כֵּיוָן שֶׁרָאֲתָה רוּחַ הַקֹּדֶשׁ, עַיִן שְׁנוּנָה, מִיָּד - וַתְּהִי עָלָיו רוּחַ אֱלֹהִים. עַל מִי? עַל יִשְׂרָאֵל. שֶׁפָּרְשָׂה כְנָפֶיהָ וְכִסְּתָה עֲלֵיהֶם, וּמִיָּד שָׁב אוֹתוֹ רָשָׁע לְאָחוֹר.</p>\n<p>בַּהַתְחָלָה הַבֵּן כִּסָּה עַל אִמּוֹ. וְכָעֵת הָאֵם מְכַסָּה עַל בְּנָהּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּאוֹתָהּ שָׁעָה שֶׁהוּא כִּסָּה עַל רָחֵל אִמּוֹ שֶׁלֹּא תִשְׁלֹט הָעַיִן שֶׁל אוֹתוֹ רָשָׁע עָלֶיהָ, חַיֶּיךְ בְּשָׁעָה שֶׁתָּבֹא עַיִן רָעָה אַחֶרֶת לְהִסְתַּכֵּל עַל בָּנֶיךְ וְעַל בָּנַי - אִמְּךְ תְּכַסֶּה עֲלֵיהֶם. אַתָּה כִּסִּיתָ עַל אִמְּךְ - אִמְּךְ תְּכַסֶּה עָלֶיךְ.</p>"],[9522012425,"<p>וַיִּשָּׂא אֶת עֵינָיו וַיַּרְא אֶת הַנָּשִׁים. פָּסוּק זֶה נֶאֱמַר בְּסוֹד הַחָכְמָה, בְּיוֹם הַכִּפּוּרִים, שֶׁבְּנֵי הָעוֹלָם עוֹמְדִים בְּדִין, וְיִשְׂרָאֵל שָׁבִים בִּתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַפֵּר עַל עֲווֹנוֹתֵיהֶם. וְאוֹתוֹ מְקַטְרֵג עוֹמֵד עֲלֵיהֶם, שֶׁחוֹשֵׁב לְאַבֵּד אוֹתָם עַל חֲטָאֵיהֶם, שׁוֹלְחִים לוֹ אוֹתוֹ דּוֹרוֹן, וְאָז כָּתוּב (בראשית לב) כִּי אָמַר אֲכַפְּרָה פָנָיו בַּמִּנְחָה הַהֹלֶכֶת לְפָנָי. אַחַר שֶׁמְּקַבֵּל אוֹתוֹ מְקַטְרֵג הַדּוֹרוֹן, מִתְהַפֵּךְ לָהֶם לְסָנֵגוֹר.</p>\n<p>מִזְדַּקֵּף וְרוֹאֶה אֶת יִשְׂרָאֵל כֻּלָּם מִתְעַנִּים, יְחֵפֵי רַגְלַיִם. רוֹאֶה נָשִׁים, רוֹאֶה תִינוֹקוֹת, כֻּלָּם בְּתַעֲנִית, כֻּלָּם נְקִיִּים בְּנִקָּיוֹן. וַיֹּאמֶר מִי אֵלֶּה לָּךְ. שֵׁם קָדוֹשׁ לָךְ. מִי אֵלֶּה לָּךְ. שׁוֹאֵל עַל הַתִּינוֹקוֹת, וְאוֹמֵר, הַיְלָדִים אֲשֶׁר חָנַן אֱלֹהִים אֶת עַבְדֶּךְ. וְכִי לָמָּה צָרִיךְ לַהֲשִׁיבוֹ כְלוּם? אֶלָּא כֵּיוָן שֶׁמְּקַבֵּל אוֹתוֹ שֹׁחַד, מִתְהַפֵּךְ לָהֶם לְסָנֵגוֹר. מֵרִים עֵינָיו וְרוֹאֶה אֶת יִשְׂרָאֵל כְּמוֹ זֶה, חוֹשֵׁב שֶׁבִּגְלַל פַּחְדּוֹ הֵם עוֹמְדִים כָּךְ.</p>\n<p>שׁוֹאֵל עַל הַתִּינוֹקוֹת, וְאוֹמֵר מִי אֵלֶּה לָּךְ. (ואמר בדרך נסתר הילדים) מַה זֶּה מִי אֵלֶּה לָּךְ? אֶלָּא אָמַר, מֵילָא אַתֶּם שֶׁחֲטָאתֶם לִפְנֵי הַמֶּלֶךְ, אֲבָל תִּינוֹקוֹת אֵלּוּ מַדּוּעַ עוֹמְדִים כָּךְ? מִי אֵלֶּה לָּךְ? וַיֹּאמַר הַיְלָדִים. רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת, וְעַל זֶה טַעַם זָקוּף. וַיֹּאמַר הַיְלָדִים, בְּדֶרֶךְ נִסְתָּר, אֲשֶׁר חָנַן אֱלֹהִים אֶת עַבְדֶּךְ. וְכִי רוּחַ הַקֹּדֶשׁ אָמְרָה אֶת עַבְדֶּךְ? אֶלָּא רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת: אֵלֶּה אוֹתָם תִּינוֹקוֹת שֶׁלֹּא חָטְאוּ וְלֹא טָעֲמוּ טַעַם חֵטְא, וּמְסָרָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיַד הַמְמֻנֶּה שֶׁלְּךְ וְהָרַג אוֹתָם בְּלִי חֵטְא, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ד) וּמִיַּד עֹשְׁקֵיהֶם כֹּחַ. וְזֶהוּ אֶת עַבְדֶּךְ.</p>\n<p>כֵּיוָן שֶׁשָּׁמַע מֵאוֹתָם תִּינוֹקוֹת, מִיָּד עוֹלֶה לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְאוֹמֵר: רִבּוֹן הָעוֹלָם, כָּל דְּרָכֶיךְ בְּדִין אֱמֶת, וְאִם הַדִּין שׁוֹרֶה עַל יִשְׂרָאֵל בִּגְלַל חֲטָאֵיהֶם הֵם, תִּינוֹקוֹת שֶׁלָּהֶם שֶׁלֹּא חָטְאוּ לְפָנֶיךְ, לָמָּה מָסַרְתָּ אוֹתָם לְהָרְגָם בְּלִי חֵטְא? וְהַקָּדוֹשׁ בָּרוּךְ הוּא לוֹקֵחַ דְּבָרָיו בְּכָךְ וְחָס עֲלֵיהֶם. וְאוֹתָהּ שָׁעָה אֵין אַסְכָּרָה בַּתִּינוֹקוֹת.</p>\n<p>וְאוֹתוֹ מְקַטְרֵג לוֹקֵחַ קִנְאָה מֵאוֹתוֹ מְמֻנֶּה שֶׁתַּחַת יָדָיו, וְאוֹמֵר: וְכִי לִי נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם שֶׁמִּתְלַבְּשִׁים בַּחֲטָאִים וַעֲווֹנוֹת, וּלְאוֹתוֹ מְמֻנֶּה שֶׁלִּי מָסַר תִּינוֹקוֹת בְּלִי חֵטְא שֶׁלֹּא טָעֲמוּ טַעַם חֵטְא?! מִיָּד הוֹלֵךְ לְהוֹצִיאָם מִתַּחַת יָדוֹ וְלֹא יִשְׁלֹט בָּהֶם. וְעַל זֶה מַקְדִּים לוֹ וְאוֹמֵר לוֹ, הַיְלָדִים אֲשֶׁר חָנַן אֱלֹהִים אֶת עַבְדֶּךְ. לְאוֹתוֹ עַבְדֶּךְ, בְּלִי חֵטְא וּבְלִי חַטָּאָה. וּכְדֵי שֶׁלֹּא יִהְיֶה שֶׁבַח לַמְמֻנֶּה שֶׁלּוֹ יוֹתֵר מִמֶּנּוּ, רוֹצֶה לְהוֹצִיאָם מִיָּדוֹ.</p>\n<p>כְּשֶׁעוֹלוֹת תְּפִלּוֹת יִשְׂרָאֵל בְּיוֹם זֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מַה כָּתוּב? וְהוּא עָבַר לִפְנֵיהֶם. הֲרֵי רוּחַ הַקֹּדֶשׁ עוֹבֶרֶת לִפְנֵיהֶם, (כמו שנאמר (מיכה ב) ויעבר מלכם לפניהם) וְהוּא וַדַּאי עָבַר לִפְנֵיהֶם. וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים, רוּחַ הַקֹּדֶשׁ הִקְטִינָה עַצְמָהּ לְגַבֵּי מַעְלָה שֶׁבַע פְּעָמִים לְגַבֵּי שֶׁבַע דְּרָגוֹת עֶלְיוֹנוֹת שֶׁמֵּעָלָיו, וְהִקְטִינָה עַצְמָהּ לִכְלֹל אוֹתָם עִמּוֹ כָּל אֶחָד וְאֶחָד. עַד גִּשְׁתּוֹ עַד אָחִיו, לְאוֹתָהּ דַּרְגַּת הָרַחֲמִים, שֶׁהֲרֵי הֵם בֵּן וּבַת. בֵּן - (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל. בַּת - כְּנֶסֶת יִשְׂרָאֵל. רוּחַ הַקֹּדֶשׁ עָשְׂתָה הַקְטָנַת עַצְמָהּ, עַד גִּשְׁתּוֹ.</p>\n<p>כֵּיוָן שֶׁהִגִּיעַ אֵלָיו, תָּבַע מִמֶּנּוּ וְהוֹדִיעַ לוֹ צַעַר בְּנֵיהֶם לְמַטָּה, וּשְׁנֵיהֶם נִכְנָסִים לְהֵיכָל טָמִיר גָּנוּז שֶׁל יוֹם הַכִּפּוּרִים, אֵם שֶׁלָּהֶם, וְתוֹבְעִים עַל יִשְׂרָאֵל לְכַפֵּר לָהֶם, וְאָז כָּתוּב (ויקרא טז) כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם וְגוֹ'. אֲכַפֵּר עֲלֵיכֶם לֹא כָתוּב, אֶלָּא יְכַפֵּר עֲלֵיכֶם.</p>\n<p>וְכָעֵת הַיְלָדִים, חֲכָמִים אֵלּוּ שֶׁל כָּאן, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם סוֹדוֹת הַתּוֹרָה לְהִתְעַטֵּר בָּהֶם וּלְהִתְתַּקֵּן (ולהשתדל) בָּהֶם, עַיִן רָעָה לֹא שׁוֹלֶטֶת עֲלֵיהֶם בִּגְלַל עַיִן טוֹבָה, רוּחַ הַקֹּדֶשׁ שֶׁל רַבִּי פִּנְחָס שֶׁשּׁוֹרָה עֲלֵיהֶם. בָּא רַבִּי פִּנְחָס וּנְשָׁקוֹ. אָמַר, אִלְמָלֵא לֹא בָאתִי בְּדֶרֶךְ זוֹ אֶלָּא לִשְׁמֹע דְּבָרִים אֵלּוּ - דַּי לִי. אַשְׁרֵי דֶּרֶךְ זוֹ שֶׁבָּאתִי אֵלֶיךְ.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא כָּאן, שֶׁהִסְכִּים אִתָּנוּ. וְלֹא דַי אִילָן אֶחָד, אֶלָּא שְׁלֹשָׁה. אֲבָל מַעְיָן זֶה דְּמוּת עֶלְיוֹנָה הִיא אֶל אוֹתוֹ מַעְיָן טָמִיר וְגָנוּז. שְׁלֹשָׁה אִילָנוֹת אֵלּוּ, שְׁלֹשָׁה אֲרָזִים הֵם שֶׁנִּקְרָאִים אַרְזֵי הָלְּבָנוֹן, וְהֵם דְּמוּת שְׁלֹשָׁה אִילָנוֹת גְּדוֹלִים, סוֹד הָאָבוֹת. (שהסכים עמנו. מעין זה דגמת אותו מעין עליון שטמיר וגנוז. שלשה אילנות הם דמות של שלשה אילנות גדולים, סוד האבות) אַשְׁרֵי חֶלְקֵנוּ בְּאוֹתָהּ שָׁעָה.</p>\n<p>הִרְכִּינוּ הָאִילָנוֹת אֶחָד עַל רֹאשׁ רַבִּי שִׁמְעוֹן, וְאֶחָד עַל רֹאשׁ רַבִּי פִּנְחָס, וְאֶחָד עַל רֹאשׁ רַבִּי אֶלְעָזָר. הִתְפַּשְּׁטוּ הָעֲנָפִים לְכָל צַד עַל רָאשֵׁי הַחֲבֵרִים. בָּכָה (שמח) רַבִּי פִּנְחָס וְאָמַר, אַשְׁרֵי חֶלְקִי וְאַשְׁרֵי עֵינַי שֶׁרָאוּ כָּךְ. וְלֹא עַל שֶׁלְּךְ וְעַל שֶׁלִּי שָׂמַחְתִּי בִּלְבַדָּם, אֶלָּא עַל רַבִּי אֶלְעָזָר בְּנֵנוּ אֲנִי שָׂמֵחַ, שֶׁחָשׁוּב הוּא לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ כְּאֶחָד מֵאִתָּנוּ. קָם וּנְשָׁקוֹ. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, קוּם בְּעָמְדְּךְ וֶאֱמֹר לִפְנֵי רִבּוֹנְךְ דְּבָרִים שֶׁלּוֹ. קָם רַבִּי אֶלְעָזָר.</p>"],[9522012426,"<p>פָּתַח וְאָמַר, (מיכה ו) עַמִּי זְכָר נָא מַה יָּעַץ בָּלָק מֶלֶךְ מוֹאָב וְגוֹ'. עַמִּי, כַּמָּה רַחֲמָן הַקָּדוֹשׁ בָּרוּךְ הוּא עַל בָּנָיו. אַף עַל גַּב שֶׁחָטְאוּ לְפָנָיו, כָּל דְּבָרָיו בְּאַהֲבָה אֲלֵיהֶם כְּאָב אֶל בְּנוֹ. חָטָא הַבֵּן לְאָבִיו - מַלְקֵהוּ. כָּל עוֹד כְּשֶׁמַּלְקֵהוּ וְלֹא שָׁב מִדַּרְכּוֹ, נוֹזֵף בּוֹ בִּדְבָרִים וְלֹא מְקַבֵּל. אָמַר אָבִיו: אֵינִי רוֹצֶה לַעֲשׂוֹת לִבְנִי כְּמוֹ שֶׁעָשִׂיתִי עַד הַיּוֹם. אִם אַלְקֶנּוּ - יַחֲשֹׁשׁ בְּרֹאשׁוֹ, הֲרֵי הַכְּאֵב שֶׁלּוֹ אֶצְלִי. אִם אֶנְזֹף בּוֹ - דְּמוּתוֹ מִשְׁתַּנֵּית. מָה אֶעֱשֶׂה? אֶלָּא אֵלֵךְ וְאֶתְחַנֵּן אֵלָיו וְאֹמַר לוֹ דְּבָרִים רַכִּים כְּדֵי שֶׁלֹּא יִתְעַצֵּב.</p>\n<p>כָּךָ בְּכָל הַמִּינִים הוֹלֵךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיִשְׂרָאֵל. שׁוֹרֶה אִתָּם הַלְקָאָה, וְלֹא קִבְּלוּ. נָזַף בָּהֶם, וְלֹא קִבְּלוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֲנִי רוֹאֶה בִּבְנִי שֶׁבִּגְלַל הַמַּלְקוּת שֶׁהִלְקֵיתִי אוֹתָם, הֵם חוֹשְׁשִׁים בְּרֹאשָׁם. אוֹי, שֶׁהֲרֵי מִתּוֹךְ כְּאֵבָם אֲנִי חוֹשֵׁשׁ, שֶׁכָּתוּב (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר. נָזַפְתִּי בָהֶם, הִשְׁתַּנְּתָה דְמוּתָם, שֶׁכָּתוּב (איכה ד) חָשַׁךְ מִשְּׁחוֹר תָּאֳרָם לֹא נִכְּרוּ בַּחוּצוֹת. אוֹי כְּשֶׁהִסְתַּכַּלְתִּי בָהֶם וְלֹא נוֹדְעוּ. כָּעֵת אֶתְחַנֵּן לִפְנֵיהֶם תּוֹךְ תַּחֲנוּנִים. עַמִּי מֶה עָשִׂיתִי לָךְ וּמָה הֶלְאֵיתִיךְ. בְּנִי יָחִיד שֶׁלִּי, חֲבִיב נַפְשִׁי, רְאֵה מֶה עָשִׂיתִי לָךְ, הִשְׁלַטְתִּי אוֹתְךְ עַל כָּל בְּנֵי הֵיכָלִי, הִשְׁלַטְתִּי אוֹתְךְ עַל כָּל מַלְכֵי הָעוֹלָם. וְאִם עָשִׂיתִי לְךְ מַעֲשִׂים אֲחֵרִים, עֲנֵה בִּי, אַתָּה תָּעִיד בִּי.</p>\n<p>עַמִּי זְכָר נָא מַה יָּעַץ בָּלָק מֶלֶךְ מוֹאָב וּמֶה עָנָה אֹתוֹ בִּלְעָם בֶּן בְּעוֹר (מיכה ו). זְכָר נָא, הֱיֵה זוֹכֵר בְּבַקָּשָׁה מִמְּךְ, מַה יָּעַץ. כָּעֵת יֵשׁ לְהִסְתַּכֵּל מֶה הָיְתָה עֲצַת בָּלָק עַל הָעָם הַקָּדוֹשׁ, וְהַתּוֹרָה לֹא הֶחְשִׁיבָה אֶת בָּלָק כְּלוּם, כְּמוֹ שֶׁהָיָה לְלָבָן, שֶׁכָּתוּב (דברים כו) אֲרַמִּי אֹבֵד אָבִי.</p>"],[9522012427,"<p>אֲשׁוּרֶנּוּ וְגוֹ', צִיּוּר וּדְמוּת אָבִיו נִרְשָׁם בּוֹ מַמָּשׁ. וּמֵאוֹתוֹ זְמַן שֶׁהָיָה בִּמְעֵי אִמּוֹ, מִצַּד שֶׁלָּהּ הִתְמַתַּח וְהוֹשִׁיט פְּסִיעָה לַחוּץ יוֹתֵר. כִּי מֵרֹאשׁ צֻרִים אֶרְאֶנּוּ, זוֹ דְּמוּת וְצִיּוּר אָבִיו (ממש). כֵּיוָן שֶׁהָיָה בִּמְעֵי אִמּוֹ, אֲשׁוּרֶנּוּ, הוֹשִׁיט פְּסִיעָה לַחוּץ, כְּמוֹ זֶה ת' (ו').</p>\n<p>וְזְהִוּ וּמִגְּבָעוֹת אֲשׁוּרֶנּוּ. בַּיְשִׁיבָה הָעֶלְיוֹנָה גְּבָעֹת חָסֵר ו' (גבוהת הכל אותה עליונת הכל). בִּישִׁיבַת הָרָקִיעַ וּמִגְּבָעוֹת, בְּאוֹת ו'. וּמַשְׁלִים לִשְׁנֵי צְדָדִים. אֶחָד, שֶׁהֲרֵי הַגִּבְעַת הַזּוֹ לֹא נִפְרֶדֶת מִבְּנָהּ לְעוֹלָמִים וְאֵינָהּ עוֹזֶבֶת אוֹתוֹ, וְעַל כֵּן נִכְלָל ו' אִתָּהּ לְעוֹלָם. וְאֶחָד, שֶׁהֲרֵי גִּבְעָה שֶׁלְּמַטָּה, בְּנָהּ שֶׁנִּכְלָל עִמָּהּ צָרִיךְ לֶעָתִיד לָבא כְּשֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ לָקַחַת לוֹ גִּבְעַת עֶלְיוֹנָה, וּלְהַכְנִיסוֹ תּוֹךְ כְּנָפֶיהָ כְּדֵי לְחַזֵּק אוֹתוֹ וּלְהַעֲמִידוֹ בְחַיִּים עֶלְיוֹנִים, וּמִמֶּנָּה יֵצֵא בְּאוֹתוֹ יוֹם מֶלֶךְ הַמָּשִׁיחַ.</p>\n<p>וְסוֹד זֶה - (תהלים ב) אֲסַפְּרָה אֶל חֹק ה' אָמַר אֵלַי בְּנִי אַתָּה אֲנִי הַיּוֹם יְלִדְתִּיךְ. עָתִיד אֲנִי לוֹמַר לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא חֹק וּלְבַשְּׂרוֹ, (ה' אמר אליבני אתה אני היום ילדתיך). בְּאוֹתוֹ יוֹם מַמָּשׁ יוֹצִיא אוֹתוֹ הַחֹק הַהוּא מִתַּחַת כְּנָפֶיהָ בְּכַמָּה חַיִּים, בְּכַמָּה עֲטָרוֹת, בְּכַמָּה בְרָכוֹת כָּרָאוּי.</p>\n<p>וְאוֹתוֹ חֹק לֹא יִשָּׁאֵר לְבַדּוֹ. יִכָּלֵל בּוֹ מָשִׁיחַ אַחֵר, בֶּן יוֹסֵף, וְשָׁם יִתְחַזֵּק, וְלֹא בְמָקוֹם אַחֵר. וּמִשּׁוּם שֶׁהוּא גִּבְעָה תַחְתּוֹנָה שֶׁאֵין בָּהּ חַיִּים, יָמוּת מָשִׁיחַ זֶה וְיֵהָרֵג, וְיָמוּת עַד שֶׁתִּלְקֹט גִּבְעָה זוֹ חַיִּים מֵאוֹתָהּ גִּבְעָה עֶלְיוֹנָה, וְיָקוּם.</p>\n<p>וּמִשּׁוּם כָּךְ בִּישִׁיבַת הָרָקִיעַ וּמִגְּבָעוֹת שָׁלֵם, בְּאוֹת ו', עַל שְׁנֵי צְדָדִים אֵלּוּ (כתוב). אֲבָל בַּיְשִׁיבָה הָעֶלְיוֹנָה חָסֵר, בְּלִי ו', לְהַרְאוֹת דָּבָר שֶׁאֵין בּוֹ קֻשְׁיָה וְסָפֵק. הֶן עָם לְבָדָד יִשְׁכֹּן, בְּיִחוּד, בְּלִי עִרְבּוּבְיָה אַחֶרֶת.</p>"],[9522012428,"<p>כָּל יִחוּד שָׁלֵם כָּאן הוּא. ה' אֱלֹהֵינוּ ה'. שֶׁהֲרֵי סוֹדוֹ מֵרֹאשׁ צֻרִים הוּא, וְהִתְיַחֵד בָּרֹאשׁ, בַּגֶּזַע וּשְׁבִיל. ה' - זֶה הָרֹאשׁ הָעֶלְיוֹן, אֲוִיר שֶׁעוֹלֶה. אֱלֹהֵינוּ - זֶה הַגֶּזַע, שֶׁנֶּאֱמַר (ישעיה יא) גֶּזַע יִשַׁי. ה' - זֶה הַשְּׁבִיל שֶׁלְּמַטָּה. וְעַל סוֹד זֶה הִתְיַחֵד בּוֹ כָּרָאוּי. וּמִשּׁוּם שֶׁנִּמְתָּח בּוֹ שְׁבִיל, צָרִיךְ סוֹד שֶׁנִּגְזָר בִּשְׁתֵּי יְשִׁיבוֹת.</p>\n<p>אַשְׁרֵי חֶלְקְךְ, רַבִּי שִׁמְעוֹן, שֶׁזָּכִיתָ לִדְבָרִים עֶלְיוֹנִים שֶׁל רִבּוֹנְךְ, וְרִבּוֹנְךְ הִתְרַצָּה בְּךְ. כַּמָּה שִׁעוּר שֶׁל הִתְפַּשְּׁטוּת שֶׁל שְׁבִיל זֶה בְּשִׁעוּר עֶלְיוֹן שֶׁל רֹאשׁ וְגֶזַע וּשְׁבִיל, וְהִתְלַבְּשׁוּ בְהִתְפַּשְּׁטוּת זוֹ. (ועל זה התפשטות של אחד, שעור של ששה צדדים, והכל התיחד באות ד' הזו, אח ד') וְעַל זֶה הִתְפַּשְּׁטוּת שֶׁל א' (ה') שִׁעוּר שֶׁל שִׁשָּׁה צְדָדִים. וְהַכֹּל הִתְיַחֵד בָּאוֹת (אח) הַזּוֹ. וּמִשּׁוּם כָּךְ לְבָדָד יִשְׁכֹּן כָּרָאוּי.</p>\n<p>וּבַגּוֹיִם לֹא יִתְחַשָּׁב. לְיִשְׂרָאֵל יֵשׁ כְּתָב וְלָשׁוֹן, וּבְכָל אוֹת יְכוֹלִים לְהִסְתַּכֵּל בִּדְמוּת וְצִיּוּר כָּרָאוּי, אֲבָל בַּגּוֹיִם - עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת - לֹא יִתְחַשָּׁב. הַסּוֹד שֶׁלָּנוּ, מִשּׁוּם שֶׁאֵין לָהֶם כְּתָב וְלָשׁוֹן, וְאֵין לָהֶם לְהִסְתַּכֵּל וְלָדַעַת כְּלוּם, שֶׁהֲרֵי (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים, וְלֹא יִתְחַשָּׁב סוֹד שֶׁלָּנוּ בְּמַחֲשָׁבָה וּבְהִסְתַּכְּלוּת שֶׁלָּהֶם, הוֹאִיל וְאֵין לָהֶם כְּתָב. אַשְׁרֵיהֶם יִשְׂרָאֵל.</p>\n<p>מִי מָנָה עֲפַר יַעֲקֹב וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. (מי) אוֹתָהּ נְקֻדָּה עֶלְיוֹנָה, רֹאשׁ וְגֶזַע וּשְׁבִיל, בְּנִסְתָּר הִיא, וְלֹא עוֹמֶדֶת לִשְׁאֵלָה לַחוּץ. אֲבָל מִשָּׁעָה שֶׁמַּתְחִילָה לְהִבָּנוֹת וְלַעֲשׂוֹת הֵיכָל בִּרְצוֹנוֹ, וְנִקְרֵאת מִ\"י, מַתְחִילָה לְהִבָּנוֹת. הַדְּמוּת, שֶׁלּוֹ מַמָּשׁ. מוֹצִיא נְקֵבָה שֶׁלּוֹ בִּדְמוּת אִמּוֹ.</p>\n<p>מַה זֶּה מִי? זֶה רֹאשׁ וְגֶזַע וּשְׁבִיל. (י') וְהִתְפַּשֵּׁט לְהִבָּנוֹת בִּפְשִׁיטוּת הֵיכָל אֶחָד, לִשְׁנֵי צְדָדִים בּוֹנֶה. וְאַף עַל גַּב שֶׁהוֹצִיא אֶת יִשְׂרָאֵל, שֶׁהוּא ו' - גַּם כָּךְ הוֹצִיא אֶת נְקֵבָתוֹ כְּאֶחָד וְהִזְמִינָהּ אֵלָיו. מָנָה, כְּמוֹ שֶׁנֶּאֱמַר (דניאל א) וַיְמַן לָהֶם הַמֶּלֶךְ, (אסתרט) וּמִשְׁלוֹחַ מָנוֹת. נָתַן לוֹ אוֹצָר גָּדוֹל וְיָקָר, וְהוֹצִיא אוֹתָהּ כְּאֶחָד מִמֶּנּוּ. בְּאוֹתָהּ פְּשִׁיטוּת שֶׁהִתְפַּשֵּׁט, הוֹצִיא שְׁנֵיהֶם כְּאֶחָד, (כדגמה זו פשוט לכאן ולכאן, הוציא בן ובת ברגע אחד, ועל זה שמים וארץ ברגע אחד נבראו כאחד) בְּשָׁעָה אַחַת.</p>\n<p>וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל. רֹבַע יִשְׂרָאֵל, סוֹד זֶה בִּגְלָלְךְ, רַבִּי, נִמְסַר. אַשְׁרֵי חֶלְקְךְ! רֹבַע יִשְׂרָאֵל, רְבִיעִית מִמְּדִידוּת יִשְׂרָאֵל, הִיא בְּרִית. לָמָּה נִקְרָא רֹבַע? אֶלָּא שִׁעוּר הַגּוּף, אַרְבַּע בְּרִיתוֹת הָיוּ בַּשִּׁעוּר שֶׁלּוֹ. וּבְרִית רֹבַע הוּא בַּשִּׁעוּר שֶׁל מְדִידוּת הַגּוּף. הַכֹּל הוֹצִיא מִי.</p>"],[9522012429,"<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי יוֹסֵי חָמִיו, רַבִּי אַבָּא וַחֲבֵרָיו הָלְכוּ עִמּוֹ. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים ה) ה' בּקֶר תִּשְׁמַע קוֹלִי וְגוֹ'. ה' בֹּקֶר, אֵיזֶה בֹּקֶר? אֶלָּא זֶה בֹּקֶר שֶׁל אַבְרָהָם שֶׁהִתְעוֹרֵר בָּעוֹלָם, שֶׁכָּתוּב (בראשית כב) וישכם אברהם בבקר. שהרי כְּשֶׁמַּגִּיעַ הַבּקֶר, אוֹתוֹ בֹּקֶר מִתְעוֹרֵר בָּעוֹלָם, וְהוּא עֵת רָצוֹן לַכֹּל, וְלַעֲשׂוֹת טוֹב לְכָל הָעוֹלָם, לַצַּדִּיקִים וְלָרְשָׁעִים. וְאָז זְמַן תְּפִלָּה הוּא לְהִתְפַּלֵּל לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וְעַל זֶה, בְּשָׁעָה שֶׁבָּא הַבֹּקֶר, כָּל אוֹתָם אֲסִירֵי הַמֶּלֶךְ מוֹצְאִים מְנוּחָה, זְמַן תְּפִלָּה הוּא עֲלֵיהֶם, וְכָל שֶׁכֵּן אוֹתָם שֶׁחוֹזְרִים בִּתְשׁוּבָה וּמְבַקְשִׁים בַּקָּשׁוֹתֵיהֶם לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, מִשּׁוּם שֶׁבְּשָׁעָה זוֹ יוֹצֵא מְמֻנֶּה אֶחָד לְצַד דָּרוֹם, וּרְפָאֵל שְׁמוֹ, וְכָל מִינֵי רְפוּאָה בְּיָדוֹ. וּמִצַּד דָּרוֹם יוֹצֵאת רוּחַ אַחַת וּמַגִּיעָה לְאוֹתוֹ הַמְמֻנֶּה שֶׁמְּמֻנֶּה עַל הָרְפוּאָה. וּכְשֶׁמַּגִּיעָה הָרְפוּאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא פּוֹקֵד לְבֵית דִּינוֹ שֶׁלֹּא יִפְתְּחוּ בְדִין, מִשּׁוּם שֶׁהַחַיִּים בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא בִידֵיהֶם.</p>\n<p>וּמִתּוֹךָ שֶׁהוּא עֵת רָצוֹן, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא זְכוּת אוֹתוֹ הָאִישׁ. אִם יִמָּצֵא בִתְפִלָּה (יפה. ואם לא נחשב לו בשוגג) אוֹ שֶׁהוּא בַּעַל תְּשׁוּבָה - חָס עָלָיו. בְּאוֹתָהּ שָׁעָה נִשְׁמָע קוֹל צִפֳּרִים הַמְקַנְּנוֹת, שֶׁכָּתוּב (תהלים קד) אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ. וְאוֹתָן צִפֳּרִים מוֹדוֹת וּמְשַׁבְּחוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וְאוֹתָהּ אַיֶּלֶת הַשַּׁחַר מִתְעוֹרֶרֶת בָּעוֹלָם וְאוֹמֶרֶת, (שם לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ וְגוֹ'. אָז אוֹתוֹ מְמֻנֶּה יוֹצֵא, וְעוֹשֶׂה כָּל מַה שֶּׁנִּצְטַוָּה.</p>\n<p>וְאִם תֹּאמַר שֶׁמִּינֵי רְפוּאָה בְיָדוֹ כְּמוֹ שֶׁאָמַרְנוּ - לֹא כָּךְ! שֶׁהֲרֵי רְפוּאָה לֹא הָיְתָה, רַק בִּידֵי הַמֶּלֶךְ הַקָּדוֹשׁ. אֲבָל בְּשָׁעָה שֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא רְפוּאָה לְאוֹתוֹ הָאָדָם, הוּא יוֹצֵא, וְכָל הַמְקַטְרְגִים הַמְמֻנִּים עַל מַחֲלוֹת רָעוֹת פּוֹחֲדִים מִמֶּנּוּ. אָז אוֹתָהּ הָרוּחַ שֶׁנָּסְעָה מִצַּד דָּרוֹם מוֹשִׁיטָה לוֹ לְאוֹתוֹ אָדָם, וַהֲרֵי הָרְפוּאָה נִמְצֵאת, וְהַכֹּל בִּידֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְעַל זֶה כָּתוּב (שם ה) ה' בֹּקֶר תִּשְׁמַע קוֹלִי, וְלֹא כָתוּב ה' בַּבֹּקֶר תִּשְׁמַע קוֹלִי. אֶלָּא לְגַבֵּי הַבֹּקֶר שֶׁל אַבְרָהָם הוּא אָמַר. בֹּקֶר אֶעֱרָךְ לְךְ וַאֲצַפֶּה. שְׁנֵי בֹקֶר לָמָּה? אֶלָּא אֶחָד בֹּקֶר שֶׁל אַבְרָהָם, וְאֶחָד בֹּקֶר שֶׁל יוֹסֵף, שֶׁכָּתוּב (בראשית מד) הַבֹּקֶר אוֹר, וּמְתַרְגְּמִים: בֹּקֶר מֵאִיר, מֵאִיר וַדַּאי. אֶעֱרָךְ לְךְ וַאֲצַפֶּה, מַה זֶּה אֶעֱרָךְ לְךְ? אֶלָּא אֲסַדֵּר לְךְ נֵר שֶׁלְּךְ לְהַדְלִיק, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קלב) עָרַכְתִּי נֵר לִמְשִׁיחִי. וּלְגַבֵּי הַבֹּקֶר שֶׁל יוֹסֵף הוּא אָמַר, שֶׁאוֹתוֹ סִדּוּר שֶׁל נֵר שֶׁלּוֹ הוּא.</p>\n<p>וַאֲצַפֶּה, מַה זֶּה וַאֲצַפֶּה? הֲרֵי כָּל בְּנֵי הָעוֹלָם מְצַפִּים וּמְחַכִּים לְטוּב הַקָּדוֹשׁ בָּרוּךְ הוּא, וַאֲפִלּוּ בַּהֲמוֹת הַשָּׂדֶה, וּמַה שֶּׁבַח שֶׁל דָּוִד יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם? אֶלָּא דָּבָר זֶה שָׁאַלְתִּי, וְכָךְ אָמְרוּ לִי, וְהוּא דְּבַר אֱמֶת שֶׁבָּא מֵרָחוֹק. אוֹר רִאשׁוֹן שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מֵאִיר עַד שֶׁלֹּא יָכְלוּ הָעוֹלָמוֹת לִסְבֹּל אוֹתוֹ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? עָשָׂה אוֹר לְאוֹרוֹ לְהִתְלַבֵּשׁ זֶה בָּזֶה. וְכֵן כָּל שְׁאָר הָאוֹרוֹת, עַד שֶׁכָּל הָעוֹלָמוֹת הִתְקַיְּמוּ בְקִיּוּמָם וְיָכְלוּ לִסְבֹּל.</p>\n<p>וּמִשּׁוּם כָּךְ הִתְפַּשְּׁטוּ דְרָגוֹת וְהִתְלַבְּשׁוּ אוֹרוֹת, וְהֵם נִקְרָאִים כְּנָפַיִם עֶלְיוֹנִים, עַד שֶׁמַּגִּיעִים לְבֹקֶר זֶה שֶׁל יוֹסֵף, וְהוּא לוֹקֵחַ כָּל הָאוֹרוֹת הָעֶלְיוֹנִים. וּמִתּוֹךְ שֶׁכָּל הָאוֹרוֹת הָעֶלְיוֹנִים בּוֹ תְּלוּיִים, זִיווֹ עוֹלֶה מִסּוֹף הָעוֹלָם עַד סוֹף הָעוֹלָם שֶׁלְּמַעְלָה, עַד שֶׁהָעוֹלָמוֹת שֶׁלְּמַטָּה לֹא יְכוֹלִים לִסְבֹּל. בָּא דָוִד וְהִתְקִין נֵר זֶה, כִּסּוּי לְבֹקֶר זֶה שֶׁל יוֹסֵף לְהִתְכַּסּוֹת בּוֹ וּלְהַעֲמִיד עוֹלָמוֹת שֶׁלְּמַטָּה בְּסִדּוּר הַנֵּר הַזֶּה, וְעַל זֶה כָּתוּב בּקֶר אֶעֱרָךְ לְךְ וַאֲצַפֶּה, כְּמוֹ שֶׁנֶּאֱמַר (שמות לז) וַיְצַפֵּהוּ זָהָב טָהוֹר. (ומשום שאותו נר, דוד תלוי בו וכו') וּמִשּׁוּם שֶׁאוֹתוֹ הַנֵּר הוּא שֶׁל דָּוִד וּבוֹ תָלוּי, אָמַר שֶׁהוּא יִהְיֶה כִסּוּי לַבֹּקֶר הַזֶּה. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ, וְאָמַר, אִלְמָלֵא לֹא יָצָאתִי לַדֶּרֶךְ רַק לִשְׁמֹעַ דָּבָר זֶה - דַּי לִי!</p>"],[9522012430,"<p>עַד שֶׁהָיוּ הוֹלְכִים, בָּאָה יוֹנָה אַחַת לְרַבִּי אֶלְעָזָר, שָׁרְתָה וְצִפְצְפָה לְפָנָיו. אָמַר רַבִּי אֶלְעָזָר, יוֹנָה כְּשֵׁרָה, תָּמִיד הָיִית נֶאֱמָנָה בִשְׁלִיחוּתֵךְ. לְכִי וְאִמְרִי לוֹ, הֲרֵי הַחֲבֵרִים בָּאִים אֵלֶיךְ, וַאֲנִי עִמָּהֶם, וְנֵר יִתְרַחֵשׁ לָנוּ לִשְׁלֹשָׁה יָמִים, וְלֹא יִפֹּל עָלָיו פַּחַד, שֶׁהֲרֵי בְּחֶדְוָה אָנוּ הוֹלְכִים אֵלָיו. הֵשִׁיב פַּעַם אַחֶרֶת וְאָמַר, לֹא שָׂמַחְנוּ מַסְפִּיק, וְרַע בְּעֵינַי הַרְבֵּה עַל רִמּוֹן אֶחָד מָלֵא שֶׁנִּתָּן תַּחְתָּיו, וְיוֹסֵי שְׁמוֹ. הָלְכָה אוֹתָהּ הַיּוֹנָה מִלְּפָנָיו, וְאוֹתָם הַחֲבֵרִים הָלְכוּ.</p>\n<p>אָמַר רַבִּי אַבָּא לְרַבִּי אֶלְעָזָר, מַה זֶּה? תָּמַהְתִּי הַרְבֵּה מִמַּה שֶּׁרָאִיתִי. אָמַר לוֹ, הַיּוֹנָה הַזּוֹ בָּאָה אֵלַי בִּשְׁלִיחוּת רַבִּי יוֹסֵי חָמִי, שֶׁהוּא בְּבֵית חָלְיוֹ, וְיָדַעְתִּי מֵהַיּוֹנָה הַזּוֹ שֶׁהוּא נִצַּל, וְחִלּוּף נִתַּן עָלָיו וְנִתְרַפֵּא.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, הֲרֵי עוֹרֵב אֶחָד עָמַד לִפְנֵיהֶם, קוֹרֵא בְּכֹחַ וּמְצַפְצֵף צִפְצוּף גָּדוֹל. אָמַר רַבִּי אֶלְעָזָר, לְכָךְ אַתָּה קַיָּם וּלְכָךְ אַתָּה מְתֻקָּן. לֵךְ לְדַרְכְּךְ, שֶׁהֲרֵי יָדַעְתִּי. אָמַר רַבִּי אֶלְעָזָר, חֲבֵרִים, נֵלֵךְ וְנִגְמֹל חֶסֶד לְרִמּוֹן שֶׁהָיָה מָלֵא מֵהַכֹּל, וְרַבִּי יוֹסֵי מִפְּקִיעִין הוּא שְׁמוֹ, שֶׁהֲרֵי הִסְתַּלֵּק מֵהָעוֹלָם הַזֶּה וְאֵין מִי שֶׁרָאוּי לְהִשְׁתַּדֵּל בּוֹ, וְהוּא קָרוֹב אֵלֵינוּ.</p>\n<p>סָטוּ מֵהַדֶּרֶךְ וְהָלְכוּ לְשָׁם. כֵּיוָן שֶׁרָאוּ אוֹתָם כָּל בְּנֵי הָעִיר, יָצְאוּ אֲלֵיהֶם, וְנִכְנְסוּ שָׁם לְבֵית רַבִּי יוֹסֵי מִפְּקִיעִין אוֹתָם הַחֲבֵרִים הַלָּלוּ. בֵּן קָטָן הָיָה לוֹ לְרַבִּי יוֹסֵי, וְלֹא נָתַן לְשׁוּם אָדָם שֶׁיַּגִּיעַ לְמִטַּת אָבִיו אַחַר שֶׁמֵּת, אֶלָּא הָיָה לְבַדּוֹ סָמוּךְ לוֹ, וּבָכָה עָלָיו, פִּיו בְּפִיו מִתְדַּבֵּק.</p>\n<p>פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר: רִבּוֹן הָעוֹלָם, כָּתוּב בַּתּוֹרָה (דברים כב) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ וְגוֹ', שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְגוֹ'. הָיָה צוֹעֵק אוֹתוֹ תִּינוֹק וּבוֹכֶה, וְאָמַר: רִבּוֹן הָעוֹלָם, קַיֵּם דָּבָר זֶה שֶׁל הַתּוֹרָה! שְׁנֵי בָנִים הָיִינוּ מֵאַבָּא וְאִמִּי, אֲנִי וַאֲחוֹתִי הַקְּטַנָּה מִמֶּנִּי, הָיָה לְךְ לָקַחַת אוֹתָנוּ וּלְקַיֵּם דְּבַר הַתּוֹרָה. וְאִם תֹּאמַר, רִבּוֹן הָעוֹלָם, אֵם כָּתוּב, וְלֹא אָב - הֲרֵי כָּאן הַכֹּל הוּא, אַבָּא וְאִמָּא. אִמָּא מֵתָה, וְלָקַחְתָּ אוֹתָהּ מֵעַל הַבָּנִים. כָּעֵת אַבָּא שֶׁהָיָה מְכַסֶּה עָלֵינוּ נִלְקַח מֵעַל הַבָּנִים. אֵיפֹה דִּין הַתּוֹרָה? בָּכוּ רַבִּי אֶלְעָזָר וְהַחֲבֵרִים מוּל הַבְּכִי וְהַצְּעָקָה שֶׁל אוֹתוֹ תִּינוֹק.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (משלי כה) שָׁמַיִם לָרוּם וָאָרֶץ לָעֹמֶק וְגוֹ'. עַד שֶׁהָיָה אוֹמֵר רַבִּי אֶלְעָזָר פָּסוּק זֶה, הָיָה עַמּוּד אֵשׁ מַפְסִיק בֵּינֵיהֶם, וְאוֹתוֹ תִּינוֹק הָיָה דָבֵק בְּפִי אָבִיו וְלֹא הָיוּ נִפְרָדִים. אָמַר רַבִּי אֶלְעָזָר, אוֹ שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַרְחִישׁ נֵס, אוֹ שֶׁרוֹצֶה שֶׁלֹּא יִשְׁתַּדֵּל אָדָם אַחֵר עָלָיו, אֲבָל עַל דִּבְרֵי אוֹתוֹ הַתִּינוֹק וְדִמְעוֹתָיו אֵינִי יָכוֹל לִסְבֹּל.</p>\n<p>עֵד שֶׁהָיוּ יוֹשְׁבִים, שָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: אַשְׁרֶיךְ רַבִּי יוֹסֵי שֶׁדִּבְרֵי הַגְּדִי הַקָּטָן הַזֶּה וְדִמְעוֹתָיו עָלוּ אֶל כִּסֵּא הַמֶּלֶךְ הַקָּדוֹשׁ, וְדָנוּ דִין, וּשְׁלֹשָׁה עָשָׂר בְּנֵי אָדָם הִזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַלְאַךְ הַמָּוֶת בִּגְלָלְךְ, וַהֲרֵי עֶשְׂרִים וּשְׁתַּיִם שָׁנִים הוֹסִיפוּ לְךְ עַד שֶׁתְּלַמֵּד תּוֹרָה אֶת הַגְּדִי הַשָּׁלֵם הַזֶּה הֶחָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>קָמוּ רַבִּי אֶלְעָזָר וְהַחֲבֵרִים, וְלֹא הִשְׁאִירוּ אָדָם לַעֲמֹד בַּבַּיִת. מִיָּד רָאוּ אוֹתוֹ עַמּוּד אֵשׁ שֶׁעוֹלֶה, וְרַבִּי יוֹסֵי פָּתַח עֵינָיו, וְאוֹתוֹ תִּינוֹק דָּבוּק פִּיו בְּפִיו. אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי חֶלְקֵנוּ שֶׁרָאִינוּ תְחִיַּת הַמֵּתִים עַיִן בְּעַיִן. קָרְבוּ אֵלָיו, וְהָיָה אוֹתוֹ תִּינוֹק יָשֵׁן כְּאִלּוּ שֶׁגָּוַע מֵהָעוֹלָם הַזֶּה. אָמְרוּ, אַשְׁרֵי חֶלְקְךְ רַבִּי יוֹסֵי, וּבָרוּךְ הָרַחֲמָן שֶׁהִרְחִישׁ לְךְ נֵס עַל הַצְּעָקָה וְהַבְּכִי שֶׁל בִּנְךְ וּבִדְבָרָיו, שֶׁכָּךְ דָּחַק בִּדְבָרִים יָפִים לְשַׁעַר הַשָּׁמַיִם, בִּדְבָרָיו וּבְדִמְעוֹתָיו הוֹסִיפוּ לְךְ חַיִּים.</p>\n<p>לָקְחוּ אֶת אוֹתוֹ תִּינוֹק וּנְשָׁקוּהוּ, וּבָכוּ עִמּוֹ מֵרֹב חֶדְוָה, וְהוֹצִיאוּהוּ לְבַיִת אַחֵר, וְהִתְעוֹרְרוּ עָלָיו, וְלֹא הוֹדִיעַ לוֹ מִיָּד, אֶלָּא אַחַר כָּךְ. שָׂמְחוּ שָׁם שְׁלֹשָׁה יָמִים, וְחִדְּשׁוּ יַחַד עִם אוֹתוֹ רַבִּי יוֹסֵי כַּמָּה חִדּוּשֵׁי תוֹרָה.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, חֲבֵרִים, לֹא נִתְּנָה לִי רְשׁוּת לְגַלּוֹת מִמַּה שֶּׁרָאִיתִי בְּאוֹתוֹ עוֹלָם, אֶלָּא לְאַחַר שְׁתֵּים עֶשְׂרֵה שָׁנִים. אֲבָל שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וְחָמֵשׁ דְּמָעוֹת שֶׁשָּׁפַךְ בְּנִי, נִכְנְסוּ בְחֶשְׁבּוֹן לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וַאֲנִי נִשְׁבָּע לָכֶם, חֲבֵרִים, שֶׁבְּשָׁעָה שֶׁפָּתַח בְּאוֹתוֹ הַפָּסוּק וְצָעַק בַּדְּבָרִים הָהֵם, הִזְדַּעְזְעוּ שְׁלֹשׁ מֵאוֹת אֶלֶף סַפְסְלֵי יְשִׁיבַת הָרָקִיעַ, וְכֻלָּם עוֹמְדִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וּבִקְשׁוּ עָלַי רַחֲמִים וְעָרְבוּ לִי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְמַלֵּא רַחֲמִים עָלַי.</p>\n<p>וְיָפֶה לְפָנָיו אוֹתָם דְּבָרִים וְאֵיךְ מָסַר נַפְשׁוֹ עָלַי. וְאַפּוֹטְרוֹפּוֹס אֶחָד הָיָה לְפָנָיו, וְאָמַר: רִבּוֹן הָעוֹלָם, הֲרֵי כָּתוּב (תהלים ח) מִפִּי עוֹלְלִים וְיֹנְקִים יִסַּדְתָּ עֹז לְמַעַן צוֹרְרֶיךְ לְהַשְׁבִּית אוֹיֵב וּמִתְנַקֵּם. יְהִי רָצוֹן מִלְּפָנֶיךְ שֶׁזְּכוּת הַתּוֹרָה וּזְכוּת אוֹתוֹ הַתִּינוֹק שֶׁמָּסַר נַפְשׁוֹ עַל אָבִיו, שֶׁתָּחוּס עָלָיו וְיִנָּצֵל.</p>\n<p>וּשְׁלֹשָה עָשָׂר בְּנֵי אָדָם הִזְמִין לוֹ תַּחְתַּי, וְעֵרָבוֹן נָתַן לוֹ מִדִּין קָשֶׁה זֶה. אָז קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַלְאַךְ הַמָּוֶת, וְצִוָּה אוֹתוֹ עָלַי שֶׁיַּחֲזֹר לְאַחַר עֶשְׂרִים וּשְׁתַּיִם שָׁנִים, שֶׁהֲרֵי אֵין הָעֵרָבוֹן לְפָנָיו, אֶלָּא לְהָשִׁיב לְיָדוֹ מַשְׁכּוֹנוֹת שֶׁהָיוּ בְיָדוֹ. כָּעֵת חֲבֵרִים, מִשּׁוּם שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאַתֶּם צַדִּיקֵי אֱמֶת, הִתְרַחֵשׁ הַנֵּס לְעֵינֵיהֶם.</p>"],[9522012431,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שמואל א ב) ה' מֵמִית וּמְחַיֶּה מוֹרִיד שְׁאוֹל וַיָּעַל. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, וְכִי ה' מֵמִית? וַהֲרֵי שֵׁם זֶה סַם חַיִּים הוּא לַכֹּל, וְדָבָר זֶה שֶׁל מָוֶת לֹא שׁוֹרֶה בּוֹ, וּבְכָל מָקוֹם שֵׁם זֶה נוֹתֵן חַיִּים לְכָל הָעוֹלָם, אָז מַה זֶּה ה' מֵמִית? חוֹשְׁבִים בְּנֵי אָדָם שֶׁהוּא הוֹרֵג לְכָל בְּנֵי הָאָדָם?! אֶלָּא ה' מֵמִית בְּוַדַּאי. אֵיךְ הוּא מֵמִית? אִם תֹּאמַר מִשּׁוּם שֶׁהִסְתַּלֵּק מֵעַל בְּנֵי אָדָם, שֶׁהֲרֵי בְּעוֹד שֶׁהוּא עָלָיו, לֹא יְכוֹלִים כָּל מְקַטְרְגֵי הָעוֹלָם לְהַזִּיק לוֹ. בְּשָׁעָה שֶׁמִּסְתַּלֵּק מִמֶּנּוּ, מִיָּד כָּל הַמְקַטְרְגִים יְכוֹלִים לוֹ וּמֵת הַבֶּן אָדָם. לֹא כָּךְ?!</p>\n<p>אֶלָּא ה' מֵמִית, אֶת מִי הוּא מֵמִית? לְאוֹתָהּ הִתְפַּשְּׁטוּת הַצַּד הָאַחֵר הָרָע. כֵּיוָן שֶׁמְּשִׁיכוּת הַצַּד הָרָע רוֹאָה אֶת זִיו כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִיָּד מֵתָה, וְאֵין לָהּ קִיּוּם אֲפִלּוּ רֶגַע אֶחָד. כֵּיוָן שֶׁאוֹתָהּ הִתְפַּשְּׁטוּת צַד הָאַחֵר מֵתָה וְעָבְרָה מִן הָעוֹלָם, מִיָּד מְחַיֶּה. אֶת מִי הוּא מְחַיֶּה? אוֹתָהּ הִתְפַּשְּׁטוּת רוּחַ הַקֹּדֶשׁ שֶׁבָּאָה מִצַּד הַקְּדֻשָּׁה, מְחַיֶּה אוֹתָהּ וּמַעֲמִידָהּ בְּקִיּוּם שָׁלֵם. הַכֹּל עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּזְמַן אֶחָד. וּמַה שֶּׁאָמַר מוֹרִיד שְׁאוֹל וַיָּעַל - מוֹרִיד אוֹתָהּ רוּחַ קְדוֹשָׁה לַשְּׁאוֹל, וְעוֹשֶׂה לָהּ שָׁם טְבִילָה לְהִטַּהֵר, וּמִיָּד מַעֲלֶה אוֹתָהּ, (לשאל, להדון שם, ומיד מעלה אותה ועושה לה טבילה) וְנִכְנָס לַמָּקוֹם שֶׁצָּרִיךְ בְּגַן עֵדֶן.</p>\n<p>וַאֲנִי, חֲבֵרִים, בְּאוֹתָהּ שָׁעָה שֶׁהִסְתַּלַּקְתִּי מֵהָעוֹלָם, רוּחִי עָלְתָה וְנִרְדְּמָה מִיָּד, עַד שָׁעָה קַלָּה שֶׁהֶחֱיָנִי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַגּוּף הָיָה מֵת. בְּשָׁעָה שֶׁפָּתַח בְּנִי בְּאוֹתָם דְּבָרִים, אָז פָּרְחָה נִשְׁמָתוֹ (נשמתי), וּפָגְשָׁה בְנִשְׁמָתִי שֶׁהָיְתָה עוֹלָה מִתּוֹךְ טָהֳרָה וּמִתּוֹךְ טְבִילָה, וְנִכְנְסָה בְמָקוֹם שֶׁנִּכְנְסָה, וְשָׁם דָּנוּ אֶת דִּינָהּ, וְנִתְּנוּ לִי עֶשְׂרִים וּשְׁתַּיִם שְׁנוֹת חַיִּים בִּגְלַל דִּמְעוֹת וְדִבְרֵי בְנִי. מִכָּאן וָהָלְאָה יֵשׁ לִי לְהִשְׁתַּדֵּל בְּמַה שֶּׁרָאִיתִי, שֶׁהֲרֵי אֵין לִי לְהִשְׁתַּדֵּל בְּדִבְרֵי הָעוֹלָם הַזֶּה. כֵּיוָן שֶׁרָאִיתִי מַה שֶּׁרָאִיתִי, וְרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יֹאבַד וְיִשָּׁכַח מִמֶּנִּי כְּלוּם.</p>"],[9522012432,"<p>פָּתַח וְאָמַר, (תהלים קיח) יַסֹּר יִסְּרַנִּי יָּהּ וְגוֹ'. דָּוִד הַמֶּלֶךְ אָמַר אֶת זֶה עַל כָּל מַה (שעבר) שֶּׁעָשָׂה בְּזֶה הָעוֹלָם, וְאָמַר עַל הַהַבְטָחָה שֶׁהָיְתָה לוֹ בְּאוֹתוֹ עוֹלָם. עַל כָּל מַה שֶּׁעָבַר בָּעוֹלָם הַזֶּה, שֶׁרָדְפוּ אוֹתוֹ, וְהָיָה (לו) בּוֹרֵחַ בְּאֶרֶץ נָכְרִיָּה, בְּאֶרֶץ מוֹאָב וּבְאֶרֶץ פְּלִשְׁתִּים, וּמִכֻּלָּם הִצִּילוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא הִשְׁאִירוֹ לָמוּת, וְאָמַר עַל הַהַבְטָחָה שֶׁל אוֹתוֹ הָעוֹלָם.</p>\n<p>אָמַר דָּוִד, אִם כָּאן חָטָאתִי לַקָּדוֹשׁ- בָּרוּךְ-הוּא, כָּאן לָקִיתִי וְקִבַּלְתִּי עָנְשִׁי, וְטִהֵר אוֹתִי מִכָּל מַה שֶּׁחָטָאתִי, וְלֹא הִשְׁאִיר עֹנֶשׁ שֶׁלִּי לָעוֹלָם הַהוּא לְאַחַר מִיתָה, וַדַּאי יַסֹּר יִסְּרַנִּי יָּהּ - בָּעוֹלָם הַזֶּה כְּדֵי לְנַקּוֹתֵנִי, וְלַמָּוֶת לֹא נְתָנָנִי - בְּאוֹתוֹ הָעוֹלָם לָקַחַת מִמֶּנִּי נְקָמָה. וַאֲנִי, הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נִקָּה אוֹתִי פַּעַם אַחַת בָּעוֹלָם הַזֶּה, מִכָּאן וָהָלְאָה אֲנִי צָרִיךְ שֶׁלֹּא לִהְיוֹת בְּבוּשָׁה בָּעוֹלָם הַבָּא.</p>"],[9522012433,"<p>פָּתַח אוֹתוֹ תִּינוֹק בְּנוֹ וְאָמַר, (במדבר כז) אָבִינוּ מֵת בַּמִּדְבָּר וְהוּא לֹא הָיָה בְּתוֹךְ הָעֵדָה וְגוֹ'. אָבִינוּ, הֲרֵי הַטַּעַם לְמַעְלָה, הֶאֱרִיךְ בַּמִּלָּה וּמָשַׁךְ אוֹתָהּ. אִי חֲסִידִים קְדוֹשִׁים, כַּמָּה מְשִׁיכוּת צַעַר בִּקְרִיאַת אָבִינוּ. אֵין צַעַר וְאֵין כְּאֵב שֶׁל רוּחַ וָנֶפֶשׁ אֶלָּא כְּשֶׁקָּרָאנוּ כָּךְ, אָבִינוּ, בִּכְאֵב מִלֵּב. מֵת בַּמִּדְבָּר, וְכִי אֲחֵרִים לֹא מֵתוּ בַמִּדְבָּר שֶׁכָּאן רָשַׁם אוֹתוֹ וְאָמַר שֶׁהוּא מֵת בַּמִּדְבָּר? וַהֲרֵי אֲלָפִים וּרְבָבוֹת מֵתוּ בַמִּדְבָּר!</p>\n<p>אֶלָּא כַּמָּה בְּנֵי אָדָם מְעֻרְטָלִים עַל זֶה, מֵהֶם אוֹמְרִים שֶׁהוּא הָיָה מְקוֹשֵׁשׁ הָעֵצִים, שֶׁכָּתוּב כִּי בְחֶטְאוֹ מֵת. וּמֵהֶם אָמְרוּ כָּךְ, וּמֵהֶם אָמְרוּ כָּךְ, וַאֲנִי כָּךְ לָמַדְתִּי: יוֹם שֶׁאַבָּא נָפַל בְּבֵית חָלְיוֹ, לִמְּדַנִי אֶת זֶה, וַאֲנִי רָאִיתִי מַה שֶּׁרָאִיתִי, שֶׁצִּוָּה אוֹתִי אַבָּא שֶׁלֹּא לְגַלּוֹת. אֶלָּא כַּמָּה וְכַמָּה הָיוּ שֶׁמֵּתוּ בַמִּדְבָּר, וְלֹא עַל חֵטְא קֹרַח וְלֹא עַל חֵטְא הַמְרַגְּלִים. כָּךְ נִגְזְרָה הַגְּזֵרָה. (ולא על חטא העגל שעשו וכו') אֶלָּא קֹדֶם (שמתו על חטא קרח, על חטא המרגלים, כאשר נגזרה הגזרה, וקדם) מַתַּן תּוֹרָה, וְאַחַר הָעֵגֶל שֶׁעָשׂוּ אוֹתָם מַטְעֵי הָעוֹלָם וְאֵלּוּ שֶׁנִּמְשְׁכוּ אַחֲ רֵיהֶם.</p>\n<p>אֲבָל טַעֲנָה שֶׁטָּעֲנוּ אוֹתָן בָּנוֹת, שֶׁמֵּת בַּמִּדְבָּר הוּא, וְהָיָה צְלָפְחָד גָּדוֹל לְבֵית יוֹסֵף, וּמִתּוֹךְ שֶׁלֹּא יָדַע דַּרְכֵי הַתּוֹרָה כָּרָאוּי, לֹא הָיָה נָשִׂיא, וְהוּא הָיָה שֶׁלֹּא שָׁמַר פִּיו וּדְבָרָיו מוּל מֹשֶׁה, וְעָלָיו כָּתוּב (שם כא) וַיָּמָת עַם רָב מִיִּשְׂרָאֵל. גֶּבֶר שֶׁלֹּא יָדַע אֶת הַתּוֹרָה, (לאגדולבתורה) וְהוּא גְּדוֹל הַמִּשְׁפָּחָה. גָּדוֹל שֶׁל זֶרַע יוֹסֵף, מִבְּנֵי מְנַשֶּׁה. וּמִשּׁוּם שֶׁחָטָא בַמִּדְבָּר בְּדִבּוּר לְמֹשֶׁה, חָשְׁבוּ שֶׁמֹּשֶׁה שָׁמַר לוֹ שִׂנְאָה, וּמִשּׁוּם כָּךְ קָרְבוּ לִפְנֵי מֹשֶׁה וְאֶלְעָזָר וְכָל הַנְּשִׂיאִים וְכָל רָאשֵׁי הָאָבוֹת, וְלֹא דִבְּרוּ עִם מֹשֶׁה אֶלָּא לִפְנֵיהֶם, מִשּׁוּם שֶׁקִּנְּאוּ מִמֶּנּוּ קִנְאָה.</p>\n<p>מִכָּאן, מִי שֶׁחוֹשֵׁשׁ מִן הַדִּין, יְקָרֵב אֲחֵרִים וְיַרְבֶּה אֲנָשִׁים אֵצֶל אוֹתוֹ דַּיָּן, כְּדֵי שֶׁיִּשְׁמְעוּ דִין מִמֶּנּוּ וְיִפְחַד מֵהֶם, וְלֹא יְהֵא דָן אֶלָּא כָּרָאוּי, וְאִם לֹא - יִדְחֶה אוֹתוֹ מִן הַדִּין. וְהֵם לֹא יָדְעוּ שֶׁהֲרֵי (שם יב) מֹשֶׁה עָנָו מְאֹד מִכֹּל הָאָדָם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה, וְלֹא יָדְעוּ שֶׁמֹּשֶׁה לֹא כָּךְ.</p>\n<p>כֵּיוָן שֶׁרָאָה מֹשֶׁה כָּךְ, אָמַר, רָאִיתִי שֶׁכָּל הִתְכַּנְּסוּת שֶׁל אֲנָשִׁים גְּדוֹלִים מִיִּשְׂרָאֵל וְכָל רָאשֵׁי הָאָבוֹת וְכָל נְשִׂיאֵי הַכְּנֶסֶת קָרְבוּ אֵלַי. מִיָּד פֵּרַשׁ מֹשֶׁה מִן הַדִּין, זֶהוּ שֶׁכָּתוּב (שם כז) וַיַּקְרֵב מֹשֶׁה אֶת מִשְׁפָּטָן לִפְנֵי ה'. (אמר משה, לא ראוי לי לדין זה) עַנְוְתָנוּתוֹ שֶׁל מֹשֶׁה, הִקְרִיב אֶת מִשְׁפָּטָן לִפְנֵי ה'. דַּיָּנִים אֲחֵרִים לֹא לוֹקְחִים דֶּרֶךְ זוֹ, שֶׁאַף עַל גַּב שֶׁהִתְכַּנְּסוּת גְּדוֹלָה עֲלֵיהֶם. הֵם נִקְרָאִים דַּיָּנִים עַזֵּי פָנִים, אֵין בָּהֶם מֵעַנְוְתָנוּתוֹ שֶׁל מֹשֶׁה כְּלָל. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה. שָׂמְחוּ רַבִּי אֶלְעָזָר וְהַחֲבֵרִים.</p>\n<p>אָמַר אוֹתוֹ תִּינוֹק, חָזַרְנוּ לַדְּבָרִים הָרִאשׁוֹנִים. אָבִינוּ מֵת בַּמִּדְבָּר. אָבִינוּ, הַטַּעַם דּוֹמֶה לְנָחָשׁ שֶׁתָּלוּי עַל עָרְפּוֹ, וּמוֹשֵׁךְ זְנָבוֹ בְּפִיו בְּטַעַם שֶׁאתוֹ שֶׁנִּמְשָׁךְ עָלָיו לְמַעְלָה. מֵת בַּמִּדְבָּר, בְּדִבּוּר פִּיו. הִתְבַּהֵל אוֹתוֹ תִּינוֹק בְּבֶהָלָה וְתָפַס בְּעֹרֶף אָבִיו, וּבָכָה וְאָמַר, צְלָפְחָד זֶה מֵת בְּדִבּוּר, וְאַתָּה אַבָּא, בְּדִבּוּר חָזַרְתָּ לָעוֹלָם הַזֶּה. חָזַר אָבִיו וּנְשָׁקוֹ וְחִבְּקוֹ. בָּכוּ רַבִּי אֶלְעָזָר וְכָל הַחֲבֵרִים, וְאָבִיו בָּכָה אִתָּם. לְקָחוּהוּ כֻלָּם וּנְשָׁקוּהוּ בְּפִיו, עַל רֹאשׁוֹ, וְעַל עֵינָיו, וְאָבִיו הָיָה בּוֹכֶה עִמּוֹ.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, בְּנִי, הוֹאִיל וְאָמַרְתָּ דָּבָר זֶה, מַה זֶּה כִּי בְחֶטְאוֹ מֵת? אָמַר אוֹתוֹ תִּינוֹק, אַבָּא אַבָּא, בְּדָבָר אֶחָד מַסְפִּיק לָהֶם, בְּחֶטְאוֹ שֶׁל אוֹתוֹ (כיון שאותו) נָחָשׁ הַכָּרוּךְ בִּזְנָבוֹ לְמַעְלָה, מָשַׁךְ טַעַם בְּחֶטְאוֹ. מַה זֶּה בְּחֶטְאוֹ? בְּחֵטְא אוֹתוֹ הַנָּחָשׁ (ולא בחטא אחר). וּמַהוּ? דִּבּוּר פִּיו, כִּי בְחֶטְאוֹ מֵת, טַעַם אוֹתָהּ מְשִׁיכוּת שֶׁל אוֹתוֹ נָחָשׁ הַכָּרוּךְ בִּזְנָבוֹ, בְּחֶטְאוֹ וַדַּאי.</p>\n<p>לְקָחוֹ רַבִּי אֶלְעָזָר בְּכֹחוֹ בֵּין זְרוֹעוֹתָיו, וּבָכוּ כָּל הַחֲבֵרִים. אָמַר לָהֶם, רַבּוֹתֵינוּ, הַשְׁאִירוּנִי אֵצֶל אַבָּא, שֶׁעַד עַכְשָׁו לֹא הִתְיַשְּׁבָה רוּחִי (רוחו). אָמַר רַבִּי אֶלְעָזָר לְרַבִּי יוֹסֵי, אֱמֹר כַּמָּה יָמִים וְשָׁנִים לַתִּינוֹק הַזֶּה? אָמַר לָהֶם, חֲבֵרִים, בְּבַקָּשָׁה מִכֶּם, אַל תְּבַקְשׁוּ זֶה, שֶׁהֲרֵי עוֹד לֹא הִגִּיעוּ עָלָיו חָמֵשׁ שָׁנִים.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, חַס וְשָׁלוֹם, שֶׁהֲרֵי בְּעַיִן טוֹבָה אָנוּ מַשְׁגִּיחִים בּוֹ. וּמַה שֶּׁאָמַרְתָּ חָמֵשׁ שָׁנִים, אוֹתָם חָמֵשׁ שָׁנִים (בראשית מה) אֲשֶׁר אֵין חָרִישׁ וְקָצִיר, שֶׁלֹּא תִקְצֹר אוֹתוֹ לְעוֹלָמִים. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי אַבָּא, נֵשֵׁב כָּאן עַד שִׁבְעָה יָמִים כְּדֵי שֶׁהִתְיַשֵּׁב הַבַּיִת. שֶׁהֲרֵי כָּל שִׁבְעַת הַיָּמִים שֶׁהַנְּשָׁמָה יוֹצֵאת מֵהַגּוּף, הוֹלֶכֶת עֲרֻמָּה. וְכָעֵת שֶׁחָזְרָה, עַד עַכְשָׁו לֹא הִתְיַשְּׁבָה בִמְקוֹמָהּ עַד שִׁבְעָה יָמִים.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּתוּב (דברים טו) פָּתֹחַ תִּפְתַּח אֶת יָדְךְ לְּאָחִיךְ לַעֲנִיֶּךְ וּלְאֶבְיֹנְךְ. פָּסוּק זֶה הֲרֵי לָמַדְנוּ אוֹתוֹ, שֶׁלֹּא יַשְׁאִיר אָדָם אֶת הֶעָנִי שֶׁלּוֹ וְיִתֵּן לְאַחֵר. הֲרֵי רַבִּי יוֹסֵי חָמִיךְ בְּבֵית חָלְיוֹ, נֵלֵךְ וְנִגְמֹל אִתּוֹ חֶסֶד, וְאַחַר שֶׁנַּחֲזֹּר, נִכָּנֵס בָּזֶה. וַהֲרֵי כָּל זְמַן שֶׁנֵּלֵךְ וְנַחֲזֹר בְּדֶרֶךְ זוֹ, נִרְאֶה תְּחִיַּת הַמֵּתִים. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא. נָשְׁקוּ אֶת אוֹתוֹ תִּינוֹק, בֵּרְכוּהוּ וְהָלְכוּ.</p>\n<p>אָמַר רַבִּי אַבָּא, תְּמֵהַנִי עַל הַדַּרְדַּקִּים שֶׁל דּוֹר זֶה, כַּמָּה חָזָק כֹּחָם, וְהֵם סְלָעִים גְּדוֹלִים רָמִים. אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי חֶלְקוֹ שֶׁל אַבָּא בַּעַל הַדּוֹר הַזֶּה, שֶׁהֲרֵי בְּיָמָיו רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַתְקִין שְׁתֵּי יְשִׁיבוֹת שֶׁלּוֹ וְלַעֲשׂוֹת לָהֶם יִשּׁוּב גָּדוֹל וְעֶלְיוֹן כָּרָאוּי, שֶׁהֲרֵי לֹא יִהְיֶה כַדּוֹר הַזֶּה עַד שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ. הָלְכוּ.</p>"],[9522012434,"<p>עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אַבָּא, הֲרֵי שָׁנִינוּ, עַל אַחַד עָשָׂר דְּבָרִים בָּאִים נְגָעִים עַל בְּנֵי אָדָם, וְאֵלּוּ הֵם: עַל עֲבוֹדָה זָרָה, וְעַל קִלְלַת הַשֵּׁם, וְעַל גִּלּוּי עֲרָיוֹת, וְעַל גְּנֵבָה, וְעַל לָשׁוֹן הָרָע, וְעַל עֵדוּת שֶׁקֶר, וְעַל דַּיָּן שֶׁמְּקַלְקֵל אֶת הַדִּין, וְעַל שְׁבוּעַת שָׁוְא, וְעַל שֶׁנִּכְנָס בִּתְחוּם חֲבֵרוֹ, וְעַל הַחוֹשֵׁב מַחֲשָׁבוֹת רָעוֹת, וְעַל הַמְשַׁלֵּחַ מְדָנִים בֵּין אַחִים. וְיֵשׁ אוֹמְרִים אַף עַל עַיִן הָרָע. וְכֻלָּם שָׁנִינוּ בַמִּשְׁנָה.</p>\n<p>עָבוֹדָה זָרָה מִנַּיִן? שֶׁכָּתוּב (שמות לב) וַיַּרְא מֹשֶׁה אֶת הָעָם כִּי פָרֻעַ הוּא כִּי פְרָעֹה אַהֲרֹן. מַה זֶּה כִּי פָרֻעַ הוּא? שֶׁלָּקוּ בְצָרַעַת. כָּתוּב כָּאן כִּי פָרֻעַ הוּא, וְכָתוּב שָׁם, (ויקרא יג) וְהַצָּרוּעַ אֲשֶׁר בּוֹ הַנֶּגַע בְּגָדָיו יִהְיוּ פְרֻמִים וְרֹאשׁוֹ יִהְיֶה פָרוּעַ. וְעַל קִלְלַת הַשֵּׁם, שֶׁכָּתוּב (שמואל א יז) הַיּוֹם הַזֶּה יְסַגֶּרְךְ ה' בְּיָדִי, וְכָתוּב (ויקרא יג) וְהִסְגִּירוֹ הַכֹּהֵן.</p>"]]});
